def _candle_ttl_seconds(resolution):
    r = str(resolution or "").upper()
    if r in {"1", "5"}:
        return 10
    if r in {"15"}:
        return 30
    if r in {"30", "60", "1H"}:
        return 90
    return 180


def _now_utc_iso():
    return datetime.now(UTC).isoformat().replace("+00:00", "Z")


def _record_hot_path_timing(name, duration_ms):
    bucket = _HOT_PATH_TIMINGS.get(str(name))
    if bucket is None:
        return
    try:
        bucket.append(round(max(0.0, _to_float(duration_ms, 0.0)), 3))
    except Exception:
        return


def _hot_path_timing_stats(name):
    vals = list(_HOT_PATH_TIMINGS.get(str(name)) or [])
    if not vals:
        return {"last_ms": None, "avg_ms": None, "max_ms": None, "samples": 0}
    return {
        "last_ms": round(vals[-1], 3),
        "avg_ms": round(sum(vals) / len(vals), 3),
        "max_ms": round(max(vals), 3),
        "samples": int(len(vals)),
    }


def _load_user_preferences():
    prefs = dict(DEFAULT_USER_PREFERENCES)
    try:
        if os.path.exists(USER_PREFERENCES_PATH):
            with open(USER_PREFERENCES_PATH, "r", encoding="utf-8") as f:
                payload = json.load(f)
            if isinstance(payload, dict):
                for key in DEFAULT_USER_PREFERENCES.keys():
                    val = payload.get(key)
                    if isinstance(val, str) and val.strip():
                        prefs[key] = val.strip()
    except Exception:
        pass
    return prefs


def _save_user_preferences(payload):
    prefs = dict(DEFAULT_USER_PREFERENCES)
    if isinstance(payload, dict):
        for key in DEFAULT_USER_PREFERENCES.keys():
            val = payload.get(key)
            if isinstance(val, str) and val.strip():
                prefs[key] = val.strip()
    os.makedirs(STATE, exist_ok=True)
    with open(USER_PREFERENCES_PATH, "w", encoding="utf-8") as f:
        json.dump(prefs, f, indent=2)
    return prefs


def _best_ollama_model(models):
    if not models:
        return None
    preferred = str(OLLAMA_INLINE_DEFAULT_MODEL or "").strip().lower()
    if preferred:
        for name in models:
            n = str(name or "").strip()
            if n and n.lower() == preferred:
                return n
    ranked = []
    for name in models:
        n = str(name or "").strip()
        if not n:
            continue
        score = 0
        low = n.lower()
        if "70b" in low:
            score += 70
        elif "34b" in low:
            score += 34
        elif "27b" in low:
            score += 27
        elif "14b" in low:
            score += 14
        elif "13b" in low:
            score += 13
        elif "8b" in low or "7b" in low:
            score += 8
        if "qwen" in low:
            score += 8
        if "llama3.3" in low or "llama3.2" in low or "llama3.1" in low:
            score += 7
        if "mistral" in low or "mixtral" in low:
            score += 6
        if "phi" in low:
            score += 5
        if "instruct" in low or "chat" in low:
            score += 2
        ranked.append((score, n))
    if not ranked:
        return None
    ranked.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return ranked[0][1]


def _discover_ollama_models_from_fs():
    out = []
    try:
        root = os.path.expanduser("~/.ollama/models/manifests")
        if not os.path.isdir(root):
            return out
        for dirpath, _dirnames, filenames in os.walk(root):
            for fn in filenames:
                rel = os.path.relpath(os.path.join(dirpath, fn), root)
                parts = [p for p in rel.split(os.sep) if p and p != "."]
                if len(parts) >= 3:
                    model = f"{parts[0]}/{parts[1]}:{parts[2]}"
                    out.append(model)
        out = sorted(list(dict.fromkeys(out)))
    except Exception:
        return []
    return out


def _ollama_models_status():
    bin_path = shutil.which("ollama")
    status = {
        "available": bool(bin_path),
        "binary_path": bin_path or "",
        "installed_models": [],
        "selected_model": None,
        "error": "",
        "last_checked_utc": _now_utc_iso(),
    }
    if not bin_path:
        status["error"] = "ollama_not_installed"
        return status
    try:
        proc = subprocess.run(
            [bin_path, "list"],
            capture_output=True,
            text=True,
            timeout=12,
            check=False,
        )
        raw = proc.stdout or ""
        if proc.returncode != 0:
            status["error"] = (proc.stderr or raw or f"exit_{proc.returncode}").strip()[:220]
            models_fs = _discover_ollama_models_from_fs()
            if models_fs:
                status["installed_models"] = models_fs
                status["selected_model"] = _best_ollama_model(models_fs)
                status["error"] = status["error"] + " | daemon_unavailable_fs_fallback"
            return status
        models = []
        for line in raw.splitlines():
            line = line.strip()
            if not line or line.lower().startswith("name"):
                continue
            model = line.split()[0].strip()
            if model:
                models.append(model)
        status["installed_models"] = models
        status["selected_model"] = _best_ollama_model(models)
        if not status["selected_model"]:
            models_fs = _discover_ollama_models_from_fs()
            if models_fs:
                status["installed_models"] = models_fs
                status["selected_model"] = _best_ollama_model(models_fs)
                status["error"] = "daemon_list_empty_fs_fallback"
            else:
                status["error"] = "no_models_installed"
    except Exception as e:
        status["error"] = str(e)[:220]
        models_fs = _discover_ollama_models_from_fs()
        if models_fs:
            status["installed_models"] = models_fs
            status["selected_model"] = _best_ollama_model(models_fs)
            status["error"] = status["error"] + " | daemon_exception_fs_fallback"
    return status


def _ollama_models_status_cached(force=False):
    now = time.time()
    cached = dict(_OLLAMA_STATUS_CACHE.get("data") or {})
    ts = _to_float(_OLLAMA_STATUS_CACHE.get("ts"), 0.0)
    if cached and not force and (now - ts) <= OLLAMA_STATUS_TTL_SECONDS:
        return dict(cached)
    status = _ollama_models_status()
    _OLLAMA_STATUS_CACHE["data"] = dict(status)
    _OLLAMA_STATUS_CACHE["ts"] = now
    return status


def _safe_text(value, max_len=240):
    text = str(value or "").strip()
    if len(text) <= max_len:
        return text
    return text[: max(1, max_len - 1)].rstrip() + "."


def _json_from_maybe_markdown(raw):
    text = str(raw or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        pass
    start = text.find("{")
    end = text.rfind("}")
    if start >= 0 and end > start:
        try:
            parsed = json.loads(text[start : end + 1])
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


def _ollama_run_prompt(prompt, model=None, timeout_seconds=None):
    status = _ollama_models_status_cached()
    timeout = float(timeout_seconds or OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS)
    selected = str(model or "").strip()
    if not selected:
        preferred = str(OLLAMA_INLINE_DEFAULT_MODEL or "").strip().lower()
        installed = [str(m or "").strip() for m in list(status.get("installed_models") or [])]
        for m in installed:
            if m and m.lower() == preferred:
                selected = m
                break
    if not selected:
        selected = str(status.get("selected_model") or "").strip()
    if not bool(status.get("available")):
        return {"ok": False, "error": "ollama_not_available", "status": status, "text": ""}
    if not selected:
        return {"ok": False, "error": "no_local_model_available", "status": status, "text": ""}

    # Prefer local Ollama HTTP API for faster, safer prompt transport; keep CLI fallback.
    api_error = ""
    try:
        resp = requests.post(
            OLLAMA_API_URL,
            json={"model": selected, "prompt": str(prompt or ""), "stream": False},
            timeout=max(1.0, timeout),
            proxies={"http": "", "https": ""},
        )
        if resp.status_code == 200:
            payload = resp.json() if "application/json" in str(resp.headers.get("content-type", "")).lower() else {}
            text = str((payload or {}).get("response") or "").strip()
            if text:
                return {
                    "ok": True,
                    "status": status,
                    "model": selected,
                    "text": text,
                    "error": "",
                }
        api_error = _safe_text(f"ollama_api_status_{resp.status_code}", 120)
    except Exception as exc:
        api_error = _safe_text(f"ollama_api_request_failed:{exc}", 180)

    if not OLLAMA_INLINE_CLI_FALLBACK_ENABLED:
        return {
            "ok": False,
            "error": api_error or "ollama_api_no_text",
            "status": status,
            "model": selected,
            "text": "",
        }

    try:
        proc = subprocess.run(
            [status.get("binary_path") or "ollama", "run", selected, str(prompt or "")],
            capture_output=True,
            text=True,
            timeout=timeout,
            check=False,
        )
        if proc.returncode != 0:
            return {
                "ok": False,
                "error": _safe_text(proc.stderr or proc.stdout or f"ollama_exit_{proc.returncode}", 280),
                "status": status,
                "model": selected,
                "text": "",
            }
        return {
            "ok": True,
            "status": status,
            "model": selected,
            "text": str(proc.stdout or "").strip(),
            "error": "",
        }
    except Exception as exc:
        return {
            "ok": False,
            "error": _safe_text(str(exc), 280),
            "status": status,
            "model": selected,
            "text": "",
        }


def _buy_row_explain_signature(row):
    r = dict(row or {})
    mem = dict(r.get("memory_context") or {})
    return "|".join(
        [
            str(r.get("symbol") or "").upper(),
            str(r.get("canonical_final_state") or ""),
            str(r.get("setup_type") or ""),
            str(r.get("confirmation_state") or ""),
            str(r.get("follow_through_state") or ""),
            f"{_to_float(r.get('buy_quality_score'), _to_float(r.get('trade_quality_score'), 0.0)):.2f}",
            f"{_to_float(r.get('confidence'), _to_float(r.get('predicted_win_probability'), 0.0)):.2f}",
            str(r.get("primary_hero_release_blocker") or r.get("primary_promotion_blocker") or "none"),
            str(mem.get("memory_verdict") or "neutral_or_low_sample"),
        ]
    )


def _sell_row_explain_signature(alert):
    a = dict(alert or {})
    mem = dict(a.get("memory_context") or {})
    return "|".join(
        [
            str(a.get("symbol") or "").upper(),
            str(a.get("recommended_action") or "HOLD"),
            str(a.get("urgency") or "low"),
            str(a.get("strongest_exit_trigger") or a.get("primary_trigger") or "none"),
            f"{_to_float(a.get('exit_signal_confidence'), 0.0):.2f}",
            f"{_to_float(a.get('unrealized_pnl_percent'), 0.0):.2f}",
            f"{_to_float(a.get('pullback_from_peak_percent'), 0.0):.2f}",
            str(mem.get("memory_verdict") or "neutral_or_low_sample"),
        ]
    )


def _projected_move_summary_v1(row):
    r = dict(row or {})
    existing = _safe_text(r.get("ollama_expected_move_summary") or r.get("projected_move_summary") or r.get("projected_move_note"), 180)
    if existing:
        return existing
    price = _to_float(r.get("price"), _to_float(r.get("current_price"), 0.0))
    stop = _to_float(r.get("stop_loss"), 0.0)
    conf_raw = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
    conf = conf_raw if conf_raw <= 1.0 else (conf_raw / 100.0)
    conf = max(0.0, min(1.0, conf))
    quality = _to_float(r.get("buy_quality_score"), _to_float(r.get("trade_quality_score"), 0.0))
    posture = str(r.get("buy_eligibility") or r.get("core_decision_discipline_action") or "").lower()
    base_width = max(price * 0.005, 0.20)
    if price > 0 and stop > 0 and stop < price:
        base_width = max(base_width, price - stop)
    reward_mult = 1.25 + (conf * 0.75)
    if quality >= 80.0:
        reward_mult += 0.25
    if quality < 60.0:
        reward_mult -= 0.20
    if posture in {"watchlist", "watchlist_only", "blocked", "reject"}:
        reward_mult -= 0.20
    reward_mult = max(0.85, min(2.25, reward_mult))
    low_move = max(0.10, base_width * reward_mult * 0.70)
    high_move = max(low_move + 0.10, base_width * reward_mult * 1.15)
    if price <= 0:
        return "Expected move: weak/unclear if setup holds."
    low_pct = (low_move / price) * 100.0
    high_pct = (high_move / price) * 100.0
    return _safe_text(
        f"Expected move: +${low_move:.2f} to +${high_move:.2f} (+{low_pct:.1f}% to +{high_pct:.1f}%) if setup holds.",
        150,
    )


def _structured_buy_summary_v1(row):
    r = dict(row or {})
    conf_raw = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
    conf_pct = conf_raw * 100.0 if conf_raw <= 1.0 else conf_raw
    conf_pct = max(0.0, min(100.0, conf_pct))
    grade_txt = _safe_text(str(r.get("astra_grade") or r.get("grade") or r.get("buy_qualification_tier") or "n/a"), 20)
    strength = _safe_text(
        str(r.get("follow_through_state") or r.get("entry_confirmation_state") or r.get("setup_type") or "mixed setup").replace("_", " "),
        30,
    )
    uncertainty = _safe_text(str(r.get("uncertainty_tier") or "moderate_uncertainty").replace("_", " "), 22)
    risk = _safe_text(
        str(
            r.get("primary_hero_release_blocker")
            or r.get("primary_promotion_blocker")
            or r.get("release_reroute_reason")
            or "confirmation loss"
        ).replace("_", " "),
        40,
    )
    posture = _safe_text(
        str(r.get("buy_eligibility") or r.get("core_decision_discipline_action") or "watchlist").replace("_", " "),
        24,
    )
    projected = _projected_move_summary_v1(r).replace("Expected move:", "").strip()
    projected = _safe_text(projected, 96)
    return _safe_text(
        f"{grade_txt} | {conf_pct:.0f}% confidence | {strength} | Uncertainty {uncertainty} | Risk: {risk} | Expected move: {projected} | Posture: {posture}",
        280,
    )


def _default_buy_user_explanations(row):
    r = dict(row or {})
    compact_line = _structured_buy_summary_v1(r)
    expected_move = _projected_move_summary_v1(r)
    logic_summary = _safe_text(
        r.get("plain_decision_summary")
        or r.get("plain_actionability_summary")
        or "Astra uses setup clarity, consensus, quality, and risk checks before deciding posture.",
        220,
    )
    return {
        "user_buy_summary": _safe_text(r.get("plain_decision_summary"), 220),
        "user_caution_summary": _safe_text(r.get("plain_actionability_summary"), 220),
        "user_invalidation_summary": _safe_text(r.get("plain_invalidation_summary"), 220),
        "ollama_expected_move_summary": expected_move,
        "ollama_projected_move": expected_move,
        "ollama_logic_summary": logic_summary,
        "ollama_explanation": compact_line or "Explanation unavailable (fallback).",
        "ollama_buy_explanation": compact_line or "Explanation unavailable (fallback).",
    }


def _default_sell_user_explanations(alert):
    a = dict(alert or {})
    position_explanation = _safe_text(
        a.get("plain_sell_summary")
        or "Astra is monitoring continuation, drawdown, and signal deterioration before changing posture.",
        240,
    )
    position_watchlist = _safe_text(
        a.get("plain_sell_memory_summary")
        or "Watching signal confidence, pullback from peak, and quote freshness for changes in risk.",
        220,
    )
    position_risk = _safe_text(
        a.get("plain_sell_discipline_note")
        or "Risk rises if deterioration persists; posture can shift to tighten, trim, or exit.",
        220,
    )
    return {
        "user_sell_summary": _safe_text(a.get("plain_sell_summary"), 220),
        "user_sell_caution_summary": _safe_text(a.get("plain_sell_memory_summary"), 220),
        "user_sell_invalidation_summary": _safe_text(a.get("plain_sell_discipline_note"), 220),
        "ollama_position_explanation": position_explanation,
        "ollama_position_watchlist": position_watchlist,
        "ollama_position_risk_summary": position_risk,
        "ollama_sell_explanation": position_explanation,
    }


def _apply_ollama_buy_explanations(rows):
    out = [dict(r or {}) for r in list(rows or [])]
    if not out:
        return out
    now = time.time()
    for row in out:
        row.update(_default_buy_user_explanations(row))
        row["explanation_layer_source"] = "deterministic_fallback"
        row["ollama_explanation_used"] = False
    if not OLLAMA_INLINE_EXPLANATIONS_ENABLED:
        return out

    target = []
    for row in out:
        # Explain every displayed stock row; explainability is post-decision only.
        target.append(row)
    target = target[:OLLAMA_INLINE_MAX_BUY_ROWS]
    if not target:
        return out
    started = time.perf_counter()

    cache_bucket = _OLLAMA_INLINE_EXPLAIN_CACHE.setdefault("buy", {})
    missing = []
    for row in target:
        sig = _buy_row_explain_signature(row)
        cached = dict(cache_bucket.get(sig) or {})
        if cached and (now - _to_float(cached.get("ts"), 0.0)) <= OLLAMA_INLINE_EXPLAIN_TTL_SECONDS:
            data = dict(cached.get("data") or {})
            explanation_text = _safe_text(
                data.get("explanation")
                or " ".join(
                    [
                        _safe_text(data.get("buy"), 120),
                        _safe_text(data.get("caution"), 120),
                    ]
                ).strip(),
                320,
            ) or str(row.get("ollama_buy_explanation") or row.get("ollama_explanation") or "Explanation unavailable (fallback).")
            row.update({
                "user_buy_summary": _safe_text(data.get("buy"), 220) or row.get("user_buy_summary"),
                "user_caution_summary": _safe_text(data.get("caution"), 220) or row.get("user_caution_summary"),
                "user_invalidation_summary": _safe_text(data.get("invalidate"), 220) or row.get("user_invalidation_summary"),
                "ollama_expected_move_summary": _safe_text(data.get("expected_move"), 220) or row.get("ollama_expected_move_summary"),
                "ollama_projected_move": _safe_text(data.get("expected_move"), 220) or row.get("ollama_projected_move"),
                "ollama_logic_summary": _safe_text(data.get("logic"), 220) or row.get("ollama_logic_summary"),
                "ollama_explanation": explanation_text,
                "ollama_buy_explanation": explanation_text,
                "explanation_layer_source": "ollama_cached",
                "ollama_explanation_used": True,
            })
            continue
        missing.append((sig, row))

    if not missing:
        return out

    model_status = _ollama_models_status_cached()
    if not bool(model_status.get("available")) or not str(model_status.get("selected_model") or "").strip():
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_run_utc"] = _now_utc_iso()
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_success"] = False
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = str(model_status.get("error") or "ollama_unavailable")
        return out

    # Keep top_buys responsive: skip heavy multi-row prompts and converge with short per-row calls + cache.
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_run_utc"] = _now_utc_iso()
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_success"] = False
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = ""
    prompt_rows = []
    for idx, (_sig, row) in enumerate(missing, start=1):
        prompt_rows.append(
            {
                "id": f"b{idx}",
                "symbol": str(row.get("symbol") or "").upper(),
                "state": str(row.get("canonical_final_state") or ""),
                "action": str(row.get("final_action") or row.get("top_buy_action") or row.get("action") or ""),
                "grade": str(row.get("astra_grade") or row.get("grade") or row.get("buy_qualification_tier") or ""),
                "confidence": round(_to_float(row.get("confidence"), _to_float(row.get("predicted_win_probability"), 0.0)), 2),
                "follow_through": str(row.get("follow_through_state") or ""),
                "uncertainty_tier": str(row.get("uncertainty_tier") or ""),
                "projected_move": str(row.get("ollama_projected_move") or row.get("ollama_expected_move_summary") or ""),
                "posture": str(row.get("buy_eligibility") or row.get("core_decision_discipline_action") or ""),
                "blocker": str(
                    row.get("primary_hero_release_blocker")
                    or row.get("primary_promotion_blocker")
                    or row.get("primary_blocker")
                    or "none"
                ),
            }
        )
    prompt = (
        "Return strict JSON only. No markdown.\n"
        "Schema: {\"items\":[{\"id\":\"b1\",\"explanation\":\"...\",\"expected_move\":\"...\",\"logic\":\"...\"}]}\n"
        "Write one compact line per item using '|' separators.\n"
        "Format: '<grade> | <confidence>% confidence | <one strength> | Uncertainty <tier> | Risk: <main risk> | Expected move: <conditional projected move> | Posture: <posture>'.\n"
        "Keep each explanation under 220 chars. No guarantees.\n"
        "expected_move must be conditional using wording like 'if setup holds'.\n"
        f"Input: {json.dumps({'items': prompt_rows}, ensure_ascii=True)}"
    )
    batch_timeout = min(2.8, max(1.3, OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS / 2.2))
    run = _ollama_run_prompt(prompt, timeout_seconds=batch_timeout)
    _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = str(run.get("error") or "")
    parsed = _json_from_maybe_markdown(run.get("text")) if bool(run.get("ok")) else {}
    items = list(parsed.get("items") or []) if isinstance(parsed, dict) else []
    by_id = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        key = str(item.get("id") or "").strip()
        if not key:
            continue
        by_id[key] = {
            "explanation": _safe_text(item.get("explanation"), 260),
            "expected_move": _safe_text(item.get("expected_move"), 220),
            "logic": _safe_text(item.get("logic"), 220),
        }
    unresolved = []
    for idx, (sig, row) in enumerate(missing, start=1):
        item = by_id.get(f"b{idx}") or {}
        if not item:
            unresolved.append((sig, row, idx))
            continue
        explanation_text = _safe_text(
            item.get("explanation")
            or " ".join(
                [
                    _safe_text(item.get("logic"), 120),
                    _safe_text(item.get("expected_move"), 120),
                ]
            ).strip(),
            260,
        ) or str(row.get("ollama_buy_explanation") or row.get("ollama_explanation") or "Explanation unavailable (fallback).")
        row.update({
            "user_buy_summary": item.get("logic") or row.get("user_buy_summary"),
            "user_caution_summary": item.get("logic") or row.get("user_caution_summary"),
            "user_invalidation_summary": item.get("logic") or row.get("user_invalidation_summary"),
            "ollama_expected_move_summary": item.get("expected_move") or row.get("ollama_expected_move_summary"),
            "ollama_projected_move": item.get("expected_move") or row.get("ollama_projected_move"),
            "ollama_logic_summary": item.get("logic") or row.get("ollama_logic_summary"),
            "ollama_explanation": explanation_text,
            "ollama_buy_explanation": explanation_text,
            "explanation_layer_source": "ollama_live",
            "ollama_explanation_used": True,
        })
        cache_bucket[sig] = {"ts": now, "data": dict(item)}
    if unresolved:
        per_item_timeout = max(1.5, min(2.8, OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS / 1.8))
        for sig, row, idx in unresolved:
            if (time.perf_counter() - started) >= OLLAMA_INLINE_TOTAL_BUDGET_SECONDS:
                _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = "ollama_budget_exceeded"
                break
            per_payload = {
                "id": f"b{idx}",
                "symbol": str(row.get("symbol") or "").upper(),
                "state": str(row.get("canonical_final_state") or ""),
                "action": str(row.get("final_action") or row.get("top_buy_action") or row.get("action") or ""),
                "grade": str(row.get("astra_grade") or row.get("grade") or row.get("buy_qualification_tier") or ""),
                "confidence": round(_to_float(row.get("confidence"), _to_float(row.get("predicted_win_probability"), 0.0)), 2),
                "follow_through": str(row.get("follow_through_state") or ""),
                "uncertainty_tier": str(row.get("uncertainty_tier") or ""),
                "projected_move": str(row.get("ollama_projected_move") or row.get("ollama_expected_move_summary") or ""),
                "posture": str(row.get("buy_eligibility") or row.get("core_decision_discipline_action") or ""),
                "blocker": str(
                    row.get("primary_hero_release_blocker")
                    or row.get("primary_promotion_blocker")
                    or row.get("primary_blocker")
                    or "none"
                ),
            }
            per_prompt = (
                "Return strict JSON only. No markdown.\n"
                "Schema: {\"explanation\":\"...\",\"expected_move\":\"...\",\"logic\":\"...\"}\n"
                "Write one compact line under 220 chars with '|' separators.\n"
                "Include grade, confidence, one strength, uncertainty, risk, conditional expected move, and posture.\n"
                "No guarantees.\n"
                f"Input: {json.dumps(per_payload, ensure_ascii=True)}"
            )
            run = _ollama_run_prompt(per_prompt, timeout_seconds=per_item_timeout)
            _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = str(run.get("error") or _OLLAMA_EXPLANATION_RUNTIME.get("buy_last_error") or "")
            if not bool(run.get("ok")):
                continue
            parsed = _json_from_maybe_markdown(run.get("text"))
            explanation_text = _safe_text(
                parsed.get("explanation")
                or " ".join(
                    [
                        _safe_text(parsed.get("logic"), 120),
                        _safe_text(parsed.get("expected_move"), 120),
                    ]
                ).strip(),
                260,
            ) or str(row.get("ollama_buy_explanation") or row.get("ollama_explanation") or "Explanation unavailable (fallback).")
            item = {
                "explanation": _safe_text(parsed.get("explanation"), 260),
                "expected_move": _safe_text(parsed.get("expected_move"), 220),
                "logic": _safe_text(parsed.get("logic"), 220),
            }
            row.update({
                "user_buy_summary": item.get("logic") or row.get("user_buy_summary"),
                "user_caution_summary": item.get("logic") or row.get("user_caution_summary"),
                "user_invalidation_summary": item.get("logic") or row.get("user_invalidation_summary"),
                "ollama_expected_move_summary": item.get("expected_move") or row.get("ollama_expected_move_summary"),
                "ollama_projected_move": item.get("expected_move") or row.get("ollama_projected_move"),
                "ollama_logic_summary": item.get("logic") or row.get("ollama_logic_summary"),
                "ollama_explanation": explanation_text,
                "ollama_buy_explanation": explanation_text,
                "explanation_layer_source": "ollama_live",
                "ollama_explanation_used": True,
            })
            cache_bucket[sig] = {"ts": now, "data": dict(item)}
    if missing:
        any_live = any(
            str((row or {}).get("explanation_layer_source") or "").strip().lower() in {"ollama_live", "ollama_cached"}
            for _, row in missing
        )
        _OLLAMA_EXPLANATION_RUNTIME["buy_last_success"] = bool(any_live)
        if not any_live and not str(_OLLAMA_EXPLANATION_RUNTIME.get("buy_last_error") or "").strip():
            _OLLAMA_EXPLANATION_RUNTIME["buy_last_error"] = "ollama_no_structured_items"
    return out


def generate_ollama_explanation(row):
    """
    Read-only explainability helper.
    Returns a short posture explanation string and never influences decisions.
    """
    r = dict(row or {})
    fallback = _structured_buy_summary_v1(r) or "Explanation unavailable (fallback)."
    if not OLLAMA_INLINE_EXPLANATIONS_ENABLED:
        return fallback
    status = _ollama_models_status_cached()
    if not bool(status.get("available")) or not str(status.get("selected_model") or "").strip():
        return fallback
    prompt_payload = {
        "symbol": str(r.get("symbol") or "").upper(),
        "action": str(r.get("final_action") or r.get("top_buy_action") or r.get("action") or ""),
        "grade": str(r.get("grade") or r.get("grade_letter") or ""),
        "confidence": round(_to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0)), 4),
        "uncertainty_score": round(_to_float(r.get("uncertainty_score"), 0.0), 2),
        "uncertainty_tier": str(r.get("uncertainty_tier") or ""),
        "uncertainty_reasons": list(r.get("uncertainty_reasons") or []),
        "discipline_tier": str(r.get("core_decision_discipline_tier") or ""),
        "discipline_action": str(r.get("core_decision_discipline_action") or ""),
        "persona_best_fit": str(r.get("persona_best_fit") or ""),
        "consensus_strength": round(_to_float(r.get("consensus_strength"), 0.0), 2),
        "funnel_score_total": round(_to_float(r.get("funnel_score_total"), 0.0), 2),
        "buy_qualification_tier": str(r.get("buy_qualification_tier") or ""),
    }
    prompt = (
        "Return strict JSON only. No markdown.\n"
        "Schema: {\"explanation\":\"...\"}\n"
        "Write one compact line under 220 chars with '|' separators.\n"
        "Include: grade, confidence, one strength, uncertainty, main risk, conditional expected move, posture.\n"
        "No guarantees.\n"
        f"Input: {json.dumps(prompt_payload, ensure_ascii=True)}"
    )
    run = _ollama_run_prompt(prompt, timeout_seconds=min(2.5, float(OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS)))
    if not bool(run.get("ok")):
        return fallback
    parsed = _json_from_maybe_markdown(run.get("text"))
    explanation = _safe_text((parsed or {}).get("explanation"), 320)
    return explanation or fallback


def _apply_ollama_sell_explanations(alerts):
    out = [dict(a or {}) for a in list(alerts or [])]
    if not out:
        return out
    now = time.time()
    for alert in out:
        alert.update(_default_sell_user_explanations(alert))
        alert["sell_explanation_layer_source"] = "deterministic_fallback"
        alert["ollama_sell_explanation_used"] = False
    if not OLLAMA_INLINE_EXPLANATIONS_ENABLED:
        return out

    target = list(out)[:OLLAMA_INLINE_MAX_SELL_ROWS]
    if not target:
        return out
    started = time.perf_counter()

    cache_bucket = _OLLAMA_INLINE_EXPLAIN_CACHE.setdefault("sell", {})
    missing = []
    for alert in target:
        sig = _sell_row_explain_signature(alert)
        cached = dict(cache_bucket.get(sig) or {})
        if cached and (now - _to_float(cached.get("ts"), 0.0)) <= OLLAMA_INLINE_EXPLAIN_TTL_SECONDS:
            data = dict(cached.get("data") or {})
            alert.update({
                "user_sell_summary": _safe_text(data.get("sell"), 220) or alert.get("user_sell_summary"),
                "user_sell_caution_summary": _safe_text(data.get("caution"), 220) or alert.get("user_sell_caution_summary"),
                "user_sell_invalidation_summary": _safe_text(data.get("invalidate"), 220) or alert.get("user_sell_invalidation_summary"),
                "ollama_position_explanation": _safe_text(data.get("position_explanation"), 260) or alert.get("ollama_position_explanation"),
                "ollama_position_watchlist": _safe_text(data.get("watchlist"), 220) or alert.get("ollama_position_watchlist"),
                "ollama_position_risk_summary": _safe_text(data.get("risk"), 220) or alert.get("ollama_position_risk_summary"),
                "ollama_sell_explanation": _safe_text(data.get("position_explanation"), 260) or alert.get("ollama_sell_explanation"),
                "sell_explanation_layer_source": "ollama_cached",
                "ollama_sell_explanation_used": True,
            })
            continue
        missing.append((sig, alert))
    if not missing:
        return out

    model_status = _ollama_models_status_cached()
    if not bool(model_status.get("available")) or not str(model_status.get("selected_model") or "").strip():
        _OLLAMA_EXPLANATION_RUNTIME["sell_last_run_utc"] = _now_utc_iso()
        _OLLAMA_EXPLANATION_RUNTIME["sell_last_success"] = False
        _OLLAMA_EXPLANATION_RUNTIME["sell_last_error"] = str(model_status.get("error") or "ollama_unavailable")
        return out

    prompt_rows = []
    for idx, (_sig, alert) in enumerate(missing, start=1):
        prompt_rows.append(
            {
                "id": f"s{idx}",
                "symbol": str(alert.get("symbol") or "").upper(),
                "action": str(alert.get("recommended_action") or "HOLD"),
                "urgency": str(alert.get("urgency") or "low"),
                "trigger": str(alert.get("strongest_exit_trigger") or alert.get("primary_trigger") or "none"),
                "signal_confidence": round(_to_float(alert.get("exit_signal_confidence"), 0.0), 2),
                "unrealized_pct": round(_to_float(alert.get("unrealized_pnl_percent"), 0.0), 2),
                "pullback_pct": round(_to_float(alert.get("pullback_from_peak_percent"), 0.0), 2),
                "expected_risk_if_hold": round(_to_float(alert.get("expected_risk_if_hold"), 0.0), 4),
                "hold_quality_estimate": round(_to_float(((alert.get("exit_policy_applied") or {}).get("exit_learning_hold_quality_estimate")), 0.0), 4),
                "missed_profit_pressure": round(_to_float(((alert.get("exit_policy_applied") or {}).get("exit_learning_missed_profit_pressure")), 0.0), 4),
                "memory_verdict": str((alert.get("memory_context") or {}).get("memory_verdict") or "neutral_or_low_sample"),
            }
        )
    prompt = (
        "Return strict JSON only. No markdown.\n"
        "For each item create simple position guidance for non-technical users.\n"
        "Keep each item concise and practical.\n"
        "Schema: {\"items\":[{\"id\":\"s1\",\"sell\":\"...\",\"caution\":\"...\",\"invalidate\":\"...\",\"position_explanation\":\"...\",\"watchlist\":\"...\",\"risk\":\"...\"}]}\n"
        "position_explanation: what Astra is watching now and current lean (hold/tighten/trim/exit).\n"
        "watchlist: what conditions keep the trade healthy.\n"
        "risk: what conditions can push Astra toward trim/exit.\n"
        "Use only supplied evidence.\n"
        f"Input: {json.dumps({'items': prompt_rows}, ensure_ascii=True)}"
    )
    run = _ollama_run_prompt(prompt, timeout_seconds=min(6.0, OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS))
    _OLLAMA_EXPLANATION_RUNTIME["sell_last_run_utc"] = _now_utc_iso()
    _OLLAMA_EXPLANATION_RUNTIME["sell_last_success"] = bool(run.get("ok"))
    _OLLAMA_EXPLANATION_RUNTIME["sell_last_error"] = str(run.get("error") or "")
    parsed = _json_from_maybe_markdown(run.get("text")) if bool(run.get("ok")) else {}
    items = list(parsed.get("items") or []) if isinstance(parsed, dict) else []
    by_id = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        key = str(item.get("id") or "").strip()
        if not key:
            continue
        by_id[key] = {
            "sell": _safe_text(item.get("sell"), 220),
            "caution": _safe_text(item.get("caution"), 220),
            "invalidate": _safe_text(item.get("invalidate"), 220),
            "position_explanation": _safe_text(item.get("position_explanation"), 260),
            "watchlist": _safe_text(item.get("watchlist"), 220),
            "risk": _safe_text(item.get("risk"), 220),
        }
    unresolved = []
    for idx, (sig, alert) in enumerate(missing, start=1):
        item = by_id.get(f"s{idx}") or {}
        if not item:
            unresolved.append((sig, alert, idx))
            continue
        alert.update({
            "user_sell_summary": item.get("sell") or alert.get("user_sell_summary"),
            "user_sell_caution_summary": item.get("caution") or alert.get("user_sell_caution_summary"),
            "user_sell_invalidation_summary": item.get("invalidate") or alert.get("user_sell_invalidation_summary"),
            "ollama_position_explanation": item.get("position_explanation") or alert.get("ollama_position_explanation"),
            "ollama_position_watchlist": item.get("watchlist") or alert.get("ollama_position_watchlist"),
            "ollama_position_risk_summary": item.get("risk") or alert.get("ollama_position_risk_summary"),
            "ollama_sell_explanation": item.get("position_explanation") or alert.get("ollama_sell_explanation"),
            "sell_explanation_layer_source": "ollama_live",
            "ollama_sell_explanation_used": True,
        })
        cache_bucket[sig] = {"ts": now, "data": dict(item)}
    if unresolved:
        per_item_timeout = max(3.0, min(5.5, OLLAMA_INLINE_EXPLAIN_TIMEOUT_SECONDS / 2.5))
        for sig, alert, idx in unresolved:
            if (time.perf_counter() - started) >= OLLAMA_INLINE_TOTAL_BUDGET_SECONDS:
                _OLLAMA_EXPLANATION_RUNTIME["sell_last_error"] = "ollama_budget_exceeded"
                break
            per_payload = {
                "id": f"s{idx}",
                "symbol": str(alert.get("symbol") or "").upper(),
                "action": str(alert.get("recommended_action") or "HOLD"),
                "urgency": str(alert.get("urgency") or "low"),
                "trigger": str(alert.get("strongest_exit_trigger") or alert.get("primary_trigger") or "none"),
                "signal_confidence": round(_to_float(alert.get("exit_signal_confidence"), 0.0), 2),
                "unrealized_pct": round(_to_float(alert.get("unrealized_pnl_percent"), 0.0), 2),
                "pullback_pct": round(_to_float(alert.get("pullback_from_peak_percent"), 0.0), 2),
                "expected_risk_if_hold": round(_to_float(alert.get("expected_risk_if_hold"), 0.0), 4),
                "memory_verdict": str((alert.get("memory_context") or {}).get("memory_verdict") or "neutral_or_low_sample"),
            }
            per_prompt = (
                "Return strict JSON only. No markdown.\n"
                "Schema: {\"sell\":\"...\",\"caution\":\"...\",\"invalidate\":\"...\",\"position_explanation\":\"...\",\"watchlist\":\"...\",\"risk\":\"...\"}\n"
                "Use simple language and describe what Astra is watching in real time.\n"
                f"Input: {json.dumps(per_payload, ensure_ascii=True)}"
            )
            run = _ollama_run_prompt(per_prompt, timeout_seconds=per_item_timeout)
            if not bool(run.get("ok")):
                continue
            parsed = _json_from_maybe_markdown(run.get("text"))
            item = {
                "sell": _safe_text(parsed.get("sell"), 220),
                "caution": _safe_text(parsed.get("caution"), 220),
                "invalidate": _safe_text(parsed.get("invalidate"), 220),
                "position_explanation": _safe_text(parsed.get("position_explanation"), 260),
                "watchlist": _safe_text(parsed.get("watchlist"), 220),
                "risk": _safe_text(parsed.get("risk"), 220),
            }
            alert.update({
                "user_sell_summary": item.get("sell") or alert.get("user_sell_summary"),
                "user_sell_caution_summary": item.get("caution") or alert.get("user_sell_caution_summary"),
                "user_sell_invalidation_summary": item.get("invalidate") or alert.get("user_sell_invalidation_summary"),
                "ollama_position_explanation": item.get("position_explanation") or alert.get("ollama_position_explanation"),
                "ollama_position_watchlist": item.get("watchlist") or alert.get("ollama_position_watchlist"),
                "ollama_position_risk_summary": item.get("risk") or alert.get("ollama_position_risk_summary"),
                "ollama_sell_explanation": item.get("position_explanation") or alert.get("ollama_sell_explanation"),
                "sell_explanation_layer_source": "ollama_live",
                "ollama_sell_explanation_used": True,
            })
            cache_bucket[sig] = {"ts": now, "data": dict(item)}
    if missing:
        any_live = any(
            str((alert or {}).get("sell_explanation_layer_source") or "").strip().lower() in {"ollama_live", "ollama_cached"}
            for _, alert in missing
        )
        _OLLAMA_EXPLANATION_RUNTIME["sell_last_success"] = bool(any_live)
        if not any_live and not str(_OLLAMA_EXPLANATION_RUNTIME.get("sell_last_error") or "").strip():
            _OLLAMA_EXPLANATION_RUNTIME["sell_last_error"] = "ollama_no_structured_items"
    return out


def _load_universe_symbols():
    diag = {
        "universe_file_path_used": UNIVERSE_FILE_PATH,
        "universe_size": 0,
        "large_cap_count": 0,
        "mid_cap_count": 0,
        "small_cap_count": 0,
        "fallback_to_hardcoded": False,
        "last_universe_loaded_utc": _now_utc_iso(),
        "last_warning": "",
    }
    symbols = []
    seen = set()
    cap_map = {}
    sector_map = {}
    try:
        with open(UNIVERSE_FILE_PATH, "r") as f:
            payload = json.load(f)
        stocks = payload.get("stocks", []) if isinstance(payload, dict) else payload
        if not isinstance(stocks, list):
            raise ValueError("stocks_not_list")
        for raw in stocks:
            symbol = None
            category = None
            if isinstance(raw, dict):
                symbol = str(raw.get("symbol", "")).upper().strip()
                category = str(raw.get("market_cap_category", "")).lower().strip()
                if symbol:
                    cap_map[symbol] = category if category in UNIVERSE_CAP_CATEGORIES else "unknown"
                    sector_map[symbol] = str(raw.get("sector", "unknown")).lower()
            elif isinstance(raw, str):
                symbol = raw.upper().strip()
            if not symbol or symbol in seen:
                continue
            if category and category not in UNIVERSE_CAP_CATEGORIES:
                continue
            seen.add(symbol)
            symbols.append(symbol)
            if category == "large":
                diag["large_cap_count"] += 1
            elif category == "mid":
                diag["mid_cap_count"] += 1
            elif category == "small":
                diag["small_cap_count"] += 1
        if not symbols:
            raise ValueError("empty_universe")
    except Exception as e:
        symbols = list(FALLBACK_STOCK_SYMBOLS)
        diag["fallback_to_hardcoded"] = True
        diag["last_warning"] = f"universe_load_failed:{e}"
        for sym in symbols:
            cap_map[str(sym).upper()] = "unknown"
            sector_map[str(sym).upper()] = "unknown"
    diag["universe_size"] = len(symbols)
    diag["cap_map"] = dict(cap_map)
    diag["sector_map"] = dict(sector_map)
    _UNIVERSE_RUNTIME.update(diag)
    return symbols


def _finnhub_key():
    key = os.getenv("FINNHUB_API_KEY", "")
    if key and not str(key).startswith("YOUR_"):
        return key
    try:
        from api_keys import FINNHUB_API_KEY
        if FINNHUB_API_KEY and not str(FINNHUB_API_KEY).startswith("YOUR_"):
            return FINNHUB_API_KEY
    except Exception:
        pass
    return ""


def _alpaca_creds():
    key = (
        os.getenv("ALPACA_API_KEY", "")
        or os.getenv("APCA_API_KEY_ID", "")
        or os.getenv("ALPACA_API_KEY_ID", "")
    )
    secret = (
        os.getenv("ALPACA_SECRET_KEY", "")
        or os.getenv("APCA_API_SECRET_KEY", "")
        or os.getenv("ALPACA_API_SECRET", "")
    )
    generic_base = os.getenv("ALPACA_BASE_URL", "").rstrip("/")
    trading_base = (
        os.getenv("ALPACA_TRADING_BASE_URL", "").rstrip("/")
        or (generic_base if "paper-api.alpaca.markets" in generic_base else "https://paper-api.alpaca.markets/v2")
    )
    market_raw = (
        os.getenv("ALPACA_MARKET_DATA_BASE_URL", "").rstrip("/")
        or os.getenv("ALPACA_DATA_BASE_URL", "").rstrip("/")
        or (generic_base if "data.alpaca.markets" in generic_base else "https://data.alpaca.markets")
    )
    market_base = "https://data.alpaca.markets" if "paper-api.alpaca.markets" in market_raw else (
        market_raw[:-3] if market_raw.endswith("/v2") else market_raw
    )
    if key and secret and not str(key).startswith("YOUR_") and not str(secret).startswith("YOUR_"):
        return key, secret, market_base, trading_base
    return "", "", market_base, trading_base


def _alpaca_timeframe(resolution):
    r = str(resolution or "15").upper()
    mapping = {
        "1": "1Min",
        "5": "5Min",
        "15": "15Min",
        "60": "1Hour",
        "D": "1Day",
    }
    return mapping.get(r, "15Min")


def _cache_get(bucket, key, ttl):
    row = _CACHE.get(bucket, {}).get(key)
    if not row:
        return None
    age = time.time() - float(row.get("ts", 0.0))
    if age > ttl:
        return None
    data = dict(row.get("data", {}))
    data["cached"] = True
    return data


def _cache_set(bucket, key, data):
    _CACHE.setdefault(bucket, {})[key] = {"ts": time.time(), "data": dict(data)}


def _cap_distribution(symbols, cap_map):
    out = {"large": 0, "mid": 0, "small": 0, "unknown": 0}
    for sym in symbols or []:
        c = str((cap_map or {}).get(str(sym).upper(), "unknown")).lower()
        if c not in out:
            c = "unknown"
        out[c] = int(out.get(c, 0)) + 1
    return out


def _ensure_persona_fields(row, funnel_hint=None):
    item = dict(row or {})
    if not isinstance(item.get("persona_grades"), dict) or not item.get("persona_grades"):
        grades = {}
        for p in item.get("persona_breakdown", []) or []:
            if not isinstance(p, dict):
                continue
            pname = str(p.get("persona_name") or "Unknown")
            rs = p.get("reasoning_summary") or ""
            grades[pname] = {
                "persona_grade_percent": float(p.get("grade_percent", p.get("numeric_score", 0.0)) or 0.0),
                "persona_grade_letter": p.get("grade_letter") or "C",
                "persona_confidence": float(p.get("confidence", 0.0) or 0.0),
                "persona_reasons": [str(rs)] if rs else [],
                "persona_signal_weights_used": {},
                "persona_signal": p.get("buy_hold_sell_signal") or "Hold",
            }
        item["persona_grades"] = grades
    if not isinstance(item.get("persona_consensus_summary"), dict) or not item.get("persona_consensus_summary"):
        item["persona_consensus_summary"] = {
            "consensus_strength": float(item.get("consensus_strength", 0.0) or 0.0),
            "disagreement_index": float(item.get("persona_disagreement_index", 100.0) or 100.0),
            "persona_best_fit": "Unknown",
            "funnel_score_total": float(item.get("persona_weighted_grade", item.get("grade_percent", 0.0)) or 0.0),
        }
    if isinstance(funnel_hint, dict):
        if isinstance(funnel_hint.get("persona_grades"), dict):
            item["persona_grades"] = funnel_hint.get("persona_grades")
        if isinstance(funnel_hint.get("persona_consensus_summary"), dict):
            item["persona_consensus_summary"] = funnel_hint.get("persona_consensus_summary")
        if funnel_hint.get("funnel_score_total") is not None:
            item["funnel_score_total"] = float(funnel_hint.get("funnel_score_total") or 0.0)
        if funnel_hint.get("funnel_reason"):
            item["funnel_reason"] = str(funnel_hint.get("funnel_reason"))
    best_fit = item.get("persona_best_fit")
    if not best_fit:
        best_fit = item.get("persona_consensus_summary", {}).get("persona_best_fit")
    if (not best_fit or str(best_fit).lower() == "unknown") and isinstance(item.get("persona_grades"), dict):
        g = item.get("persona_grades") or {}
        if g:
            best_fit = max(g.items(), key=lambda x: float((x[1] or {}).get("persona_grade_percent", 0.0)))[0]
    item["persona_best_fit"] = best_fit or "Unknown"
    persona_summary = item.get("persona_consensus_summary", {}) if isinstance(item.get("persona_consensus_summary"), dict) else {}
    item["persona_disagreement_index"] = float(
        item.get("persona_disagreement_index", persona_summary.get("disagreement_index", 100.0)) or 100.0
    )
    consensus_grade_score = float(
        persona_summary.get("funnel_score_total", item.get("persona_weighted_grade", item.get("grade_percent", 0.0))) or 0.0
    )
    if consensus_grade_score >= 90:
        cgrade = "A"
    elif consensus_grade_score >= 80:
        cgrade = "B"
    elif consensus_grade_score >= 70:
        cgrade = "C"
    elif consensus_grade_score >= 60:
        cgrade = "D"
    else:
        cgrade = "F"
    item["persona_consensus_grade"] = cgrade
    return item


def _market_regime_snapshot():
    try:
        return REGIME_ENGINE.market_regime_snapshot()
    except Exception:
        return {"current_regime": "neutral", "regime_confidence": 50.0}


def _build_funnel_candidates(universe_symbols, buy_mode="balanced"):
    symbols = [str(s).upper() for s in (universe_symbols or []) if str(s).strip()]
    cap_map = dict(_UNIVERSE_RUNTIME.get("cap_map") or {})
    sector_map = dict(_UNIVERSE_RUNTIME.get("sector_map") or {})
    regime = _market_regime_snapshot()
    quote_map = {}
    rows = []
    try:
        rows = GUARDIAN_API.fetch_stock_batch(symbols) if symbols else []
    except Exception:
        rows = []
    if isinstance(rows, list):
        for r in rows:
            if not isinstance(r, dict):
                continue
            sym = str(r.get("symbol") or "").upper()
            if not sym:
                continue
            quote_map[sym] = {
                "price": r.get("price"),
                "prev_close": r.get("prev_close"),
                "provider_used": r.get("provider_used") or r.get("source") or "none",
                "provider_agreement": r.get("provider_agreement", 0.0),
                "quote_quality": r.get("quote_quality", "placeholder"),
                "data_unavailable_reason": r.get("data_unavailable_reason"),
            }
    for sym in symbols:
        quote_map.setdefault(
            sym,
            {
                "price": 0.0,
                "prev_close": None,
                "provider_used": "none",
                "provider_agreement": 0.0,
                "quote_quality": "placeholder",
                "data_unavailable_reason": "missing_funnel_quote",
            },
        )

    learning = _get_enriched_learning_insights_cached()
    weight_hints = (learning or {}).get("funnel_weight_hints", {})
    target = int(os.getenv("ASTRA_FUNNEL_CANDIDATE_TARGET", "50"))
    ranked = FUNNEL_ENGINE.rank_candidates(
        symbols=symbols,
        quote_map=quote_map,
        cap_map=cap_map,
        sector_map=sector_map,
        market_regime=regime,
        candidate_target=max(12, min(80, target)),
        learning_weights=weight_hints,
        learning_context=learning,
        trading_style=str(os.getenv("ASTRA_TRADING_STYLE", "swing")).strip().lower() or "swing",
        min_learning_samples=int((learning or {}).get("min_segment_samples", 25) or 25),
        buy_mode=str(buy_mode or "balanced").strip().lower() or "balanced",
    )
    candidate_symbols = ranked.get("candidate_symbols") or symbols
    scores_by_symbol = ranked.get("scores_by_symbol", {}) if isinstance(ranked.get("scores_by_symbol"), dict) else {}
    persona_rejections = {
        "not_buy_majority": 0,
        "weak_persona_consensus": 0,
        "high_persona_disagreement": 0,
    }
    persona_filtered = []
    for sym in candidate_symbols:
        hint = scores_by_symbol.get(str(sym or "").upper()) if isinstance(scores_by_symbol, dict) else {}
        summary = hint.get("persona_consensus_summary", {}) if isinstance(hint, dict) else {}
        grades = hint.get("persona_grades", {}) if isinstance(hint, dict) else {}
        consensus_strength = _to_float(summary.get("consensus_strength"), 0.0)
        disagreement = _to_float(summary.get("disagreement_index"), 100.0)
        buy_votes = 0
        total_votes = 0
        if isinstance(grades, dict):
            for g in grades.values():
                if not isinstance(g, dict):
                    continue
                total_votes += 1
                sig = str(g.get("persona_signal") or "").strip().lower()
                if sig == "buy":
                    buy_votes += 1
        majority_buy = bool(total_votes > 0 and buy_votes >= max(2, (total_votes // 2) + 1))
        if not majority_buy:
            persona_rejections["not_buy_majority"] += 1
            continue
        if consensus_strength < 55.0:
            persona_rejections["weak_persona_consensus"] += 1
            continue
        if disagreement > 45.0:
            persona_rejections["high_persona_disagreement"] += 1
            continue
        persona_filtered.append(sym)
    if persona_filtered:
        candidate_symbols = persona_filtered
    elif candidate_symbols:
        candidate_symbols = list(candidate_symbols[:12])
    _FUNNEL_RUNTIME["persona_rejection_counts"] = dict(persona_rejections)
    quoted_symbols = [
        sym for sym, q in quote_map.items()
        if _to_float((q or {}).get("price"), 0.0) > 0 and _to_float((q or {}).get("prev_close"), 0.0) > 0
    ]
    return {
        "candidate_symbols": candidate_symbols,
        "scores_by_symbol": scores_by_symbol,
        "rows_evaluated": int(ranked.get("rows_evaluated", len(symbols))),
        "candidate_count": int(len(candidate_symbols)),
        "quoted_count": int(len(quoted_symbols)),
        "quoted_symbols": quoted_symbols,
        "universe_cap_distribution": _cap_distribution(symbols, cap_map),
        "quoted_cap_distribution": _cap_distribution(quoted_symbols, cap_map),
        "scored_cap_distribution": _cap_distribution(symbols, cap_map),
        "candidate_cap_distribution": _cap_distribution(candidate_symbols, cap_map),
        "adaptive_weights_applied": (learning or {}).get("adaptive_weights", {}),
    }


