    def _finalize_trace_bucket(bucket):
        out = dict(bucket or {})
        stages = [
            "stage_0_symbols_input",
            "stage_1_quotes_fetched",
            "stage_2_quotes_normalized",
            "stage_3_pre_entry_pass",
            "stage_4_setup_detected",
            "stage_5_entry_quality_valid",
            "stage_6_context_activation_count",
            "stage_7_post_suppression",
            "stage_8_final_output",
        ]
        prev = int(_to_float(out.get("stage_0_symbols_input"), 0.0))
        for key in stages[1:]:
            cur = int(_to_float(out.get(key), 0.0))
            drop_count = max(0, prev - cur)
            out[f"{key}_drop_count"] = int(drop_count)
            out[f"{key}_drop_percent"] = round((float(drop_count) / max(1.0, float(prev))) * 100.0, 2)
            prev = cur
        out.pop("_providers_used", None)
        p = dict(((out.get("provider_usage_summary") or {})))
        p.pop("_providers_used", None)
        out["provider_usage_summary"] = p
        return out

    def _confidence_calibration_v2(
        row,
        *,
        base_adjustment_pct,
        entry_intelligence_penalty=0.0,
    ):
        r = dict(row or {})
        reasons = []
        penalty = 0.0
        support = 0.0

        entry_edge = _to_float(r.get("entry_edge_score"), _to_float(confidence_calibration.get("entry_edge_score"), 0.0))
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        uncertainty_score = _to_float(r.get("uncertainty_score"), 50.0)
        follow_quality = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(confidence_calibration.get("follow_through_entry_score"), 0.0),
        )
        released_vs_blocked = _to_float(
            confidence_calibration.get("released_vs_blocked_win_rate_delta"),
            _to_float(entry_conversion_feedback.get("released_vs_blocked_win_rate_delta"), 0.0),
        )
        execution_evidence = _to_float(
            confidence_calibration.get("execution_evidence_count"),
            _to_float(entry_conversion_feedback.get("execution_evidence_count"), 0.0),
        )
        confidence_truthfulness = _to_float(confidence_calibration.get("calibration_score"), 55.0)
        evidence_confidence = max(
            0.10,
            min(
                1.0,
                min(
                    _to_float(confidence_calibration.get("evidence_confidence"), 0.0) or 1.0,
                    _to_float(entry_conversion_feedback.get("evidence_confidence"), 0.0) or 1.0,
                ),
            ),
        )

        if entry_edge < 0.02:
            penalty += 1.05
            reasons.append("entry_edge_weak")
        elif entry_edge < 0.05:
            penalty += 0.50
            reasons.append("entry_edge_moderate")
        elif entry_edge >= 0.08:
            support += 0.28
            reasons.append("entry_edge_strong")

        if disagreement >= 52.0:
            penalty += 0.95
            reasons.append("persona_disagreement_high")
        elif disagreement >= 46.0:
            penalty += 0.35
            reasons.append("persona_disagreement_moderate")
        elif disagreement <= 36.0:
            support += 0.24
            reasons.append("persona_disagreement_low")

        if uncertainty_tier in {"extreme_uncertainty", "high_uncertainty"}:
            penalty += 1.25
            reasons.append("uncertainty_high")
        elif uncertainty_tier == "moderate_uncertainty" or uncertainty_score >= 58.0:
            penalty += 0.45
            reasons.append("uncertainty_moderate")
        elif uncertainty_score <= 36.0:
            support += 0.22
            reasons.append("uncertainty_low")

        if execution_evidence < 120.0 or evidence_confidence < 0.30:
            penalty += 0.70
            reasons.append("execution_evidence_weak")
        elif execution_evidence >= 320.0 and evidence_confidence >= 0.45:
            support += 0.20
            reasons.append("execution_evidence_strong")

        if released_vs_blocked < 0.0:
            penalty += 0.65
            reasons.append("released_vs_blocked_negative")
        elif released_vs_blocked >= 1.0:
            support += 0.20
            reasons.append("released_vs_blocked_positive")

        if confidence_truthfulness < 58.0:
            penalty += 0.65
            reasons.append("confidence_truthfulness_weak")
        elif confidence_truthfulness >= 70.0:
            support += 0.20
            reasons.append("confidence_truthfulness_supported")

        if follow_quality < 58.0:
            penalty += 0.30
            reasons.append("follow_through_weak")
        elif follow_quality >= 68.0:
            support += 0.18
            reasons.append("follow_through_strong")

        if entry_intelligence_penalty > 0.0:
            penalty += min(0.95, entry_intelligence_penalty * 0.12)
            reasons.append("entry_intelligence_penalty_applied")

        raw_adjustment = _to_float(base_adjustment_pct, 0.0) + support - penalty
        bounded_adjustment = max(-4.2, min(2.0, raw_adjustment))
        calibration_score = max(
            0.0,
            min(
                100.0,
                60.0
                + (bounded_adjustment * 10.0)
                + ((support - penalty) * 8.0)
                + ((evidence_confidence - 0.35) * 18.0),
            ),
        )
        return {
            "confidence_calibration_score": round(calibration_score, 2),
            "confidence_adjustment_pct": round(bounded_adjustment, 2),
            "calibration_reasons": list(dict.fromkeys(reasons)),
            "evidence_confidence": round(evidence_confidence, 4),
            "components": {
                "penalty": round(max(0.0, penalty), 3),
                "support": round(max(0.0, support), 3),
                "entry_edge_score": round(entry_edge, 4),
                "persona_disagreement_index": round(disagreement, 2),
                "uncertainty_score": round(uncertainty_score, 2),
                "released_vs_blocked_win_rate_delta": round(released_vs_blocked, 2),
                "execution_evidence_count": int(execution_evidence),
            },
        }

    def _context_intelligence_v1(row):
        r = dict(row or {})
        li = dict(learning_snapshot or {})
        policy = dict(li.get("policy_adaptation") or {})
        context_conf = dict(li.get("context_confidence_evidence") or {})
        contextual_hints = dict(li.get("contextual_policy_hints") or {})
        external_ctx = dict(li.get("external_context_classification") or {})
        follow_quality = dict(li.get("followthrough_quality") or {})

        reasons = []
        penalty = 0.0
        support = 0.0

        setup_key = str(r.get("setup_type") or "unknown").strip().lower()
        regime_key = str(r.get("regime_context") or r.get("market_regime") or "unknown").strip().lower()
        persona_key = str(r.get("persona_best_fit") or "unknown").strip().lower()
        cap_key = str(r.get("market_cap_category") or "unknown").strip().lower()

        context_conf_score = _to_float(
            context_conf.get("overall_confidence_score"),
            _to_float(policy.get("context_confidence_score"), 0.0),
        )
        execution_evidence = _to_float(
            policy.get("contextual_execution_evidence_count"),
            _to_float(context_conf.get("total_evidence_count"), 0.0),
        )
        evidence_confidence = max(
            0.10,
            min(
                1.0,
                max(
                    execution_evidence / 900.0,
                    _to_float(context_conf.get("overall_confidence_score"), 0.0) / 180.0,
                ),
            ),
        )

        def _ctx_mult(scope, key):
            hint = ((contextual_hints.get(scope) or {}).get(key) or {})
            return _to_float(hint.get("weighted_multiplier", hint.get("multiplier", 1.0)), 1.0)

        setup_regime_mult = _ctx_mult("setup_regime", f"{setup_key}|{regime_key}")
        persona_regime_mult = _ctx_mult("persona_regime", f"{persona_key}|{regime_key}")
        setup_cap_mult = _ctx_mult("setup_cap_bucket", f"{setup_key}|{cap_key}")

        if setup_regime_mult < 0.98:
            penalty += min(1.8, (1.0 - setup_regime_mult) * 16.0)
            reasons.append("setup_regime_context_weak")
        elif setup_regime_mult >= 1.03:
            support += min(1.2, (setup_regime_mult - 1.0) * 14.0)
            reasons.append("setup_regime_context_supportive")

        if persona_regime_mult < 0.98:
            penalty += min(1.4, (1.0 - persona_regime_mult) * 14.0)
            reasons.append("persona_regime_context_weak")
        elif persona_regime_mult >= 1.03:
            support += min(0.9, (persona_regime_mult - 1.0) * 12.0)
            reasons.append("persona_regime_context_supportive")

        if setup_cap_mult < 0.985:
            penalty += min(0.8, (1.0 - setup_cap_mult) * 10.0)
            reasons.append("setup_cap_context_weak")
        elif setup_cap_mult >= 1.02:
            support += min(0.5, (setup_cap_mult - 1.0) * 8.0)
            reasons.append("setup_cap_context_supportive")

        external_tier = str(external_ctx.get("external_environment_tier") or "caution").strip().lower()
        if external_tier == "hostile":
            penalty += 1.2
            reasons.append("external_context_hostile")
        elif external_tier == "favorable":
            support += 0.6
            reasons.append("external_context_favorable")

        follow_through_score = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(follow_quality.get("follow_through_entry_score"), 0.0),
        )
        if follow_through_score < 56.0 and context_conf_score < 50.0:
            penalty += 0.8
            reasons.append("follow_through_context_weak")
        elif follow_through_score >= 66.0 and context_conf_score >= 55.0:
            support += 0.6
            reasons.append("follow_through_context_supportive")

        if setup_key in {"fallback_unclear", "unclassified_setup"}:
            penalty += 1.0
            reasons.append("weak_setup_family")
            if regime_key in {"risk_off", "high_volatility", "range_high_vol", "mixed"}:
                penalty += 0.8
                reasons.append("weak_setup_in_unfavorable_regime")

        if context_conf_score < 40.0:
            penalty += 0.9
            reasons.append("context_confidence_low")
        elif context_conf_score >= 62.0:
            support += 0.5
            reasons.append("context_confidence_supported")

        if execution_evidence < 120.0:
            penalty += 0.7
            reasons.append("context_execution_evidence_weak")
        elif execution_evidence >= 280.0:
            support += 0.4
            reasons.append("context_execution_evidence_strong")

        context_score = max(
            0.0,
            min(
                100.0,
                55.0
                + ((context_conf_score - 50.0) * 0.20)
                + (support * 8.0)
                - (penalty * 9.0)
                + ((evidence_confidence - 0.35) * 16.0),
            ),
        )

        return {
            "context_intelligence_score": round(context_score, 2),
            "context_penalty": round(max(0.0, penalty), 3),
            "context_support": round(max(0.0, support), 3),
            "context_reasons": list(dict.fromkeys(reasons)),
            "context_evidence_confidence": round(evidence_confidence, 4),
        }

    def _context_activation_engine_v1(row, learning_context=None):
        r = dict(row or {})
        li = dict(learning_snapshot or {})
        hints = dict(li.get("contextual_policy_hints") or {})
        context_conf = dict(li.get("context_confidence_evidence") or {})
        segments = dict(li.get("segments") or {})
        by_setup = dict(segments.get("by_setup_type") or {})

        setup_key = str(r.get("detected_setup_type") or r.get("setup_type") or "fallback_unclear").strip().lower()
        regime_key = str(r.get("regime_context") or r.get("market_regime") or "unknown").strip().lower()
        persona_key = str(r.get("persona_best_fit") or "unknown").strip().lower()
        realness = str(r.get("setup_candidate_realness") or "fallback").strip().lower()
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        setup_score = _to_float(r.get("setup_detection_score"), 0.0)
        entry_quality = _to_float(r.get("entry_quality_score"), 0.0)
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        entry_class = str(r.get("entry_quality_candidate_class") or "fallback_recovery").strip().lower()
        entry_evidence = str(r.get("entry_quality_evidence_label") or "insufficient").strip().lower()
        conf_pct = _to_float(r.get("confidence_pct"), _to_float(r.get("confidence"), 0.0) * 100.0)
        trade_quality = _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        uncertainty_score = _to_float(r.get("uncertainty_score"), 50.0)
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        data_quality = _to_float(r.get("data_quality_score"), _to_float(r.get("provider_confidence"), 0.0) * 100.0)
        freshness = _to_float(r.get("freshness_seconds"), 9999.0)

        support = 0.0
        penalty = 0.0
        reasons = []
        penalties = []
        learning_used = False
        policy = "row_only_fallback"

        def _hint_mult(scope, key):
            hint = ((hints.get(scope) or {}).get(key) or {})
            return _to_float(hint.get("weighted_multiplier", hint.get("multiplier", 1.0)), 1.0)

        setup_regime_mult = _hint_mult("setup_regime", f"{setup_key}|{regime_key}")
        persona_regime_mult = _hint_mult("persona_regime", f"{persona_key}|{regime_key}")
        if setup_regime_mult != 1.0 or persona_regime_mult != 1.0:
            learning_used = True
            policy = "contextual_policy_hints"
        if setup_regime_mult >= 1.03:
            support += min(1.1, (setup_regime_mult - 1.0) * 14.0)
            reasons.append("learning_support_setup_regime")
        elif setup_regime_mult <= 0.98:
            penalty += min(1.4, (1.0 - setup_regime_mult) * 14.0)
            penalties.append("learning_weak_setup_regime")
        if persona_regime_mult >= 1.03:
            support += min(0.9, (persona_regime_mult - 1.0) * 12.0)
            reasons.append("learning_support_persona_regime")
        elif persona_regime_mult <= 0.98:
            penalty += min(1.1, (1.0 - persona_regime_mult) * 12.0)
            penalties.append("learning_weak_persona_regime")

        setup_stats = dict(by_setup.get(setup_key) or {})
        setup_trades = int(_to_float(setup_stats.get("trade_count"), 0.0))
        setup_wr = _to_float(setup_stats.get("win_rate"), 0.0)
        setup_usefulness = _to_float(setup_stats.get("setup_usefulness_score"), 0.0)
        if setup_trades >= 8:
            learning_used = True
            policy = "setup_history"
            reasons.append("setup_history_available")
            if setup_usefulness >= 60.0 and setup_wr >= 50.0:
                support += 1.0
                reasons.append("setup_family_supported")
            elif setup_usefulness <= 42.0 or setup_wr <= 38.0:
                penalty += 1.4
                penalties.append("setup_family_weak")

        mem = learning_context if isinstance(learning_context, dict) else {}
        mem_sample = int(_to_float(mem.get("memory_sample_size"), 0.0))
        mem_wr = _to_float(mem.get("memory_win_rate"), 0.0)
        mem_fast_loss = _to_float(mem.get("memory_fast_loss_rate"), 0.0)
        mem_expectancy = _to_float(mem.get("memory_expectancy"), 0.0)
        mem_verdict = str(mem.get("memory_verdict") or "").strip().lower()
        if mem_sample > 0:
            learning_used = True
            policy = "setup_memory_index"
            reasons.append("memory_context_available")
            if mem_verdict == "similar_winner_bias" and mem_sample >= 20:
                support += 1.1
                reasons.append("memory_winner_bias_support")
            elif mem_verdict == "similar_loser_risk":
                penalty += 1.5
                penalties.append("memory_loser_risk_penalty")
            if mem_fast_loss >= 9.0:
                penalty += 0.8
                penalties.append("memory_fast_loss_elevated")
            elif mem_expectancy >= 0.12 and mem_wr >= 50.0:
                support += 0.6
                reasons.append("memory_expectancy_support")

        context_conf_score = _to_float(context_conf.get("overall_confidence_score"), 0.0)
        if context_conf_score >= 58.0:
            support += 0.6
            reasons.append("context_confidence_supported")
        elif context_conf_score < 40.0:
            penalty += 0.8
            penalties.append("context_confidence_low")

        if realness in {"fallback", "degraded"}:
            penalty += 2.8
            penalties.append("fallback_or_degraded_candidate")
        elif realness == "thin_real":
            penalty += 0.9
            penalties.append("thin_real_candidate")
            reasons.append("thin_real_candidate")
        elif realness == "strong_real":
            support += 1.0
            reasons.append("strong_real_candidate")
        else:
            support += 0.5
            reasons.append("real_candidate_detected")

        if setup_key in {"fallback_unclear", "unclassified_setup", "range_or_no_edge"}:
            penalty += 1.6
            penalties.append("weak_setup_family")
        elif setup_key in {"momentum_breakout", "trend_continuation", "reclaim_setup"} and setup_score >= 60.0:
            support += 0.7
            reasons.append("setup_type_supportive")

        if entry_band == "strong" or entry_band == "elite":
            support += 1.2
            reasons.append("entry_quality_strong")
        elif entry_band == "moderate":
            support += 0.2
            reasons.append("entry_quality_moderate")
        elif entry_band == "weak":
            penalty += 1.1
            penalties.append("entry_quality_weak")
        else:
            penalty += 2.0
            penalties.append("entry_quality_poor")

        if entry_class in {"fallback_recovery", "degraded_candidate"}:
            penalty += 1.3
            penalties.append("entry_quality_class_degraded")
        elif entry_class in {"strong_candidate", "real_candidate"}:
            support += 0.6
            reasons.append("entry_quality_class_real")

        if entry_evidence == "aligned":
            support += 0.4
            reasons.append("entry_evidence_aligned")
        elif entry_evidence == "strongly_aligned":
            support += 0.7
            reasons.append("entry_evidence_strongly_aligned")
        elif entry_evidence == "thin_but_coherent":
            penalty += 0.3
            reasons.append("entry_evidence_thin_but_coherent")
        elif entry_evidence == "insufficient":
            penalty += 1.0
            penalties.append("entry_evidence_insufficient")
        elif entry_evidence == "mixed":
            penalty += 0.6
            penalties.append("entry_evidence_mixed")

        if disagreement >= 52.0:
            penalty += 1.4
            penalties.append("persona_disagreement_high")
        elif disagreement <= 38.0:
            support += 0.5
            reasons.append("persona_disagreement_low")
        if uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"} or uncertainty_score >= 66.0:
            penalty += 2.2
            penalties.append("uncertainty_high")
        elif uncertainty_tier == "moderate_uncertainty" or uncertainty_score >= 55.0:
            penalty += 0.9
            penalties.append("uncertainty_moderate")
        else:
            support += 0.4
            reasons.append("uncertainty_low")

        if data_quality > 0.0 and data_quality < 42.0:
            penalty += 0.9
            penalties.append("quote_data_quality_low")
        if freshness > 360.0 and freshness < 9999.0:
            penalty += 0.7
            penalties.append("quote_data_stale")

        raw_score = (
            42.0
            + (setup_score * 0.24)
            + (entry_quality * 0.30)
            + (trade_quality * 0.12)
            + (conf_pct * 0.08)
            + (support * 7.0)
            - (penalty * 8.0)
        )
        activation_score = max(0.0, min(100.0, raw_score))

        if activation_score >= 84.0:
            band = "elite"
        elif activation_score >= 70.0:
            band = "strong"
        elif activation_score >= 56.0:
            band = "moderate"
        elif activation_score >= 40.0:
            band = "weak"
        else:
            band = "poor"

        evidence_label = "insufficient"
        if learning_used and (setup_trades >= 8 or mem_sample >= 8):
            evidence_label = "contextual"
        elif entry_evidence in {"thin_but_coherent", "aligned", "strongly_aligned"}:
            evidence_label = "row_coherent"
        elif entry_evidence == "mixed":
            evidence_label = "mixed"

        decision = "watchlist"
        if (
            realness in {"fallback", "degraded"}
            or entry_band == "poor"
            or activation_score < 34.0
            or uncertainty_tier == "extreme_uncertainty"
        ):
            decision = "block"
        elif activation_score < 45.0:
            decision = "observe_only"
        elif activation_score < 60.0:
            decision = "watchlist"
        elif activation_score < 74.0:
            decision = "confirmation_required"
        else:
            decision = "paper_ready_candidate"

        # Low-data safeguard: only allow paper-ready when setup is real enough and learning support exists.
        if decision == "paper_ready_candidate":
            has_learning_support = (
                learning_used
                and (support - penalty) >= 0.15
                and (setup_trades >= 8 or mem_sample >= 8 or setup_regime_mult >= 1.03 or persona_regime_mult >= 1.03)
            )
            if (
                realness not in {"real", "strong_real"}
                or entry_band not in {"moderate", "strong", "elite"}
                or entry_quality < 58.0
                or disagreement > 46.0
                or uncertainty_tier in {"moderate_uncertainty", "high_uncertainty", "extreme_uncertainty"}
                or not has_learning_support
            ):
                decision = "confirmation_required" if activation_score >= 62.0 else "watchlist"
                penalties.append("paper_ready_requires_stronger_context")

        if decision in {"block", "observe_only"}:
            policy_out = "suppress"
        elif decision == "watchlist":
            policy_out = "watchlist"
        elif decision == "confirmation_required":
            policy_out = "confirm"
        else:
            policy_out = "paper_safe_candidate"

        return {
            "context_activation_score": round(activation_score, 2),
            "context_activation_band": str(band),
            "context_activation_decision": str(decision),
            "context_activation_reasons": list(dict.fromkeys(reasons))[:12],
            "context_activation_penalties": list(dict.fromkeys(penalties))[:12],
            "context_activation_evidence_label": str(evidence_label),
            "context_activation_learning_used": bool(learning_used),
            "context_activation_policy": str(policy_out),
        }

    def _historical_replay_policy_influence_v1(row, policy_review=None):
        r = dict(row or {})
        pr = dict(policy_review or {})
        setup_key = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower() or "unknown"
        setup_score = _to_float(r.get("setup_detection_score"), 0.0)
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        realness = str(r.get("setup_candidate_realness") or "fallback").strip().lower()
        entry_quality = _to_float(r.get("entry_quality_score"), 0.0)
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        conf_pct = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
        conf_pct = conf_pct * 100.0 if conf_pct <= 1.0 else conf_pct
        trade_quality = _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))
        data_quality = _to_float(r.get("data_quality_score"), _to_float(r.get("provider_confidence"), 0.0) * 100.0)
        quote_valid = bool(_to_float(r.get("price"), 0.0) > 0.0 and (bool(r.get("valid_quote", False)) or bool(r.get("trusted_quote_for_buys", False))))
        policy_items = list(pr.get("recommended_setup_policies") or [])
        policy_map = {}
        for item in policy_items:
            if not isinstance(item, dict):
                continue
            k = str(item.get("setup_type") or "").strip().lower()
            if k:
                policy_map[k] = dict(item)
        policy_item = dict(policy_map.get(setup_key) or {})
        policy_class = str(policy_item.get("policy") or "").strip().lower()
        policy_strength = _to_float(policy_item.get("policy_strength_score"), 0.0)
        replay_conf = str(pr.get("replay_confidence") or "not_available").strip().lower()
        replay_weight = 1.0 if replay_conf == "moderate" else (0.65 if replay_conf in {"limited", "low"} else 0.50)

        support = 0.0
        penalty = 0.0
        reasons = []
        penalties = []
        action_hint = "allow_normal_review"
        label = "neutral"
        used = bool(policy_item)

        if policy_class == "favor":
            support += 4.0
            reasons.append("historical_replay_favors_setup_family")
            label = "supportive"
            action_hint = "allow_normal_review"
        elif policy_class == "allow":
            support += 2.0
            reasons.append("historical_replay_allows_setup_family")
            label = "supportive"
            action_hint = "allow_normal_review"
        elif policy_class == "confirmation_required":
            penalty += 2.5
            penalties.append("historical_replay_requires_confirmation")
            label = "confirmation_required"
            action_hint = "require_confirmation"
        elif policy_class == "paper_only":
            penalty += 5.0
            penalties.append("historical_replay_paper_only")
            label = "caution"
            action_hint = "paper_only"
        elif policy_class == "avoid":
            penalty += 8.0
            penalties.append("historical_replay_avoid_setup_family")
            label = "avoid"
            action_hint = "avoid_for_now"

        if setup_key == "squeeze_breakout":
            penalty += 1.2
            penalties.append("squeeze_breakout_confirmation_bias")
            if action_hint == "allow_normal_review":
                action_hint = "require_confirmation"
                label = "confirmation_required"
        if setup_key in {"range_rotation", "trend_continuation"}:
            penalty += 2.0
            penalties.append("historical_weak_setup_family")
            action_hint = "avoid_for_now"
            label = "avoid"
        if setup_key in {"fallback_unclear", "unclassified_setup"}:
            penalty += 2.8
            penalties.append("fallback_family_paper_monitor_only")
            if action_hint != "avoid_for_now":
                action_hint = "paper_only"
            label = "caution" if label != "avoid" else label

        if setup_band in {"strong", "elite"} and entry_band in {"strong", "elite"} and entry_quality >= 72.0 and setup_score >= 70.0:
            support += 1.3
            reasons.append("current_setup_entry_quality_aligns")
        elif setup_band in {"poor", "weak"} or entry_band in {"poor", "weak"}:
            penalty += 1.9
            penalties.append("current_setup_or_entry_quality_weak")
            if action_hint == "allow_normal_review":
                action_hint = "require_confirmation"
                label = "caution"

        if realness in {"fallback", "degraded"}:
            penalty += 2.2
            penalties.append("candidate_realness_degraded")
            if action_hint in {"allow_normal_review", "require_confirmation"}:
                action_hint = "monitor_only"
                label = "caution"
        elif realness == "thin_real":
            penalty += 0.8
            penalties.append("candidate_realness_thin")

        if context_decision in {"block", "observe_only"}:
            penalty += 2.4
            penalties.append("context_activation_restrictive")
            if action_hint != "avoid_for_now":
                action_hint = "monitor_only"
            label = "caution" if label != "avoid" else label

        if not quote_valid or data_quality < 38.0:
            penalty += 1.8
            penalties.append("quote_or_data_quality_not_ready")
            if action_hint in {"allow_normal_review", "require_confirmation"}:
                action_hint = "require_confirmation"
                label = "caution" if label != "avoid" else label
        if conf_pct >= 76.0 and trade_quality >= 66.0 and quote_valid:
            support += 0.8
            reasons.append("current_confidence_trade_quality_supportive")
        elif conf_pct < 62.0 or trade_quality < 56.0:
            penalty += 1.2
            penalties.append("current_confidence_trade_quality_weak")

        net = (support - penalty) * replay_weight
        influence_score = max(-12.0, min(5.0, net))
        if action_hint == "avoid_for_now":
            influence_label = "avoid"
        elif action_hint == "require_confirmation":
            influence_label = "confirmation_required"
        elif action_hint in {"paper_only", "monitor_only"}:
            influence_label = "caution"
        elif influence_score > 0.75:
            influence_label = "supportive"
        elif influence_score < -2.0:
            influence_label = "caution"
        else:
            influence_label = "neutral"

        evidence_conf = max(
            0.10,
            min(
                1.0,
                ((_to_float(policy_item.get("sample_count"), 0.0) / 1200.0) * 0.50)
                + ((policy_strength / 100.0) * 0.35)
                + ((1.0 if replay_conf == "moderate" else 0.6) * 0.15),
            ),
        ) if used else 0.10

        return {
            "historical_policy_influence_score": round(influence_score, 3),
            "historical_policy_influence_label": str(influence_label),
            "historical_policy_action_hint": str(action_hint),
            "historical_policy_reasons": list(dict.fromkeys(reasons))[:10],
            "historical_policy_penalties": list(dict.fromkeys(penalties))[:10],
            "historical_policy_used": bool(used),
            "historical_policy_enforcement_mode": "bounded_influence_v1",
            "historical_policy_influence_confidence": round(evidence_conf, 4),
            "historical_policy_replay_confidence": str(replay_conf or "not_available"),
            "historical_policy_setup_policy": str(policy_class or "none"),
            "historical_policy_setup_strength": round(policy_strength, 2),
        }

    def _replay_learning_influence_v1(row, replay_context=None):
        r = dict(row or {})
        rc = dict(replay_context or {})
        reasons = []
        penalties = []
        supportive = 0.0
        negative = 0.0

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_score = _to_float(r.get("setup_detection_score"), 0.0)
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_quality = _to_float(r.get("entry_quality_score"), 0.0)
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        signal_penalties = list(r.get("signal_quality_penalties") or [])
        timing_decision = str(r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
        learning_decision = str(r.get("learning_activation_decision") or "neutral").strip().lower()
        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        limited_data_mode = bool(r.get("limited_data_mode", False))

        replay_conf = str(
            rc.get("replay_confidence")
            or r.get("historical_policy_replay_confidence")
            or "not_available"
        ).strip().lower()
        policy_items = list(rc.get("recommended_setup_policies") or [])
        policy_map = {}
        for item in policy_items:
            if not isinstance(item, dict):
                continue
            k = str(item.get("setup_type") or "").strip().lower()
            if k:
                policy_map[k] = dict(item)
        policy_item = dict(policy_map.get(setup_type) or {})
        if not policy_item and str(r.get("historical_policy_setup_policy") or "none").strip().lower() != "none":
            policy_item = {
                "policy": str(r.get("historical_policy_setup_policy") or "none"),
                "policy_strength_score": _to_float(r.get("historical_policy_setup_strength"), 0.0),
                "sample_count": _to_float(r.get("historical_policy_sample_count"), 0.0),
            }

        policy_class = str(policy_item.get("policy") or "none").strip().lower()
        policy_strength = _to_float(
            policy_item.get("policy_strength_score"),
            _to_float(r.get("historical_policy_setup_strength"), 0.0),
        )
        sample_count = _to_float(policy_item.get("sample_count"), 0.0)
        if sample_count <= 0.0:
            sample_count = _to_float(r.get("historical_policy_sample_count"), 0.0)

        non_data_reject = bool(
            signal_decision == "reject"
            and any(
                not any(tok in str(p).lower() for tok in ("missing_", "history", "stale_quote", "enriched_signal_not_ready"))
                for p in signal_penalties
            )
        )
        hard_reject = bool(
            (not trusted_quote)
            or (not valid_quote)
            or (setup_band == "poor")
            or (entry_band == "poor")
            or non_data_reject
            or (majority_signal in {"avoid", "sell", "strong sell"} and disagreement >= 52.0)
            or (
                timing_decision == "avoid_for_now"
                and policy_class not in {"favor", "allow"}
            )
        )

        if policy_class in {"favor", "allow"}:
            supportive += 2.2 if policy_class == "favor" else 1.2
            reasons.append("replay_supports_setup_family")
        elif policy_class == "confirmation_required":
            reasons.append("replay_requires_confirmation")
            negative += 0.5
        elif policy_class in {"paper_only", "avoid"}:
            negative += 2.3 if policy_class == "paper_only" else 3.2
            penalties.append("replay_flags_setup_weak")

        if setup_type in {"range_rotation", "trend_continuation", "fallback_unclear"}:
            negative += 1.4
            penalties.append("historically_weak_setup_family")
        elif setup_type == "momentum_breakout":
            supportive += 1.1
            reasons.append("historically_supported_setup_family")
        elif setup_type == "squeeze_breakout":
            negative += 0.4
            penalties.append("squeeze_requires_confirmation")

        if setup_band in {"strong", "elite"} and entry_band in {"moderate", "strong", "elite"}:
            supportive += 1.0
            reasons.append("current_setup_entry_alignment")
        elif setup_band in {"weak", "poor"} or entry_band in {"weak", "poor"}:
            negative += 1.0
            penalties.append("current_evidence_weak")

        if timing_decision in {"avoid_for_now", "avoid_chase"}:
            negative += 1.0
            penalties.append("timing_avoid_state")
        elif timing_decision in {"wait_for_confirmation", "wait_for_pullback"}:
            negative += 0.3
        else:
            supportive += 0.3

        if signal_decision == "allow":
            supportive += 0.6
        elif signal_decision in {"watchlist_only", "monitor_only"}:
            negative += 0.5
        elif signal_decision == "reject":
            negative += 0.8

        if replay_conf == "moderate":
            conf_weight = 1.0
        elif replay_conf in {"limited", "low"}:
            conf_weight = 0.72
        else:
            conf_weight = 0.50
        evidence_ratio = min(1.0, max(0.0, sample_count / 400.0)) if sample_count > 0 else 0.0
        evidence_conf = max(
            0.10,
            min(
                1.0,
                (conf_weight * 0.55)
                + ((policy_strength / 100.0) * 0.30)
                + (evidence_ratio * 0.15),
            ),
        )

        if hard_reject:
            supportive = 0.0
            reasons.append("replay_support_blocked_by_safety_gate")

        raw = (supportive - negative) * (0.75 + (evidence_conf * 0.25))
        score = max(-5.0, min(5.0, raw))

        if not policy_item and str(policy_class or "none") == "none":
            alignment = "insufficient"
        elif score >= 1.0:
            alignment = "supportive"
        elif score <= -1.0:
            alignment = "negative"
        else:
            alignment = "neutral"

        entry_base = _to_float(
            r.get("entry_score_learning_adjusted"),
            _to_float(r.get("entry_score_signal_quality_adjusted"), _to_float(r.get("entry_score_timing_adjusted"), 0.0)),
        )
        entry_score_replay_adjusted = max(0.0, min(100.0, entry_base + score))

        signal_adjusted = False
        signal_original_decision = str(signal_decision or "unknown")
        signal_decision_out = str(signal_decision or "monitor_only")
        if (
            score >= 2.0
            and alignment == "supportive"
            and trusted_quote
            and valid_quote
            and setup_band not in {"poor"}
            and entry_band not in {"poor"}
            and not hard_reject
            and signal_decision == "reject"
            and (limited_data_mode or not non_data_reject)
        ):
            if timing_decision in {"avoid_for_now", "avoid_chase"}:
                signal_decision_out = "watchlist_only"
            else:
                signal_decision_out = "allow_with_confirmation"
            signal_adjusted = True
            reasons.append("replay_softens_signal_reject")

        learning_adjusted = False
        learning_original_decision = str(learning_decision or "neutral")
        learning_decision_out = str(learning_decision or "neutral")
        if (
            score >= 3.0
            and alignment == "supportive"
            and setup_band not in {"poor"}
            and entry_band not in {"poor"}
            and signal_decision_out not in {"reject", "monitor_only"}
            and timing_decision not in {"avoid_for_now"}
        ):
            if learning_decision_out == "suppress":
                learning_decision_out = "caution"
                learning_adjusted = True
            elif learning_decision_out == "caution" and score >= 4.0:
                learning_decision_out = "neutral"
                learning_adjusted = True
            if learning_adjusted:
                reasons.append("replay_reduces_over_suppression")

        if alignment == "negative" and learning_decision_out == "neutral" and score <= -3.0:
            learning_decision_out = "caution"
            penalties.append("replay_negative_context")

        replay_context_available = bool(
            policy_item
            or list(rc.get("recommended_setup_policies") or [])
            or replay_conf not in {"", "not_available", "none"}
        )

        return {
            "replay_influence_applied": bool(replay_context_available and abs(score) >= 0.01),
            "replay_influence_score": round(score, 3),
            "replay_alignment": str(alignment),
            "replay_confidence": round(evidence_conf, 4),
            "replay_reason": _safe_text("; ".join(list(dict.fromkeys(reasons))[:3]), 220),
            "replay_penalties": list(dict.fromkeys(penalties))[:10],
            "entry_score_replay_adjusted": round(entry_score_replay_adjusted, 2),
            "signal_quality_replay_adjusted": bool(signal_adjusted),
            "signal_quality_original_decision": str(signal_original_decision),
            "signal_quality_replay_decision": str(signal_decision_out),
            "learning_activation_replay_adjusted": bool(learning_adjusted),
            "learning_activation_original_decision": str(learning_original_decision),
            "learning_activation_replay_decision": str(learning_decision_out),
        }

    def _entry_timing_engine_v1(row, historical_policy_review=None):
        r = dict(row or {})
        _ = historical_policy_review  # reserved for future policy payload detail use
        reasons = []
        penalties = []
        score = 50.0

        def _pct_like(value, fallback=0.0):
            v = _to_float(value, fallback)
            if v is None:
                return fallback
            if abs(v) <= 1.0:
                return v * 100.0
            return v

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_score = max(0.0, min(100.0, _to_float(r.get("setup_detection_score"), 0.0)))
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        realness = str(r.get("setup_candidate_realness") or "fallback").strip().lower()
        entry_quality = max(0.0, min(100.0, _to_float(r.get("entry_quality_score"), 0.0)))
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        historical_hint = str(r.get("historical_policy_action_hint") or "allow_normal_review").strip().lower()
        historical_label = str(r.get("historical_policy_influence_label") or "neutral").strip().lower()
        historical_used = bool(r.get("historical_policy_used", False))

        price = _to_float(r.get("price"), _to_float(r.get("current_price"), 0.0))
        day_open = _to_float(r.get("open"), _to_float(r.get("day_open"), None))
        day_high = _to_float(r.get("high"), _to_float(r.get("day_high"), None))
        day_low = _to_float(r.get("low"), _to_float(r.get("day_low"), None))
        change_pct = _pct_like(r.get("change_percent"), 0.0)
        volume = _to_float(r.get("volume"), 0.0)
        prev_close = _to_float(r.get("previous_close"), 0.0)
        quote_quality = _pct_like(r.get("quote_quality"), _pct_like(r.get("quote_confidence"), 55.0))
        provider_conf = _pct_like(r.get("provider_confidence"), 55.0)
        data_quality = _pct_like(r.get("data_quality_score"), provider_conf)
        enriched_signal_ready = bool(r.get("enriched_signal_ready", False))
        signal_limitations = str(r.get("enriched_signal_limitations") or "").strip().lower()

        near_high_ratio = None
        if price > 0.0 and day_high is not None and day_low is not None and day_high > day_low:
            near_high_ratio = (price - day_low) / max(0.01, (day_high - day_low))
        extension_score = 0.0
        if change_pct >= 4.0:
            extension_score += 45.0
            penalties.append("change_percent_extended")
        elif change_pct >= 2.5:
            extension_score += 25.0
            penalties.append("change_percent_elevated")
        if near_high_ratio is not None:
            if near_high_ratio >= 0.90:
                extension_score += 40.0
                penalties.append("price_near_day_high")
            elif near_high_ratio >= 0.82:
                extension_score += 20.0
                penalties.append("price_upper_range_entry")
        if volume <= 0.0 and (change_pct >= 2.0 or (near_high_ratio is not None and near_high_ratio >= 0.82)):
            extension_score += 15.0
            penalties.append("extended_move_without_volume_confirmation")
        chase_risk = max(0.0, min(100.0, extension_score))

        if setup_band in {"strong", "elite"}:
            score += 9.0
            reasons.append("setup_structure_supportive")
        elif setup_band == "moderate":
            score += 4.0
            reasons.append("setup_structure_plausible")
        else:
            score -= 10.0
            penalties.append("setup_structure_weak")

        if entry_band in {"strong", "elite"}:
            score += 10.0
            reasons.append("entry_quality_strong")
        elif entry_band == "moderate":
            score += 4.0
            reasons.append("entry_quality_moderate")
        elif entry_band == "weak":
            score -= 6.0
            penalties.append("entry_quality_weak")
        else:
            score -= 14.0
            penalties.append("entry_quality_poor")

        if context_decision in {"block", "observe_only"}:
            score -= 18.0
            penalties.append("context_activation_restrictive")
        elif context_decision == "watchlist":
            score -= 10.0
            penalties.append("context_activation_watchlist")
        elif context_decision == "confirmation_required":
            score -= 4.0
            reasons.append("context_requires_confirmation")
        elif context_decision == "paper_ready_candidate":
            score += 4.0
            reasons.append("context_supports_paper_candidate")

        if historical_hint == "avoid_for_now":
            score -= 14.0
            penalties.append("historical_policy_avoid")
        elif historical_hint == "paper_only":
            score -= 8.0
            penalties.append("historical_policy_paper_only")
        elif historical_hint == "require_confirmation":
            score -= 5.0
            penalties.append("historical_policy_confirmation_required")
        elif historical_hint == "allow_normal_review":
            if historical_label == "supportive":
                score += 3.0
                reasons.append("historical_policy_supportive")
            elif historical_label == "caution":
                score -= 2.0
                penalties.append("historical_policy_caution")

        if setup_type in {"range_rotation", "trend_continuation"}:
            score -= 6.0
            penalties.append("historical_weak_setup_family")
        elif setup_type == "squeeze_breakout":
            score -= 3.0
            penalties.append("squeeze_requires_confirmation")
        elif setup_type == "momentum_breakout" and setup_score >= 66.0 and entry_quality >= 60.0:
            score += 3.5
            reasons.append("favored_setup_with_current_alignment")

        if realness in {"fallback", "degraded"}:
            score -= 16.0
            penalties.append("candidate_realness_degraded")
        elif realness == "thin_real":
            score -= 4.0
            penalties.append("candidate_realness_thin")
        else:
            score += 2.0
            reasons.append("candidate_realness_supported")

        if price <= 0.0 or (prev_close <= 0.0 and day_open is None):
            score -= 12.0
            penalties.append("insufficient_quote_quality")
        if data_quality < 40.0 or quote_quality < 40.0:
            score -= 10.0
            penalties.append("data_quality_degraded")
        elif data_quality >= 58.0 and quote_quality >= 58.0:
            score += 3.0
            reasons.append("data_quality_supportive")
        if not enriched_signal_ready:
            score -= 4.0
            penalties.append("enriched_signal_not_ready")
        if signal_limitations:
            score -= 2.0
            penalties.append("signal_limitations_present")

        score -= (chase_risk * 0.12)
        if chase_risk >= 62.0:
            penalties.append("chase_risk_elevated")
        if chase_risk <= 28.0 and entry_band in {"moderate", "strong", "elite"}:
            reasons.append("entry_location_not_chasing")
            score += 2.0

        score = max(0.0, min(100.0, score))
        if score >= 78.0:
            band = "elite"
        elif score >= 66.0:
            band = "strong"
        elif score >= 52.0:
            band = "moderate"
        elif score >= 40.0:
            band = "weak"
        else:
            band = "poor"

        confirmation_required = False
        decision = "wait_for_confirmation"
        if (
            context_decision in {"block", "observe_only"}
            or realness in {"fallback", "degraded"}
            or entry_band == "poor"
            or historical_hint in {"avoid_for_now", "monitor_only"}
            or score < 36.0
        ):
            decision = "avoid_for_now"
        elif chase_risk >= 72.0 and (entry_quality < 74.0 or setup_score < 72.0):
            decision = "avoid_chase"
        elif chase_risk >= 52.0:
            decision = "wait_for_pullback"
        elif (
            historical_hint in {"require_confirmation", "paper_only"}
            or setup_type == "squeeze_breakout"
            or entry_band in {"weak", "moderate"}
            or context_decision in {"watchlist", "confirmation_required"}
            or data_quality < 52.0
            or quote_quality < 52.0
        ):
            decision = "wait_for_confirmation"
            confirmation_required = True
        elif (
            setup_type == "momentum_breakout"
            and setup_band in {"strong", "elite"}
            and entry_band in {"moderate", "strong", "elite"}
            and context_decision == "paper_ready_candidate"
            and historical_hint == "allow_normal_review"
            and chase_risk <= 35.0
            and data_quality >= 56.0
            and quote_quality >= 56.0
            and score >= 70.0
        ):
            decision = "immediate"
        else:
            decision = "wait_for_confirmation"
            confirmation_required = True

        if decision == "wait_for_confirmation":
            confirmation_required = True
        policy = "bounded_timing_v1"
        if historical_used and historical_hint in {"require_confirmation", "paper_only", "avoid_for_now"}:
            policy = f"bounded_timing_v1:{historical_hint}"
        evidence_components = 0
        evidence_components += 1 if price > 0.0 else 0
        evidence_components += 1 if prev_close > 0.0 else 0
        evidence_components += 1 if day_high is not None and day_low is not None and day_high > day_low else 0
        evidence_components += 1 if volume > 0.0 else 0
        evidence_components += 1 if data_quality >= 45.0 else 0
        evidence_components += 1 if quote_quality >= 45.0 else 0
        timing_confidence = max(0.12, min(1.0, (evidence_components / 6.0) * 0.7 + (score / 100.0) * 0.3))

        return {
            "entry_timing_decision": str(decision),
            "entry_timing_score": round(score, 2),
            "entry_timing_band": str(band),
            "entry_timing_reasons": list(dict.fromkeys(reasons))[:12],
            "entry_timing_penalties": list(dict.fromkeys(penalties))[:12],
            "entry_timing_policy": str(policy),
            "entry_timing_confidence": round(timing_confidence, 4),
            "entry_timing_historical_policy_used": bool(historical_used),
            "entry_timing_chase_risk": round(chase_risk, 2),
            "entry_timing_confirmation_required": bool(confirmation_required),
        }

    def _signal_quality_selectivity_engine_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []
        support = 0.0
        conflict = 0.0
        missing_evidence_count = 0

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_score = max(0.0, min(100.0, _to_float(r.get("setup_detection_score"), 0.0)))
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        realness = str(r.get("setup_candidate_realness") or "fallback").strip().lower()
        entry_quality = max(0.0, min(100.0, _to_float(r.get("entry_quality_score"), 0.0)))
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        historical_label = str(r.get("historical_policy_influence_label") or "neutral").strip().lower()
        historical_hint = str(r.get("historical_policy_action_hint") or "allow_normal_review").strip().lower()
        entry_timing_decision = str(r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
        entry_timing_score = max(0.0, min(100.0, _to_float(r.get("entry_timing_score"), 0.0)))
        chase_risk = max(0.0, min(100.0, _to_float(r.get("entry_timing_chase_risk"), 0.0)))
        conf_pct = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
        conf_pct = conf_pct * 100.0 if conf_pct <= 1.0 else conf_pct
        grade_pct = max(0.0, min(100.0, _to_float(r.get("grade_percent"), 0.0)))
        trade_quality = max(0.0, min(100.0, _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))))
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        consensus = _to_float(r.get("consensus_strength"), 50.0)

        valid_quote = bool(r.get("valid_quote", False))
        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        price = _to_float(r.get("price"), 0.0)
        prev_close = _to_float(r.get("previous_close"), 0.0)
        volume = _to_float(r.get("volume"), 0.0)
        quote_quality = _to_float(r.get("quote_quality"), _to_float(r.get("quote_confidence"), 55.0))
        provider_conf = _to_float(r.get("provider_confidence"), 55.0)
        data_quality = _to_float(r.get("data_quality_score"), provider_conf)
        enriched_signal_ready = bool(r.get("enriched_signal_ready", False))
        signal_limitations = str(r.get("enriched_signal_limitations") or "").strip().lower()
        history_source = str(r.get("history_source") or r.get("enriched_history_source") or "").strip().lower()
        fmp_mode = str(os.getenv("ASTRA_FMP_MODE", "conserve")).strip().lower()

        missing_volume_flag = bool(volume <= 0.0)
        missing_history_flag = bool(not history_source)
        missing_enriched_flag = bool(not enriched_signal_ready)
        stale_quote_flag = bool("stale_quote_timestamp" in signal_limitations)
        missing_limitations_flag = any(
            tok in signal_limitations
            for tok in ("missing_volume", "missing_history", "history_unavailable", "stale_quote_timestamp")
        )
        fmp_limited_env = bool(fmp_mode in {"conserve", "paused", "offline", "off", "quota_exhausted"})
        limited_data_mode = bool(
            trusted_quote
            and valid_quote
            and price > 0.0
            and data_quality >= 45.0
            and quote_quality >= 45.0
            and (missing_volume_flag or missing_history_flag or missing_enriched_flag or stale_quote_flag)
            and (fmp_limited_env or missing_limitations_flag)
        )
        limited_data_reason_parts = []
        if missing_volume_flag:
            limited_data_reason_parts.append("missing_volume")
        if missing_history_flag:
            limited_data_reason_parts.append("missing_history_source")
        if missing_enriched_flag:
            limited_data_reason_parts.append("enriched_signal_not_ready")
        if stale_quote_flag:
            limited_data_reason_parts.append("stale_quote_timestamp")
        limited_data_reason = (
            ",".join(limited_data_reason_parts[:4])
            if limited_data_mode
            else ""
        )
        limited_data_penalty_weight = 0.45 if limited_data_mode else 1.0

        if realness in {"real", "strong_real"}:
            support += 1.4
            reasons.append("candidate_realness_supported")
        elif realness == "thin_real":
            support += 0.4
            conflict += 0.8
            reasons.append("candidate_realness_thin")
            penalties.append("candidate_realness_thin")
        else:
            conflict += 2.0
            penalties.append("candidate_realness_degraded")

        if setup_band in {"moderate", "strong", "elite"} and setup_score >= 56.0:
            support += 1.0
            reasons.append("setup_detection_supportive")
        else:
            conflict += 1.2
            penalties.append("setup_detection_weak")

        if entry_band in {"moderate", "strong", "elite"} and entry_quality >= 56.0:
            support += 1.2
            reasons.append("entry_quality_supportive")
        else:
            conflict += 1.6
            penalties.append("entry_quality_weak")

        if entry_timing_decision in {"immediate", "wait_for_confirmation"}:
            support += 0.7
            reasons.append("timing_not_avoid")
        elif entry_timing_decision in {"wait_for_pullback"}:
            conflict += 0.9
            penalties.append("timing_wait_pullback")
        elif entry_timing_decision in {"avoid_chase", "avoid_for_now"}:
            conflict += 1.8
            penalties.append("timing_avoid_signal")

        if historical_hint in {"avoid_for_now", "monitor_only"} or historical_label == "avoid":
            conflict += 1.6
            penalties.append("historical_policy_caution")
        elif historical_hint == "require_confirmation" or historical_label in {"caution", "confirmation_required"}:
            conflict += 0.7
            penalties.append("historical_policy_confirmation")
        else:
            support += 0.4
            reasons.append("historical_policy_non_blocking")

        if context_decision in {"block", "observe_only"}:
            conflict += 2.0
            penalties.append("context_activation_restrictive")
        elif context_decision == "watchlist":
            conflict += 1.0
            penalties.append("context_activation_watchlist")
        elif context_decision in {"confirmation_required", "paper_ready_candidate"}:
            support += 0.5
            reasons.append("context_activation_supportive")

        if majority_signal in {"avoid", "sell", "strong sell"}:
            conflict += 1.8
            penalties.append("majority_signal_avoid")
        elif majority_signal in {"buy", "strong buy"}:
            support += 0.6
            reasons.append("majority_signal_buy")

        if disagreement >= 52.0:
            conflict += 1.6
            penalties.append("persona_disagreement_high")
        elif disagreement <= 38.0:
            support += 0.7
            reasons.append("persona_disagreement_low")
        if consensus >= 64.0:
            support += 0.7
            reasons.append("consensus_strength_supportive")
        elif consensus < 48.0:
            conflict += 0.8
            penalties.append("consensus_strength_weak")

        if valid_quote and trusted_quote and price > 0.0 and data_quality >= 50.0 and quote_quality >= 50.0:
            support += 1.1
            reasons.append("trusted_quote_quality_supported")
        else:
            conflict += 1.3
            penalties.append("quote_trust_or_quality_weak")

        if volume <= 0.0:
            missing_evidence_count += 1
            penalties.append("missing_volume")
        if prev_close <= 0.0:
            missing_evidence_count += 1
            penalties.append("missing_previous_close")
        if not enriched_signal_ready:
            missing_evidence_count += 1
            penalties.append("enriched_signal_not_ready")
        if not history_source:
            missing_evidence_count += 1
            penalties.append("missing_history_source")
        for token in ("missing_volume", "stale_quote_timestamp", "missing_history", "history_unavailable"):
            if token in signal_limitations:
                missing_evidence_count += 1
                penalties.append(f"signal_limitation_{token}")
        if chase_risk >= 70.0:
            conflict += 1.2
            penalties.append("entry_chase_risk_high")

        effective_missing_evidence = max(
            0.0,
            float(missing_evidence_count) * float(limited_data_penalty_weight),
        )
        base_score = (
            48.0
            + (setup_score * 0.08)
            + (entry_quality * 0.14)
            + (entry_timing_score * 0.07)
            + (trade_quality * 0.08)
            + (conf_pct * 0.03)
            + (grade_pct * 0.02)
            + (support * 8.5)
            - (conflict * 9.0)
            - (effective_missing_evidence * 3.2)
        )
        score = max(0.0, min(100.0, base_score))
        agreement_score = max(0.0, min(100.0, 35.0 + (support * 16.0) + max(0.0, (consensus - 50.0) * 0.4)))
        conflict_score = max(
            0.0,
            min(
                100.0,
                (conflict * 14.0)
                + max(0.0, (disagreement - 45.0) * 0.8)
                + (effective_missing_evidence * 3.0),
            ),
        )

        if score >= 82.0:
            band = "elite"
        elif score >= 68.0:
            band = "strong"
        elif score >= 54.0:
            band = "moderate"
        elif score >= 40.0:
            band = "weak"
        else:
            band = "poor"

        historically_favored = bool(
            setup_type == "momentum_breakout"
            or (historical_hint == "allow_normal_review" and historical_label == "supportive")
        )
        hard_reject = bool(
            (not trusted_quote)
            or (not valid_quote)
            or (setup_band == "poor")
            or (entry_band == "poor")
            or (context_decision == "block")
            or (entry_timing_decision == "avoid_for_now" and not historically_favored)
            or (majority_signal in {"avoid", "sell", "strong sell"} and disagreement >= 52.0)
        )

        if hard_reject or (
            score < 32.0
            or (conflict >= 4.0 and missing_evidence_count >= 3)
        ):
            decision = "reject"
            action_cap = "monitor-only"
        elif score < 44.0 or context_decision == "observe_only" or historical_hint in {"avoid_for_now", "monitor_only"}:
            decision = "monitor_only"
            action_cap = "monitor-only"
        elif score < 58.0 or entry_timing_decision == "wait_for_pullback":
            decision = "watchlist_only"
            action_cap = "watchlist"
        elif (
            score < 74.0
            or entry_timing_decision == "wait_for_confirmation"
            or historical_hint in {"require_confirmation", "paper_only"}
            or missing_evidence_count >= 2
        ):
            decision = "allow_with_confirmation"
            action_cap = "confirmation_required"
        else:
            decision = "allow"
            action_cap = "normal_review"

        original_decision = str(decision)
        limited_data_adjusted = False
        if (
            limited_data_mode
            and decision == "reject"
            and not hard_reject
            and setup_band != "poor"
            and entry_band != "poor"
            and context_decision not in {"block", "observe_only"}
        ):
            if score >= 44.0 and entry_timing_decision not in {"avoid_for_now", "avoid_chase"}:
                decision = "allow_with_confirmation"
                action_cap = "confirmation_required"
                reasons.append("limited_data_mode_confirmation_path")
                limited_data_adjusted = True
            elif score >= 34.0:
                decision = "watchlist_only"
                action_cap = "watchlist"
                reasons.append("limited_data_mode_watchlist_path")
                limited_data_adjusted = True

        return {
            "signal_quality_score": round(score, 2),
            "signal_quality_band": str(band),
            "signal_quality_decision": str(decision),
            "signal_quality_reasons": list(dict.fromkeys(reasons))[:12],
            "signal_quality_penalties": list(dict.fromkeys(penalties))[:12],
            "signal_quality_agreement_score": round(agreement_score, 2),
            "signal_quality_conflict_score": round(conflict_score, 2),
            "signal_quality_missing_evidence_count": int(missing_evidence_count),
            "signal_quality_selectivity_mode": "suppression_first_v1",
            "signal_quality_action_cap": str(action_cap),
            "signal_quality_gate_passed": bool(decision in {"allow", "allow_with_confirmation"}),
            "signal_quality_original_decision": str(original_decision),
            "signal_quality_limited_data_adjusted": bool(limited_data_adjusted),
            "limited_data_mode": bool(limited_data_mode),
            "limited_data_reason": str(limited_data_reason),
            "limited_data_trusted_quote": bool(trusted_quote and valid_quote and price > 0.0),
            "limited_data_penalty_weight": round(_to_float(limited_data_penalty_weight, 1.0), 3),
        }

    def _entry_precision_timing_v2(row, training_policy=None):
        r = dict(row or {})
        tp = dict(training_policy or {})
        reasons = []
        penalties = []

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_score = max(0.0, min(100.0, _to_float(r.get("setup_detection_score"), 0.0)))
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_quality_score = max(0.0, min(100.0, _to_float(r.get("entry_quality_score"), 0.0)))
        entry_quality_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        signal_band = str(r.get("signal_quality_band") or "poor").strip().lower()
        signal_limited_adjusted = bool(r.get("signal_quality_limited_data_adjusted", False))
        timing_decision = str(r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
        timing_score = max(0.0, min(100.0, _to_float(r.get("entry_timing_score"), 0.0)))
        base_chase = max(0.0, min(100.0, _to_float(r.get("entry_timing_chase_risk"), 0.0)))

        training_alignment = str(r.get("historical_training_alignment") or "insufficient").strip().lower()
        training_decision = str(r.get("historical_training_decision") or "neutral").strip().lower()
        training_score = _to_float(r.get("historical_training_score"), 0.0)
        replay_alignment = str(r.get("replay_alignment") or "insufficient").strip().lower()
        replay_score = _to_float(r.get("replay_influence_score"), 0.0)
        limited_data_mode = bool(r.get("limited_data_mode", False))
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()

        price = _to_float(r.get("price"), _to_float(r.get("current_price"), 0.0))
        day_open = _to_float(r.get("open"), _to_float(r.get("day_open"), 0.0))
        day_high = _to_float(r.get("high"), _to_float(r.get("day_high"), 0.0))
        day_low = _to_float(r.get("low"), _to_float(r.get("day_low"), 0.0))
        prev_close = _to_float(r.get("previous_close"), 0.0)
        change_pct = _to_float(r.get("change_percent"), 0.0)
        if abs(change_pct) <= 1.0:
            change_pct *= 100.0
        volume = _to_float(r.get("volume"), 0.0)
        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        quote_quality = max(0.0, min(100.0, _to_float(r.get("quote_quality"), _to_float(r.get("provider_confidence"), 55.0))))
        data_quality = max(0.0, min(100.0, _to_float(r.get("data_quality_score"), quote_quality)))
        signal_limitations = str(r.get("enriched_signal_limitations") or "").strip().lower()
        history_source = str(r.get("history_source") or r.get("enriched_history_source") or "").strip().lower()
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)

        favor_setups = set(str(x or "").strip().lower() for x in list(tp.get("favor_setups") or []))
        avoid_setups = set(str(x or "").strip().lower() for x in list(tp.get("avoid_setups") or []))
        confirm_setups = set(str(x or "").strip().lower() for x in list(tp.get("confirmation_required_setups") or []))

        near_high_ratio = None
        if price > 0.0 and day_high > day_low > 0.0:
            near_high_ratio = (price - day_low) / max(0.01, (day_high - day_low))
        extension = 0.0
        if change_pct >= 4.0:
            extension += 34.0
            penalties.append("extended_move_change_percent")
        elif change_pct >= 2.5:
            extension += 20.0
            penalties.append("elevated_move_change_percent")
        if near_high_ratio is not None:
            if near_high_ratio >= 0.90:
                extension += 30.0
                penalties.append("price_near_day_high")
            elif near_high_ratio >= 0.82:
                extension += 14.0
                penalties.append("price_upper_range")
        if day_open > 0.0 and price > day_open and change_pct >= 2.0:
            extension += 8.0
        missing_history = not bool(history_source)
        missing_volume = bool(volume <= 0.0)
        if (missing_volume or missing_history) and extension >= 18.0:
            extension += 12.0
            penalties.append("extension_without_confirmation_evidence")
        chase_risk = max(0.0, min(100.0, (base_chase * 0.58) + (extension * 0.42)))

        hard_reject = bool(
            (not trusted_quote)
            or (not valid_quote)
            or price <= 0.0
            or setup_band == "poor"
            or entry_quality_band == "poor"
            or context_decision in {"block", "observe_only"}
            or (signal_decision == "reject" and not signal_limited_adjusted and not limited_data_mode)
            or (majority_signal in {"avoid", "sell", "strong sell"} and disagreement >= 54.0)
        )

        if trusted_quote and valid_quote and quote_quality >= 50.0 and data_quality >= 50.0:
            reasons.append("trusted_quote_quality_supportive")
        else:
            penalties.append("quote_reliability_weak")
        if setup_band in {"moderate", "strong", "elite"}:
            reasons.append("setup_not_poor")
        if entry_quality_band in {"moderate", "strong", "elite"}:
            reasons.append("entry_quality_not_poor")
        if signal_decision == "allow":
            reasons.append("signal_quality_allow")
        elif signal_decision == "allow_with_confirmation":
            reasons.append("signal_quality_confirmation")
        elif signal_decision in {"monitor_only", "watchlist_only"}:
            penalties.append("signal_quality_restrictive")
        elif signal_decision == "reject":
            penalties.append("signal_quality_reject")

        training_used = False
        supportive_training = False
        unfavorable_training = False
        if setup_type and setup_type in favor_setups:
            supportive_training = True
            training_used = True
            reasons.append("training_policy_favor_setup")
        if setup_type and setup_type in avoid_setups:
            unfavorable_training = True
            training_used = True
            penalties.append("training_policy_avoid_setup")
        if setup_type and setup_type in confirm_setups:
            training_used = True
            penalties.append("training_policy_confirmation_setup")
        if training_alignment == "favorable" and training_score >= 0.8:
            supportive_training = True
            training_used = True
            reasons.append("historical_training_favorable")
        elif training_alignment == "unfavorable" and training_score <= -0.8:
            unfavorable_training = True
            training_used = True
            penalties.append("historical_training_unfavorable")
        if replay_alignment == "supportive" and replay_score > 0.4:
            supportive_training = True
            reasons.append("replay_supportive")
        elif replay_alignment == "negative" and replay_score < -0.4:
            unfavorable_training = True
            penalties.append("replay_negative")

        score = (
            45.0
            + ((setup_score - 50.0) * 0.22)
            + ((entry_quality_score - 50.0) * 0.30)
            + ((timing_score - 50.0) * 0.24)
            + (max(-6.0, min(4.0, training_score)) * 1.4)
            + (max(-5.0, min(5.0, replay_score)) * 0.9)
            - (chase_risk * 0.18)
        )
        if supportive_training and not unfavorable_training:
            score += 3.0
        if unfavorable_training:
            score -= 4.5
        if limited_data_mode:
            score += 1.2
            reasons.append("limited_data_mode_enabled")
        if missing_volume:
            penalties.append("missing_volume")
            score -= 2.0 if not limited_data_mode else 0.8
        if missing_history:
            penalties.append("missing_history_source")
            score -= 2.0 if not limited_data_mode else 0.8
        if "stale_quote_timestamp" in signal_limitations:
            penalties.append("stale_quote_timestamp")
            score -= 2.2 if not limited_data_mode else 0.9
        if "history_unavailable" in signal_limitations:
            penalties.append("history_unavailable")
            score -= 1.7 if not limited_data_mode else 0.7
        if hard_reject:
            score = min(score, 26.0)

        score = max(0.0, min(100.0, score))
        if score >= 72.0:
            band = "strong"
        elif score >= 54.0:
            band = "moderate"
        elif score >= 38.0:
            band = "weak"
        else:
            band = "poor"

        pullback_preferred = bool(chase_risk >= 55.0)
        confirmation_required = bool(
            signal_decision in {"allow_with_confirmation", "watchlist_only"}
            or limited_data_mode
            or setup_type in confirm_setups
            or timing_decision in {"wait_for_confirmation", "wait_for_pullback"}
        )

        if hard_reject:
            decision = "avoid_for_now"
        elif unfavorable_training and score < 52.0:
            decision = "avoid_for_now"
        elif chase_risk >= 72.0 and (entry_quality_band not in {"strong", "elite"} or not supportive_training):
            decision = "avoid_chase"
        elif pullback_preferred:
            decision = "wait_for_pullback"
        elif supportive_training and setup_band not in {"poor"} and entry_quality_band not in {"poor"} and timing_decision != "avoid_for_now":
            decision = "enter_if_confirmed"
            confirmation_required = True
        elif timing_decision == "avoid_for_now" and supportive_training and limited_data_mode and not unfavorable_training:
            decision = "wait_for_confirmation"
            confirmation_required = True
            reasons.append("training_softens_avoid_for_now")
        else:
            decision = "wait_for_confirmation"
            confirmation_required = True

        entry_score_base = _to_float(
            r.get("entry_score_learning_adjusted"),
            _to_float(
                r.get("entry_score_historical_training_adjusted"),
                _to_float(r.get("entry_score_replay_adjusted"), _to_float(r.get("entry_score_signal_quality_adjusted"), 0.0)),
            ),
        )
        if decision == "enter_if_confirmed":
            adjustment = 2.1 + ((score - 60.0) * 0.03)
        elif decision == "wait_for_confirmation":
            adjustment = 0.4 + ((score - 55.0) * 0.02)
        elif decision == "wait_for_pullback":
            adjustment = -1.4
        elif decision == "avoid_chase":
            adjustment = -2.8
        else:
            adjustment = -3.6
        if hard_reject and adjustment > 0:
            adjustment = 0.0
        adjustment = max(-4.0, min(3.0, adjustment))
        entry_score_adjusted = max(0.0, min(100.0, entry_score_base + adjustment))

        return {
            "entry_precision_v2_score": round(score, 2),
            "entry_precision_v2_band": str(band),
            "entry_precision_v2_decision": str(decision),
            "entry_precision_v2_reasons": list(dict.fromkeys(reasons))[:12],
            "entry_precision_v2_penalties": list(dict.fromkeys(penalties))[:12],
            "entry_precision_v2_chase_risk": round(chase_risk, 2),
            "entry_precision_v2_pullback_preferred": bool(pullback_preferred),
            "entry_precision_v2_confirmation_required": bool(confirmation_required),
            "entry_precision_v2_training_used": bool(training_used),
            "entry_score_precision_v2_adjusted": round(entry_score_adjusted, 2),
        }

    def _confirmation_path_tuning_v1(row):
        r = dict(row or {})
        original_decision = str(r.get("entry_precision_v2_decision") or "wait_for_confirmation").strip().lower()
        final_decision = str(original_decision)
        reasons = []
        penalties = []
        allowed = False
        applied = False

        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        limited_data_mode = bool(r.get("limited_data_mode", False))
        limited_data_reason = str(r.get("limited_data_reason") or "").strip().lower()
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        signal_penalties = [str(x or "").strip().lower() for x in list(r.get("signal_quality_penalties") or [])]
        learning_decision = str(r.get("learning_activation_decision") or "neutral").strip().lower()
        training_alignment = str(r.get("historical_training_alignment") or "insufficient").strip().lower()
        training_decision = str(r.get("historical_training_decision") or "neutral").strip().lower()
        training_conf = _to_float(r.get("historical_training_confidence"), 0.0)
        chase_risk = max(
            0.0,
            min(
                100.0,
                _to_float(
                    r.get("entry_precision_v2_chase_risk"),
                    _to_float(r.get("entry_timing_chase_risk"), 0.0),
                ),
            ),
        )
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        kill_action = str(r.get("kill_switch_action") or "").strip().lower()
        discipline_action = str(r.get("core_decision_discipline_action") or "").strip().lower()

        missing_data_related = (
            "missing_volume" in signal_penalties
            or "missing_history_source" in signal_penalties
            or "signal_limitation_missing_history" in signal_penalties
            or "signal_limitation_missing_volume" in signal_penalties
            or "signal_limitation_stale_quote_timestamp" in signal_penalties
            or "stale_quote_timestamp" in signal_penalties
            or "history_unavailable" in signal_penalties
            or "fmp" in limited_data_reason
            or "offline" in limited_data_reason
        )
        hard_reject_signal = bool(signal_decision == "reject" and not missing_data_related)
        strong_training_suppress = bool(
            training_decision == "suppress"
            and training_alignment == "unfavorable"
            and training_conf >= 0.75
        )
        severe_chase = bool(chase_risk >= 82.0)
        major_disagreement_avoid = bool(
            majority_signal in {"avoid", "sell", "strong sell"}
            and disagreement >= 62.0
            and setup_band in {"poor", "weak"}
        )
        explicit_blocker = bool(
            kill_action == "reject"
            or discipline_action == "reject"
            or context_decision == "block"
            or (not trusted_quote)
            or (not valid_quote)
            or setup_band == "poor"
            or entry_band == "poor"
            or hard_reject_signal
            or learning_decision == "suppress"
            or strong_training_suppress
            or severe_chase
            or major_disagreement_avoid
        )

        if original_decision == "avoid_for_now":
            applied = True
            if (
                trusted_quote
                and valid_quote
                and (limited_data_mode or missing_data_related)
                and setup_band != "poor"
                and entry_band != "poor"
                and context_decision != "block"
                and not hard_reject_signal
                and learning_decision != "suppress"
                and (training_alignment != "unfavorable" or training_conf < 0.75)
                and chase_risk < 72.0
                and kill_action != "reject"
                and discipline_action != "reject"
            ):
                final_decision = "wait_for_confirmation"
                allowed = True
                reasons.append("limited_data_confirmation_path")
                reasons.append("trusted_quote_allows_confirmation")
                if training_alignment == "favorable":
                    reasons.append("training_alignment_supportive")
            else:
                final_decision = "avoid_for_now"
                if not trusted_quote or not valid_quote:
                    penalties.append("quote_not_trusted_or_invalid")
                if setup_band == "poor" or entry_band == "poor":
                    penalties.append("poor_setup_or_entry_quality")
                if context_decision == "block":
                    penalties.append("context_blocked")
                if hard_reject_signal:
                    penalties.append("signal_hard_reject")
                if learning_decision == "suppress":
                    penalties.append("learning_activation_suppress")
                if strong_training_suppress:
                    penalties.append("historical_training_strong_suppress")
                if severe_chase:
                    penalties.append("severe_chase_risk")
                if major_disagreement_avoid:
                    penalties.append("majority_avoid_high_disagreement")
        else:
            final_decision = original_decision
            if original_decision in {"wait_for_confirmation", "wait_for_pullback", "enter_if_confirmed"}:
                reasons.append("confirmation_path_not_needed")

        if explicit_blocker and final_decision != "avoid_for_now":
            final_decision = "avoid_for_now"
            allowed = False
            applied = True
            penalties.append("hard_safety_block_preserved")

        base = _to_float(
            r.get("entry_score_precision_v2_adjusted"),
            _to_float(r.get("entry_score_learning_adjusted"), 0.0),
        )
        if applied and allowed and final_decision == "wait_for_confirmation":
            adjust = 1.0
        elif applied and not allowed:
            adjust = -0.6
        else:
            adjust = 0.0
        adjust = max(-2.0, min(2.0, adjust))
        adjusted = max(0.0, min(100.0, base + adjust))

        if applied and allowed:
            score = 66.0
        elif applied:
            score = 38.0
        else:
            score = 50.0

        return {
            "confirmation_path_tuning_applied": bool(applied),
            "confirmation_path_original_decision": str(original_decision),
            "confirmation_path_final_decision": str(final_decision),
            "confirmation_path_reason": list(dict.fromkeys(reasons))[:8],
            "confirmation_path_penalties": list(dict.fromkeys(penalties))[:8],
            "confirmation_path_score": round(max(0.0, min(100.0, score)), 2),
            "confirmation_path_allowed": bool(allowed),
            "entry_score_confirmation_path_adjusted": round(adjusted, 2),
        }

    def _entry_filter_v2(row):
        r = dict(row or {})
        reasons = []
        penalties = []
        learning_used = False
        score = 62.0

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        regime_context = str(r.get("regime_context") or r.get("regime") or "unknown").strip().lower()
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        timing_decision = str(r.get("entry_precision_v2_decision") or r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
        confirmation_decision = str(r.get("confirmation_path_final_decision") or timing_decision).strip().lower()
        learning_decision = str(r.get("learning_activation_decision") or "neutral").strip().lower()
        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        limited_data_mode = bool(r.get("limited_data_mode", False))
        chase_risk = _to_float(r.get("entry_precision_v2_chase_risk"), _to_float(r.get("entry_timing_chase_risk"), 0.0))

        entry_q_score = _to_float(r.get("entry_quality_score"), 0.0)
        precision_score = _to_float(r.get("entry_precision_v2_score"), _to_float(r.get("entry_timing_score"), 0.0))
        hist_score = max(-6.0, min(6.0, _to_float(r.get("historical_training_score"), 0.0)))
        replay_score = max(-5.0, min(5.0, _to_float(r.get("replay_influence_score"), 0.0)))
        adaptive_mult = max(0.92, min(1.08, _to_float(r.get("adaptive_multiplier"), 1.0)))

        if setup_type == "fallback_unclear":
            penalties.append("fallback_unclear")
            score -= 12.0
        if regime_context == "range_low_vol":
            penalties.append("range_low_vol")
            score -= 7.0
        if setup_band in {"poor", "weak"}:
            penalties.append("weak_setup_structure")
            score -= 9.0 if setup_band == "poor" else 5.0
        if entry_band in {"poor", "weak"}:
            penalties.append("weak_entry_quality_band")
            score -= 11.0 if entry_band == "poor" else 6.0
        if majority_signal in {"avoid", "sell", "strong sell"}:
            penalties.append("majority_signal_avoid")
            score -= 7.0
        if chase_risk >= 72.0:
            penalties.append("elevated_chase_risk")
            score -= 8.0
        if timing_decision in {"avoid_for_now", "avoid_chase"}:
            penalties.append("timing_avoid_signal")
            score -= 8.0
        if signal_decision == "reject":
            penalties.append("signal_quality_reject")
            score -= 16.0
        elif signal_decision == "monitor_only":
            penalties.append("signal_quality_monitor_only")
            score -= 8.0
        if context_decision == "block":
            penalties.append("context_block")
            score -= 18.0
        if learning_decision == "suppress":
            penalties.append("learning_activation_suppress")
            score -= 8.0

        signal_penalties = [str(x or "").strip().lower() for x in list(r.get("signal_quality_penalties") or [])]
        limitations = [str(x or "").strip().lower() for x in list(r.get("enriched_signal_limitations") or [])]
        if any(x in signal_penalties for x in {"missing_volume", "signal_limitation_missing_volume"}):
            penalties.append("missing_volume")
            score -= 4.5 if not limited_data_mode else 2.0
        if any(x in signal_penalties for x in {"missing_history_source", "signal_limitation_missing_history", "history_unavailable"}):
            penalties.append("missing_history_source")
            score -= 4.5 if not limited_data_mode else 2.0
        if "stale_quote_timestamp" in limitations or "signal_limitation_stale_quote_timestamp" in signal_penalties:
            penalties.append("stale_quote_timestamp")
            score -= 4.0 if not limited_data_mode else 1.5

        if trusted_quote and valid_quote and setup_band not in {"poor"} and entry_band not in {"poor"} and signal_decision not in {"reject"}:
            reasons.append("trusted_valid_quote_with_non_poor_setup_entry")
            score += 4.0
        if confirmation_decision == "wait_for_confirmation":
            reasons.append("confirmation_path_allowed")
            score += 2.5

        learning_effect = 0.0
        if abs(hist_score) > 0.01 or abs(replay_score) > 0.01 or abs(adaptive_mult - 1.0) > 0.0001:
            learning_used = True
            learning_effect += max(-6.0, min(4.0, hist_score * 0.55))
            learning_effect += max(-4.0, min(3.0, replay_score * 0.45))
            learning_effect += max(-2.0, min(2.0, (adaptive_mult - 1.0) * 30.0))
        learning_effect = max(-6.0, min(4.0, learning_effect))
        score += learning_effect
        if learning_effect >= 1.0:
            reasons.append("learning_weights_support_entry")
        elif learning_effect <= -1.0:
            penalties.append("learning_weights_penalize_entry")

        if not trusted_quote or not valid_quote:
            penalties.append("quote_not_trusted_or_invalid")
            score = min(score, 24.0)
        if context_decision == "block" or setup_band == "poor" or entry_band == "poor":
            score = min(score, 28.0)

        score = max(0.0, min(100.0, score))
        if score < 35.0:
            band = "poor"
        elif score < 55.0:
            band = "weak"
        elif score < 70.0:
            band = "moderate"
        else:
            band = "strong"

        if not trusted_quote or not valid_quote or context_decision == "block":
            decision = "hard_block_preserved"
        elif score < 35.0:
            decision = "suppress_entry"
        elif score < 55.0:
            decision = "require_confirmation"
        elif score < 70.0:
            decision = "allow_paper_review"
        else:
            decision = "allow_paper_review"

        requires_confirmation = bool(decision == "require_confirmation" or confirmation_decision == "wait_for_confirmation")
        original_state = str(r.get("hero_deployment_status") or r.get("canonical_final_state") or "unknown")
        final_state = str(original_state)
        if decision in {"hard_block_preserved", "suppress_entry"}:
            final_state = "monitor_only"
        elif decision == "require_confirmation":
            final_state = "require_confirmation"
        elif decision == "allow_paper_review":
            final_state = "allow_paper_review"

        return {
            "entry_filter_v2_applied": True,
            "entry_filter_v2_score": round(score, 2),
            "entry_filter_v2_band": str(band),
            "entry_filter_v2_decision": str(decision),
            "entry_filter_v2_reason": list(dict.fromkeys(reasons))[:10],
            "entry_filter_v2_penalties": list(dict.fromkeys(penalties))[:12],
            "entry_filter_v2_original_state": str(original_state),
            "entry_filter_v2_final_state": str(final_state),
            "entry_filter_v2_requires_confirmation": bool(requires_confirmation),
            "entry_filter_v2_learning_used": bool(learning_used),
        }

    def _profit_quality_engine_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []
        score = 50.0

        realized = _to_float(r.get("realized_return_pct"), None)
        mfe = _to_float(r.get("max_favorable_excursion"), None)
        mae = _to_float(r.get("max_adverse_excursion"), None)
        hold_s = _to_float(r.get("hold_time_seconds"), None)
        deploy_state = str(r.get("hero_deployment_status") or "").strip().lower()
        paper_only_context = bool(
            r.get("paper_mode", False)
            or deploy_state in {"paper-ready", "monitor-only"}
            or str(r.get("entry_filter_v2_final_state") or "").strip().lower() in {"allow_paper_review", "require_confirmation", "monitor_only"}
        )
        if not paper_only_context:
            return {
                "profit_quality_score": 50.0,
                "profit_quality_band": "moderate",
                "profit_quality_reason": ["paper_only_context_not_active"],
                "profit_quality_penalties": [],
                "profit_quality_learning_influence": 0.0,
                "profit_quality_applied": False,
            }

        if realized is None and mfe is None and mae is None and hold_s is None:
            return {
                "profit_quality_score": 50.0,
                "profit_quality_band": "moderate",
                "profit_quality_reason": ["insufficient_profit_quality_inputs"],
                "profit_quality_penalties": [],
                "profit_quality_learning_influence": 0.0,
                "profit_quality_applied": True,
            }

        if realized is not None:
            score += max(-20.0, min(22.0, realized * 3.2))
            if realized >= 2.0:
                reasons.append("strong_realized_return")
            elif realized <= -1.5:
                penalties.append("negative_realized_return")
        if mae is not None:
            if mae <= -2.0:
                penalties.append("high_drawdown")
                score -= min(20.0, abs(mae) * 4.0)
            elif mae >= -0.4:
                reasons.append("contained_drawdown")
                score += 4.0
        if mfe is not None and realized is not None:
            if mfe >= 0.01:
                capture = realized / mfe
                if capture < 0.35 and mfe >= 1.5:
                    penalties.append("missed_large_move")
                    score -= min(12.0, (0.35 - capture) * 30.0)
                elif capture >= 0.65:
                    reasons.append("captured_move_well")
                    score += min(8.0, (capture - 0.65) * 15.0)
        if hold_s is not None:
            if hold_s < 300 and (realized is not None and realized <= -0.6):
                penalties.append("fast_failure")
                score -= 14.0
            elif hold_s >= 1800 and (realized is not None and realized >= 1.2) and (mae is not None and mae > -1.0):
                reasons.append("clean_trend_capture")
                score += 8.0

        score = max(0.0, min(100.0, score))
        if score < 35.0:
            band = "poor"
        elif score < 55.0:
            band = "weak"
        elif score < 70.0:
            band = "moderate"
        else:
            band = "strong"

        influence = (score - 50.0) * 0.04
        influence = max(-2.0, min(2.0, influence))
        return {
            "profit_quality_score": round(score, 2),
            "profit_quality_band": str(band),
            "profit_quality_reason": list(dict.fromkeys(reasons))[:8],
            "profit_quality_penalties": list(dict.fromkeys(penalties))[:8],
            "profit_quality_learning_influence": round(influence, 3),
            "profit_quality_applied": True,
        }

    def _exit_capture_learning_bridge_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []

        realized = _to_float(r.get("realized_return_pct"), None)
        mfe = _to_float(r.get("max_favorable_excursion"), None)
        mae = _to_float(r.get("max_adverse_excursion"), None)
        hold_s = _to_float(r.get("hold_time_seconds"), None)
        deploy_state = str(r.get("hero_deployment_status") or "").strip().lower()
        paper_only_context = bool(
            r.get("paper_mode", False)
            or deploy_state in {"paper-ready", "monitor-only"}
            or str(r.get("entry_filter_v2_final_state") or "").strip().lower() in {"allow_paper_review", "require_confirmation", "monitor_only"}
        )
        if not paper_only_context:
            return {
                "capture_ratio": None,
                "mfe_efficiency_score": 50.0,
                "exit_quality_band": "moderate",
                "exit_quality_reason": ["paper_only_context_not_active"],
                "exit_quality_penalties": [],
                "exit_learning_adjustment": 0.0,
                "exit_quality_applied": False,
            }

        capture_ratio = None
        if mfe is not None and mfe > 0.0 and realized is not None:
            capture_ratio = max(0.0, min(1.2, realized / max(0.000001, mfe)))

        score = 50.0
        if capture_ratio is not None:
            if capture_ratio >= 0.85:
                reasons.append("captured_majority_of_move")
                score += 24.0
            elif capture_ratio >= 0.4:
                reasons.append("partial_capture")
                score += 8.0
            elif capture_ratio < 0.3:
                penalties.append("missed_profit")
                reasons.append("missed_large_move")
                score -= 16.0
            if capture_ratio < 0.2 and mfe is not None and mfe >= 1.5:
                penalties.append("early_exit_signal")
                reasons.append("early_exit")
                score -= 10.0
            elif capture_ratio > 1.0:
                reasons.append("late_exit")
                score -= 2.0

        if mae is not None and realized is not None:
            drawdown_pressure = abs(min(0.0, mae))
            if drawdown_pressure >= 1.2 and realized <= 0.5:
                penalties.append("excessive_drawdown")
                reasons.append("high_drawdown_exit")
                score -= min(18.0, drawdown_pressure * 7.0)
            elif drawdown_pressure >= 0.8 and realized > 0 and capture_ratio is not None and capture_ratio < 0.45:
                penalties.append("inefficient_hold")
                score -= 6.0

        if hold_s is not None and capture_ratio is not None:
            if hold_s < 240 and capture_ratio < 0.35 and (mfe or 0) >= 0.8:
                penalties.append("early_exit_signal")
                reasons.append("early_exit")
                score -= 7.0
            elif hold_s > 7200 and capture_ratio < 0.35 and (realized or 0) <= 0.4:
                penalties.append("late_exit_signal")
                reasons.append("late_exit")
                score -= 6.0

        score = max(0.0, min(100.0, score))
        if score < 35.0:
            band = "poor"
        elif score < 55.0:
            band = "weak"
        elif score < 70.0:
            band = "moderate"
        else:
            band = "strong"

        adjustment = max(-2.0, min(2.0, (score - 50.0) * 0.04))
        return {
            "capture_ratio": (round(capture_ratio, 4) if capture_ratio is not None else None),
            "mfe_efficiency_score": round(score, 2),
            "exit_quality_band": str(band),
            "exit_quality_reason": list(dict.fromkeys(reasons))[:8],
            "exit_quality_penalties": list(dict.fromkeys(penalties))[:8],
            "exit_learning_adjustment": round(adjustment, 3),
            "exit_quality_applied": True,
        }

    def _confidence_truthfulness_calibration_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []

        conf = _to_float(r.get("confidence"), None)
        if conf is None:
            conf = _to_float(r.get("confidence_pct"), None)
        conf = max(0.0, min(100.0, conf if conf is not None else 50.0))

        realized = _to_float(r.get("realized_return_pct"), None)
        profit_quality = _to_float(r.get("profit_quality_score"), None)
        mfe_eff = _to_float(r.get("mfe_efficiency_score"), None)

        deploy_state = str(r.get("hero_deployment_status") or "").strip().lower()
        paper_only_context = bool(
            r.get("paper_mode", False)
            or deploy_state in {"paper-ready", "monitor-only"}
            or str(r.get("entry_filter_v2_final_state") or "").strip().lower() in {"allow_paper_review", "require_confirmation", "monitor_only"}
        )
        if not paper_only_context:
            return {
                "confidence_truthfulness_score": 50.0,
                "confidence_calibration_band": "moderate",
                "confidence_calibration_reason": ["paper_only_context_not_active"],
                "confidence_calibration_penalties": [],
                "confidence_learning_adjustment": 0.0,
                "confidence_calibration_applied": False,
            }

        if realized is None and profit_quality is None and mfe_eff is None:
            return {
                "confidence_truthfulness_score": 50.0,
                "confidence_calibration_band": "moderate",
                "confidence_calibration_reason": ["insufficient_confidence_outcome_inputs"],
                "confidence_calibration_penalties": [],
                "confidence_learning_adjustment": 0.0,
                "confidence_calibration_applied": True,
            }

        score = 50.0
        outcome_sign = 0
        if realized is not None:
            if realized >= 0.5:
                outcome_sign = 1
            elif realized <= -0.5:
                outcome_sign = -1
            else:
                outcome_sign = 0

        if conf >= 70.0 and outcome_sign > 0:
            reasons.append("confidence_matches_outcome")
            score += 18.0
        elif conf >= 70.0 and outcome_sign < 0:
            reasons.append("overconfident_failure")
            penalties.append("false_confidence")
            penalties.append("weak_signal_overconfidence")
            score -= 22.0
        elif conf <= 40.0 and outcome_sign > 0:
            reasons.append("underconfident_success")
            penalties.append("underconfidence_missed_opportunity")
            score -= 8.0
        elif conf <= 40.0 and outcome_sign < 0:
            reasons.append("confidence_matches_outcome")
            score += 8.0
        else:
            reasons.append("neutral_alignment")

        if profit_quality is not None:
            if conf >= 70.0 and profit_quality >= 70.0:
                score += 10.0
            elif conf >= 70.0 and profit_quality < 40.0:
                penalties.append("false_confidence")
                score -= 10.0
            else:
                score += max(-4.0, min(4.0, (profit_quality - 50.0) * 0.08))

        if mfe_eff is not None:
            if conf >= 70.0 and mfe_eff >= 70.0:
                score += 6.0
            elif conf >= 70.0 and mfe_eff < 35.0:
                penalties.append("false_confidence")
                score -= 8.0
            score += max(-3.0, min(3.0, (mfe_eff - 50.0) * 0.05))

        # bounded smoothing against spikes
        score = (score * 0.72) + 14.0
        score = max(0.0, min(100.0, score))

        if score < 35.0:
            band = "poor"
        elif score < 55.0:
            band = "weak"
        elif score < 70.0:
            band = "moderate"
        else:
            band = "strong"

        adjustment = max(-2.0, min(2.0, (score - 50.0) * 0.04))
        return {
            "confidence_truthfulness_score": round(score, 2),
            "confidence_calibration_band": str(band),
            "confidence_calibration_reason": list(dict.fromkeys(reasons))[:8],
            "confidence_calibration_penalties": list(dict.fromkeys(penalties))[:8],
            "confidence_learning_adjustment": round(adjustment, 3),
            "confidence_calibration_applied": True,
        }

    def _position_sizing_risk_tiering_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []

        trusted = bool(r.get("trusted_quote_for_buys", False))
        valid = bool(r.get("valid_quote", False))
        entry_filter_decision = str(r.get("entry_filter_v2_decision") or "").strip().lower()
        entry_filter_band = str(r.get("entry_filter_v2_band") or "poor").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        paper_only_context = bool(
            r.get("paper_mode", False)
            or str(r.get("hero_deployment_status") or "").strip().lower() in {"paper-ready", "monitor-only"}
            or str(r.get("entry_filter_v2_final_state") or "").strip().lower() in {"allow_paper_review", "require_confirmation", "monitor_only"}
        )
        if not paper_only_context:
            return {
                "risk_tier_score": 0.0,
                "risk_tier_band": "avoid",
                "suggested_paper_size_pct": 0.0,
                "risk_tier_reason": ["paper_only_context_not_active"],
                "risk_tier_penalties": [],
                "risk_tier_applied": False,
            }

        if (not trusted) or (not valid):
            return {
                "risk_tier_score": 0.0,
                "risk_tier_band": "avoid",
                "suggested_paper_size_pct": 0.0,
                "risk_tier_reason": [],
                "risk_tier_penalties": ["quote_invalid_or_untrusted"],
                "risk_tier_applied": True,
            }

        if entry_filter_decision in {"hard_block_preserved", "suppress_entry"}:
            return {
                "risk_tier_score": 5.0,
                "risk_tier_band": "avoid",
                "suggested_paper_size_pct": 0.0,
                "risk_tier_reason": [],
                "risk_tier_penalties": ["entry_filter_block_preserved"],
                "risk_tier_applied": True,
            }

        score = 52.0
        score += max(-18.0, min(18.0, (_to_float(r.get("entry_filter_v2_score"), 0.0) - 50.0) * 0.45))
        score += max(-12.0, min(12.0, (_to_float(r.get("profit_quality_score"), 50.0) - 50.0) * 0.25))
        score += max(-10.0, min(10.0, (_to_float(r.get("mfe_efficiency_score"), 50.0) - 50.0) * 0.18))
        score += max(-10.0, min(10.0, (_to_float(r.get("confidence_truthfulness_score"), 50.0) - 50.0) * 0.2))
        score += max(-8.0, min(8.0, (_to_float(r.get("entry_quality_score"), 50.0) - 50.0) * 0.16))
        score += max(-8.0, min(8.0, (_to_float(r.get("confidence"), 50.0) - 50.0) * 0.12))

        if entry_filter_band == "poor":
            penalties.append("entry_filter_poor")
            score -= 26.0
        elif entry_filter_band == "weak":
            penalties.append("entry_filter_weak")
            score -= 12.0

        if str(r.get("profit_quality_band") or "").strip().lower() == "poor":
            penalties.append("profit_quality_poor")
            score -= 10.0
        if str(r.get("exit_quality_band") or "").strip().lower() == "poor":
            penalties.append("exit_quality_poor")
            score -= 8.0
        if str(r.get("confidence_calibration_band") or "").strip().lower() == "poor":
            penalties.append("confidence_truthfulness_poor")
            score -= 8.0
        if signal_decision in {"reject", "monitor_only"}:
            penalties.append("signal_quality_cap")
            score -= 10.0

        if score >= 72.0:
            reasons.append("multi_layer_quality_alignment")
        elif score >= 55.0:
            reasons.append("moderate_quality_alignment")
        else:
            reasons.append("conservative_size_due_to_quality_risk")

        score = max(0.0, min(100.0, score))
        if score < 20.0:
            band = "avoid"
        elif score < 40.0:
            band = "tiny"
        elif score < 58.0:
            band = "small"
        elif score < 78.0:
            band = "standard"
        else:
            band = "high_quality_paper"

        if entry_filter_band == "poor":
            band = "avoid"
        elif entry_filter_band == "weak" and band in {"standard", "high_quality_paper"}:
            band = "small"

        size_map = {
            "avoid": 0.0,
            "tiny": 0.25,
            "small": 0.50,
            "standard": 1.00,
            "high_quality_paper": 1.50,
        }
        return {
            "risk_tier_score": round(score, 2),
            "risk_tier_band": str(band),
            "suggested_paper_size_pct": float(size_map.get(band, 0.0)),
            "risk_tier_reason": list(dict.fromkeys(reasons))[:8],
            "risk_tier_penalties": list(dict.fromkeys(penalties))[:10],
            "risk_tier_applied": True,
        }

    def _pseudo_replay_learning_boost_v1(row, training_policy=None):
        r = dict(row or {})
        tp = dict(training_policy or {})
        reasons = []
        penalties = []

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
        signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        signal_penalties = [str(x or "").strip().lower() for x in list(r.get("signal_quality_penalties") or [])]
        precision_decision = str(r.get("entry_precision_v2_decision") or "wait_for_confirmation").strip().lower()
        learning_decision = str(r.get("learning_activation_decision") or "").strip().lower()
        trusted_quote = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        limited_data_mode = bool(r.get("limited_data_mode", False))
        limited_data_reason = str(r.get("limited_data_reason") or "").strip().lower()
        training_alignment = str(r.get("historical_training_alignment") or "insufficient").strip().lower()
        training_score = max(-6.0, min(6.0, _to_float(r.get("historical_training_score"), 0.0)))
        replay_alignment = str(r.get("replay_alignment") or "insufficient").strip().lower()
        replay_score = max(-6.0, min(6.0, _to_float(r.get("replay_influence_score"), 0.0)))
        confirmation_allowed = bool(r.get("confirmation_path_allowed", False))

        training_available = bool(
            tp.get("training_ready", False)
            or tp.get("historical_training_available", False)
            or bool(tp)
        )
        training_conf_label = str(tp.get("training_confidence") or tp.get("historical_training_confidence") or "unknown").strip().lower()
        moderate_plus_conf = training_conf_label in {"moderate", "high", "strong"}
        fmp_mode = str(os.getenv("ASTRA_FMP_MODE", "conserve")).strip().lower()
        fmp_offline_like = bool(
            limited_data_mode
            or "fmp" in limited_data_reason
            or "offline" in limited_data_reason
            or fmp_mode in {"conserve", "off", "paused", "quota_limited", "limited"}
        )

        pseudo_mode = bool(
            fmp_offline_like
            and training_available
            and moderate_plus_conf
            and trusted_quote
            and valid_quote
        )
        if fmp_offline_like:
            mode_reason = "fmp_offline_or_limited_data"
        elif not training_available:
            mode_reason = "historical_training_unavailable"
        elif not moderate_plus_conf:
            mode_reason = "historical_training_confidence_too_low"
        elif not (trusted_quote and valid_quote):
            mode_reason = "quote_not_trusted"
        else:
            mode_reason = "pseudo_learning_inactive"

        favor_setups = set(str(x or "").strip().lower() for x in list(tp.get("favor_setups") or []))
        avoid_setups = set(str(x or "").strip().lower() for x in list(tp.get("avoid_setups") or []))
        confirm_setups = set(str(x or "").strip().lower() for x in list(tp.get("confirmation_required_setups") or []))

        if setup_type in avoid_setups or training_alignment == "unfavorable" or replay_alignment == "negative":
            alignment = "historically_unfavorable"
        elif setup_type in favor_setups or training_alignment == "favorable" or replay_alignment == "supportive":
            alignment = "historically_favorable"
        elif training_alignment == "insufficient" and replay_alignment == "insufficient":
            alignment = "insufficient"
        else:
            alignment = "historically_neutral"

        missing_data_reject = bool(
            signal_decision == "reject"
            and any(
                k in signal_penalties
                for k in {
                    "missing_volume",
                    "missing_history_source",
                    "signal_limitation_missing_volume",
                    "signal_limitation_missing_history",
                    "signal_limitation_stale_quote_timestamp",
                    "stale_quote_timestamp",
                    "history_unavailable",
                }
            )
        )
        hard_reject_signal = bool(signal_decision == "reject" and not missing_data_reject)
        hard_block = bool(
            (not trusted_quote)
            or (not valid_quote)
            or setup_band == "poor"
            or entry_band == "poor"
            or hard_reject_signal
            or str(r.get("context_activation_decision") or "").strip().lower() == "block"
        )

        raw = 0.0
        if alignment == "historically_favorable":
            raw += 2.1
            reasons.append("historical_alignment_favorable")
        elif alignment == "historically_unfavorable":
            raw -= 2.6
            penalties.append("historical_alignment_unfavorable")
        elif alignment == "historically_neutral":
            raw += 0.2
        else:
            penalties.append("historical_alignment_insufficient")

        raw += max(-2.0, min(2.0, training_score * 0.42))
        raw += max(-1.6, min(1.6, replay_score * 0.33))
        if setup_type in favor_setups:
            raw += 0.8
            reasons.append("historical_favor_setup_family")
        if setup_type in avoid_setups:
            raw -= 1.4
            penalties.append("historical_avoid_setup_family")
        if setup_type in confirm_setups:
            raw -= 0.4
            reasons.append("historical_confirmation_setup_family")
        if precision_decision in {"avoid_for_now", "avoid_chase"}:
            raw -= 0.8
            penalties.append("timing_currently_restrictive")

        if hard_block:
            raw = min(raw, 0.0)
            penalties.append("hard_safety_block_preserved")
        if not pseudo_mode:
            raw = 0.0
            if mode_reason:
                penalties.append(mode_reason)

        boost_score = max(-4.0, min(4.0, raw))
        if boost_score >= 2.0:
            decision = "reinforce"
        elif boost_score >= 0.8:
            decision = "confirm"
        elif boost_score <= -2.0:
            decision = "suppress"
        elif boost_score <= -0.8:
            decision = "caution"
        else:
            decision = "neutral"

        signal_adjusted = False
        signal_after = signal_decision
        if (
            pseudo_mode
            and decision in {"reinforce", "confirm"}
            and missing_data_reject
            and not hard_block
            and setup_band != "poor"
            and entry_band != "poor"
        ):
            signal_adjusted = True
            signal_after = "allow_with_confirmation"
            reasons.append("pseudo_learning_softens_limited_data_reject")

        precision_adjusted = False
        precision_after = precision_decision
        if (
            pseudo_mode
            and decision in {"reinforce", "confirm"}
            and precision_decision == "avoid_for_now"
            and confirmation_allowed
            and not hard_block
        ):
            precision_adjusted = True
            precision_after = "wait_for_confirmation"
            reasons.append("pseudo_learning_enables_confirmation_path")

        learning_adjusted = False
        learning_after = learning_decision
        if (
            pseudo_mode
            and decision == "reinforce"
            and learning_decision == "caution"
            and not hard_block
        ):
            learning_adjusted = True
            learning_after = "neutral"
            reasons.append("pseudo_learning_reduces_learning_caution")

        entry_score_base = _to_float(
            r.get("entry_score_confirmation_path_adjusted"),
            _to_float(r.get("entry_score_precision_v2_adjusted"), 0.0),
        )
        adjust = max(-4.0, min(4.0, boost_score * 0.55))
        if hard_block and adjust > 0:
            adjust = 0.0
        entry_adjusted = max(0.0, min(100.0, entry_score_base + adjust))

        return {
            "pseudo_learning_mode": bool(pseudo_mode),
            "pseudo_learning_reason": str(mode_reason),
            "pseudo_learning_temporary": True,
            "pseudo_learning_confidence": str(training_conf_label or "unknown"),
            "pseudo_learning_boost_applied": bool(pseudo_mode and abs(boost_score) >= 0.2),
            "pseudo_learning_boost_score": round(boost_score, 3),
            "pseudo_learning_alignment": str(alignment),
            "pseudo_learning_decision": str(decision),
            "pseudo_learning_reasons": list(dict.fromkeys(reasons))[:10],
            "pseudo_learning_penalties": list(dict.fromkeys(penalties))[:10],
            "entry_score_pseudo_learning_adjusted": round(entry_adjusted, 2),
            "signal_quality_pseudo_learning_adjusted": bool(signal_adjusted),
            "signal_quality_pseudo_learning_decision": str(signal_after),
            "entry_precision_pseudo_learning_adjusted": bool(precision_adjusted),
            "entry_precision_pseudo_learning_decision": str(precision_after),
            "learning_activation_pseudo_learning_adjusted": bool(learning_adjusted),
            "learning_activation_pseudo_learning_decision": str(learning_after),
        }

    def _learning_activation_context_policy_engine_v1(row):
        r = dict(row or {})
        reasons = []
        penalties = []
        support = 0.0
        penalty = 0.0

        setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower()
        setup_score = max(0.0, min(100.0, _to_float(r.get("setup_detection_score"), 0.0)))
        setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
        entry_quality_score = max(0.0, min(100.0, _to_float(r.get("entry_quality_score"), 0.0)))
        signal_quality_score = max(0.0, min(100.0, _to_float(r.get("signal_quality_score"), 0.0)))
        signal_quality_band = str(r.get("signal_quality_band") or "poor").strip().lower()
        signal_quality_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
        signal_quality_penalties = list(r.get("signal_quality_penalties") or [])
        entry_timing_decision = str(r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
        entry_timing_score = max(0.0, min(100.0, _to_float(r.get("entry_timing_score"), 0.0)))
        historical_hint = str(r.get("historical_policy_action_hint") or "allow_normal_review").strip().lower()
        historical_label = str(r.get("historical_policy_influence_label") or "neutral").strip().lower()
        historical_policy_class = str(r.get("historical_policy_setup_policy") or "none").strip().lower()
        historical_strength = max(0.0, min(100.0, _to_float(r.get("historical_policy_setup_strength"), 0.0)))
        replay_conf = str(r.get("historical_policy_replay_confidence") or "not_available").strip().lower()
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        consensus_strength = _to_float(r.get("consensus_strength"), 50.0)
        context_decision = str(r.get("context_activation_decision") or "watchlist").strip().lower()
        limited_data_mode = bool(r.get("limited_data_mode", False))
        conf_pct = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
        conf_pct = conf_pct * 100.0 if conf_pct <= 1.0 else conf_pct
        trade_quality = max(0.0, min(100.0, _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))))

        setup_alignment = "unknown"
        if setup_type == "momentum_breakout":
            setup_alignment = "favor"
            support += 1.8
            reasons.append("historical_setup_family_favored")
        elif setup_type in {"range_rotation", "trend_continuation"}:
            setup_alignment = "avoid"
            penalty += 2.0
            penalties.append("historical_setup_family_weak")
        elif setup_type == "fallback_unclear":
            setup_alignment = "avoid"
            penalty += 2.6
            penalties.append("fallback_setup_strong_penalty")
        elif setup_type == "squeeze_breakout":
            setup_alignment = "conditional"
            penalty += 0.7
            reasons.append("squeeze_breakout_requires_confirmation")
        else:
            setup_alignment = "neutral"

        if historical_policy_class in {"favor", "allow"} and historical_label in {"supportive", "neutral"}:
            support += 0.9
            reasons.append("historical_policy_supportive")
        elif historical_policy_class in {"avoid", "paper_only"} or historical_hint in {"avoid_for_now", "monitor_only", "paper_only"}:
            penalty += 1.6
            penalties.append("historical_policy_caution")
        elif historical_policy_class == "confirmation_required" or historical_hint == "require_confirmation":
            penalty += 0.8
            penalties.append("historical_policy_requires_confirmation")

        if signal_quality_decision == "reject":
            penalty += 2.6
            penalties.append("signal_quality_reject")
        elif signal_quality_decision in {"monitor_only", "watchlist_only"}:
            penalty += 1.4
            penalties.append("signal_quality_restrictive")
        elif signal_quality_decision == "allow_with_confirmation":
            penalty += 0.6
            reasons.append("signal_quality_confirmation_only")
        elif signal_quality_decision == "allow":
            support += 0.8
            reasons.append("signal_quality_supportive")

        if entry_timing_decision in {"avoid_for_now", "avoid_chase"}:
            penalty += 2.0
            penalties.append("entry_timing_avoid_state")
        elif entry_timing_decision in {"wait_for_pullback", "wait_for_confirmation"}:
            penalty += 0.6
            reasons.append("entry_timing_requires_patience")
        elif entry_timing_decision == "immediate" and entry_timing_score >= 70.0:
            support += 0.6
            reasons.append("entry_timing_supportive")

        if setup_score < 50.0 or setup_band in {"poor", "weak"}:
            penalty += 1.4
            penalties.append("setup_detection_weak")
        elif setup_score >= 62.0 and setup_band in {"moderate", "strong", "elite"}:
            support += 0.9
            reasons.append("setup_detection_aligned")

        if disagreement >= 52.0:
            penalty += 1.0
            penalties.append("persona_disagreement_high")
        elif disagreement <= 38.0:
            support += 0.5
            reasons.append("persona_disagreement_low")
        if consensus_strength >= 64.0:
            support += 0.6
            reasons.append("consensus_strength_supportive")
        elif consensus_strength < 48.0:
            penalty += 0.7
            penalties.append("consensus_strength_weak")
        if majority_signal in {"avoid", "sell", "strong sell"}:
            penalty += 1.2
            penalties.append("majority_signal_avoid")

        if entry_quality_score >= 60.0:
            support += 0.6
            reasons.append("entry_quality_supportive")
        elif entry_quality_score < 48.0:
            penalty += 0.8
            penalties.append("entry_quality_weak")
        if signal_quality_score >= 62.0 and signal_quality_band in {"moderate", "strong", "elite"}:
            support += 0.6
        elif signal_quality_score < 45.0:
            penalty += 0.7

        if conf_pct >= 75.0 and trade_quality >= 64.0:
            support += 0.4
        elif conf_pct < 60.0 or trade_quality < 55.0:
            penalty += 0.5

        replay_weight = 1.0
        if replay_conf == "moderate":
            replay_weight = 1.0
        elif replay_conf == "limited":
            replay_weight = 0.75
        else:
            replay_weight = 0.55

        raw_score = 50.0 + ((support - penalty) * 11.0 * replay_weight) + ((historical_strength - 50.0) * 0.04)
        score = max(0.0, min(100.0, raw_score))
        if score >= 63.0:
            band = "strong"
        elif score >= 45.0:
            band = "moderate"
        else:
            band = "weak"

        if score < 40.0 or setup_alignment == "avoid":
            decision = "suppress"
        elif score < 50.0 or signal_quality_decision in {"monitor_only", "watchlist_only"}:
            decision = "caution"
        elif score >= 62.0 and setup_alignment in {"favor", "neutral"}:
            decision = "support"
        else:
            decision = "neutral"

        if signal_quality_decision == "reject" or entry_timing_decision in {"avoid_for_now", "avoid_chase"}:
            decision = "suppress" if score < 58.0 else "caution"
        if setup_type == "squeeze_breakout" and decision == "support":
            decision = "neutral"
            penalties.append("squeeze_breakout_confirmation_bias")

        original_decision = str(decision)
        limited_data_adjusted = False
        missing_data_reject = bool(
            signal_quality_decision == "reject"
            and any(
                any(tok in str(p).lower() for tok in ("missing_", "history", "stale_quote", "enriched_signal_not_ready"))
                for p in signal_quality_penalties
            )
        )
        if (
            decision == "suppress"
            and limited_data_mode
            and missing_data_reject
            and setup_band not in {"poor"}
            and entry_quality_score >= 45.0
            and context_decision not in {"block", "observe_only"}
            and not (majority_signal in {"avoid", "sell", "strong sell"} and disagreement >= 52.0)
        ):
            decision = "caution"
            limited_data_adjusted = True
            reasons.append("limited_data_mode_suppress_downgraded_to_caution")
            penalties.append("limited_data_mode_missing_evidence_bias")

        if decision == "support":
            effect = 2.4
        elif decision == "neutral":
            effect = 0.0
        elif decision == "caution":
            effect = -2.2
        else:
            effect = -5.4

        if signal_quality_decision == "allow_with_confirmation" and effect > 1.2:
            effect = 1.2
        if historical_hint in {"require_confirmation", "paper_only"} and effect > 0.8:
            effect = 0.8
        if signal_quality_decision == "reject" and effect > 0:
            effect = 0.0
        if entry_timing_decision in {"avoid_for_now", "avoid_chase"} and effect > 0:
            effect = 0.0

        evidence_conf = max(
            0.10,
            min(
                1.0,
                ((1.0 if replay_conf == "moderate" else (0.7 if replay_conf == "limited" else 0.45)) * 0.45)
                + ((historical_strength / 100.0) * 0.30)
                + ((min(100.0, max(0.0, signal_quality_score + setup_score + entry_timing_score)) / 300.0) * 0.25),
            ),
        )

        return {
            "learning_activation_score": round(score, 2),
            "learning_activation_band": str(band),
            "learning_activation_decision": str(decision),
            "learning_activation_original_decision": str(original_decision),
            "learning_activation_limited_data_adjusted": bool(limited_data_adjusted),
            "learning_activation_reasons": list(dict.fromkeys(reasons))[:12],
            "learning_activation_penalties": list(dict.fromkeys(penalties))[:12],
            "learning_activation_setup_alignment": str(setup_alignment),
            "learning_activation_confidence": round(evidence_conf, 4),
            "learning_activation_policy_used": bool(
                str(historical_policy_class or "none") != "none" or bool(r.get("historical_policy_used", False))
            ),
            "learning_activation_effect_on_entry_score": round(max(-6.0, min(3.0, effect)), 3),
        }

    def _setup_detection_engine_v1(row, *, entry_score, trade_quality, confidence_pct):
        r = dict(row or {})
        reasons = []
        penalties = []
        missing_signals = 0

        def _indicator(name, default=None):
            nonlocal missing_signals
            v = r.get(name, default)
            if v is None:
                missing_signals += 1
                return default
            fv = _to_float(v, default)
            if fv is None:
                missing_signals += 1
            return fv

        conf_pct = max(0.0, min(100.0, _to_float(confidence_pct, 0.0)))
        quality_seed = max(0.0, min(100.0, _to_float(trade_quality, 0.0)))
        setup_type_raw = str(r.get("setup_type") or "").strip().lower()
        fallback_flag = bool(r.get("fallback_non_buy_candidate", False)) or bool(r.get("candidate_recovery_triggered", False))
        real_quoted_override = bool(r.get("buy_direction_real_quoted_candidate", False))

        price = _indicator("price", _indicator("current_price", None))
        sma20 = _indicator("sma_20", _indicator("ma20", None))
        sma50 = _indicator("sma_50", _indicator("ma50", None))
        ema9 = _indicator("ema_9", _indicator("ema9", None))
        vwap = _indicator("vwap", None)
        rsi = _indicator("rsi", None)
        macd = _indicator("macd", None)
        macd_signal = _indicator("macd_signal", None)
        rel_volume = _indicator("relative_volume", _indicator("rel_volume", _indicator("volume_ratio", None)))
        atr = _indicator("atr", _indicator("atr_value", None))
        breakout_distance_pct = _indicator("breakout_distance_pct", _indicator("distance_from_breakout_pct", None))
        entry_distance_pct = _indicator("entry_distance_pct", breakout_distance_pct)
        follow_state = str(r.get("follow_through_state") or "").strip().lower()
        confirmation_state = str(r.get("confirmation_state") or "").strip().lower()
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        uncertainty = _to_float(r.get("uncertainty_score"), 50.0)
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        prediction = str(r.get("prediction") or "").strip().lower()
        action = str(r.get("action") or "").strip().lower()
        majority_signal = str(r.get("majority_signal") or "").strip().lower()

        trend_support = 0.0
        momentum_support = 0.0
        volume_support = 0.0
        location_support = 0.0
        structure_support = 0.0
        contradiction_penalty = 0.0
        extension_penalty = 0.0
        fallback_penalty = 0.0
        missing_evidence_penalty = 0.0

        if price is not None and sma20 is not None:
            if price >= sma20:
                trend_support += 1.1
                reasons.append("trend_price_above_short_ma")
            else:
                contradiction_penalty += 1.1
                penalties.append("trend_price_below_short_ma")
        if sma20 is not None and sma50 is not None:
            if sma20 >= sma50:
                trend_support += 0.9
                reasons.append("trend_ma_alignment")
            else:
                contradiction_penalty += 0.9
                penalties.append("trend_ma_misaligned")
        if ema9 is not None and price is not None:
            if price >= ema9:
                trend_support += 0.5
            else:
                contradiction_penalty += 0.5

        if rsi is not None:
            if 50.0 <= rsi <= 70.0:
                momentum_support += 1.0
                reasons.append("momentum_rsi_supportive")
            elif rsi > 78.0:
                extension_penalty += 1.0
                penalties.append("momentum_rsi_overextended")
            elif rsi < 44.0:
                contradiction_penalty += 0.8
                penalties.append("momentum_rsi_weak")
        if macd is not None and macd_signal is not None:
            if macd >= macd_signal:
                momentum_support += 0.8
                reasons.append("momentum_macd_aligned")
            else:
                contradiction_penalty += 0.9
                penalties.append("momentum_macd_conflict")

        if rel_volume is not None:
            if rel_volume >= 1.35:
                volume_support += 1.3
                reasons.append("volume_participation_strong")
            elif rel_volume >= 1.05:
                volume_support += 0.6
                reasons.append("volume_participation_supportive")
            else:
                contradiction_penalty += 1.0
                penalties.append("volume_participation_weak")

        if price is not None and vwap is not None:
            if price >= vwap:
                location_support += 0.8
                reasons.append("location_above_vwap")
            else:
                contradiction_penalty += 0.8
                penalties.append("location_below_vwap")

        if confirmation_state in {"strong_confirmation", "confirmed"}:
            structure_support += 1.2
            reasons.append("structure_confirmation_strong")
        elif confirmation_state in {"weak_confirmation", "pending_confirmation"}:
            contradiction_penalty += 0.8
            penalties.append("structure_confirmation_weak")

        if breakout_distance_pct is not None:
            if 0.5 <= breakout_distance_pct <= 3.0:
                structure_support += 1.0
                reasons.append("structure_breakout_distance_clean")
            elif breakout_distance_pct > 3.8:
                extension_penalty += 1.1
                penalties.append("structure_chase_risk")
            elif breakout_distance_pct < 0.25:
                contradiction_penalty += 0.5
                penalties.append("structure_breakout_not_confirmed")

        if entry_distance_pct is not None and entry_distance_pct > 3.8:
            extension_penalty += 0.9
            penalties.append("entry_overextended")

        if follow_state in {"healthy_follow_through", "strong_follow_through", "confirmed_follow_through"}:
            structure_support += 0.9
            reasons.append("follow_through_supportive")
        elif "weak" in follow_state:
            contradiction_penalty += 0.9
            penalties.append("follow_through_weak")

        supportive_votes = sum(1 for x in (prediction, action, majority_signal) if x in {"buy", "strong buy", "buy candidate", "hold"})
        negative_votes = sum(1 for x in (prediction, action, majority_signal) if x in {"sell", "strong sell", "avoid"})
        if supportive_votes >= 2 and negative_votes == 0:
            structure_support += 0.8
            reasons.append("signal_direction_supportive")
        elif negative_votes > 0:
            contradiction_penalty += 1.2
            penalties.append("signal_direction_conflict")
        elif supportive_votes == 0:
            contradiction_penalty += 0.4
            penalties.append("signal_direction_thin")

        if atr is not None and price is not None and price > 0:
            atr_pct = (atr / price) * 100.0
            if 1.2 <= atr_pct <= 5.5:
                structure_support += 0.6
                reasons.append("volatility_expansion_healthy")
            elif atr_pct > 8.0:
                contradiction_penalty += 0.9
                penalties.append("volatility_chaotic")
            elif atr_pct < 0.5:
                contradiction_penalty += 0.4
                penalties.append("volatility_compressed")

        if setup_type_raw in {"fallback_unclear", "unclassified_setup"}:
            fallback_penalty += 1.2
            penalties.append("setup_family_fallback")
        if fallback_flag:
            fallback_penalty += 1.8
            penalties.append("fallback_recovery_row")
        if uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"}:
            contradiction_penalty += 0.8
            penalties.append("uncertainty_elevated")
        if disagreement >= 52.0:
            contradiction_penalty += 0.8
            penalties.append("persona_disagreement_high")

        missing_evidence_penalty = min(1.6, max(0.0, missing_signals * 0.18))
        if missing_evidence_penalty > 0.0:
            penalties.append("setup_evidence_incomplete")

        setup_score = max(
            0.0,
            min(
                100.0,
                28.0
                + (quality_seed * 0.26)
                + (_to_float(entry_score, 0.0) * 0.18)
                + (conf_pct * 0.10)
                + (trend_support * 11.0)
                + (momentum_support * 9.0)
                + (volume_support * 10.0)
                + (location_support * 8.0)
                + (structure_support * 12.0)
                - (contradiction_penalty * 11.0)
                - (extension_penalty * 9.5)
                - (fallback_penalty * 14.0)
                - (missing_evidence_penalty * 8.0),
            ),
        )

        evidence_ratio = max(0.0, min(1.0, 1.0 - (float(missing_signals) / 12.0)))
        coherent = contradiction_penalty < 1.8 and trend_support + structure_support + momentum_support >= 2.8
        if evidence_ratio < 0.33:
            evidence_label = "insufficient"
        elif evidence_ratio < 0.50:
            evidence_label = "thin_but_coherent" if coherent else "mixed"
        elif contradiction_penalty >= 2.4:
            evidence_label = "mixed"
        elif setup_score >= 72.0:
            evidence_label = "strongly_aligned"
        else:
            evidence_label = "aligned"

        detected_setup_type = "RANGE_OR_NO_EDGE"
        if fallback_flag or setup_type_raw in {"fallback_unclear", "unclassified_setup"}:
            detected_setup_type = "FALLBACK_UNCLEAR"
        else:
            if price is not None and vwap is not None and price >= vwap and confirmation_state in {"strong_confirmation", "confirmed"} and trend_support < 1.2:
                detected_setup_type = "RECLAIM_SETUP"
            if setup_score >= 66.0 and structure_support >= 2.2 and trend_support >= 1.4 and volume_support >= 0.8:
                detected_setup_type = "MOMENTUM_BREAKOUT"
            elif setup_score >= 60.0 and trend_support >= 2.0 and structure_support >= 1.2:
                detected_setup_type = "TREND_CONTINUATION"
            elif atr is not None and price is not None and price > 0 and ((atr / price) * 100.0) >= 1.8 and structure_support >= 1.4:
                detected_setup_type = "VOLATILITY_EXPANSION"
            elif str(r.get("sector_leadership_tone") or r.get("rotation_tone") or "").strip():
                detected_setup_type = "ROTATION_SETUP"

        if fallback_flag:
            candidate_realness = "fallback"
            setup_score = min(setup_score, 24.0)
        elif setup_type_raw in {"fallback_unclear", "unclassified_setup"}:
            candidate_realness = "degraded"
            setup_score = min(setup_score, 38.0)
        elif evidence_label in {"insufficient", "thin_but_coherent"} and setup_score < 66.0:
            candidate_realness = "thin_real"
            setup_score = max(42.0, min(setup_score, 68.0))
        elif setup_score >= 76.0 and contradiction_penalty <= 1.5:
            candidate_realness = "strong_real"
            setup_score = max(setup_score, 74.0)
        else:
            candidate_realness = "real"

        if setup_score >= 84.0:
            band = "elite"
        elif setup_score >= 70.0:
            band = "strong"
        elif setup_score >= 54.0:
            band = "moderate"
        elif setup_score >= 38.0:
            band = "weak"
        else:
            band = "poor"

        signal_profile = "aligned" if contradiction_penalty < 1.2 else ("mixed" if contradiction_penalty < 2.4 else "noisy")
        setup_confidence = max(
            0.10,
            min(
                1.0,
                (evidence_ratio * 0.55)
                + (max(0.0, 1.0 - (contradiction_penalty / 4.0)) * 0.25)
                + (max(0.0, min(1.0, setup_score / 100.0)) * 0.20),
            ),
        )
        structure_label = "structured" if structure_support >= 1.8 else ("developing" if structure_support >= 1.0 else "weak_or_choppy")
        summary = (
            f"{detected_setup_type} / {band}; realness={candidate_realness}; "
            f"trend={trend_support:.1f}, structure={structure_support:.1f}, "
            f"volume={volume_support:.1f}, contradiction={contradiction_penalty:.1f}, evidence={evidence_label}"
        )

        return {
            "detected_setup_type": str(detected_setup_type),
            "setup_detection_score": round(setup_score, 2),
            "setup_detection_band": str(band),
            "setup_detection_confidence": round(setup_confidence, 4),
            "setup_signal_profile": str(signal_profile),
            "setup_reasons": list(dict.fromkeys(reasons))[:10],
            "setup_penalties": list(dict.fromkeys(penalties))[:10],
            "setup_summary": summary,
            "setup_candidate_realness": str(candidate_realness),
            "setup_structure_label": str(structure_label),
            "setup_confirmation_state": str(confirmation_state or ("strong_confirmation" if setup_score >= 72.0 else "weak_confirmation")),
            "setup_detection_evidence_label": str(evidence_label),
            "setup_detection_missing_signal_count": int(missing_signals),
            "setup_detection_components": {
                "trend_support": round(trend_support, 3),
                "momentum_support": round(momentum_support, 3),
                "volume_support": round(volume_support, 3),
                "location_support": round(location_support, 3),
                "structure_support": round(structure_support, 3),
                "contradiction_penalty": round(contradiction_penalty, 3),
                "extension_penalty": round(extension_penalty, 3),
                "fallback_penalty": round(fallback_penalty, 3),
                "missing_evidence_penalty": round(missing_evidence_penalty, 3),
            },
        }

    def _entry_quality_engine_v1(row, *, entry_score, trade_quality, confidence_pct):
        r = dict(row or {})
        reasons = []
        penalties = []
        missing_signals = 0

        def _indicator(name, default=None):
            nonlocal missing_signals
            v = r.get(name, default)
            if v is None:
                missing_signals += 1
                return default
            fv = _to_float(v, default)
            if fv is None:
                missing_signals += 1
            return fv

        conf_pct = max(0.0, min(100.0, _to_float(confidence_pct, 0.0)))
        quality_seed = max(0.0, min(100.0, _to_float(trade_quality, 0.0)))
        setup_detection_score = _to_float(r.get("setup_detection_score"), None)
        if setup_detection_score is not None:
            quality_seed = max(0.0, min(100.0, (quality_seed * 0.72) + (setup_detection_score * 0.28)))
        setup_type = str(r.get("setup_type") or "").strip().lower()
        setup_candidate_realness = str(r.get("setup_candidate_realness") or "").strip().lower()
        fallback_flag = bool(r.get("fallback_non_buy_candidate", False)) or bool(r.get("candidate_recovery_triggered", False))
        prediction = str(r.get("prediction") or "").strip().lower()
        action = str(r.get("action") or "").strip().lower()
        majority_signal = str(r.get("majority_signal") or "").strip().lower()

        penalty_components = {
            "fallback_penalty": 0.0,
            "trend_penalty": 0.0,
            "breakout_penalty": 0.0,
            "volume_penalty": 0.0,
            "contradiction_penalty": 0.0,
            "extension_penalty": 0.0,
            "missing_evidence_penalty": 0.0,
        }
        positive_components = {
            "momentum_support": 0.0,
            "trend_support": 0.0,
            "volume_support": 0.0,
            "breakout_support": 0.0,
            "agreement_support": 0.0,
        }

        rsi = _indicator("rsi", None)
        macd = _indicator("macd", None)
        macd_signal = _indicator("macd_signal", None)
        macd_hist = _indicator("macd_histogram", None)
        momentum_score_seed = _to_float(r.get("momentum_score"), _to_float(r.get("momentum_quality_score"), None))
        if momentum_score_seed is None:
            momentum_score_seed = max(30.0, min(84.0, (quality_seed * 0.36) + (conf_pct * 0.24)))
        momentum_score = momentum_score_seed
        if rsi is not None:
            if 52.0 <= rsi <= 68.0:
                momentum_score += 6.0
                reasons.append("rsi_supportive_zone")
                positive_components["momentum_support"] += 6.0
            elif rsi > 78.0:
                momentum_score -= 8.0
                penalties.append("rsi_overextended")
                penalty_components["extension_penalty"] += 8.0
            elif rsi < 45.0:
                momentum_score -= 6.0
                penalties.append("rsi_weak")
                penalty_components["trend_penalty"] += 6.0
        if macd is not None and macd_signal is not None:
            if macd >= macd_signal:
                momentum_score += 5.0
                reasons.append("macd_aligned")
                positive_components["momentum_support"] += 5.0
            else:
                momentum_score -= 6.0
                penalties.append("macd_misaligned")
                penalty_components["contradiction_penalty"] += 6.0
        if macd_hist is not None and macd_hist < 0.0:
            momentum_score -= 3.5
            penalties.append("macd_histogram_negative")
            penalty_components["contradiction_penalty"] += 3.5
        momentum_score = max(0.0, min(100.0, momentum_score))

        sma20 = _indicator("sma_20", _indicator("ma20", None))
        sma50 = _indicator("sma_50", _indicator("ma50", None))
        ema9 = _indicator("ema_9", _indicator("ema9", None))
        price = _indicator("price", _indicator("current_price", None))
        trend_score = max(28.0, min(86.0, (quality_seed * 0.50) + (conf_pct * 0.18)))
        if price is not None and sma20 is not None:
            if price >= sma20:
                trend_score += 6.0
                reasons.append("price_above_short_ma")
                positive_components["trend_support"] += 6.0
            else:
                trend_score -= 7.0
                penalties.append("price_below_short_ma")
                penalty_components["trend_penalty"] += 7.0
        if sma20 is not None and sma50 is not None:
            if sma20 >= sma50:
                trend_score += 4.5
                reasons.append("short_ma_above_mid_ma")
                positive_components["trend_support"] += 4.5
            else:
                trend_score -= 5.5
                penalties.append("ma_trend_misaligned")
                penalty_components["trend_penalty"] += 5.5
        if ema9 is not None and price is not None and price < ema9:
            trend_score -= 3.5
            penalties.append("price_below_fast_ema")
            penalty_components["trend_penalty"] += 3.5
        if str(r.get("follow_through_state") or "").strip().lower() in {"healthy_follow_through", "strong_follow_through", "confirmed_follow_through"}:
            trend_score += 4.0
            reasons.append("follow_through_trend_supportive")
            positive_components["trend_support"] += 4.0
        elif "weak" in str(r.get("follow_through_state") or "").strip().lower():
            trend_score -= 5.0
            penalties.append("follow_through_trend_weak")
            penalty_components["trend_penalty"] += 5.0
        trend_score = max(0.0, min(100.0, trend_score))

        rel_volume = _indicator("relative_volume", _indicator("rel_volume", _indicator("volume_ratio", None)))
        volume_score = max(24.0, min(84.0, (quality_seed * 0.34) + (conf_pct * 0.14)))
        if rel_volume is not None:
            if rel_volume >= 1.35:
                volume_score += 9.0
                reasons.append("relative_volume_strong")
                positive_components["volume_support"] += 9.0
            elif rel_volume >= 1.05:
                volume_score += 3.0
                reasons.append("relative_volume_supportive")
                positive_components["volume_support"] += 3.0
            else:
                volume_score -= 8.0
                penalties.append("relative_volume_weak")
                penalty_components["volume_penalty"] += 8.0
        if bool(r.get("signal_quality_gate_passed", False)):
            volume_score += 2.0
            reasons.append("signal_gate_confirmed")
            positive_components["volume_support"] += 2.0
        else:
            volume_score -= 3.5
            penalties.append("signal_gate_missing")
            penalty_components["volume_penalty"] += 3.5
        volume_score = max(0.0, min(100.0, volume_score))

        breakout_score = max(22.0, min(88.0, (quality_seed * 0.42) + (_to_float(entry_score, 0.0) * 0.28)))
        breakout_distance_pct = _indicator("breakout_distance_pct", None)
        entry_distance_pct = _indicator("entry_distance_pct", _indicator("distance_from_breakout_pct", None))
        confirmation_state = str(r.get("confirmation_state") or "").strip().lower()
        if confirmation_state in {"strong_confirmation", "confirmed"}:
            breakout_score += 7.0
            reasons.append("confirmation_state_strong")
            positive_components["breakout_support"] += 7.0
        elif confirmation_state in {"weak_confirmation", "pending_confirmation"}:
            breakout_score -= 5.5
            penalties.append("confirmation_state_weak")
            penalty_components["breakout_penalty"] += 5.5
        distance_for_chase = entry_distance_pct if entry_distance_pct is not None else breakout_distance_pct
        if distance_for_chase is not None:
            if distance_for_chase > 3.5:
                breakout_score -= 9.0
                penalties.append("entry_chase_risk")
                penalty_components["extension_penalty"] += 9.0
            elif distance_for_chase < 0.4:
                breakout_score -= 2.0
                penalties.append("breakout_not_confirmed")
                penalty_components["breakout_penalty"] += 2.0
            else:
                breakout_score += 3.0
                reasons.append("breakout_distance_reasonable")
                positive_components["breakout_support"] += 3.0
        if str(r.get("follow_through_state") or "").strip().lower() in {"weak_follow_through_risk", "weak_follow_through"}:
            breakout_score -= 5.0
            penalties.append("breakout_follow_through_weak")
            penalty_components["breakout_penalty"] += 5.0
        breakout_score = max(0.0, min(100.0, breakout_score))

        atr = _indicator("atr", _indicator("atr_value", None))
        volatility_score = max(30.0, min(82.0, (quality_seed * 0.30) + 35.0))
        if atr is not None and price is not None and price > 0:
            atr_pct = (atr / price) * 100.0
            if 1.2 <= atr_pct <= 5.2:
                volatility_score += 5.0
                reasons.append("atr_volatility_supportive")
                positive_components["breakout_support"] += 2.0
            elif atr_pct > 8.0:
                volatility_score -= 8.0
                penalties.append("volatility_chaotic")
                penalty_components["breakout_penalty"] += 4.0
            elif atr_pct < 0.6:
                volatility_score -= 4.0
                penalties.append("volatility_too_compressed")
                penalty_components["breakout_penalty"] += 2.0
        volatility_score = max(0.0, min(100.0, volatility_score))

        vwap = _indicator("vwap", None)
        vwap_score = max(26.0, min(82.0, (quality_seed * 0.30) + (conf_pct * 0.18)))
        if vwap is not None and price is not None:
            if price >= vwap:
                vwap_score += 6.0
                reasons.append("vwap_location_supportive")
                positive_components["trend_support"] += 2.0
            else:
                vwap_score -= 7.0
                penalties.append("below_vwap")
                penalty_components["trend_penalty"] += 4.0
        vwap_score = max(0.0, min(100.0, vwap_score))

        agreement_score = max(24.0, min(86.0, (quality_seed * 0.36) + 28.0))
        supportive_votes = sum(1 for x in (prediction, action, majority_signal) if x in {"buy", "strong buy", "hold", "buy candidate"})
        negative_votes = sum(1 for x in (prediction, action, majority_signal) if x in {"sell", "strong sell", "avoid"})
        if supportive_votes >= 2 and negative_votes == 0:
            agreement_score += 8.0
            reasons.append("signal_agreement_supportive")
            positive_components["agreement_support"] += 8.0
        elif negative_votes > 0:
            agreement_score -= 10.0
            penalties.append("signal_direction_conflict")
            penalty_components["contradiction_penalty"] += 10.0
        elif supportive_votes == 0:
            agreement_score -= 4.0
            penalties.append("signal_agreement_thin")
            penalty_components["contradiction_penalty"] += 4.0
        if bool(r.get("trusted_quote_for_buys", False)) and bool(r.get("valid_quote", False)):
            agreement_score += 3.0
            reasons.append("quote_trust_confirmed")
            positive_components["agreement_support"] += 3.0
        else:
            agreement_score -= 5.0
            penalties.append("quote_trust_missing")
            penalty_components["fallback_penalty"] += 5.0
        agreement_score = max(0.0, min(100.0, agreement_score))

        contradiction_penalty = 0.0
        if momentum_score < 48.0 and trend_score >= 64.0:
            contradiction_penalty += 3.0
            penalties.append("momentum_trend_conflict")
            penalty_components["contradiction_penalty"] += 3.0
        if volume_score < 45.0 and breakout_score >= 62.0:
            contradiction_penalty += 4.0
            penalties.append("breakout_without_volume")
            penalty_components["volume_penalty"] += 4.0
        if vwap_score < 45.0 and breakout_score >= 62.0:
            contradiction_penalty += 2.5
            penalties.append("breakout_below_vwap")
            penalty_components["contradiction_penalty"] += 2.5

        if setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalty_components["fallback_penalty"] += 10.0
            penalties.append("weak_setup_family")
        if setup_candidate_realness in {"fallback", "degraded"}:
            penalty_components["fallback_penalty"] += 6.0
            penalties.append("setup_detection_degraded")
        elif setup_candidate_realness == "strong_real":
            positive_components["agreement_support"] += 3.0
            reasons.append("setup_detection_strong_real")

        if fallback_flag:
            penalty_components["fallback_penalty"] += 20.0
            penalties.append("fallback_recovery_row")

        missing_signal_penalty = min(8.0, max(0.0, missing_signals * 0.75))
        if missing_signal_penalty > 0.0:
            penalties.append("indicator_evidence_incomplete")
            penalty_components["missing_evidence_penalty"] += missing_signal_penalty

        entry_quality_score = max(
            0.0,
            min(
                100.0,
                (momentum_score * 0.13)
                + (trend_score * 0.22)
                + (volume_score * 0.16)
                + (breakout_score * 0.22)
                + (volatility_score * 0.10)
                + (vwap_score * 0.08)
                + (agreement_score * 0.09)
                - contradiction_penalty
                - missing_signal_penalty
                - (penalty_components["fallback_penalty"] * 0.60)
                - (penalty_components["trend_penalty"] * 0.18)
                - (penalty_components["breakout_penalty"] * 0.18)
                - (penalty_components["volume_penalty"] * 0.16)
                - (penalty_components["extension_penalty"] * 0.22),
            ),
        )

        evidence_ratio = max(0.0, min(1.0, 1.0 - (float(missing_signals) / 12.0)))
        if evidence_ratio < 0.35:
            evidence_label = "insufficient"
        elif evidence_ratio < 0.52:
            evidence_label = "thin_but_coherent"
        elif contradiction_penalty >= 6.0:
            evidence_label = "mixed"
        elif entry_quality_score >= 72.0:
            evidence_label = "strongly_aligned"
        else:
            evidence_label = "aligned"

        if fallback_flag:
            candidate_class = "fallback_recovery"
        elif setup_type in {"fallback_unclear", "unclassified_setup"}:
            candidate_class = "degraded_candidate"
        elif evidence_label in {"insufficient", "thin_but_coherent"} and entry_quality_score < 65.0:
            candidate_class = "real_but_thin"
        elif entry_quality_score >= 76.0 and contradiction_penalty < 4.0:
            candidate_class = "strong_candidate"
        else:
            candidate_class = "real_candidate"

        if candidate_class == "fallback_recovery":
            entry_quality_score = min(entry_quality_score, 24.0)
        elif candidate_class == "degraded_candidate":
            entry_quality_score = min(entry_quality_score, 38.0)
        elif candidate_class == "real_but_thin":
            entry_quality_score = max(42.0, min(entry_quality_score, 68.0))
        elif candidate_class == "strong_candidate":
            entry_quality_score = max(entry_quality_score, 72.0)

        if entry_quality_score >= 84.0:
            band = "elite"
        elif entry_quality_score >= 70.0:
            band = "strong"
        elif entry_quality_score >= 54.0:
            band = "moderate"
        elif entry_quality_score >= 38.0:
            band = "weak"
        else:
            band = "poor"

        adjusted_entry_score = max(0.0, min(100.0, (_to_float(entry_score, 0.0) * 0.62) + (entry_quality_score * 0.38)))
        suppression_bias = 0.0
        if band == "poor":
            suppression_bias = 1.0
        elif band == "weak":
            suppression_bias = 0.65
        elif band == "moderate":
            suppression_bias = 0.30

        primary_driver = max(
            positive_components.items(),
            key=lambda kv: kv[1],
        )[0] if positive_components else "none"
        primary_penalty = max(
            penalty_components.items(),
            key=lambda kv: kv[1],
        )[0] if penalty_components else "none"
        signal_profile = "aligned_signals" if contradiction_penalty < 3.0 else ("mixed_signals" if contradiction_penalty < 7.0 else "contradictory_signals")
        summary = (
            f"{band} setup quality ({candidate_class}); "
            f"trend={trend_score:.0f}, breakout={breakout_score:.0f}, volume={volume_score:.0f}, "
            f"agreement={agreement_score:.0f}, evidence={evidence_label}"
        )

        return {
            "momentum_score": round(momentum_score, 2),
            "trend_score": round(trend_score, 2),
            "volume_score": round(volume_score, 2),
            "breakout_score": round(breakout_score, 2),
            "volatility_score": round(volatility_score, 2),
            "vwap_score": round(vwap_score, 2),
            "agreement_score": round(agreement_score, 2),
            "entry_quality_score": round(entry_quality_score, 2),
            "entry_quality_band": str(band),
            "entry_quality_reasons": list(dict.fromkeys(reasons))[:10],
            "entry_quality_penalties": list(dict.fromkeys(penalties))[:10],
            "entry_quality_summary": summary,
            "entry_quality_candidate_class": str(candidate_class),
            "entry_quality_primary_driver": str(primary_driver),
            "entry_quality_primary_penalty": str(primary_penalty),
            "entry_quality_signal_profile": str(signal_profile),
            "entry_quality_evidence_label": str(evidence_label),
            "entry_quality_penalty_components": {
                k: round(_to_float(v, 0.0), 3) for k, v in penalty_components.items()
            },
            "entry_quality_adjusted_entry_score": round(adjusted_entry_score, 2),
            "entry_quality_suppression_bias": round(suppression_bias, 3),
            "entry_quality_missing_signal_count": int(missing_signals),
        }

    def _entry_activation_v1(row, *, entry_score, confidence_pct):
        r = dict(row or {})
        reasons = []
        support = 0.0
        penalty = 0.0

        entry_edge = _to_float(r.get("entry_edge_score"), _to_float(confidence_calibration.get("entry_edge_score"), 0.0))
        conf_cal = _to_float(r.get("confidence_calibrated"), 0.0)
        conf_pct = _to_float(confidence_pct, 0.0)
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        uncertainty_score = _to_float(r.get("uncertainty_score"), 50.0)
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        entry_penalty = _to_float(r.get("entry_intelligence_penalty"), 0.0)
        context_score = _to_float(r.get("context_intelligence_score"), 50.0)
        context_penalty = _to_float(r.get("context_penalty"), 0.0)
        follow_score = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(confidence_calibration.get("follow_through_entry_score"), 0.0),
        )
        trade_quality = _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))
        setup_type = str(r.get("setup_type") or "").strip().lower()
        execution_evidence = _to_float(
            r.get("execution_evidence_count"),
            _to_float(entry_conversion_feedback.get("execution_evidence_count"), _to_float(confidence_calibration.get("execution_evidence_count"), 0.0)),
        )
        released_vs_blocked_delta = _to_float(
            confidence_calibration.get("released_vs_blocked_win_rate_delta"),
            _to_float(entry_conversion_feedback.get("released_vs_blocked_win_rate_delta"), 0.0),
        )

        evidence_confidence = max(
            0.10,
            min(
                1.0,
                min(
                    _to_float(confidence_calibration.get("evidence_confidence"), 0.0) or 1.0,
                    _to_float(entry_conversion_feedback.get("evidence_confidence"), 0.0) or 1.0,
                ),
            ),
        )

        if entry_edge >= 0.08:
            support += 1.6
            reasons.append("entry_edge_strong")
        elif entry_edge >= 0.05:
            support += 0.8
            reasons.append("entry_edge_moderate")
        else:
            penalty += 1.6
            reasons.append("entry_edge_weak")

        if conf_cal >= 0.82:
            support += 1.3
            reasons.append("confidence_calibrated_high")
        elif conf_cal >= 0.72:
            support += 0.5
            reasons.append("confidence_calibrated_supportive")
        else:
            penalty += 1.3
            reasons.append("confidence_calibrated_weak")

        if disagreement <= 36.0:
            support += 1.0
            reasons.append("disagreement_low")
        elif disagreement >= 52.0:
            penalty += 1.5
            reasons.append("disagreement_high")
        else:
            penalty += 0.4
            reasons.append("disagreement_moderate")

        if uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"} or uncertainty_score >= 66.0:
            penalty += 2.0
            reasons.append("uncertainty_elevated")
        elif uncertainty_tier == "moderate_uncertainty" or uncertainty_score >= 54.0:
            penalty += 0.9
            reasons.append("uncertainty_moderate")
        else:
            support += 0.8
            reasons.append("uncertainty_low")

        if context_score >= 66.0:
            support += 1.0
            reasons.append("context_supportive")
        elif context_score < 50.0:
            penalty += 1.1
            reasons.append("context_weak")
        penalty += min(1.8, max(0.0, context_penalty * 0.8))

        if follow_score >= 68.0:
            support += 1.0
            reasons.append("follow_through_strong")
        elif follow_score < 58.0:
            penalty += 1.1
            reasons.append("follow_through_weak")

        if trade_quality >= 68.0:
            support += 0.7
            reasons.append("trade_quality_supportive")
        elif trade_quality < 58.0:
            penalty += 0.8
            reasons.append("trade_quality_weak")

        if execution_evidence >= 260.0 and evidence_confidence >= 0.34:
            support += 0.7
            reasons.append("execution_evidence_strong")
        elif execution_evidence < 120.0 or evidence_confidence < 0.28:
            penalty += 0.9
            reasons.append("execution_evidence_weak")

        if released_vs_blocked_delta >= 1.0:
            support += 0.6
            reasons.append("released_vs_blocked_positive")
        elif released_vs_blocked_delta < 0.0:
            penalty += 0.8
            reasons.append("released_vs_blocked_negative")

        if entry_penalty >= 7.0:
            penalty += 2.2
            reasons.append("entry_intelligence_penalty_high")
        elif entry_penalty >= 4.0:
            penalty += 1.3
            reasons.append("entry_intelligence_penalty_moderate")

        if setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalty += 1.4
            reasons.append("weak_setup_family")

        activation_score = max(
            0.0,
            min(
                100.0,
                52.0
                + ((entry_score - 60.0) * 0.25)
                + (entry_edge * 200.0 * 0.24)
                + ((conf_pct - 60.0) * 0.08)
                + ((context_score - 50.0) * 0.10)
                + (support * 5.6)
                - (penalty * 6.6),
            ),
        )

        high_activation = bool(
            activation_score >= 78.0
            and entry_edge >= 0.08
            and conf_cal >= 0.80
            and disagreement <= 36.0
            and uncertainty_tier not in {"moderate_uncertainty", "high_uncertainty", "extreme_uncertainty"}
            and uncertainty_score <= 40.0
            and context_score >= 66.0
            and follow_score >= 68.0
            and execution_evidence >= 220.0
            and entry_penalty < 2.5
        )
        block_activation = bool(
            activation_score < 42.0
            or entry_edge < 0.02
            or entry_penalty >= 7.0
            or uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"}
            or uncertainty_score >= 72.0
            or context_score < 44.0
            or setup_type in {"fallback_unclear", "unclassified_setup"}
        )

        if high_activation:
            decision = "activate"
            conviction_tier = "high"
            entry_mode = "immediate" if disagreement <= 34.0 and uncertainty_score <= 36.0 else "confirmation"
        elif block_activation:
            decision = "block"
            conviction_tier = "none"
            entry_mode = "skip"
        elif activation_score >= 60.0:
            decision = "conditional"
            conviction_tier = "moderate"
            entry_mode = "wait_pullback" if (
                disagreement >= 44.0
                or uncertainty_tier == "moderate_uncertainty"
                or uncertainty_score >= 52.0
                or context_score < 58.0
            ) else "confirmation"
        else:
            decision = "conditional"
            conviction_tier = "low"
            entry_mode = "wait_pullback"

        return {
            "entry_activation_score": round(activation_score, 2),
            "entry_activation_decision": str(decision),
            "conviction_tier": str(conviction_tier),
            "entry_mode": str(entry_mode),
            "entry_activation_reasons": list(dict.fromkeys(reasons)),
            "entry_activation_evidence_confidence": round(evidence_confidence, 4),
            "promotion_support_bias": round(0.8 if (decision == "activate" and conviction_tier == "high") else 0.0, 3),
        }

    def _entry_execution_intelligence_v1(row, *, entry_score, confidence_pct):
        r = dict(row or {})
        reasons = []
        penalty = 0.0
        support = 0.0
        context_eval = _context_intelligence_v1(r)
        context_score = _to_float(context_eval.get("context_intelligence_score"), 50.0)
        context_penalty = _to_float(context_eval.get("context_penalty"), 0.0)
        context_support = _to_float(context_eval.get("context_support"), 0.0)
        context_reasons = list(context_eval.get("context_reasons") or [])
        context_evidence_conf = _to_float(context_eval.get("context_evidence_confidence"), 0.0)
        reasons.extend(context_reasons)

        entry_edge = _to_float(r.get("entry_edge_score"), _to_float(confidence_calibration.get("entry_edge_score"), 0.0))
        conf_calibrated = _to_float(r.get("confidence_calibrated"), 0.0)
        conf_pct = _to_float(confidence_pct, 0.0)
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        uncertainty_score = _to_float(r.get("uncertainty_score"), 50.0)
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        entry_intel_penalty = _to_float(r.get("entry_intelligence_penalty"), 0.0)
        follow_through_score = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(confidence_calibration.get("follow_through_entry_score"), 0.0),
        )
        execution_evidence = _to_float(
            entry_conversion_feedback.get("execution_evidence_count"),
            _to_float(confidence_calibration.get("execution_evidence_count"), 0.0),
        )
        released_vs_blocked_delta = _to_float(
            confidence_calibration.get("released_vs_blocked_win_rate_delta"),
            _to_float(entry_conversion_feedback.get("released_vs_blocked_win_rate_delta"), 0.0),
        )
        evidence_confidence = max(
            0.10,
            min(
                1.0,
                min(
                    _to_float(confidence_calibration.get("evidence_confidence"), 0.0) or 1.0,
                    _to_float(entry_conversion_feedback.get("evidence_confidence"), 0.0) or 1.0,
                ),
            ),
        )

        if entry_edge < 0.02:
            penalty += 2.2
            reasons.append("entry_edge_weak")
        elif entry_edge < 0.05:
            penalty += 1.1
            reasons.append("entry_edge_moderate")
        elif entry_edge >= 0.08:
            support += 1.2
            reasons.append("entry_edge_strong")

        if conf_calibrated >= 0.82:
            support += 1.0
            reasons.append("confidence_calibrated_high")
        elif conf_calibrated < 0.64:
            penalty += 1.2
            reasons.append("confidence_calibrated_weak")

        if disagreement >= 52.0:
            penalty += 1.5
            reasons.append("persona_disagreement_high")
        elif disagreement >= 46.0:
            penalty += 0.7
            reasons.append("persona_disagreement_moderate")
        elif disagreement <= 36.0:
            support += 0.8
            reasons.append("persona_disagreement_low")

        if uncertainty_tier in {"extreme_uncertainty", "high_uncertainty"}:
            penalty += 2.2
            reasons.append("uncertainty_high")
        elif uncertainty_tier == "moderate_uncertainty" or uncertainty_score >= 58.0:
            penalty += 1.0
            reasons.append("uncertainty_moderate")
        elif uncertainty_score <= 36.0:
            support += 0.8
            reasons.append("uncertainty_low")

        if follow_through_score >= 68.0:
            support += 0.9
            reasons.append("follow_through_strong")
        elif follow_through_score < 58.0:
            penalty += 1.2
            reasons.append("follow_through_weak")

        if execution_evidence >= 260.0 and evidence_confidence >= 0.36:
            support += 0.6
            reasons.append("execution_evidence_strong")
        elif execution_evidence < 120.0 or evidence_confidence < 0.30:
            penalty += 1.0
            reasons.append("execution_evidence_weak")

        if released_vs_blocked_delta >= 1.0:
            support += 0.5
            reasons.append("released_vs_blocked_positive")
        elif released_vs_blocked_delta < 0.0:
            penalty += 0.8
            reasons.append("released_vs_blocked_negative")

        if entry_intel_penalty >= 7.0:
            penalty += 2.0
            reasons.append("entry_intelligence_penalty_high")
        elif entry_intel_penalty >= 4.0:
            penalty += 1.1
            reasons.append("entry_intelligence_penalty_moderate")
        penalty += min(2.4, max(0.0, context_penalty * 0.85))
        support += min(1.2, max(0.0, context_support * 0.70))

        activation = _entry_activation_v1(
            r,
            entry_score=entry_score,
            confidence_pct=conf_pct,
        )
        activation_score = _to_float(activation.get("entry_activation_score"), 0.0)
        activation_decision = str(activation.get("entry_activation_decision") or "conditional")
        activation_conviction = str(activation.get("conviction_tier") or "low")
        activation_mode = str(activation.get("entry_mode") or "confirmation")
        activation_reasons = list(activation.get("entry_activation_reasons") or [])
        activation_evidence_conf = _to_float(activation.get("entry_activation_evidence_confidence"), evidence_confidence)
        reasons.extend(activation_reasons)

        timing_score = max(
            0.0,
            min(
                100.0,
                54.0
                + ((entry_score - 60.0) * 0.32)
                + (entry_edge * 220.0 * 0.20)
                + ((conf_pct - 60.0) * 0.10)
                + (support * 6.0)
                - (penalty * 7.5),
            ),
        )
        timing_score = max(0.0, min(100.0, timing_score + ((context_score - 50.0) * 0.14)))
        timing_score = max(0.0, min(100.0, (timing_score * 0.70) + (activation_score * 0.30)))
        execution_confidence = max(0.10, min(1.0, activation_evidence_conf * 0.55 + (timing_score / 100.0) * 0.45))

        immediate_ready = bool(
            timing_score >= 75.0
            and entry_edge >= 0.08
            and conf_calibrated >= 0.80
            and disagreement <= 36.0
            and uncertainty_tier not in {"moderate_uncertainty", "high_uncertainty", "extreme_uncertainty"}
            and uncertainty_score <= 40.0
            and follow_through_score >= 68.0
            and execution_evidence >= 220.0
            and entry_intel_penalty < 2.5
        )
        skip_ready = bool(
            timing_score < 44.0
            or entry_edge < 0.02
            or entry_intel_penalty >= 7.0
            or uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"}
            or context_score < 40.0
            or (execution_evidence < 90.0 and evidence_confidence < 0.30)
        )
        if activation_decision == "block":
            skip_ready = True

        if skip_ready:
            entry_mode = "skip"
            entry_reason = "entry_execution_skip_weak_or_uncertain"
        elif activation_decision == "activate":
            entry_mode = "immediate" if activation_mode == "immediate" else "confirmation"
            entry_reason = "entry_activation_high_conviction"
        elif immediate_ready:
            entry_mode = "immediate"
            entry_reason = "entry_execution_immediate_clean_high_conviction"
        elif timing_score >= 58.0 and (
            disagreement >= 42.0
            or uncertainty_tier in {"moderate_uncertainty", "high_uncertainty"}
            or uncertainty_score >= 50.0
            or follow_through_score < 64.0
            or context_score < 58.0
        ):
            entry_mode = "wait_pullback"
            entry_reason = "entry_execution_wait_pullback_for_structure"
        else:
            entry_mode = "confirmation"
            entry_reason = "entry_execution_confirmation_required"

        if activation_conviction == "none" or entry_mode == "skip":
            conviction_tier = "none"
        elif activation_conviction == "high" and entry_mode in {"immediate", "confirmation"} and timing_score >= 72.0:
            conviction_tier = "high"
        elif activation_conviction in {"high", "moderate"} and timing_score >= 56.0 and entry_mode in {"confirmation", "wait_pullback"}:
            conviction_tier = "moderate"
        else:
            conviction_tier = "low"

        return {
            "entry_timing_score": round(timing_score, 2),
            "entry_mode": str(entry_mode),
            "conviction_tier": str(conviction_tier),
            "entry_activation_score": round(activation_score, 2),
            "entry_activation_decision": str(activation_decision),
            "entry_activation_reasons": list(dict.fromkeys(activation_reasons)),
            "entry_activation_evidence_confidence": round(activation_evidence_conf, 4),
            "entry_activation_support_bias": _to_float(activation.get("promotion_support_bias"), 0.0),
            "entry_execution_reason": str(entry_reason),
            "entry_execution_reasons": list(dict.fromkeys(reasons)),
            "entry_execution_confidence": round(execution_confidence, 4),
            "context_intelligence_score": round(context_score, 2),
            "context_penalty": round(context_penalty, 3),
            "context_support": round(context_support, 3),
            "context_reasons": list(dict.fromkeys(context_reasons)),
            "context_evidence_confidence": round(context_evidence_conf, 4),
        }

    def _entry_intelligence_promotion_v2(row, *, entry_score, trade_quality, conf_pct):
        r = dict(row or {})
        setup_type = str(r.get("setup_type") or "").strip().lower()
        follow_state = str(r.get("follow_through_state") or "").strip().lower()
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        uncertainty_score = _to_float(r.get("uncertainty_score"), 50.0)
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        discipline_action = str(r.get("core_decision_discipline_action") or "").strip().lower()
        discipline_tier = str(r.get("core_decision_discipline_tier") or "").strip().lower()

        exec_evidence = _to_float(entry_conversion_feedback.get("execution_evidence_count"), 0.0)
        evidence_conf = max(
            0.10,
            min(
                1.0,
                min(
                    _to_float(entry_conversion_feedback.get("evidence_confidence"), 0.0) or 1.0,
                    _to_float(confidence_calibration.get("evidence_confidence"), 0.0) or 1.0,
                ),
            ),
        )
        entry_edge = _to_float(r.get("entry_edge_score"), _to_float(entry_conversion_feedback.get("entry_edge_score"), 0.0))
        released_vs_blocked = _to_float(
            confidence_calibration.get("released_vs_blocked_win_rate_delta"),
            _to_float(entry_conversion_feedback.get("released_vs_blocked_win_rate_delta"), 0.0),
        )
        follow_quality = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(entry_conversion_feedback.get("follow_through_entry_score"), 0.0),
        )
        calibration_score = _to_float(confidence_calibration.get("calibration_score"), 0.0)
        weak_reason_counts = dict(entry_conversion_feedback.get("weak_reason_counts") or {})

        penalty = 0.0
        reasons = []
        strong_markers = []

        if setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalty += 3.2
            reasons.append("weak_setup_family")
        if weak_reason_counts.get("setup_clarity_weak", 0) >= 30 and setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalty += 1.2
            reasons.append("learning_setup_clarity_weak")
        if disagreement >= 52.0:
            penalty += 2.4
            reasons.append("high_persona_disagreement")
        elif disagreement >= 46.0:
            penalty += 1.0
            reasons.append("moderate_persona_disagreement")
        if uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"}:
            penalty += 4.0
            reasons.append("uncertainty_tier_high")
        elif uncertainty_score >= 62.0:
            penalty += 1.6
            reasons.append("uncertainty_score_elevated")
        if discipline_action in {"watchlist_only", "reject"} or discipline_tier in {"monitor", "reject"}:
            penalty += 2.0
            reasons.append("discipline_conservative")
        if follow_state in {"weak_follow_through_risk", "deteriorating", "unclear_follow_through"}:
            penalty += 2.2
            reasons.append("weak_follow_through_profile")
        if entry_edge < 0.02:
            penalty += 1.8
            reasons.append("entry_edge_weak")
        elif entry_edge < 0.05:
            penalty += 0.8
            reasons.append("entry_edge_moderate")
        if released_vs_blocked < 0.0:
            penalty += 1.6
            reasons.append("released_vs_blocked_negative")
        if evidence_conf < 0.30 or exec_evidence < 120.0:
            penalty += 1.4
            reasons.append("low_execution_evidence")
        if calibration_score < 56.0:
            penalty += 0.9
            reasons.append("confidence_truthfulness_weak")

        if (
            setup_type not in {"fallback_unclear", "unclassified_setup"}
            and disagreement <= 40.0
            and follow_quality >= 66.0
            and entry_edge >= 0.06
            and released_vs_blocked >= 0.6
            and evidence_conf >= 0.38
            and trade_quality >= 64.0
            and entry_score >= 66.0
        ):
            strong_markers.append("clean_supported_entry_profile")
            penalty = max(0.0, penalty - 1.2)
        if conf_pct >= 78.0 and calibration_score >= 64.0:
            strong_markers.append("confidence_truthfulness_supported")

        penalty = max(0.0, min(14.0, penalty))
        intelligence_score = max(
            0.0,
            min(
                100.0,
                72.0
                + ((entry_score - 60.0) * 0.35)
                + ((trade_quality - 60.0) * 0.28)
                + ((conf_pct - 60.0) * 0.12)
                + ((follow_quality - 55.0) * 0.10)
                + (entry_edge * 40.0 * 0.08)
                + (released_vs_blocked * 0.05)
                - (penalty * 4.8),
            ),
        )

        promotion_adjustment = max(-8.0, min(1.5, -(penalty * 0.85)))
        if (
            penalty <= 1.5
            and intelligence_score >= 70.0
            and released_vs_blocked >= 1.0
            and evidence_conf >= 0.42
        ):
            promotion_adjustment = min(2.0, promotion_adjustment + 1.0)
            strong_markers.append("bounded_unlock_supported")

        return {
            "entry_intelligence_score": round(intelligence_score, 2),
            "entry_intelligence_penalty": round(penalty, 2),
            "promotion_adjustment_score": round(promotion_adjustment, 2),
            "entry_intelligence_reasons": list(dict.fromkeys(reasons)),
            "entry_intelligence_strong_markers": list(dict.fromkeys(strong_markers)),
            "entry_intelligence_evidence_confidence": round(evidence_conf, 4),
            "execution_evidence_count": int(exec_evidence),
        }

    def _promotion_gate_v2():
        tracked_total = _to_float(promotion_feedback.get("tracked_total"), 0.0)
        score = _to_float(promotion_feedback.get("promotion_feedback_score"), 0.0)
        continuation_rate = _to_float(promotion_feedback.get("continuation_rate_percent"), 0.0)
        deterioration_rate = _to_float(promotion_feedback.get("deterioration_rate_percent"), 0.0)
        early_obs_rate = _to_float(promotion_feedback.get("early_observation_rate_percent"), 100.0)
        avg_drawdown = _to_float(promotion_feedback.get("average_drawdown_from_peak_percent"), 0.0)
        maturity = str(promotion_feedback.get("maturity_signal") or "none").strip().lower()
        if tracked_total <= 0 or score < 38.0:
            return "BLOCK_WEAK_EVIDENCE", "promotion_feedback_score_too_low_for_release"
        if deterioration_rate >= 46.0 or avg_drawdown >= 2.4:
            return "BLOCK_HIGH_DETERIORATION", "lifecycle_deterioration_or_drawdown_elevated"
        if continuation_rate < 26.0 and deterioration_rate >= 28.0:
            return "BLOCK_LOW_CONTINUATION", "continuation_rate_too_low_vs_deterioration"
        if maturity in {"none", "early"} and early_obs_rate >= 62.0:
            return "BLOCK_TOO_EARLY", "lifecycle_evidence_still_early_observation"
        return "ALLOW", "promotion_feedback_supports_release"

    promotion_gate_decision, promotion_gate_reason = _promotion_gate_v2()

    def _buy_direction_refinement_v1(row, *, allow_non_buy_fallback=False):
        r = dict(row or {})
        reasons = []
        penalties = 0.0
        supports = 0.0

        action = str(r.get("action") or "").strip().lower()
        prediction = str(r.get("prediction") or "").strip().lower()
        majority = str(r.get("majority_signal") or "").strip().lower()
        directional_intent = float(sum(1 for v in (action, prediction, majority) if v in {"buy", "strong buy"}))

        conf = _to_float(r.get("confidence"), _to_float(r.get("predicted_win_probability"), 0.0))
        conf = conf if conf <= 1.0 else (conf / 100.0)
        conf = max(0.0, min(1.0, conf))
        consensus = _to_float(r.get("consensus_strength"), 0.0)
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        trade_quality = _to_float(r.get("trade_quality_score"), _to_float(r.get("buy_quality_score"), 0.0))
        setup_type = str(r.get("setup_type") or "").strip().lower()
        signal_gate = bool(r.get("signal_quality_gate_passed", False))
        trusted = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        entry_edge = _to_float(r.get("entry_edge_score"), _to_float(entry_conversion_feedback.get("entry_edge_score"), 0.0))
        follow_score = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(entry_conversion_feedback.get("follow_through_entry_score"), 0.0),
        )
        released_vs_blocked = _to_float(
            confidence_calibration.get("released_vs_blocked_win_rate_delta"),
            _to_float(entry_conversion_feedback.get("released_vs_blocked_win_rate_delta"), 0.0),
        )
        execution_evidence = _to_float(
            entry_conversion_feedback.get("execution_evidence_count"),
            _to_float(confidence_calibration.get("execution_evidence_count"), 0.0),
        )

        supports += directional_intent * 2.8
        if directional_intent >= 2.0:
            reasons.append("directional_consensus_present")
        elif directional_intent <= 0.0:
            penalties += 2.2
            reasons.append("no_buy_direction_signal")

        if trusted and valid_quote:
            supports += 1.2
            reasons.append("trusted_valid_quote")
        elif not trusted:
            penalties += 1.6
            reasons.append("quote_not_trusted")

        if signal_gate:
            supports += 1.0
            reasons.append("signal_quality_gate_passed")
        else:
            penalties += 1.1
            reasons.append("signal_quality_gate_missing")

        if trade_quality >= 68.0:
            supports += 1.2
            reasons.append("trade_quality_supportive")
        elif trade_quality < 58.0:
            penalties += 1.4
            reasons.append("trade_quality_weak")

        if conf >= 0.72:
            supports += 0.8
            reasons.append("confidence_supportive")
        elif conf < 0.62:
            penalties += 0.9
            reasons.append("confidence_weak")

        if consensus >= 62.0:
            supports += 0.7
            reasons.append("consensus_supportive")
        if disagreement >= 52.0:
            penalties += 1.1
            reasons.append("disagreement_high")
        elif disagreement <= 38.0:
            supports += 0.5
            reasons.append("disagreement_low")

        if entry_edge >= 0.06:
            supports += 0.9
            reasons.append("entry_edge_supportive")
        elif entry_edge < 0.02:
            penalties += 0.9
            reasons.append("entry_edge_weak")

        if follow_score >= 64.0:
            supports += 0.7
            reasons.append("follow_through_supportive")
        elif follow_score < 56.0:
            penalties += 0.8
            reasons.append("follow_through_weak")

        if released_vs_blocked >= 0.5:
            supports += 0.5
            reasons.append("released_vs_blocked_supportive")
        elif released_vs_blocked < 0.0:
            penalties += 0.7
            reasons.append("released_vs_blocked_negative")

        if execution_evidence < 120.0:
            penalties += 0.5
            reasons.append("execution_evidence_thin")

        if setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalties += 1.6
            reasons.append("weak_setup_family")

        score = max(
            0.0,
            min(
                100.0,
                52.0
                + (supports * 6.0)
                - (penalties * 7.0)
                + ((trade_quality - 60.0) * 0.22)
                + ((consensus - 50.0) * 0.10)
                + ((conf * 100.0 - 60.0) * 0.08),
            ),
        )

        is_buy_direction_candidate = bool(
            directional_intent >= 1.0
            and score >= 56.0
            and trusted
            and trade_quality >= 54.0
            and disagreement <= 60.0
        )
        keep_as_non_buy_fallback = bool(
            allow_non_buy_fallback
            and not is_buy_direction_candidate
            and score >= 58.0
            and trusted
            and conf >= 0.64
            and trade_quality >= 58.0
            and disagreement <= 50.0
            and setup_type not in {"fallback_unclear", "unclassified_setup"}
        )

        return {
            "buy_direction_refinement_score": round(score, 2),
            "buy_direction_quality_penalty": round(max(0.0, penalties), 3),
            "buy_direction_reason_count": int(len(set(reasons))),
            "buy_direction_reasons": list(dict.fromkeys(reasons)),
            "is_buy_direction_candidate": bool(is_buy_direction_candidate),
            "keep_as_non_buy_fallback": bool(keep_as_non_buy_fallback),
        }

    def _pre_entry_candidate_filter_v1(row, *, entry_score, trade_quality, confidence_pct):
        r = dict(row or {})
        reasons = []
        penalties = []
        penalty_score = 0.0

        conf_pct = max(0.0, min(100.0, _to_float(confidence_pct, 0.0)))
        entry_score_local = max(0.0, min(100.0, _to_float(entry_score, 0.0)))
        trade_quality_local = max(0.0, min(100.0, _to_float(trade_quality, 0.0)))
        disagreement = _to_float(r.get("persona_disagreement_index"), 50.0)
        uncertainty = _to_float(r.get("uncertainty_score"), 50.0)
        uncertainty_tier = str(r.get("uncertainty_tier") or "").strip().lower()
        entry_edge = _to_float(r.get("entry_edge_score"), 0.0)
        follow_score = _to_float(
            r.get("entry_followthrough_quality_score"),
            _to_float(r.get("follow_through_entry_score"), 0.0),
        )
        setup_type = str(r.get("setup_type") or "").strip().lower()
        confirmation_state = str(r.get("confirmation_state") or "").strip().lower()
        follow_state = str(r.get("follow_through_state") or "").strip().lower()
        trend_hint = str(r.get("trend_direction") or r.get("trend_state") or "").strip().lower()
        signal_gate = bool(r.get("signal_quality_gate_passed", False))
        trusted = bool(r.get("trusted_quote_for_buys", False))
        valid_quote = bool(r.get("valid_quote", False))
        rel_volume = _to_float(
            r.get("relative_volume"),
            _to_float(r.get("rel_volume"), _to_float(r.get("volume_ratio"), None)),
        )
        fallback_flag = bool(r.get("fallback_non_buy_candidate", False)) or bool(r.get("candidate_recovery_triggered", False))
        real_quoted_override = bool(r.get("buy_direction_real_quoted_candidate", False))
        action = str(r.get("action") or "").strip().lower()
        prediction = str(r.get("prediction") or "").strip().lower()
        majority_signal = str(r.get("majority_signal") or "").strip().lower()
        buy_direction_score = _to_float(r.get("buy_direction_refinement_score"), 0.0)
        buy_direction_candidate = bool(r.get("buy_direction_is_candidate", False))

        supportive_votes = sum(
            1 for x in (action, prediction, majority_signal)
            if x in {"buy", "strong buy", "buy candidate", "hold"}
        )
        negative_votes = sum(
            1 for x in (action, prediction, majority_signal)
            if x in {"sell", "strong sell", "avoid"}
        )

        support_score = 0.0
        if trusted and valid_quote:
            support_score += 1.2
            reasons.append("trusted_valid_quote")
        if signal_gate:
            support_score += 0.8
            reasons.append("signal_gate_passed")
        if supportive_votes >= 2 and negative_votes == 0:
            support_score += 0.8
            reasons.append("directional_intent_supportive")
        if trade_quality_local >= 62.0:
            support_score += 0.9
            reasons.append("trade_quality_supportive")
        if entry_score_local >= 60.0:
            support_score += 0.8
            reasons.append("entry_score_supportive")
        if conf_pct >= 68.0:
            support_score += 0.7
            reasons.append("confidence_supportive")
        if follow_score >= 58.0:
            support_score += 0.6
            reasons.append("follow_through_supportive")
        if entry_edge >= 0.035:
            support_score += 0.8
            reasons.append("entry_edge_supportive")
        if rel_volume is not None and rel_volume >= 1.05:
            support_score += 0.5
            reasons.append("volume_participation_supportive")
        if buy_direction_candidate or buy_direction_score >= 58.0:
            support_score += 0.7
            reasons.append("buy_direction_refinement_supportive")

        if fallback_flag:
            penalty_score += 2.1
            penalties.append("fallback_recovery_row")
        if setup_type in {"fallback_unclear", "unclassified_setup"}:
            penalty_score += 1.9
            penalties.append("fallback_non_buy_candidate")
        if negative_votes > 0:
            penalty_score += 1.7
            penalties.append("directional_signal_conflict")
        if not trusted or not valid_quote:
            penalty_score += 1.7
            penalties.append("quote_not_trusted_or_invalid")
        if trade_quality_local < 54.0:
            penalty_score += 1.0
            penalties.append("trade_quality_weak")
        if entry_score_local < 52.0:
            penalty_score += 0.9
            penalties.append("entry_score_weak")
        if conf_pct < 62.0:
            penalty_score += 0.9
            penalties.append("confidence_weak")
        if follow_score < 52.0:
            penalty_score += 0.8
            penalties.append("follow_through_weak")
        if entry_edge < 0.018:
            penalty_score += 0.9
            penalties.append("entry_edge_weak")
        if disagreement >= 54.0:
            penalty_score += 1.0
            penalties.append("disagreement_high")
        elif disagreement >= 48.0:
            penalty_score += 0.45
            penalties.append("disagreement_elevated")
        if uncertainty_tier in {"high_uncertainty", "extreme_uncertainty"} or uncertainty >= 70.0:
            penalty_score += 1.1
            penalties.append("uncertainty_high")
        elif uncertainty >= 60.0:
            penalty_score += 0.55
            penalties.append("uncertainty_elevated")
        if "weak" in confirmation_state or "weak" in follow_state:
            penalty_score += 0.6
            penalties.append("confirmation_or_followthrough_weak")
        if trend_hint in {"down", "downtrend", "bearish"}:
            penalty_score += 0.8
            penalties.append("trend_conflict")
        if rel_volume is not None and rel_volume < 0.85:
            penalty_score += 0.55
            penalties.append("volume_participation_weak")

        score = max(
            0.0,
            min(
                100.0,
                44.0
                + (entry_score_local * 0.20)
                + (trade_quality_local * 0.20)
                + (conf_pct * 0.14)
                + (max(0.0, min(100.0, buy_direction_score)) * 0.14)
                + (max(0.0, min(100.0, follow_score)) * 0.10)
                + (max(0.0, min(100.0, entry_edge * 1200.0)) * 0.12)
                + (support_score * 5.5)
                - (penalty_score * 8.0)
                - (max(0.0, disagreement - 44.0) * 0.25)
                - (max(0.0, uncertainty - 50.0) * 0.22),
            ),
        )

        hard_reject = bool(
            fallback_flag
            or (setup_type in {"fallback_unclear", "unclassified_setup"} and not real_quoted_override)
            or (negative_votes > 0 and supportive_votes == 0)
            or (trade_quality_local < 50.0 and entry_score_local < 50.0 and entry_edge < 0.015)
            or (uncertainty >= 74.0 and disagreement >= 54.0)
        )

        if hard_reject or score < 40.0:
            candidate_class = "filtered_fallback" if (fallback_flag or setup_type in {"fallback_unclear", "unclassified_setup"}) else "filtered_no_edge"
            band = "reject"
            passed = False
            reason = "pre_entry_filter_reject_low_edge"
        elif score < 52.0:
            candidate_class = "filtered_conflicted"
            band = "weak"
            passed = False
            reason = "pre_entry_filter_reject_conflicted_signals"
        elif score < 64.0:
            candidate_class = "thin_pass"
            band = "thin"
            passed = True
            reason = "pre_entry_filter_thin_but_coherent"
        elif score < 78.0:
            candidate_class = "real_pass"
            band = "pass"
            passed = True
            reason = "pre_entry_filter_real_candidate_pass"
        else:
            candidate_class = "strong_pass"
            band = "strong"
            passed = True
            reason = "pre_entry_filter_strong_candidate_pass"

        return {
            "pre_entry_filter_pass": bool(passed),
            "pre_entry_filter_score": round(score, 2),
            "pre_entry_filter_band": str(band),
            "pre_entry_filter_reason": str(reason),
            "pre_entry_filter_penalties": list(dict.fromkeys(penalties))[:10],
            "pre_entry_filter_candidate_class": str(candidate_class),
            "pre_entry_filter_reasons": list(dict.fromkeys(reasons))[:10],
        }

    def _select(rows, asset_type):
        nonlocal partial_build_triggered
        nonlocal partial_build_reason
        nonlocal partial_build_stage
        nonlocal partial_build_count
        nonlocal candidate_build_progress_rows
        nonlocal candidate_build_rows_before_abort
        def _apply_deploy_state(target_row, deploy_state):
            if deploy_state == "live-ready":
                target_row["buy_eligibility"] = "QUALIFIED"
            elif deploy_state == "paper-ready":
                target_row["buy_eligibility"] = "SOFT_BUY"
            else:
                target_row["buy_eligibility"] = "WATCHLIST"
            target_row["hero_deployment_status"] = deploy_state
            target_row["canonical_final_state"] = (
                "released_buy"
                if deploy_state == "live-ready"
                else ("paper_ready" if deploy_state == "paper-ready" else "watchlist")
            )
            target_row["canonical_release_state"] = target_row["canonical_final_state"]

        def _confidence_percent(raw_conf):
            c = _to_float(raw_conf, 0.0)
            return max(0.0, min(100.0, c * 100.0 if c <= 1.0 else c))

        def _is_real_quoted_candidate(candidate_row):
            rr = dict(candidate_row or {})
            symbol_ok = bool(str(rr.get("symbol") or "").strip())
            price_ok = _to_float(rr.get("price"), 0.0) > 0.0
            explicit_recovery = bool(rr.get("candidate_recovery_triggered", False))
            explicit_fallback = bool(rr.get("fallback_non_buy_candidate", False))
            if explicit_recovery:
                return False
            quote_norm_ok = bool(
                bool(rr.get("valid_quote", False))
                or bool(rr.get("trusted_quote_for_buys", False))
                or bool(rr.get("quote_enriched", False))
                or str(rr.get("provider_name") or "").strip()
                or (rr.get("freshness_seconds") is not None)
            )
            quality_ok = bool(
                _to_float(rr.get("provider_confidence"), 0.0) >= 0.18
                or _to_float(rr.get("data_quality_score"), 0.0) >= 18.0
                or bool(rr.get("trusted_quote_for_buys", False))
            )
            if not (symbol_ok and price_ok and quote_norm_ok and quality_ok):
                return False
            # If explicitly fallback-marked but quote is real, treat it as real quoted unless recovery was explicitly triggered.
            if explicit_fallback and not explicit_recovery:
                return True
            return True

        trace_bucket = _new_pipeline_trace_bucket(rows)
        candidates = []
        fallback_non_buy = []
        min_viable_rows = 2 if str(asset_type or "").strip().lower() == "crypto" else 3
        loop_rows_seen = 0
        for raw in list(rows or []):
            loop_rows_seen += 1
            candidate_build_progress_rows = int(candidate_build_progress_rows) + 1
            if (
                max_build_seconds > 0.0
                and (loop_rows_seen % 5 == 0)
                and not partial_build_triggered
            ):
                elapsed_loop = max(0.0, time.perf_counter() - started_at_perf)
                remaining_budget = max(0.0, max_build_seconds - elapsed_loop)
                avg_row_cost = elapsed_loop / max(1.0, float(loop_rows_seen))
                if remaining_budget < max(0.35, avg_row_cost * 1.40):
                    partial_build_triggered = True
                    partial_build_stage = "candidate_loop_budget_guard"
                    partial_build_reason = (
                        f"remaining_budget_low:{round(remaining_budget, 2)}s"
                    )
            if partial_build_triggered and (len(candidates) + len(fallback_non_buy)) >= int(min_viable_rows):
                candidate_build_rows_before_abort = int(candidate_build_progress_rows)
                break
            if not isinstance(raw, dict):
                continue
            row = _ensure_persona_fields(dict(raw))
            quote_fetched = bool(
                (row.get("price") is not None)
                or (row.get("current_price") is not None)
                or str(row.get("provider_name") or "").strip()
                or bool(row.get("trusted_quote_for_buys", False))
                or bool(row.get("quote_enriched", False))
            )
            if quote_fetched:
                trace_bucket["stage_1_quotes_fetched"] = int(trace_bucket.get("stage_1_quotes_fetched", 0)) + 1
            else:
                trace_bucket["drop_reasons_summary"]["no_quote"] = int(
                    trace_bucket["drop_reasons_summary"].get("no_quote", 0)
                ) + 1
            raw_signal_tags = row.get("entry_signal_tags") or row.get("signal_tags") or row.get("entry_reason")
            parsed_signal_tags = _supplement_signal_tags_from_row(row, existing_tags=_normalized_signal_tags(raw_signal_tags))
            if parsed_signal_tags:
                row["entry_signal_tags"] = list(dict.fromkeys(parsed_signal_tags))[:8]
            setup_fields = _derive_canonical_setup_fields(row, parsed_tags=parsed_signal_tags)
            if isinstance(setup_fields, dict):
                for k, v in setup_fields.items():
                    row[k] = v
            conf = _to_float(row.get("confidence"), _to_float(row.get("predicted_win_probability"), 0.0))
            consensus = _to_float(row.get("consensus_strength"), 0.0)
            trade_quality_seed = _to_float(row.get("trade_quality_score"), _to_float(row.get("buy_quality_score"), 0.0))
            confirmation_state_seed = str(row.get("confirmation_state") or "").strip().lower()
            follow_state_seed = str(row.get("follow_through_state") or "").strip().lower()
            if not confirmation_state_seed or "unclear" in confirmation_state_seed:
                if conf >= 0.80 and consensus >= 66.0 and trade_quality_seed >= 70.0:
                    confirmation_state_seed = "strong_confirmation"
                elif conf >= 0.70 and consensus >= 56.0:
                    confirmation_state_seed = "moderate_confirmation"
                else:
                    confirmation_state_seed = "weak_confirmation"
            if not follow_state_seed or "unclear" in follow_state_seed:
                if conf >= 0.80 and consensus >= 66.0 and trade_quality_seed >= 70.0:
                    follow_state_seed = "healthy_follow_through"
                elif conf >= 0.70 and consensus >= 56.0:
                    follow_state_seed = "moderate_follow_through"
                else:
                    follow_state_seed = "weak_follow_through_risk"
            row["confirmation_state"] = str(confirmation_state_seed or "weak_confirmation")
            row["follow_through_state"] = str(follow_state_seed or "weak_follow_through_risk")
            row["setup_type"] = str(row.get("setup_type") or "fallback_unclear")
            if row.get("trade_quality_score") is None:
                row["trade_quality_score"] = round(
                    max(
                        25.0,
                        min(
                            95.0,
                            _to_float(row.get("buy_quality_score"), _to_float(row.get("grade_percent"), 0.0)) * 0.85
                            + _to_float(row.get("consensus_strength"), 0.0) * 0.15,
                        ),
                    ),
                    2,
                )
            trusted_for_buys = bool(row.get("trusted_quote_for_buys", False))
            row_price = _to_float(row.get("price"), 0.0)
            provider_name_local = str(row.get("provider_name") or "").strip().upper()
            if not provider_name_local:
                provider_name_local = str(row.get("provider_used") or row.get("source") or "").strip().upper()
            if provider_name_local:
                trace_bucket["_providers_used"].add(provider_name_local)
            if row_price > 0 and not str(row.get("price_source") or "").strip():
                row["price_source"] = provider_name_local
            if _to_float(row.get("previous_close"), _to_float(row.get("prev_close"), 0.0)) > 0 and not str(row.get("previous_close_source") or "").strip():
                row["previous_close_source"] = str(row.get("enriched_previous_close_source") or provider_name_local or "").upper()
            if _to_float(row.get("volume"), 0.0) > 0 and not str(row.get("volume_source") or "").strip():
                row["volume_source"] = str(row.get("enriched_volume_source") or provider_name_local or "").upper()
            if _to_float(row.get("change_percent"), 0.0) != 0.0 and not str(row.get("change_percent_source") or "").strip():
                row["change_percent_source"] = provider_name_local
            if not str(row.get("history_source") or "").strip():
                row["history_source"] = str(row.get("enriched_history_source") or "").upper()
            if not isinstance(row.get("field_source_summary"), dict):
                row["field_source_summary"] = {
                    "price": str(row.get("price_source") or "").upper(),
                    "previous_close": str(row.get("previous_close_source") or "").upper(),
                    "volume": str(row.get("volume_source") or "").upper(),
                    "change_percent": str(row.get("change_percent_source") or "").upper(),
                    "history": str(row.get("history_source") or "").upper(),
                }
            quote_sources = list(row.get("quote_enrichment_sources") or [])
            if len(quote_sources) >= 2:
                trace_bucket["provider_usage_summary"]["symbols_with_multi_provider_data"] = int(
                    trace_bucket["provider_usage_summary"].get("symbols_with_multi_provider_data", 0)
                ) + 1
            if bool(row.get("quote_enriched", False)):
                trace_bucket["provider_usage_summary"]["symbols_with_enriched_quotes"] = int(
                    trace_bucket["provider_usage_summary"].get("symbols_with_enriched_quotes", 0)
                ) + 1
            if row.get("previous_close") is None and row.get("prev_close") is None:
                trace_bucket["provider_usage_summary"]["symbols_missing_previous_close"] = int(
                    trace_bucket["provider_usage_summary"].get("symbols_missing_previous_close", 0)
                ) + 1
            if row.get("volume") is None:
                trace_bucket["provider_usage_summary"]["symbols_missing_volume"] = int(
                    trace_bucket["provider_usage_summary"].get("symbols_missing_volume", 0)
                ) + 1
            if (
                not str(row.get("enriched_history_source") or "").strip()
                and not bool(row.get("candles_available", False))
                and _to_float(row.get("history_quality_score"), 0.0) <= 0.0
            ):
                trace_bucket["provider_usage_summary"]["symbols_missing_history"] = int(
                    trace_bucket["provider_usage_summary"].get("symbols_missing_history", 0)
                ) + 1
            quote_normalized = bool(
                row_price > 0.0
                and (
                    trusted_for_buys
                    or bool(row.get("quote_enriched", False))
                    or str(row.get("provider_name") or "").strip()
                    or (row.get("freshness_seconds") is not None)
                )
            )
            if quote_normalized:
                trace_bucket["stage_2_quotes_normalized"] = int(trace_bucket.get("stage_2_quotes_normalized", 0)) + 1
            else:
                trace_bucket["drop_reasons_summary"]["missing_fields"] = int(
                    trace_bucket["drop_reasons_summary"].get("missing_fields", 0)
                ) + 1
                if quote_fetched:
                    trace_bucket["drop_reasons_summary"]["data_quality_fail"] = int(
                        trace_bucket["drop_reasons_summary"].get("data_quality_fail", 0)
                    ) + 1
            buy_dir_ref = _buy_direction_refinement_v1(row, allow_non_buy_fallback=True)
            row["buy_direction_refinement_score"] = _to_float(buy_dir_ref.get("buy_direction_refinement_score"), 0.0)
            row["buy_direction_quality_penalty"] = _to_float(buy_dir_ref.get("buy_direction_quality_penalty"), 0.0)
            row["buy_direction_reasons"] = list(buy_dir_ref.get("buy_direction_reasons") or [])
            row["buy_direction_reason_count"] = int(_to_float(buy_dir_ref.get("buy_direction_reason_count"), 0.0))
            row["buy_direction_is_candidate"] = bool(buy_dir_ref.get("is_buy_direction_candidate", False))
            row["buy_direction_fallback_allowed"] = bool(buy_dir_ref.get("keep_as_non_buy_fallback", False))
            if not bool(buy_dir_ref.get("is_buy_direction_candidate", False)):
                real_quoted_candidate = bool(_is_real_quoted_candidate(row))
                if real_quoted_candidate:
                    row["buy_direction_real_quoted_candidate"] = True
                    row["buy_direction_reclassified"] = "real_quoted_non_buy_direction"
                    row["fallback_non_buy_candidate"] = False
                    row["candidate_recovery_triggered"] = False
                    bd_score = _to_float(row.get("buy_direction_refinement_score"), 0.0)
                    if bd_score >= 54.0:
                        row["buy_direction_candidate_class"] = "thin_quoted_candidates"
                        trace_bucket["thin_quoted_candidate_count"] = int(
                            trace_bucket.get("thin_quoted_candidate_count", 0)
                        ) + 1
                    else:
                        row["buy_direction_candidate_class"] = "degraded_but_real_candidates"
                        trace_bucket["degraded_but_real_candidate_count"] = int(
                            trace_bucket.get("degraded_but_real_candidate_count", 0)
                        ) + 1
                    trace_bucket["real_quoted_candidate_count"] = int(
                        trace_bucket.get("real_quoted_candidate_count", 0)
                    ) + 1
                    trace_bucket["fallback_override_count"] = int(
                        trace_bucket.get("fallback_override_count", 0)
                    ) + 1
                    row["release_suppression_applied"] = True
                    row["release_reroute_reason"] = "buy_direction_non_buy_requires_pre_entry_confirmation"
                if trusted_for_buys and row_price > 0.0:
                    if not bool(buy_dir_ref.get("keep_as_non_buy_fallback", False)):
                        if not real_quoted_candidate:
                            trace_bucket["drop_reasons_summary"]["fallback_candidates"] = int(
                                trace_bucket["drop_reasons_summary"].get("fallback_candidates", 0)
                            ) + 1
                            trace_bucket["candidate_class_distribution"]["filtered_no_edge"] = int(
                                trace_bucket["candidate_class_distribution"].get("filtered_no_edge", 0)
                            ) + 1
                            trace_bucket["true_fallback_candidate_count"] = int(
                                trace_bucket.get("true_fallback_candidate_count", 0)
                            ) + 1
                            continue
                    fb = dict(row)
                    fb_discipline = _core_decision_discipline_v1(fb)
                    fb["asset_type"] = asset_type
                    fb["fallback_non_buy_candidate"] = True
                    fb["top_buy_action"] = "WATCHLIST"
                    fb["final_action"] = "HOLD"
                    fb["action"] = str(fb.get("action") or "Hold")
                    fb["core_decision_discipline_score"] = round(_to_float(fb_discipline.get("discipline_score"), 0.0), 2)
                    fb["core_decision_discipline_tier"] = str(fb_discipline.get("discipline_tier") or "monitor")
                    fb["core_decision_discipline_action"] = str(fb_discipline.get("discipline_action") or "watchlist_only")
                    fb["core_decision_discipline_reasons"] = list(fb_discipline.get("discipline_reasons") or [])
                    fb["buy_qualification_score"] = round(_to_float(fb_discipline.get("discipline_score"), 0.0), 2)
                    fb["buy_qualification_tier"] = "weak_buy_candidate"
                    fb_unc = _uncertainty_engine_v1(fb)
                    fb["uncertainty_score"] = _to_float(fb_unc.get("uncertainty_score"), 0.0)
                    fb["uncertainty_tier"] = str(fb_unc.get("uncertainty_tier") or "low_uncertainty")
                    fb["uncertainty_reasons"] = list(fb_unc.get("uncertainty_reasons") or [])
                    fb["uncertainty_components"] = dict(fb_unc.get("uncertainty_components") or {})
                    fb["entry_timing_score"] = 0.0
                    fb["entry_mode"] = "skip"
                    fb["conviction_tier"] = "none"
                    fb["detected_setup_type"] = "FALLBACK_UNCLEAR"
                    fb["setup_detection_score"] = 0.0
                    fb["setup_detection_band"] = "poor"
                    fb["setup_detection_confidence"] = 0.0
                    fb["setup_signal_profile"] = "noisy"
                    fb["setup_reasons"] = ["fallback_recovery_row"]
                    fb["setup_penalties"] = ["non_buy_direction"]
                    fb["setup_summary"] = "fallback/non-buy placeholder candidate"
                    fb["setup_candidate_realness"] = "fallback"
                    fb["setup_structure_label"] = "weak_or_choppy"
                    fb["setup_confirmation_state"] = "weak_confirmation"
                    fb["setup_detection_evidence_label"] = "insufficient"
                    fb["setup_detection_missing_signal_count"] = 0
                    fb["setup_detection_components"] = {
                        "trend_support": 0.0,
                        "momentum_support": 0.0,
                        "volume_support": 0.0,
                        "location_support": 0.0,
                        "structure_support": 0.0,
                        "contradiction_penalty": 0.0,
                        "extension_penalty": 0.0,
                        "fallback_penalty": 2.0,
                        "missing_evidence_penalty": 0.0,
                    }
                    fb["entry_quality_score"] = 0.0
                    fb["entry_quality_band"] = "poor"
                    fb["entry_quality_reasons"] = ["non_buy_direction"]
                    fb["entry_quality_penalties"] = ["non_buy_direction"]
