                row["release_suppression_applied"] = True
                row["release_reroute_reason"] = "candidate_recovery_watchlist_conservative"
                row["promotion_feedback_gate"] = "BLOCK_RECOVERY_MONITOR_ONLY"
                row["promotion_feedback_block_reason"] = "candidate_recovery_non_buy_direction"
