                row["setup_candidate_realness"] = str(row.get("setup_candidate_realness") or "fallback")
                row["setup_structure_label"] = str(row.get("setup_structure_label") or "weak_or_choppy")
                row["setup_confirmation_state"] = str(row.get("setup_confirmation_state") or "weak_confirmation")
