def _bootstrap_stock_rows_for_top_buys():
    """
    Emergency bootstrap for stock rows when full rankings are temporarily unavailable.
    Uses the same backend fetch/scoring path on a bounded stock subset.
    """
    try:
        fmp_mode = str(os.getenv("ASTRA_FMP_MODE", "conserve")).strip().lower()
        if fmp_mode == "conserve":
            meta = get_ranking_snapshot_meta() or {}
            if int(meta.get("budget_exhausted_count", 0) or 0) > 0:
                return []
        universe_symbols = _load_universe_symbols()
        if not universe_symbols:
            return []
        if fmp_mode == "conserve":
            subset_cap = max(8, min(12, len(universe_symbols)))
        else:
            subset_cap = max(12, min(30, len(universe_symbols)))
        subset = list(universe_symbols[:subset_cap])
        rows = fetch_live_data(symbols=subset)
        if not isinstance(rows, list) or not rows:
            return []
        scored = [_ensure_persona_fields(dict(r)) for r in rows if isinstance(r, dict)]
        scored = sorted(
            scored,
            key=lambda r: (
                _to_float((r or {}).get("confidence"), 0.0),
                _to_float((r or {}).get("grade_percent"), _to_float((r or {}).get("persona_weighted_grade"), 0.0)),
                _to_float((r or {}).get("price"), 0.0),
            ),
            reverse=True,
        )
        if scored:
            _update_last_rankings("stocks", scored)
            RANKINGS_ENDPOINT_CACHE["stocks"] = {"ts": time.time(), "payload": list(scored)}
        return scored
    except Exception:
        return []


def _near_entry_candidates(limit=10):
    out = []
    rows = LAST_RANKINGS.get("stocks", []) or []
    for row in rows:
        if not isinstance(row, dict):
            continue
        action = str(row.get("action") or row.get("prediction") or "").lower()
        gate = bool(row.get("signal_quality_gate_passed", True))
        prob = _to_float(row.get("predicted_win_probability"), 0.0)
        if action == "buy" and gate and prob >= 0.56:
            out.append((prob, str(row.get("symbol") or "").upper()))
    out = sorted(out, key=lambda x: x[0], reverse=True)
    primary = [s for _, s in out[: max(0, int(limit))] if s]
    if len(primary) >= max(1, int(limit)):
        return primary
    # Fallback seeding for websocket allocation when strict near-entry list is sparse.
    secondary = []
    ranked_rows = sorted(
        [r for r in rows if isinstance(r, dict)],
        key=lambda r: (
            _to_float(r.get("predicted_win_probability"), 0.0),
            _to_float(r.get("persona_weighted_grade"), 0.0),
            _to_float(r.get("consensus_strength"), 0.0),
        ),
        reverse=True,
    )
    for row in ranked_rows:
        sym = str(row.get("symbol") or "").upper()
        if not sym or sym in primary or sym in secondary:
            continue
        if bool(row.get("live_buy_universe", False)) or bool(row.get("trusted_quote_for_buys", False)):
            secondary.append(sym)
        if len(primary) + len(secondary) >= max(0, int(limit)):
            break
    return (primary + secondary)[: max(0, int(limit))]


def _refresh_alpaca_ws_allocation():
    try:
        now = time.time()
        open_positions = POSITION_TRACKER.get_open_positions()
        open_symbols = [
            str(r.get("symbol") or "").upper()
            for r in open_positions
            if isinstance(r, dict) and r.get("symbol")
        ]
        near_symbols = _near_entry_candidates(limit=12)
        if not near_symbols:
            # Keep WS useful even with no strict near-entry candidates.
            fallback = []
            for row in LAST_RANKINGS.get("stocks", []) or []:
                if not isinstance(row, dict):
                    continue
                sym = str(row.get("symbol") or "").upper()
                if not sym or sym in fallback:
                    continue
                if bool(row.get("live_buy_universe", False)):
                    fallback.append(sym)
                if len(fallback) >= 8:
                    break
            near_symbols = fallback
        signature = f"{','.join(sorted(open_symbols))}|{','.join(sorted(near_symbols))}"
        if (
            signature == str(_ALPACA_WS_ALLOC_STATE.get("signature") or "")
            and (now - float(_ALPACA_WS_ALLOC_STATE.get("ts", 0.0))) < ALPACA_WS_ALLOC_MIN_REFRESH_SECONDS
        ):
            return
        ALPACA_WS_MONITOR.configure_symbols(
            open_position_symbols=open_symbols,
            near_entry_symbols=near_symbols,
        )
        _ALPACA_WS_ALLOC_STATE["signature"] = signature
        _ALPACA_WS_ALLOC_STATE["ts"] = now
    except Exception:
        pass


def _snapshot_age_seconds(kind):
    meta = get_ranking_snapshot_meta()
    if kind == "crypto":
        return _to_float(meta.get("crypto_snapshot_age_seconds"), 10**9)
    return _to_float(meta.get("ranking_snapshot_age_seconds"), 10**9)


def _refresh_rankings_for_asset(kind):
    if kind == "crypto":
        return crypto_rankings()
    return rankings()


def _latest_rows_for_asset(asset_type):
    kind = "crypto" if _normalize_asset_type(asset_type) == "crypto" else "stocks"
    rows = LAST_RANKINGS.get(kind, []) or []
    out = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        out.append(dict(row))
    return out


def _find_latest_row(symbol, asset_type=None):
    sym = str(symbol or "").upper().strip()
    if not sym:
        return None
    if asset_type:
        groups = [_normalize_asset_type(asset_type)]
    else:
        groups = ["stocks", "crypto"]
    for group in groups:
        rows = LAST_RANKINGS.get("crypto" if group == "crypto" else "stocks", []) or []
        for row in rows:
            if isinstance(row, dict) and str(row.get("symbol", "")).upper() == sym:
                out = dict(row)
                # Websocket monitoring is additive and bounded to open/near-entry symbols.
                # It augments monitoring freshness for positions/sell-follow without
                # changing ranking trust architecture.
                if group == "stocks":
                    wsq = ALPACA_WS_MONITOR.get_quote(sym, max_age_seconds=20)
                    if isinstance(wsq, dict):
                        ws_quote_ts = wsq.get("quote_timestamp")
                        ws_quote_age = _to_float(wsq.get("quote_age_seconds"), 0.0)
                        out["price"] = wsq.get("price", out.get("price"))
                        out["prev_close"] = wsq.get("prev_close", out.get("prev_close"))
                        out["provider_used"] = wsq.get("provider_used", out.get("provider_used"))
                        out["source"] = wsq.get("provider_used", out.get("source"))
                        out["quote_quality"] = wsq.get("quote_quality", out.get("quote_quality", "live_ws"))
                        out["quote_source"] = "alpaca_ws_overlay"
                        out["quote_overlay_applied"] = True
                        out["quote_timestamp_epoch"] = ws_quote_ts
                        out["quote_age_seconds"] = ws_quote_age
                        out["quote_freshness_bucket"] = (
                            "fresh_live"
                            if ws_quote_age <= 10
                            else ("warm_live" if ws_quote_age <= 30 else "stale_live")
                        )
                        out["cache_hit"] = False
                        out["timestamp"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
                        out["last_snapshot_timestamp"] = out["timestamp"]
                        out["data_unavailable_reason"] = out.get("data_unavailable_reason")
                return out
    return None


def _paper_top_buys_snapshot():
    cached = _CACHE.get("top_buys", {})
    mode_cache = cached.get("mode::balanced", {}) if isinstance(cached, dict) else {}
    if mode_cache.get("data") and (time.time() - float(mode_cache.get("ts", 0.0))) <= TOP_BUYS_TTL_SECONDS:
        return dict(mode_cache.get("data", {}))
    try:
        return top_buys()
    except Exception:
        return {}


def _paper_rankings_snapshot():
    _ensure_latest_rankings()
    return {
        "stocks": list(LAST_RANKINGS.get("stocks", []) or []),
        "crypto": list(LAST_RANKINGS.get("crypto", []) or []),
    }


def _paper_single_symbol_quote(symbol, asset_type):
    sym = str(symbol or "").upper().strip()
    if not sym:
        return {}
    quote = GUARDIAN_API.fetch_stock(sym)
    now_iso = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    return {
        "symbol": sym,
        "asset_type": _normalize_asset_type(asset_type),
        "price": _to_float(quote.get("price"), 0.0),
        "prev_close": quote.get("prev_close"),
        "provider_used": quote.get("provider_used") or quote.get("source") or "none",
        "source": quote.get("source") or quote.get("provider_used") or "none",
        "quote_quality": quote.get("quote_quality", "live"),
        "cache_hit": bool(quote.get("cache_hit", False)),
        "data_unavailable_reason": quote.get("data_unavailable_reason") or quote.get("feed_degraded_reason"),
        "quote_timestamp": now_iso,
        "timestamp": now_iso,
    }


def _paper_latest_symbol_snapshot(symbol, asset_type):
    kind = _normalize_asset_type(asset_type)
    _ensure_latest_rankings()
    # Keep paper exits tied to reasonably fresh snapshots so entry/exit prices can diverge.
    if _snapshot_age_seconds(kind) > 20.0:
        try:
            _refresh_rankings_for_asset(kind)
        except Exception:
            pass
    rows = LAST_RANKINGS.get("crypto" if kind == "crypto" else "stocks", []) or []
    sym = str(symbol or "").upper()
    for row in rows:
        if isinstance(row, dict) and str(row.get("symbol") or "").upper() == sym:
            out = dict(row)
            out["quote_timestamp"] = (
                out.get("timestamp")
                or out.get("last_snapshot_timestamp")
                or out.get("last_updated_utc")
            )
            return out
    return _paper_single_symbol_quote(sym, kind)


PAPER_FRESHNESS = QuoteFreshnessManager(
    max_age_seconds=int(os.getenv("ASTRA_PAPER_QUOTE_MAX_AGE_SECONDS", "20")),
    single_quote_fetcher=_paper_single_symbol_quote,
)


def _paper_replay_candles_fetcher(symbol, asset_type, resolution="D", from_ts=None, to_ts=None):
    end_ts = int(to_ts or time.time())
    start_ts = int(from_ts or (end_ts - (90 * 86400)))
    try:
        return candles(
            symbol=str(symbol or "").upper(),
            asset_type="crypto" if str(asset_type) == "crypto" else "stock",
            resolution=str(resolution or "D"),
            lookback_days=max(1, int((end_ts - start_ts) / 86400)),
            from_ts=start_ts,
            to_ts=end_ts,
        )
    except Exception as e:
        return {"candles": [], "data_unavailable": f"replay_candle_error:{str(e)[:80]}"}


