def _is_buy_direction(item):
    action = str(item.get("action") or "").strip().lower()
    prediction = str(item.get("prediction") or "").strip().lower()
    majority = str(item.get("majority_signal") or "").strip().lower()
    return action in {"buy", "strong buy"} or prediction in {"buy", "strong buy"} or majority == "buy"


def _to_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        if default is None:
            return None
        return float(default)


def _iso_age_seconds(value):
    if not value:
        return None
    try:
        s = str(value).replace("Z", "+00:00")
        dt = datetime.fromisoformat(s)
        return max(0.0, (datetime.now(UTC) - dt).total_seconds())
    except Exception:
        return None


def _update_provider_quality_memory(snapshot):
    if not isinstance(snapshot, dict):
        return
    try:
        ts = time.time()
        sample = dict(snapshot)
        sample["ts"] = ts
        _PROVIDER_QUALITY_MEMORY.append(sample)
    except Exception:
        pass


def _provider_quality_rolling_summary(now_ts=None):
    if now_ts is None:
        now_ts = time.time()
    windows = {
        "recent_1h_provider_quality": 3600.0,
        "recent_6h_provider_quality": 21600.0,
        "recent_24h_provider_quality": 86400.0,
    }
    out = {}
    data = list(_PROVIDER_QUALITY_MEMORY)
    for label, seconds in windows.items():
        rows = [r for r in data if isinstance(r, dict) and (now_ts - _to_float(r.get("ts"), 0.0)) <= seconds]
        if not rows:
            out[label] = {
                "samples": 0,
                "provider_quality_score": None,
                "quote_freshness_score": None,
                "cache_rescue_rate_percent": None,
                "data_degradation_pressure": None,
                "usable": False,
            }
            continue
        n = float(len(rows))
        avg_provider = sum(_to_float(r.get("provider_quality_score"), 0.0) for r in rows) / n
        avg_fresh = sum(_to_float(r.get("quote_freshness_score"), 0.0) for r in rows) / n
        avg_cache = sum(_to_float(r.get("cache_rescue_rate_percent"), 0.0) for r in rows) / n
        avg_degrade = sum(_to_float(r.get("data_degradation_pressure"), 0.0) for r in rows) / n
        out[label] = {
            "samples": int(len(rows)),
            "provider_quality_score": round(avg_provider, 2),
            "quote_freshness_score": round(avg_fresh, 2),
            "cache_rescue_rate_percent": round(avg_cache, 2),
            "data_degradation_pressure": round(avg_degrade, 2),
            "usable": bool(len(rows) >= 3),
        }
    return out


def _evaluate_buy_candidate(row):
    return _evaluate_buy_candidate_with_thresholds(
        row=row,
        min_probability=TOP_BUY_MIN_PROBABILITY,
        max_disagreement=TOP_BUY_MAX_DISAGREEMENT,
    )


def _evaluate_buy_candidate_with_thresholds(row, min_probability, max_disagreement):
    failed = []
    warnings = []

    if not bool(row.get("trusted_quote_for_buys", False)):
        failed.append("untrusted_quote")
    if not bool(row.get("valid_quote", False)):
        failed.append("invalid_quote")
    if not _is_buy_direction(row):
        failed.append("not_buy_direction")
    if not bool(row.get("signal_quality_gate_passed", False)):
        failed.append("gate_failed")
    prob = _to_float(row.get("predicted_win_probability"), 0.0)
    if prob < float(min_probability):
        failed.append("probability_below_min")
    disagreement = _to_float(row.get("persona_disagreement_index"), 100.0)
    if disagreement > float(max_disagreement):
        failed.append("disagreement_above_max")

    quote_quality = str(row.get("quote_quality") or "").strip().lower()
    if quote_quality in {"snapshot", "placeholder"}:
        warnings.append(f"quote_degraded:{quote_quality}")
        failed.append("quote_not_live")
    reason = str(row.get("data_unavailable_reason") or "").strip()
    if reason:
        warnings.append(f"data_unavailable:{reason}")
    agreement = _to_float(row.get("provider_agreement"), 1.0)
    if agreement < 0.6:
        warnings.append("low_provider_agreement")

    qualified = len(failed) == 0
    return qualified, failed, warnings


def _build_trade_plan(item):
    price = _to_float(item.get("price"), 0.0)
    if price <= 0:
        return {
            "entry_type": "market",
            "entry_price_suggested": 0.0,
            "stop_loss_suggested": None,
            "take_profit_suggested": None,
            "time_horizon": "swing",
            "confidence_note": "No live price available; wait for refreshed quote before entry.",
        }
    volatility_factor = _to_float(item.get("decision_breakdown", {}).get("values", {}).get("volatility_factor"), 0.0)
    base_stop_pct = 0.02 + min(0.015, max(0.0, volatility_factor * 0.01))
    base_stop_pct = min(0.035, max(0.015, base_stop_pct))

    stop_loss = item.get("stop_loss")
    stop_loss = _to_float(stop_loss, 0.0) if stop_loss is not None else 0.0
    if stop_loss <= 0:
        stop_loss = round(price * (1.0 - base_stop_pct), 4)

    risk = max(price - stop_loss, price * 0.01)
    take_profit = item.get("take_profit")
    take_profit = _to_float(take_profit, 0.0) if take_profit is not None else 0.0
    if take_profit <= 0:
        rr = 1.8 if _to_float(item.get("predicted_win_probability"), 0.0) >= 0.65 else 1.5
        take_profit = round(price + (risk * rr), 4)

    intraday_score = _to_float(item.get("intraday_score"), 0.0)
    time_horizon = "intraday" if intraday_score >= 70 else "swing"
    entry_type = "market" if str(item.get("quote_quality") or "live").lower() == "live" else "limit_suggested"
    consensus = _to_float(item.get("consensus_strength"), 0.0)
    prob = _to_float(item.get("predicted_win_probability"), 0.0) * 100.0
    confidence_note = (
        f"Plan based on consensus {consensus:.1f}, win probability {prob:.1f}%, "
        f"and volatility-aware stop at {base_stop_pct*100:.1f}%."
    )
    return {
        "entry_type": entry_type,
        "entry_price_suggested": round(price, 4),
        "stop_loss_suggested": round(stop_loss, 4),
        "take_profit_suggested": round(take_profit, 4),
        "time_horizon": time_horizon,
        "confidence_note": confidence_note,
    }


def _fill_sort_key(item):
    return (
        -_to_float(item.get("adaptive_buy_score"), 0.0),
        -_to_float(item.get("predicted_win_probability"), 0.0),
        -_to_float(item.get("persona_weighted_grade", item.get("grade_percent")), 0.0),
        -_to_float(item.get("consensus_strength"), 0.0),
        _to_float(item.get("persona_disagreement_index"), 100.0),
    )


def _top_buys_from_rows(rows):
    return _top_buys_from_rows_with_config(
        rows=rows,
        buy_mode="balanced",
        min_probability=TOP_BUY_MIN_PROBABILITY,
        max_disagreement=TOP_BUY_MAX_DISAGREEMENT,
    )


def _resolve_buy_mode_config(raw_mode):
    mode = str(raw_mode or "balanced").strip().lower()
    if mode not in BUY_MODE_CONFIG:
        mode = "balanced"
    cfg = BUY_MODE_CONFIG.get(mode, BUY_MODE_CONFIG["balanced"])
    return {
        "buy_mode": mode,
        "min_probability": float(cfg.get("min_probability", TOP_BUY_MIN_PROBABILITY)),
        "max_disagreement": float(cfg.get("max_disagreement", TOP_BUY_MAX_DISAGREEMENT)),
    }


