        conviction_framework_rank_mult = _to_float((((cf_multipliers.get(conviction_framework_tier) or {}).get("ranking"))), 1.0)
        conviction_framework_size_mult = _to_float((((cf_multipliers.get(conviction_framework_tier) or {}).get("sizing"))), 1.0)
        conviction_action_tiers = dict((conviction_action_mapping.get("tiers") or {})) if isinstance(conviction_action_mapping, dict) else {}
        conviction_action_rank_mult = _to_float((((conviction_action_tiers.get(conviction_framework_tier) or {}).get("ranking_hint_multiplier"))), 1.0)
        conviction_action_size_mult = _to_float((((conviction_action_tiers.get(conviction_framework_tier) or {}).get("sizing_hint_multiplier"))), 1.0)
        row["conviction_framework_tier"] = conviction_framework_tier
