@router.get("/api/fmp_historical_learning_audit")
def fmp_historical_learning_audit(
    include_file_scan: bool = Query(default=True),
):
    def _pct(n, d):
        return round((_to_float(n, 0.0) / max(1.0, _to_float(d, 0.0))) * 100.0, 2)

    def _iso_from_unix(value):
        try:
            v = float(value)
            if v <= 0:
                return ""
            return datetime.fromtimestamp(v, UTC).isoformat().replace("+00:00", "Z")
        except Exception:
            return ""

    def _safe_path(path):
        return str(path or "").replace(os.path.expanduser("~"), "~")

    def _table_exists(conn, table):
        try:
            row = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name=?",
                (str(table),),
            ).fetchone()
            return bool(row)
        except Exception:
            return False

    def _table_cols(conn, table):
        try:
            return {
                str(r[1] if isinstance(r, tuple) else r["name"]): True
                for r in (conn.execute(f"PRAGMA table_info({table})").fetchall() or [])
            }
        except Exception:
            return {}

    def _one(conn, query, params=()):
        try:
            row = conn.execute(query, params).fetchone()
            if row is None:
                return None
            if isinstance(row, sqlite3.Row):
                return dict(row)
            return row
        except Exception:
            return None

    def _count_where(conn, table, where="1=1", params=()):
        row = _one(conn, f"SELECT COUNT(1) AS n FROM {table} WHERE {where}", params)
        try:
            return int((row or {}).get("n", 0) if isinstance(row, dict) else (row[0] if row else 0))
        except Exception:
            return 0

    def _coverage(conn, table, total, expression):
        if total <= 0:
            return 0.0, 0
        row = _one(conn, f"SELECT SUM(CASE WHEN {expression} THEN 1 ELSE 0 END) AS n FROM {table}")
        n = int(_to_float((row or {}).get("n") if isinstance(row, dict) else 0, 0.0))
        return _pct(n, total), n

    def _sqlite_source_summary(db_path, table, fmp_bar_range=None):
        out = {
            "source_name": table,
            "source_type": "sqlite_table",
            "path_or_table": f"{_safe_path(db_path)}::{table}",
            "row_count": 0,
            "date_range": {"start": "", "end": ""},
            "provider_field_present": False,
            "fmp_rows_count": 0,
            "likely_fmp_era_rows": 0,
            "ohlcv_coverage_percent": 0.0,
            "volume_coverage_percent": 0.0,
            "outcome_coverage_percent": 0.0,
            "setup_label_coverage_percent": 0.0,
            "entry_exit_coverage_percent": 0.0,
            "usable_timestamp_coverage_percent": 0.0,
            "usable_price_coverage_percent": 0.0,
            "timing_reconstruction_possible": False,
            "exit_reconstruction_possible": False,
            "setup_context_learning_possible": False,
            "fields_available": [],
            "limitations": [],
        }
        if not os.path.exists(db_path):
            out["limitations"].append("database_file_missing")
            return out
        try:
            with sqlite3.connect(db_path, timeout=0.5) as conn:
                conn.row_factory = sqlite3.Row
                if not _table_exists(conn, table):
                    out["limitations"].append("table_missing")
                    return out
                cols = _table_cols(conn, table)
                out["fields_available"] = sorted(cols.keys())
                total = _count_where(conn, table)
                out["row_count"] = int(total)
                if total <= 0:
                    out["limitations"].append("empty_table")
                    return out

                if table == "historical_market_bars":
                    out["provider_field_present"] = bool("provider" in cols)
                    provider_expr = "LOWER(COALESCE(provider,'')) LIKE '%fmp%'" if "provider" in cols else "0"
                    out["fmp_rows_count"] = _count_where(conn, table, provider_expr)
                    out["likely_fmp_era_rows"] = int(out["fmp_rows_count"])
                    row = _one(conn, "SELECT MIN(ts) AS min_ts, MAX(ts) AS max_ts FROM historical_market_bars")
                    out["date_range"] = {
                        "start": _iso_from_unix((row or {}).get("min_ts")),
                        "end": _iso_from_unix((row or {}).get("max_ts")),
                    }
                    out["ohlcv_coverage_percent"], _ = _coverage(conn, table, total, "o IS NOT NULL AND h IS NOT NULL AND l IS NOT NULL AND c IS NOT NULL")
                    out["volume_coverage_percent"], _ = _coverage(conn, table, total, "v IS NOT NULL AND v > 0")
                    out["usable_timestamp_coverage_percent"], _ = _coverage(conn, table, total, "ts IS NOT NULL AND ts > 0")
                    out["usable_price_coverage_percent"], _ = _coverage(conn, table, total, "c IS NOT NULL AND c > 0")
                    out["timing_reconstruction_possible"] = bool(out["ohlcv_coverage_percent"] >= 75.0 and out["usable_timestamp_coverage_percent"] >= 75.0)
                    out["exit_reconstruction_possible"] = False
                    out["setup_context_learning_possible"] = False
                    if out["fmp_rows_count"] <= 0:
                        out["limitations"].append("no_fmp_labeled_bars")
                    out["limitations"].append("market_bars_need_trade_journal_join_for_outcomes")
                    providers = conn.execute(
                        """
                        SELECT provider, COUNT(1) AS rows, COUNT(DISTINCT symbol) AS symbols,
                               MIN(ts) AS min_ts, MAX(ts) AS max_ts
                        FROM historical_market_bars
                        GROUP BY provider
                        ORDER BY rows DESC
                        """
                    ).fetchall()
                    out["provider_breakdown"] = [
                        {
                            "provider": str(r["provider"] or "unknown"),
                            "rows": int(r["rows"] or 0),
                            "symbols": int(r["symbols"] or 0),
                            "date_range": {
                                "start": _iso_from_unix(r["min_ts"]),
                                "end": _iso_from_unix(r["max_ts"]),
                            },
                        }
                        for r in providers
                    ]
                    return out

                if table == "trade_journal":
                    row = _one(
                        conn,
                        """
                        SELECT MIN(entry_timestamp) AS min_entry, MAX(entry_timestamp) AS max_entry,
                               MIN(exit_timestamp) AS min_exit, MAX(exit_timestamp) AS max_exit
                        FROM trade_journal
                        """,
                    )
                    out["date_range"] = {
                        "start": str((row or {}).get("min_entry") or (row or {}).get("min_exit") or ""),
                        "end": str((row or {}).get("max_exit") or (row or {}).get("max_entry") or ""),
                    }
                    out["provider_field_present"] = any(k in cols for k in ("provider", "source", "data_source"))
                    fmp_exprs = []
                    for col in ("provider", "source", "data_source", "trade_origin", "entry_reason", "risk_context_json"):
                        if col in cols:
                            fmp_exprs.append(f"LOWER(COALESCE({col},'')) LIKE '%fmp%'")
                    out["fmp_rows_count"] = _count_where(conn, table, " OR ".join(fmp_exprs)) if fmp_exprs else 0
                    if fmp_bar_range and all(fmp_bar_range):
                        out["likely_fmp_era_rows"] = _count_where(
                            conn,
                            table,
                            "entry_timestamp >= ? AND entry_timestamp <= ?",
                            tuple(fmp_bar_range),
                        )
                    outcome_expr = "exit_timestamp IS NOT NULL AND TRIM(COALESCE(exit_timestamp,''))<>'' AND return_percent IS NOT NULL"
                    out["outcome_coverage_percent"], outcome_count = _coverage(conn, table, total, outcome_expr)
                    setup_cols = [c for c in ("detected_setup_type", "setup_type") if c in cols]
                    setup_expr = " OR ".join([f"TRIM(COALESCE({c},''))<>''" for c in setup_cols]) or "0"
                    out["setup_label_coverage_percent"], setup_count = _coverage(conn, table, total, setup_expr)
                    out["entry_exit_coverage_percent"], entry_exit_count = _coverage(
                        conn,
                        table,
                        total,
                        "TRIM(COALESCE(entry_timestamp,''))<>'' AND TRIM(COALESCE(exit_timestamp,''))<>'' AND entry_price > 0 AND exit_price > 0",
                    )
                    out["usable_timestamp_coverage_percent"], _ = _coverage(
                        conn,
                        table,
                        total,
                        "TRIM(COALESCE(entry_timestamp,''))<>'' AND TRIM(COALESCE(exit_timestamp,''))<>''",
                    )
                    out["usable_price_coverage_percent"], _ = _coverage(conn, table, total, "entry_price > 0 AND exit_price > 0")
                    out["timing_reconstruction_possible"] = bool(entry_exit_count > 0)
                    mfe_expr = "max_favorable_excursion IS NOT NULL OR peak_unrealized_pnl_percent IS NOT NULL"
                    out["exit_reconstruction_possible"] = bool(_coverage(conn, table, total, mfe_expr)[1] > 0 and outcome_count > 0)
                    out["setup_context_learning_possible"] = bool(setup_count > 0 and outcome_count > 0)
                    out["entry_quality_coverage_percent"], _ = _coverage(
                        conn,
                        table,
                        total,
                        "entry_quality_score IS NOT NULL AND entry_quality_score > 0" if "entry_quality_score" in cols else "0",
                    )
                    out["mfe_mae_coverage_percent"], _ = _coverage(conn, table, total, mfe_expr)
                    if setup_count <= 0:
                        out["limitations"].append("setup_labels_sparse_or_missing")
                    if out["fmp_rows_count"] <= 0:
                        out["limitations"].append("no_explicit_fmp_provider_label")
                    if out.get("mfe_mae_coverage_percent", 0.0) < 25.0:
                        out["limitations"].append("limited_mfe_mae_for_exit_timing")
                    return out

                if table == "paper_replay_trades":
                    row = _one(
                        conn,
                        "SELECT MIN(entry_timestamp) AS min_entry, MAX(exit_timestamp) AS max_exit FROM paper_replay_trades",
                    )
                    out["date_range"] = {
                        "start": str((row or {}).get("min_entry") or ""),
                        "end": str((row or {}).get("max_exit") or ""),
                    }
                    out["outcome_coverage_percent"], outcome_count = _coverage(
                        conn,
                        table,
                        total,
                        "exit_timestamp IS NOT NULL AND TRIM(COALESCE(exit_timestamp,''))<>'' AND return_percent IS NOT NULL",
                    )
                    out["entry_exit_coverage_percent"], entry_exit_count = _coverage(
                        conn,
                        table,
                        total,
                        "TRIM(COALESCE(entry_timestamp,''))<>'' AND TRIM(COALESCE(exit_timestamp,''))<>'' AND entry_price > 0 AND exit_price > 0",
                    )
                    metadata_expr = "LOWER(COALESCE(metadata_json,'')) LIKE '%setup%' OR LOWER(COALESCE(metadata_json,'')) LIKE '%entry_quality%'"
                    out["setup_label_coverage_percent"], setup_count = _coverage(conn, table, total, metadata_expr)
                    out["usable_timestamp_coverage_percent"], _ = _coverage(
                        conn,
                        table,
                        total,
                        "TRIM(COALESCE(entry_timestamp,''))<>'' AND TRIM(COALESCE(exit_timestamp,''))<>''",
                    )
                    out["usable_price_coverage_percent"], _ = _coverage(conn, table, total, "entry_price > 0 AND exit_price > 0")
                    out["timing_reconstruction_possible"] = bool(entry_exit_count > 0)
                    out["exit_reconstruction_possible"] = bool(outcome_count > 0)
                    out["setup_context_learning_possible"] = bool(setup_count > 0 and outcome_count > 0)
                    if setup_count <= 0:
                        out["limitations"].append("setup_fields_only_possible_inside_metadata_json")
                    return out

                if "row_json" in cols:
                    row = _one(conn, f"SELECT MIN(created_at) AS min_created, MAX(updated_at) AS max_updated FROM {table}")
                    out["date_range"] = {
                        "start": str((row or {}).get("min_created") or ""),
                        "end": str((row or {}).get("max_updated") or ""),
                    }
                    out["setup_label_coverage_percent"], setup_count = _coverage(
                        conn,
                        table,
                        total,
                        "LOWER(COALESCE(row_json,'')) LIKE '%setup%' OR LOWER(COALESCE(row_json,'')) LIKE '%entry_quality%'",
                    )
                    out["fmp_rows_count"] = _count_where(conn, table, "LOWER(COALESCE(row_json,'')) LIKE '%fmp%'")
                    out["setup_context_learning_possible"] = bool(setup_count > 0)
                    out["limitations"].append("json_payload_table_requires_row_json_parsing_for_replay")
                return out
        except Exception as e:
            out["limitations"].append(f"audit_error:{str(e)[:140]}")
            return out

    def _file_source_summary(path):
        source_type = "json_file" if str(path).endswith(".json") else ("csv_file" if str(path).endswith(".csv") else "file")
        out = {
            "source_name": os.path.basename(path),
            "source_type": source_type,
            "path_or_table": _safe_path(path),
            "row_count": 0,
            "date_range": {"start": "", "end": ""},
            "provider_field_present": False,
            "fmp_rows_count": 0,
            "likely_fmp_era_rows": 0,
            "ohlcv_coverage_percent": 0.0,
            "volume_coverage_percent": 0.0,
            "outcome_coverage_percent": 0.0,
            "setup_label_coverage_percent": 0.0,
            "entry_exit_coverage_percent": 0.0,
            "timing_reconstruction_possible": False,
            "exit_reconstruction_possible": False,
            "setup_context_learning_possible": False,
            "fields_available": [],
            "limitations": [],
        }
        try:
            if not os.path.exists(path):
                out["limitations"].append("file_missing")
                return out
            size = os.path.getsize(path)
            out["file_size_bytes"] = int(size)
            if str(path).endswith(".csv"):
                with open(path, "r", encoding="utf-8", errors="replace") as fh:
                    header_line = fh.readline().strip()
                    headers = [h.strip() for h in header_line.split(",") if h.strip()]
                    out["fields_available"] = headers
                    first_data = ""
                    last_data = ""
                    n = 0
                    fmp_hits = 0
                    for line in fh:
                        if not first_data:
                            first_data = line.strip()
                        last_data = line.strip()
                        if "fmp" in line.lower():
                            fmp_hits += 1
                        n += 1
                out["row_count"] = int(n)
                lower_headers = {h.lower(): h for h in headers}
                out["provider_field_present"] = bool({"provider", "source", "data_source"} & set(lower_headers.keys()))
                out["fmp_rows_count"] = int(fmp_hits)
                out["ohlcv_coverage_percent"] = 100.0 if {"open", "high", "low", "close"} <= set(lower_headers.keys()) else (60.0 if "close" in lower_headers else 0.0)
                out["volume_coverage_percent"] = 100.0 if "volume" in lower_headers else (100.0 if "vol_ratio" in lower_headers or "obv" in lower_headers else 0.0)
                out["outcome_coverage_percent"] = 100.0 if any(k in lower_headers for k in ("outcome_%", "return_percent", "profit_loss_percent")) else 0.0
                out["setup_label_coverage_percent"] = 100.0 if any("setup" in k for k in lower_headers.keys()) else 0.0
                out["usable_price_coverage_percent"] = 100.0 if any(k in lower_headers for k in ("close", "price", "entry_price")) else 0.0
                out["usable_timestamp_coverage_percent"] = 100.0 if any(k in lower_headers for k in ("date", "timestamp", "entry_timestamp")) else 0.0
                out["timing_reconstruction_possible"] = bool("date" in lower_headers or "timestamp" in lower_headers)
                out["exit_reconstruction_possible"] = bool(out["outcome_coverage_percent"] > 0.0)
                out["setup_context_learning_possible"] = bool(out["setup_label_coverage_percent"] > 0.0 and out["outcome_coverage_percent"] > 0.0)
                if first_data:
                    out["sample_first_row_present"] = True
                if last_data:
                    out["sample_last_row_present"] = True
                if out["fmp_rows_count"] <= 0:
                    out["limitations"].append("no_explicit_fmp_label_found")
                if out["setup_label_coverage_percent"] <= 0:
                    out["limitations"].append("no_setup_label_columns")
                return out
            if str(path).endswith(".json"):
                if size > 8_000_000:
                    out["limitations"].append("json_too_large_for_inline_scan")
                    return out
                with open(path, "r", encoding="utf-8", errors="replace") as fh:
                    text = fh.read()
                lowered = text.lower()
                out["fmp_rows_count"] = int(lowered.count("fmp"))
                try:
                    payload = json.loads(text) if text.strip() else {}
                    if isinstance(payload, list):
                        out["row_count"] = len(payload)
                        if payload and isinstance(payload[0], dict):
                            out["fields_available"] = sorted(payload[0].keys())
                    elif isinstance(payload, dict):
                        out["row_count"] = 1
                        out["fields_available"] = sorted(payload.keys())
                    out["provider_field_present"] = any(k in {"provider", "source", "data_source"} for k in out["fields_available"])
                    out["setup_context_learning_possible"] = bool("setup" in lowered or "entry_quality" in lowered)
                    out["timing_reconstruction_possible"] = bool("timestamp" in lowered or "entry_timestamp" in lowered)
                    out["exit_reconstruction_possible"] = bool("exit_timestamp" in lowered or "return_percent" in lowered)
                except Exception as e:
                    out["limitations"].append(f"json_parse_error:{str(e)[:120]}")
                if out["fmp_rows_count"] <= 0:
                    out["limitations"].append("no_explicit_fmp_label_found")
                return out
        except Exception as e:
            out["limitations"].append(f"file_audit_error:{str(e)[:140]}")
        return out

    db_candidates = [
        os.path.join(STATE, "ai_trading_memory.db"),
        "ai_trading_memory.db",
    ]
    scanned = []
    found = []
    source_summaries = []
    fmp_bar_range_iso = None

    for db_path in db_candidates:
        scanned.append(_safe_path(db_path))
        if not os.path.exists(db_path):
            continue
        found.append(_safe_path(db_path))
        try:
            with sqlite3.connect(db_path, timeout=0.5) as conn:
                conn.row_factory = sqlite3.Row
                if _table_exists(conn, "historical_market_bars"):
                    row = _one(
                        conn,
                        "SELECT MIN(ts) AS min_ts, MAX(ts) AS max_ts FROM historical_market_bars WHERE LOWER(COALESCE(provider,'')) LIKE '%fmp%'",
                    )
                    if row and row.get("min_ts") and row.get("max_ts"):
                        fmp_bar_range_iso = (_iso_from_unix(row.get("min_ts")), _iso_from_unix(row.get("max_ts")))
        except Exception:
            pass
        for table in (
            "historical_market_bars",
            "trade_journal",
            "paper_replay_trades",
            "lifecycle_tracking_v2",
            "lifecycle_tracking",
            "paper_positions",
            "open_positions_v2",
            "open_positions",
        ):
            summary = _sqlite_source_summary(db_path, table, fmp_bar_range=fmp_bar_range_iso)
            if summary.get("row_count", 0) > 0 or "table_missing" not in (summary.get("limitations") or []):
                source_summaries.append(summary)

    if include_file_scan:
        for path in (
            "trade_log.csv",
            "astra_trade_log.csv",
            "top_signals.csv",
            os.path.join(STATE, "learning_ledger_state.json"),
            os.path.join(STATE, "paper_replay_status.json"),
            os.path.join(STATE, "live_signal_log.json"),
            os.path.join(STATE, "paper_autopilot_state.json"),
            os.path.join("astra_dashboard", "universe", "universe_cache.json"),
        ):
            scanned.append(_safe_path(path))
            if os.path.exists(path):
                found.append(_safe_path(path))
                source_summaries.append(_file_source_summary(path))

    total_rows = sum(int(_to_float(s.get("row_count"), 0.0)) for s in source_summaries)
    fmp_labeled_rows = sum(int(_to_float(s.get("fmp_rows_count"), 0.0)) for s in source_summaries)
    likely_fmp_era_rows = sum(int(_to_float(s.get("likely_fmp_era_rows"), 0.0)) for s in source_summaries)
    usable_entry_rows = sum(int(_to_float(s.get("row_count"), 0.0)) for s in source_summaries if bool(s.get("timing_reconstruction_possible", False)))
    usable_exit_rows = sum(int(_to_float(s.get("row_count"), 0.0)) for s in source_summaries if bool(s.get("exit_reconstruction_possible", False)))
    usable_setup_rows = sum(int(_to_float(s.get("row_count"), 0.0)) for s in source_summaries if bool(s.get("setup_context_learning_possible", False)))
    usable_learning_rows = max(usable_entry_rows, usable_exit_rows, usable_setup_rows)
    best_source = "none"
    if source_summaries:
        ranked_sources = sorted(
            source_summaries,
            key=lambda s: (
                int(bool(s.get("fmp_rows_count", 0) > 0)) * 5
                + int(bool(s.get("timing_reconstruction_possible", False))) * 3
                + int(bool(s.get("exit_reconstruction_possible", False))) * 3
                + int(bool(s.get("setup_context_learning_possible", False))) * 2,
                int(_to_float(s.get("row_count"), 0.0)),
            ),
            reverse=True,
        )
        best_source = str(ranked_sources[0].get("path_or_table") or ranked_sources[0].get("source_name") or "none")

    missing = []
    if not any(_to_float(s.get("outcome_coverage_percent"), 0.0) > 0 for s in source_summaries if s.get("fmp_rows_count", 0) > 0):
        missing.append("fmp_labeled_outcomes")
    if not any(_to_float(s.get("setup_label_coverage_percent"), 0.0) > 25 for s in source_summaries):
        missing.append("dense_setup_labels")
    if not any(_to_float(s.get("entry_quality_coverage_percent"), 0.0) > 25 for s in source_summaries):
        missing.append("dense_entry_quality_scores")
    if not any(_to_float(s.get("mfe_mae_coverage_percent"), 0.0) > 25 for s in source_summaries):
        missing.append("dense_mfe_mae_exit_path")

    if fmp_labeled_rows > 5000 and usable_exit_rows > 10000:
        feasibility = "moderate"
        recommended = "build_partial_replay_engine"
    elif fmp_labeled_rows > 1000 and usable_entry_rows > 1000:
        feasibility = "limited"
        recommended = "improve_data_mapping_first"
    elif fmp_labeled_rows > 0:
        feasibility = "limited"
        recommended = "build_partial_replay_engine"
    else:
        feasibility = "not_available"
        recommended = "no_usable_historical_data_found"

    return {
        "fmp_historical_learning_audit_v1": True,
        "diagnostic_only": True,
        "audit_timestamp": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "sources_scanned": list(dict.fromkeys(scanned)),
        "sources_found": list(dict.fromkeys(found)),
        "total_rows_found": int(total_rows),
        "fmp_labeled_rows": int(fmp_labeled_rows),
        "likely_fmp_era_rows": int(likely_fmp_era_rows),
        "usable_learning_rows": int(usable_learning_rows),
        "usable_entry_timing_rows": int(usable_entry_rows),
        "usable_exit_learning_rows": int(usable_exit_rows),
        "usable_setup_context_rows": int(usable_setup_rows),
        "best_available_source": best_source,
        "biggest_missing_fields": missing,
        "replay_engine_feasibility": feasibility,
        "recommended_next_step": recommended,
        "entry_timing_learning_possible": bool(usable_entry_rows > 0 and fmp_labeled_rows > 0),
        "exit_behavior_learning_possible": bool(usable_exit_rows > 0),
        "setup_context_learning_possible": bool(usable_setup_rows > 0),
        "fmp_historical_bar_range": {
            "start": fmp_bar_range_iso[0] if fmp_bar_range_iso else "",
            "end": fmp_bar_range_iso[1] if fmp_bar_range_iso else "",
        },
        "per_source_summaries": source_summaries,
    }


@router.get("/api/fmp_historical_replay_v1")
def fmp_historical_replay_v1(
    force_refresh: bool = Query(default=False),
    max_trades: int = Query(default=75000),
):
    def _pct(n, d):
        return round((_to_float(n, 0.0) / max(1.0, _to_float(d, 0.0))) * 100.0, 2)

    def _iso_from_unix(value):
        try:
            v = float(value)
            if v <= 0:
                return ""
            return datetime.fromtimestamp(v, UTC).isoformat().replace("+00:00", "Z")
        except Exception:
            return ""

    def _parse_dt(value):
        text = str(value or "").strip()
        if not text:
            return None
        try:
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            dt = datetime.fromisoformat(text)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=UTC)
            return dt.astimezone(UTC)
        except Exception:
            return None

    def _bucket_hour(dt):
        if not dt:
            return "unknown"
        hour = int(dt.hour)
        if hour < 13:
            return "pre_market_or_open"
        if hour < 15:
            return "morning"
        if hour < 18:
            return "midday"
        if hour < 20:
            return "late_day"
        return "after_hours"

    def _median(values):
        vals = sorted([float(v) for v in values if v is not None])
        n = len(vals)
        if n <= 0:
            return 0.0
        mid = n // 2
        if n % 2:
            return round(vals[mid], 4)
        return round((vals[mid - 1] + vals[mid]) / 2.0, 4)

    def _quality_label(count, win_rate, avg_return):
        if count < 20:
            return "insufficient"
        if win_rate >= 45.0 and avg_return > 0.20:
            return "strong"
        if win_rate >= 35.0 and avg_return >= 0.0:
            return "usable"
        if win_rate < 22.0 or avg_return <= -0.25:
            return "avoid"
        return "weak"

    def _stats(rows):
        vals = [_to_float(r.get("return_percent"), 0.0) for r in rows]
        count = len(vals)
        wins = sum(1 for v in vals if v > 0)
        avg_ret = round(sum(vals) / max(1, count), 4)
        win_rate = _pct(wins, count)
        return {
            "sample_count": int(count),
            "win_rate": win_rate,
            "loss_rate": round(100.0 - win_rate, 2),
            "avg_return": avg_ret,
            "median_return": _median(vals),
            "quality_label": _quality_label(count, win_rate, avg_ret),
        }

    def _top_group_stats(rows, key, limit=10, min_count=10):
        groups = {}
        for row in rows:
            label = str(row.get(key) or "unknown").strip().lower() or "unknown"
            groups.setdefault(label, []).append(row)
        out = []
        for label, members in groups.items():
            if len(members) < min_count:
                continue
            item = _stats(members)
            item[key] = label
            out.append(item)
        out.sort(key=lambda x: (x.get("quality_label") == "strong", x.get("win_rate", 0), x.get("avg_return", 0), x.get("sample_count", 0)), reverse=True)
        return out[:limit]

    def _source_signature(conn):
        try:
            bars = conn.execute(
                "SELECT COUNT(1) AS n, MAX(ts) AS max_ts FROM historical_market_bars WHERE provider='FMP_HIST'"
            ).fetchone()
            trades = conn.execute(
                "SELECT COUNT(1) AS n, MAX(exit_timestamp) AS max_exit FROM trade_journal WHERE exit_timestamp IS NOT NULL AND return_percent IS NOT NULL"
            ).fetchone()
            return {
                "fmp_bar_rows": int((bars or {}).get("n", 0)),
                "fmp_bar_max_ts": int(_to_float((bars or {}).get("max_ts"), 0.0)),
                "trade_rows": int((trades or {}).get("n", 0)),
                "trade_max_exit": str((trades or {}).get("max_exit") or ""),
            }
        except Exception:
            return {}

    def _load_fmp_bars(conn):
        rows = conn.execute(
            """
            SELECT symbol, ts, o, h, l, c, v
            FROM historical_market_bars
            WHERE provider='FMP_HIST'
              AND symbol IS NOT NULL
              AND ts IS NOT NULL
            ORDER BY symbol, ts
            """
        ).fetchall()
        by_symbol = {}
        for row in rows:
            sym = str(row["symbol"] or "").upper().strip()
            if not sym:
                continue
            item = {
                "ts": int(_to_float(row["ts"], 0.0)),
                "o": _to_float(row["o"], 0.0),
                "h": _to_float(row["h"], 0.0),
                "l": _to_float(row["l"], 0.0),
                "c": _to_float(row["c"], 0.0),
                "v": _to_float(row["v"], 0.0),
            }
            by_symbol.setdefault(sym, []).append(item)
        indexes = {sym: [int(b["ts"]) for b in bars] for sym, bars in by_symbol.items()}
        return by_symbol, indexes

    def _load_trade_rows(conn, symbols, limit):
        if not symbols:
            return []
        capped = max(1000, min(200000, int(_to_float(limit, 75000))))
        placeholders = ",".join(["?"] * len(symbols))
        query = f"""
            SELECT
                trade_id, symbol, entry_timestamp, exit_timestamp, entry_price, exit_price,
                return_percent, friction_adjusted_return, holding_period, duration_minutes,
                max_favorable_excursion, max_adverse_excursion, peak_unrealized_pnl_percent,
                time_to_peak_seconds, time_to_exit_seconds, exit_reason, trade_origin,
                market_regime, entry_regime, entry_persona_best_fit, entry_persona_fit_summary,
                detected_setup_type, setup_type, setup_candidate_realness,
                setup_detection_band, setup_detection_score, entry_quality_band,
                entry_quality_score, entry_quality_candidate_class, conviction_tier,
                buy_eligibility, buy_quality_tier, entry_confidence
            FROM trade_journal
            WHERE exit_timestamp IS NOT NULL
              AND return_percent IS NOT NULL
              AND symbol IN ({placeholders})
            ORDER BY exit_timestamp DESC
            LIMIT ?
        """
        return [dict(r or {}) for r in conn.execute(query, list(symbols) + [capped]).fetchall()]

    def _match_bar(trade, bars_by_symbol, bar_indexes):
        sym = str(trade.get("symbol") or "").upper().strip()
        dt = _parse_dt(trade.get("entry_timestamp"))
        bars = bars_by_symbol.get(sym) or []
        idxs = bar_indexes.get(sym) or []
        if not dt or not bars:
            return None, "no_match"
        entry_ts = int(dt.timestamp())
        pos = bisect.bisect_right(idxs, entry_ts) - 1
        if pos < 0:
            return None, "no_match"
        bar = bars[pos]
        bar_dt = datetime.fromtimestamp(int(bar.get("ts") or 0), UTC)
        if abs(entry_ts - int(bar.get("ts") or 0)) <= 60:
            quality = "exact_time_match"
        elif bar_dt.date() == dt.date():
            quality = "same_day_match"
        else:
            quality = "nearest_prior_bar"
        return bar, quality

    def _enrich_join(trade, bar, join_quality):
        row = dict(trade or {})
        row["join_quality"] = join_quality
        row["bar_timestamp"] = int(_to_float((bar or {}).get("ts"), 0.0)) if bar else 0
        row["bar_date"] = _iso_from_unix(row["bar_timestamp"])[:10] if row["bar_timestamp"] else ""
        setup = str(row.get("detected_setup_type") or row.get("setup_type") or "fallback_unclear").strip().lower() or "fallback_unclear"
        row["setup_group"] = setup
        row["regime_group"] = str(row.get("market_regime") or row.get("entry_regime") or "unknown").strip().lower() or "unknown"
        row["persona_group"] = str(row.get("entry_persona_best_fit") or row.get("entry_persona_fit_summary") or "unknown").strip().lower() or "unknown"
        row["entry_quality_group"] = str(row.get("entry_quality_band") or "unknown").strip().lower() or "unknown"
        row["candidate_realness_group"] = str(row.get("setup_candidate_realness") or row.get("entry_quality_candidate_class") or "unknown").strip().lower() or "unknown"
        dt = _parse_dt(row.get("entry_timestamp"))
        row["entry_time_bucket"] = _bucket_hour(dt)
        entry = _to_float(row.get("entry_price"), 0.0)
        if bar:
            o = _to_float(bar.get("o"), 0.0)
            h = _to_float(bar.get("h"), 0.0)
            l = _to_float(bar.get("l"), 0.0)
            c = _to_float(bar.get("c"), 0.0)
            rng = max(0.0, h - l)
            row["bar_direction"] = "green" if c >= o else "red"
            row["entry_vs_open_percent"] = round(((entry - o) / o) * 100.0, 4) if entry > 0 and o > 0 else 0.0
            row["entry_vs_close_percent"] = round(((entry - c) / c) * 100.0, 4) if entry > 0 and c > 0 else 0.0
            if entry > 0 and rng > 0:
                loc = max(0.0, min(1.0, (entry - l) / rng))
                row["entry_vs_bar_range"] = round(loc, 4)
                if loc >= 0.78:
                    row["entry_location_bucket"] = "near_bar_high"
                elif loc <= 0.22:
                    row["entry_location_bucket"] = "near_bar_low"
                elif abs(entry - c) <= (rng * 0.18):
                    row["entry_location_bucket"] = "near_bar_close"
                else:
                    row["entry_location_bucket"] = "mid_range"
            else:
                row["entry_vs_bar_range"] = None
                row["entry_location_bucket"] = "flat_or_missing_range"
        else:
            row["bar_direction"] = "unknown"
            row["entry_vs_open_percent"] = 0.0
            row["entry_vs_close_percent"] = 0.0
            row["entry_vs_bar_range"] = None
            row["entry_location_bucket"] = "no_bar_match"
        return row

    def _hold_seconds(row):
        seconds = _to_float(row.get("time_to_exit_seconds"), 0.0)
        if seconds > 0:
            return seconds
        mins = _to_float(row.get("holding_period"), _to_float(row.get("duration_minutes"), 0.0))
        return mins * 60.0 if mins > 0 else 0.0

    now = time.time()
    db_path = os.path.join(STATE, "ai_trading_memory.db")
    try:
        with sqlite3.connect(db_path, timeout=1.0) as sig_conn:
            sig_conn.row_factory = sqlite3.Row
            signature = _source_signature(sig_conn)
    except Exception:
        signature = {}
    cached = _FMP_HISTORICAL_REPLAY_CACHE
    if (
        not bool(force_refresh)
        and cached.get("payload")
        and cached.get("signature") == signature
        and (now - float(cached.get("ts", 0.0))) <= FMP_HISTORICAL_REPLAY_TTL_SECONDS
    ):
        out = dict(cached.get("payload") or {})
        out["cache_hit"] = True
        out["cache_ttl_seconds"] = int(FMP_HISTORICAL_REPLAY_TTL_SECONDS)
        return out

    started = time.perf_counter()
    limitations = []
    try:
        with sqlite3.connect(db_path, timeout=2.0) as conn:
            conn.row_factory = sqlite3.Row
            bars_by_symbol, bar_indexes = _load_fmp_bars(conn)
            symbols = sorted(bars_by_symbol.keys())
            trades = _load_trade_rows(conn, symbols, max_trades)
    except Exception as e:
        return {
            "fmp_historical_replay_v1": True,
            "generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "diagnostic_only": True,
            "error": str(e)[:220],
            "source_summary": {"db_path": db_path, "fmp_bar_rows": 0, "trade_rows_scanned": 0},
            "replay_confidence": "not_available",
            "limitations": ["local_replay_build_failed"],
            "recommended_next_step": "improve_data_mapping_first",
        }

    joined = []
    join_counts = {"exact_time_match": 0, "same_day_match": 0, "nearest_prior_bar": 0, "no_match": 0}
    for trade in trades:
        bar, quality = _match_bar(trade, bars_by_symbol, bar_indexes)
        join_counts[quality] = int(join_counts.get(quality, 0)) + 1
        if not bar:
            continue
        joined.append(_enrich_join(trade, bar, quality))

    setup_perf = _top_group_stats(joined, "setup_group", limit=14, min_count=20)
    regime_perf = _top_group_stats(joined, "regime_group", limit=10, min_count=20)
    persona_perf = _top_group_stats(joined, "persona_group", limit=10, min_count=20)
    quality_perf = _top_group_stats(joined, "entry_quality_group", limit=10, min_count=10)
    realness_perf = _top_group_stats(joined, "candidate_realness_group", limit=10, min_count=10)

    setup_regime_groups = {}
    for row in joined:
        key = f"{row.get('setup_group','unknown')}::{row.get('regime_group','unknown')}"
        setup_regime_groups.setdefault(key, []).append(row)
    setup_regime = []
    for key, members in setup_regime_groups.items():
        if len(members) < 30:
            continue
        stats = _stats(members)
        setup_type, regime = key.split("::", 1)
        stats["setup_type"] = setup_type
        stats["regime"] = regime
        setup_regime.append(stats)
    setup_regime.sort(key=lambda x: (x.get("quality_label") == "strong", x.get("win_rate", 0), x.get("avg_return", 0)), reverse=True)

    timing_by_bucket = _top_group_stats(joined, "entry_time_bucket", limit=8, min_count=10)
    timing_by_location = _top_group_stats(joined, "entry_location_bucket", limit=8, min_count=10)
    timing_by_bar_direction = _top_group_stats(joined, "bar_direction", limit=4, min_count=10)
    timing_warnings = []
    for item in timing_by_location:
        if item.get("entry_location_bucket") == "near_bar_high" and item.get("quality_label") in {"weak", "avoid"}:
            timing_warnings.append("entries_near_bar_high_underperform")
        if item.get("entry_location_bucket") == "flat_or_missing_range":
            limitations.append("many_fmp_rows_have_flat_daily_range_or_missing_intraday_range")
    for item in timing_by_bucket:
        if item.get("quality_label") in {"weak", "avoid"}:
            timing_warnings.append(f"weak_time_bucket:{item.get('entry_time_bucket')}")

    winners = [r for r in joined if _to_float(r.get("return_percent"), 0.0) > 0]
    losers = [r for r in joined if _to_float(r.get("return_percent"), 0.0) <= 0]
    winner_holds = [_hold_seconds(r) for r in winners if _hold_seconds(r) > 0]
    loser_holds = [_hold_seconds(r) for r in losers if _hold_seconds(r) > 0]
    mfe_rows = []
    missed_profit = []
    for row in joined:
        ret = _to_float(row.get("return_percent"), 0.0)
        mfe = max(_to_float(row.get("max_favorable_excursion"), 0.0), _to_float(row.get("peak_unrealized_pnl_percent"), 0.0))
        if mfe > 0:
            mfe_rows.append(row)
        if mfe > 0 and mfe > ret + 1.25:
            missed_profit.append(row)
    exit_setup = _top_group_stats(mfe_rows, "setup_group", limit=8, min_count=10)
    exit_behavior = {
        "sample_count": int(len(joined)),
        "mfe_mae_sample_count": int(len(mfe_rows)),
        "mfe_mae_coverage_percent": _pct(len(mfe_rows), len(joined)),
        "avg_hold_seconds_winners": round(sum(winner_holds) / max(1, len(winner_holds)), 2),
        "avg_hold_seconds_losers": round(sum(loser_holds) / max(1, len(loser_holds)), 2),
        "missed_profit_case_count": int(len(missed_profit)),
        "missed_profit_case_rate_percent": _pct(len(missed_profit), len(mfe_rows)),
        "setup_exit_quality_with_mfe": exit_setup,
        "exit_behavior_note": "MFE/MAE coverage is sparse; exit findings are directional only." if _pct(len(mfe_rows), len(joined)) < 25 else "Exit path coverage is usable for partial replay.",
    }

    weak_setups = [x for x in setup_perf if x.get("quality_label") in {"avoid", "weak"}]
    weak_regimes = [x for x in regime_perf if x.get("quality_label") in {"avoid", "weak"}]
    weak_setup_regimes = [x for x in setup_regime if x.get("quality_label") in {"avoid", "weak"}][:10]
    weak_personas = [x for x in persona_perf if x.get("quality_label") in {"avoid", "weak"}]
    weak_quality_bands = [x for x in quality_perf if x.get("quality_label") in {"avoid", "weak"}]
    avoid_patterns = {
        "avoid_setup_types": weak_setups[:8],
        "avoid_setup_regimes": weak_setup_regimes,
        "weak_persona_contexts": weak_personas[:8],
        "weak_entry_quality_bands": weak_quality_bands[:8],
        "avoid_pattern_sample_count": int(sum(int(x.get("sample_count", 0)) for x in weak_setups[:8])),
    }
    recommendations = []
    if weak_setups:
        recommendations.append({
            "recommendation": "require_confirmation_for_weak_setup_families",
            "targets": [str(x.get("setup_group")) for x in weak_setups[:5]],
            "scope": "learning_summary_only",
        })
    if weak_setup_regimes:
        recommendations.append({
            "recommendation": "reduce_or_paper_only_weak_setup_regime_pairs",
            "targets": [f"{x.get('setup_type')}::{x.get('regime')}" for x in weak_setup_regimes[:5]],
            "scope": "learning_summary_only",
        })
    if timing_warnings:
        recommendations.append({
            "recommendation": "use_entry_timing_warnings_as_future_confirmation_filters",
            "targets": list(dict.fromkeys(timing_warnings))[:6],
            "scope": "learning_summary_only",
        })
    if not recommendations:
        recommendations.append({
            "recommendation": "collect_more_joined_replay_evidence_before_policy_use",
            "targets": [],
            "scope": "learning_summary_only",
        })

    joined_count = len(joined)
    same_day_or_exact = join_counts.get("same_day_match", 0) + join_counts.get("exact_time_match", 0)
    if joined_count >= 10000 and _pct(same_day_or_exact, joined_count) >= 40.0:
        replay_confidence = "moderate"
    elif joined_count >= 1000:
        replay_confidence = "limited"
    else:
        replay_confidence = "low"
    if not any(x == "dense_entry_quality_scores_missing" for x in limitations) and not quality_perf:
        limitations.append("dense_entry_quality_scores_missing")
    if exit_behavior.get("mfe_mae_coverage_percent", 0.0) < 25.0:
        limitations.append("limited_mfe_mae_exit_path")
    if join_counts.get("nearest_prior_bar", 0) > same_day_or_exact:
        limitations.append("many_joins_use_nearest_prior_daily_bar_not_exact_intraday_match")
    if len(trades) >= max(1000, min(200000, int(_to_float(max_trades, 75000)))):
        limitations.append("trade_scan_capped_by_max_trades")

    payload = {
        "fmp_historical_replay_v1": True,
        "diagnostic_only": True,
        "generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "cache_hit": False,
        "cache_generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "cache_ttl_seconds": int(FMP_HISTORICAL_REPLAY_TTL_SECONDS),
        "cache_source_row_counts": signature,
        "runtime_ms": round((time.perf_counter() - started) * 1000.0, 2),
        "source_summary": {
            "db_path": db_path,
            "fmp_provider": "FMP_HIST",
            "fmp_bar_rows": int(sum(len(v) for v in bars_by_symbol.values())),
            "fmp_symbol_count": int(len(bars_by_symbol)),
            "trade_rows_scanned": int(len(trades)),
            "max_trades": int(max(1000, min(200000, int(_to_float(max_trades, 75000))))),
            "no_external_api_calls": True,
        },
        "join_summary": {
            "joined_rows": int(joined_count),
            "join_rate_percent": _pct(joined_count, len(trades)),
            "join_quality_counts": join_counts,
            "exact_or_same_day_join_percent": _pct(same_day_or_exact, joined_count),
            "nearest_prior_join_percent": _pct(join_counts.get("nearest_prior_bar", 0), joined_count),
        },
        "setup_performance": {
            "by_setup_type": setup_perf,
            "by_regime": regime_perf,
            "by_persona": persona_perf,
            "by_entry_quality_band": quality_perf,
            "by_candidate_realness": realness_perf,
            "by_setup_regime": setup_regime[:12],
        },
        "entry_timing_summary": {
            "entry_timing_sample_count": int(joined_count),
            "best_entry_time_buckets": [x for x in timing_by_bucket if x.get("quality_label") in {"strong", "usable"}],
            "weak_entry_time_buckets": [x for x in timing_by_bucket if x.get("quality_label") in {"weak", "avoid"}],
            "entry_location_performance": timing_by_location,
            "bar_direction_performance": timing_by_bar_direction,
            "entry_timing_warnings": list(dict.fromkeys(timing_warnings)),
        },
        "exit_behavior_summary": exit_behavior,
        "avoid_trade_patterns": avoid_patterns,
        "trade_reduction_recommendations": recommendations,
        "replay_confidence": replay_confidence,
        "limitations": list(dict.fromkeys([str(x) for x in limitations if str(x).strip()])),
        "recommended_next_step": "wire_replay_summary_into_learning_policy_review" if replay_confidence in {"moderate", "limited"} else "collect_more_replay_data",
    }
    _FMP_HISTORICAL_REPLAY_CACHE["payload"] = dict(payload)
    _FMP_HISTORICAL_REPLAY_CACHE["ts"] = time.time()
    _FMP_HISTORICAL_REPLAY_CACHE["signature"] = signature
    return payload


def _build_historical_replay_policy_review_v1(replay_payload):
    def _confidence_label(sample_count, replay_confidence):
        count = int(_to_float(sample_count, 0.0))
        conf = str(replay_confidence or "").lower()
        if conf == "moderate" and count >= 1000:
            return "moderate_high"
        if count >= 250:
            return "moderate"
        if count >= 50:
            return "limited"
        return "insufficient"

    def _policy_strength(sample_count, win_rate, avg_return):
        count = max(0.0, _to_float(sample_count, 0.0))
        wr = _to_float(win_rate, 0.0)
        ret = _to_float(avg_return, 0.0)
        sample_score = min(35.0, count / 150.0)
        win_component = max(-25.0, min(25.0, (wr - 40.0) * 1.1))
        return_component = max(-25.0, min(25.0, ret * 12.0))
        score = 45.0 + sample_score + win_component + return_component
        return round(max(0.0, min(100.0, score)), 2)

    def _setup_reason(setup_type, policy, item):
        wr = round(_to_float(item.get("win_rate"), 0.0), 2)
        avg = round(_to_float(item.get("avg_return"), 0.0), 4)
        count = int(_to_float(item.get("sample_count"), 0.0))
        label = str(item.get("quality_label") or "unknown")
        if policy == "favor":
            return f"{setup_type} has the best replay support: {count} samples, {wr}% win rate, {avg}% average return."
        if policy == "allow":
            return f"{setup_type} is usable in replay but should still pass current setup, entry-quality, and safety checks."
        if policy == "confirmation_required":
            return f"{setup_type} is mixed in replay; require current confirmation before any paper-ready consideration."
        if policy == "paper_only":
            return f"{setup_type} is weak or inconsistent in replay; keep it paper/monitor oriented unless context improves."
        if policy == "avoid":
            return f"{setup_type} underperformed in replay ({label}); review-only recommendation is to reduce or avoid."
        return f"{setup_type} does not have enough replay evidence for a confident policy."

    def _classify_setup_policy(item):
        setup_type = str(item.get("setup_group") or item.get("setup_type") or "unknown").strip().lower() or "unknown"
        count = int(_to_float(item.get("sample_count"), 0.0))
        win_rate = _to_float(item.get("win_rate"), 0.0)
        avg_return = _to_float(item.get("avg_return"), 0.0)
        quality = str(item.get("quality_label") or "").lower()
        ambiguous_family = setup_type in {"fallback_unclear", "unknown", "unclassified_setup"}
        if count < 20:
            policy = "insufficient_evidence"
        elif ambiguous_family:
            policy = "paper_only" if win_rate >= 35.0 and avg_return >= 0.0 else "avoid"
        elif quality == "strong" and win_rate >= 45.0 and avg_return > 0.2:
            policy = "favor"
        elif quality == "usable" and win_rate >= 35.0 and avg_return >= 0.0:
            policy = "allow"
        elif setup_type in {"range_rotation", "trend_continuation"} and (quality in {"weak", "avoid"} or avg_return < 0.0):
            policy = "avoid"
        elif quality == "avoid" or win_rate < 28.0 or avg_return <= -0.25:
            policy = "avoid"
        elif setup_type == "squeeze_breakout" or quality == "weak":
            policy = "confirmation_required" if win_rate >= 35.0 and avg_return > -0.25 else "paper_only"
        else:
            policy = "confirmation_required"
        return {
            "setup_type": setup_type,
            "policy": policy,
            "policy_strength_score": _policy_strength(count, win_rate, avg_return),
            "sample_count": count,
            "win_rate": round(win_rate, 2),
            "avg_return": round(avg_return, 4),
            "median_return": round(_to_float(item.get("median_return"), 0.0), 4),
            "quality_label": quality or "unknown",
            "confidence_label": _confidence_label(count, replay_payload.get("replay_confidence")),
            "reason": _setup_reason(setup_type, policy, item),
            "enforcement_status": "review_only",
        }

    def _timing_policy_from_bucket(item, default_policy):
        bucket = str(item.get("entry_time_bucket") or "unknown").strip().lower() or "unknown"
        count = int(_to_float(item.get("sample_count"), 0.0))
        wr = _to_float(item.get("win_rate"), 0.0)
        avg = _to_float(item.get("avg_return"), 0.0)
        policy = default_policy
        if default_policy == "allow_when_setup_quality_strong" and (wr < 35.0 or avg < 0.0):
            policy = "confirmation_required"
        return {
            "bucket": bucket,
            "policy": policy,
            "policy_strength_score": _policy_strength(count, wr, avg),
            "sample_count": count,
            "win_rate": round(wr, 2),
            "avg_return": round(avg, 4),
            "confidence_label": _confidence_label(count, replay_payload.get("replay_confidence")),
            "reason": "Replay timing is supportive only when current setup and entry quality agree." if "allow" in policy else "Replay timing is weak or mixed; require confirmation before entry.",
            "enforcement_status": "review_only",
        }

    replay_payload = dict(replay_payload or {})
    setup_perf = dict(replay_payload.get("setup_performance") or {})
    setup_items = list(setup_perf.get("by_setup_type") or [])
    setup_policies = [_classify_setup_policy(item) for item in setup_items]
    setup_policies.sort(key=lambda x: (x.get("policy") == "favor", x.get("policy_strength_score", 0.0), x.get("sample_count", 0)), reverse=True)

    timing = dict(replay_payload.get("entry_timing_summary") or {})
    entry_policies = []
    for item in list(timing.get("best_entry_time_buckets") or []):
        entry_policies.append(_timing_policy_from_bucket(item, "allow_when_setup_quality_strong"))
    for item in list(timing.get("weak_entry_time_buckets") or []):
        entry_policies.append(_timing_policy_from_bucket(item, "confirmation_required"))
    for warning in list(timing.get("entry_timing_warnings") or []):
        entry_policies.append({
            "policy": "caution",
            "warning": str(warning),
            "policy_strength_score": 55.0,
            "confidence_label": "limited",
            "reason": "Historical bars flag this as a timing caution; do not enforce without current confirmation.",
            "enforcement_status": "review_only",
        })
    if not entry_policies:
        entry_policies.append({
            "policy": "confirmation_required",
            "policy_strength_score": 35.0,
            "confidence_label": "insufficient",
            "reason": "Replay timing evidence is unavailable or too sparse.",
            "enforcement_status": "review_only",
        })

    exit_summary = dict(replay_payload.get("exit_behavior_summary") or {})
    mfe_coverage = _to_float(exit_summary.get("mfe_mae_coverage_percent"), 0.0)
    missed_rate = _to_float(exit_summary.get("missed_profit_case_rate_percent"), 0.0)
    missed_count = int(_to_float(exit_summary.get("missed_profit_case_count"), 0.0))
    exit_conf = "moderate" if mfe_coverage >= 25.0 else "low"
    exit_policies = {
        "exit_policy_confidence": exit_conf,
        "directional_only": bool(exit_conf == "low"),
        "avoid_hard_enforcement": True,
        "missed_profit_warning": bool(missed_count >= 20 and missed_rate >= 5.0),
        "missed_profit_case_count": missed_count,
        "missed_profit_case_rate_percent": round(missed_rate, 2),
        "avg_hold_seconds_winners": round(_to_float(exit_summary.get("avg_hold_seconds_winners"), 0.0), 2),
        "avg_hold_seconds_losers": round(_to_float(exit_summary.get("avg_hold_seconds_losers"), 0.0), 2),
        "recommended_data_improvement": "enrich_mfe_mae_exit_path",
        "reason": "MFE/MAE coverage is sparse; exit findings should guide review, not automatic policy.",
        "enforcement_status": "review_only",
    }

    weak_setup_regimes = list((replay_payload.get("avoid_trade_patterns") or {}).get("avoid_setup_regimes") or [])
    trade_reduction_rules = []
    for policy in setup_policies:
        if policy.get("policy") in {"avoid", "paper_only", "confirmation_required"}:
            trade_reduction_rules.append({
                "rule": f"{policy.get('policy')}:{policy.get('setup_type')}",
                "setup_type": policy.get("setup_type"),
                "recommendation": policy.get("policy"),
                "policy_strength_score": policy.get("policy_strength_score"),
                "sample_count": policy.get("sample_count"),
                "reason": policy.get("reason"),
                "enforcement_status": "review_only",
            })
    for item in weak_setup_regimes[:8]:
        setup_type = str(item.get("setup_type") or "unknown")
        regime = str(item.get("regime") or "unknown")
        trade_reduction_rules.append({
            "rule": f"reduce_or_confirm:{setup_type}:{regime}",
            "setup_type": setup_type,
            "regime": regime,
            "recommendation": "confirmation_required" if setup_type == "squeeze_breakout" else "avoid",
            "policy_strength_score": _policy_strength(item.get("sample_count"), item.get("win_rate"), item.get("avg_return")),
            "sample_count": int(_to_float(item.get("sample_count"), 0.0)),
            "reason": f"{setup_type} in {regime} is weak in replay; keep this as review-only trade reduction guidance.",
            "enforcement_status": "review_only",
        })
    favor_policy = next((p for p in setup_policies if p.get("policy") == "favor"), None)
    if favor_policy:
        trade_reduction_rules.insert(0, {
            "rule": f"favor_only_when_current_quality_agrees:{favor_policy.get('setup_type')}",
            "setup_type": favor_policy.get("setup_type"),
            "recommendation": "favor_with_current_confirmation",
            "policy_strength_score": favor_policy.get("policy_strength_score"),
            "sample_count": favor_policy.get("sample_count"),
            "reason": "Replay support can only be used when current setup detection and entry quality also agree.",
            "enforcement_status": "review_only",
        })

    replay_confidence = str(replay_payload.get("replay_confidence") or "not_available")
    limitations = list(dict.fromkeys([str(x) for x in list(replay_payload.get("limitations") or []) if str(x).strip()]))
    confidence_warnings = []
    if replay_confidence not in {"moderate"}:
        confidence_warnings.append("replay_confidence_not_high")
    if mfe_coverage < 25.0:
        confidence_warnings.append("exit_policy_directional_only_due_sparse_mfe_mae")
    if "many_fmp_rows_have_flat_daily_range_or_missing_intraday_range" in limitations:
        confidence_warnings.append("entry_timing_precision_limited_by_daily_or_flat_bars")
    if not setup_policies:
        confidence_warnings.append("setup_policy_evidence_missing")

    top_favor = next((p for p in setup_policies if p.get("policy") in {"favor", "allow"}), {})
    top_avoid = next(
        (
            p for p in setup_policies
            if p.get("policy") == "avoid"
            and str(p.get("setup_type") or "") not in {"unknown", "fallback_unclear", "unclassified_setup"}
        ),
        None,
    )
    if not top_avoid:
        top_avoid = next((p for p in setup_policies if p.get("policy") == "avoid"), None)
    if not top_avoid:
        top_avoid = next((p for p in setup_policies if p.get("policy") == "paper_only"), {})
    return {
        "historical_replay_policy_review_v1": True,
        "generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "replay_confidence": replay_confidence,
        "source_summary": dict(replay_payload.get("source_summary") or {}),
        "join_summary": dict(replay_payload.get("join_summary") or {}),
        "policy_mode": "review_only",
        "recommended_setup_policies": setup_policies,
        "recommended_entry_timing_policies": entry_policies,
        "recommended_exit_policies": exit_policies,
        "recommended_trade_reduction_rules": trade_reduction_rules[:24],
        "top_replay_favor_setup": top_favor.get("setup_type", ""),
        "top_replay_avoid_setup": top_avoid.get("setup_type", ""),
        "confidence_warnings": confidence_warnings,
        "limitations": limitations,
        "recommended_next_step": "review_then_wire_policy_as_optional_learning_signal",
        "no_live_behavior_changes": True,
        "enforcement_status": "review_only",
    }


def _historical_policy_review_learning_summary():
    cached = dict(_HISTORICAL_REPLAY_POLICY_REVIEW_CACHE.get("payload") or {})
    if not cached:
        return {
            "historical_policy_review_available": False,
            "historical_policy_review_mode": "review_only",
            "historical_policy_review_confidence": "not_built",
        }
    return {
        "historical_policy_review_available": True,
        "historical_policy_review_mode": str(cached.get("policy_mode") or "review_only"),
        "top_replay_favor_setup": str(cached.get("top_replay_favor_setup") or ""),
        "top_replay_avoid_setup": str(cached.get("top_replay_avoid_setup") or ""),
        "historical_policy_review_confidence": str(cached.get("replay_confidence") or "not_available"),
        "historical_policy_review_generated_at": str(cached.get("generated_at") or ""),
    }


def _attach_historical_policy_review_availability(payload):
    out = dict(payload or {})
    try:
        out.update(_historical_policy_review_learning_summary())
        out.update(_historical_training_memory_learning_summary())
    except Exception:
        out["historical_policy_review_available"] = False
        out["historical_policy_review_mode"] = "review_only"
        out["historical_policy_review_confidence"] = "unavailable"
        out["historical_training_available"] = False
        out["historical_training_confidence"] = "unavailable"
    return out


@router.get("/api/historical_replay_policy_review_v1")
def historical_replay_policy_review_v1(
    force_refresh: bool = Query(default=False),
    max_trades: int = Query(default=75000),
):
    now = time.time()
    replay_cached = dict(_FMP_HISTORICAL_REPLAY_CACHE.get("payload") or {})
    signature = {
        "replay_signature": dict(_FMP_HISTORICAL_REPLAY_CACHE.get("signature") or {}),
        "replay_generated_at": str(replay_cached.get("cache_generated_at") or replay_cached.get("generated_at") or ""),
        "max_trades": int(max(1000, min(200000, int(_to_float(max_trades, 75000))))),
    }
    cached = _HISTORICAL_REPLAY_POLICY_REVIEW_CACHE
    if (
        not bool(force_refresh)
        and cached.get("payload")
        and cached.get("signature") == signature
        and (now - float(cached.get("ts", 0.0))) <= HISTORICAL_REPLAY_POLICY_REVIEW_TTL_SECONDS
    ):
        out = dict(cached.get("payload") or {})
        out["cache_hit"] = True
        out["cache_ttl_seconds"] = int(HISTORICAL_REPLAY_POLICY_REVIEW_TTL_SECONDS)
        return out
    try:
        replay_payload = fmp_historical_replay_v1(force_refresh=bool(force_refresh), max_trades=int(_to_float(max_trades, 75000)))
        payload = _build_historical_replay_policy_review_v1(replay_payload)
        payload["cache_hit"] = False
        payload["cache_generated_at"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        payload["cache_ttl_seconds"] = int(HISTORICAL_REPLAY_POLICY_REVIEW_TTL_SECONDS)
        payload["cache_source"] = "fmp_historical_replay_v1"
        _HISTORICAL_REPLAY_POLICY_REVIEW_CACHE["payload"] = dict(payload)
        _HISTORICAL_REPLAY_POLICY_REVIEW_CACHE["ts"] = time.time()
        _HISTORICAL_REPLAY_POLICY_REVIEW_CACHE["signature"] = {
            "replay_signature": dict(_FMP_HISTORICAL_REPLAY_CACHE.get("signature") or {}),
            "replay_generated_at": str(replay_payload.get("cache_generated_at") or replay_payload.get("generated_at") or ""),
            "max_trades": int(max(1000, min(200000, int(_to_float(max_trades, 75000))))),
        }
        return payload
    except Exception as e:
        return {
            "historical_replay_policy_review_v1": True,
            "generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "policy_mode": "review_only",
            "error": str(e)[:220],
            "replay_confidence": "not_available",
            "recommended_setup_policies": [],
            "recommended_entry_timing_policies": [],
            "recommended_exit_policies": {"exit_policy_confidence": "not_available", "directional_only": True},
            "recommended_trade_reduction_rules": [],
            "confidence_warnings": ["policy_review_build_failed"],
            "limitations": ["historical_policy_review_unavailable"],
            "recommended_next_step": "retry_after_replay_summary_is_available",
            "no_live_behavior_changes": True,
            "enforcement_status": "review_only",
        }


def _load_historical_training_memory_cached(force_reload=False):
    if not bool(force_reload):
        cached_payload = _HISTORICAL_TRAINING_MEMORY_CACHE.get("payload")
        if isinstance(cached_payload, dict) and cached_payload:
            return dict(cached_payload)
    try:
        if not os.path.exists(HISTORICAL_TRAINING_MEMORY_PATH):
            return {}
        mtime = float(os.path.getmtime(HISTORICAL_TRAINING_MEMORY_PATH))
        if (
            not bool(force_reload)
            and _to_float(_HISTORICAL_TRAINING_MEMORY_CACHE.get("file_mtime"), 0.0) == mtime
            and isinstance(_HISTORICAL_TRAINING_MEMORY_CACHE.get("payload"), dict)
        ):
            return dict(_HISTORICAL_TRAINING_MEMORY_CACHE.get("payload") or {})
        with open(HISTORICAL_TRAINING_MEMORY_PATH, "r") as fh:
            payload = json.load(fh)
        if isinstance(payload, dict) and payload:
            _HISTORICAL_TRAINING_MEMORY_CACHE["payload"] = dict(payload)
            _HISTORICAL_TRAINING_MEMORY_CACHE["ts"] = time.time()
            _HISTORICAL_TRAINING_MEMORY_CACHE["signature"] = dict(payload.get("cache_source_signature") or {})
            _HISTORICAL_TRAINING_MEMORY_CACHE["file_mtime"] = mtime
            return dict(payload)
    except Exception:
        return {}
    return {}


def _persist_historical_training_memory(payload):
    if not isinstance(payload, dict) or not payload:
        return False
    try:
        os.makedirs(os.path.dirname(HISTORICAL_TRAINING_MEMORY_PATH), exist_ok=True)
        tmp_path = f"{HISTORICAL_TRAINING_MEMORY_PATH}.tmp"
        with open(tmp_path, "w") as fh:
            json.dump(payload, fh)
        os.replace(tmp_path, HISTORICAL_TRAINING_MEMORY_PATH)
        _HISTORICAL_TRAINING_MEMORY_CACHE["payload"] = dict(payload)
        _HISTORICAL_TRAINING_MEMORY_CACHE["ts"] = time.time()
        _HISTORICAL_TRAINING_MEMORY_CACHE["signature"] = dict(payload.get("cache_source_signature") or {})
        try:
            _HISTORICAL_TRAINING_MEMORY_CACHE["file_mtime"] = float(os.path.getmtime(HISTORICAL_TRAINING_MEMORY_PATH))
        except Exception:
            _HISTORICAL_TRAINING_MEMORY_CACHE["file_mtime"] = 0.0
        return True
    except Exception:
        return False


def _policy_label_from_metrics(sample_count, win_rate, avg_return, *, setup_type="unknown"):
    count = int(_to_float(sample_count, 0.0))
    wr = _to_float(win_rate, 0.0)
    ar = _to_float(avg_return, 0.0)
    st = str(setup_type or "unknown").strip().lower()
    if count < 20:
        return "insufficient_data"
    if st in {"fallback_unclear", "unknown", "unclassified_setup"}:
        return "avoid" if (wr < 40.0 or ar <= 0.0) else "reduce"
    if wr >= 48.0 and ar > 0.35 and count >= 40:
        return "favor"
    if wr >= 42.0 and ar >= 0.0:
        return "allow"
    if st == "squeeze_breakout":
        return "confirmation_required" if wr >= 35.0 and ar > -0.2 else "reduce"
    if st in {"range_rotation", "trend_continuation"} and (wr < 42.0 or ar <= 0.0):
        return "avoid"
    if wr < 36.0 or ar <= -0.25:
        return "avoid"
    if wr < 42.0 or ar < 0.0:
        return "reduce"
    return "confirmation_required"


def _build_historical_training_memory_v1(replay_payload, policy_review_payload, *, max_rows, mode):
    rp = dict(replay_payload or {})
    pp = dict(policy_review_payload or {})
    setup_perf = dict(rp.get("setup_performance") or {})
    by_setup = list(setup_perf.get("by_setup_type") or [])
    by_setup_regime = list(setup_perf.get("by_setup_regime") or [])
    entry_timing = dict(rp.get("entry_timing_summary") or {})
    exit_summary = dict(rp.get("exit_behavior_summary") or {})
    avoid_patterns = dict(rp.get("avoid_trade_patterns") or {})

    setup_policies = []
    for item in by_setup:
        if not isinstance(item, dict):
            continue
        setup_type = str(item.get("setup_group") or item.get("setup_type") or "unknown").strip().lower() or "unknown"
        sample_count = int(_to_float(item.get("sample_count"), 0.0))
        win_rate = _to_float(item.get("win_rate"), 0.0)
        avg_return = _to_float(item.get("avg_return"), 0.0)
        policy_label = _policy_label_from_metrics(sample_count, win_rate, avg_return, setup_type=setup_type)
        setup_policies.append(
            {
                "setup_type": setup_type,
                "sample_count": sample_count,
                "win_rate": round(win_rate, 2),
                "avg_return": round(avg_return, 4),
                "median_return": round(_to_float(item.get("median_return"), 0.0), 4),
                "loss_rate": round(max(0.0, min(100.0, 100.0 - win_rate)), 2),
                "profit_factor": round(
                    max(0.0, min(10.0, (max(0.0, avg_return) + 0.01) / (abs(min(0.0, avg_return)) + 0.01))),
                    3,
                ),
                "policy_label": policy_label,
            }
        )
    setup_policies = sorted(
        setup_policies,
        key=lambda x: (x.get("policy_label") == "favor", x.get("avg_return", 0.0), x.get("win_rate", 0.0), x.get("sample_count", 0)),
        reverse=True,
    )

    setup_regime_policies = []
    for item in by_setup_regime:
        if not isinstance(item, dict):
            continue
        setup_type = str(item.get("setup_type") or "unknown").strip().lower() or "unknown"
        regime = str(item.get("regime") or "unknown").strip().lower() or "unknown"
        sample_count = int(_to_float(item.get("sample_count"), 0.0))
        win_rate = _to_float(item.get("win_rate"), 0.0)
        avg_return = _to_float(item.get("avg_return"), 0.0)
        setup_regime_policies.append(
            {
                "setup_type": setup_type,
                "regime_context": regime,
                "sample_count": sample_count,
                "win_rate": round(win_rate, 2),
                "avg_return": round(avg_return, 4),
                "policy_label": _policy_label_from_metrics(sample_count, win_rate, avg_return, setup_type=setup_type),
            }
        )
    setup_regime_policies = sorted(setup_regime_policies, key=lambda x: (x.get("avg_return", 0.0), x.get("win_rate", 0.0)), reverse=True)

    best_entry_conditions = list(entry_timing.get("best_entry_time_buckets") or [])[:8]
    weak_entry_conditions = list(entry_timing.get("weak_entry_time_buckets") or [])[:8]
    timing_warnings = list(entry_timing.get("entry_timing_warnings") or [])
    entry_condition_learning = {
        "best_entry_conditions": best_entry_conditions,
        "worst_entry_conditions": weak_entry_conditions,
        "avoid_entry_conditions": [c for c in weak_entry_conditions if _to_float((c or {}).get("avg_return"), 0.0) < 0.0][:6],
        "confirmation_required_conditions": list(dict.fromkeys([str(x) for x in timing_warnings if str(x).strip()]))[:8],
        "entry_timing_confidence": (
            "limited" if any("daily" in str(x).lower() or "flat" in str(x).lower() for x in list(rp.get("limitations") or []))
            else ("moderate" if best_entry_conditions else "low")
        ),
    }

    mfe_coverage = _to_float(exit_summary.get("mfe_mae_coverage_percent"), 0.0)
    exit_learning = {
        "best_hold_time_buckets": {
            "avg_hold_seconds_winners": round(_to_float(exit_summary.get("avg_hold_seconds_winners"), 0.0), 2),
            "avg_hold_seconds_losers": round(_to_float(exit_summary.get("avg_hold_seconds_losers"), 0.0), 2),
        },
        "early_exit_patterns": list(exit_summary.get("setup_exit_quality_with_mfe") or [])[:6],
        "late_exit_patterns": list(exit_summary.get("setup_exit_quality_with_mfe") or [])[-3:],
        "missed_profit_patterns": {
            "missed_profit_case_count": int(_to_float(exit_summary.get("missed_profit_case_count"), 0.0)),
            "missed_profit_case_rate_percent": round(_to_float(exit_summary.get("missed_profit_case_rate_percent"), 0.0), 2),
        },
        "recommended_trailing_stop_guidance": "directional_only_tighten_after_positive_extension" if mfe_coverage < 25.0 else "use_replay_drawdown_profiles_for_trailing_stop",
        "recommended_tighten_stop_guidance": "tighten_on_deterioration_or_drawdown_from_peak",
        "exit_policy_confidence": "low" if mfe_coverage < 25.0 else "moderate",
        "directional_only": bool(mfe_coverage < 25.0),
    }

    avoid_learning = {
        "avoid_setups": list(avoid_patterns.get("avoid_setup_types") or [])[:10],
        "avoid_setup_regime_pairs": list(avoid_patterns.get("avoid_setup_regimes") or [])[:10],
        "avoid_entry_conditions": [c for c in weak_entry_conditions if _to_float((c or {}).get("win_rate"), 0.0) < 40.0][:8],
        "weak_contexts": list(avoid_patterns.get("weak_persona_contexts") or [])[:10],
    }

    favor_setups = [p.get("setup_type") for p in setup_policies if str(p.get("policy_label")) in {"favor", "allow"}][:8]
    avoid_setups = [p.get("setup_type") for p in setup_policies if str(p.get("policy_label")) in {"avoid", "reduce"}][:8]
    confirm_setups = [p.get("setup_type") for p in setup_policies if str(p.get("policy_label")) == "confirmation_required"][:8]
    best_setup_regime = [x for x in setup_regime_policies if str(x.get("policy_label")) in {"favor", "allow"}][:8]
    avoid_setup_regime = [x for x in setup_regime_policies if str(x.get("policy_label")) in {"avoid", "reduce"}][:8]

    replay_confidence = str(rp.get("replay_confidence") or "not_available").strip().lower()
    joined_rows = int(_to_float(((rp.get("join_summary") or {}).get("joined_rows")), 0.0))
    if replay_confidence == "moderate" and joined_rows >= 10000:
        training_confidence = "moderate"
    elif joined_rows >= 2000:
        training_confidence = "limited"
    else:
        training_confidence = "low"

    runtime_policy = {
        "favor_setups": favor_setups,
        "avoid_setups": avoid_setups,
        "confirmation_required_setups": confirm_setups,
        "best_setup_regime_pairs": best_setup_regime,
        "avoid_setup_regime_pairs": avoid_setup_regime,
        "entry_condition_hints": {
            "best": best_entry_conditions[:4],
            "avoid": avoid_learning.get("avoid_entry_conditions", [])[:4],
            "confirm": entry_condition_learning.get("confirmation_required_conditions", [])[:4],
        },
        "exit_condition_hints": {
            "missed_profit_case_rate_percent": _to_float(
                (exit_learning.get("missed_profit_patterns") or {}).get("missed_profit_case_rate_percent"),
                0.0,
            ),
            "tighten_stop_guidance": str(exit_learning.get("recommended_tighten_stop_guidance") or ""),
            "trailing_stop_guidance": str(exit_learning.get("recommended_trailing_stop_guidance") or ""),
        },
        "training_confidence": training_confidence,
    }

    payload = {
        "historical_training_engine_v1": True,
        "generated_at": _now_utc_iso(),
        "mode": str(mode or "summary"),
        "source_rows": int(_to_float(((rp.get("source_summary") or {}).get("trade_rows_scanned")), 0.0)),
        "joined_rows": int(joined_rows),
        "training_confidence": training_confidence,
        "cache_source_signature": {
            "replay_generated_at": str(rp.get("cache_generated_at") or rp.get("generated_at") or ""),
            "replay_confidence": replay_confidence,
            "max_rows": int(max(1000, min(200000, int(_to_float(max_rows, 75000))))),
        },
        "data_sources_used": {
            "historical_market_bars": "state/ai_trading_memory.db::historical_market_bars",
            "trade_journal": "state/ai_trading_memory.db::trade_journal",
            "paper_replay_trades": "state/ai_trading_memory.db::paper_replay_trades",
            "replay_summary_source": "/api/fmp_historical_replay_v1",
            "policy_review_source": "/api/historical_replay_policy_review_v1",
            "no_external_api_calls": True,
        },
        "learned_setup_policies": setup_policies,
        "learned_setup_regime_policies": setup_regime_policies[:40],
        "entry_condition_learning": entry_condition_learning,
        "exit_profit_capture_learning": exit_learning,
        "avoid_trade_learning": avoid_learning,
        "historical_training_runtime_policy_v1": runtime_policy,
        "policy_review_bridge": {
            "top_replay_favor_setup": str(pp.get("top_replay_favor_setup") or ""),
            "top_replay_avoid_setup": str(pp.get("top_replay_avoid_setup") or ""),
            "replay_confidence": str(pp.get("replay_confidence") or replay_confidence or "not_available"),
        },
        "limitations": list(dict.fromkeys([str(x) for x in list(rp.get("limitations") or []) if str(x).strip()])),
        "recommended_next_step": "wire_historical_training_runtime_policy_into_replay_influence_v2",
        "no_live_behavior_changes": True,
    }
    return payload


def _historical_training_memory_learning_summary():
    cached = _load_historical_training_memory_cached(force_reload=False)
    if not cached:
        return {
            "historical_training_available": False,
            "historical_training_confidence": "not_built",
        }
    runtime_policy = dict(cached.get("historical_training_runtime_policy_v1") or {})
    return {
        "historical_training_available": True,
        "historical_training_generated_at": str(cached.get("generated_at") or ""),
        "historical_training_confidence": str(cached.get("training_confidence") or "not_available"),
        "historical_training_favor_setups": list(runtime_policy.get("favor_setups") or [])[:8],
        "historical_training_avoid_setups": list(runtime_policy.get("avoid_setups") or [])[:8],
        "historical_training_entry_policy_count": int(len(list((cached.get("entry_condition_learning") or {}).get("best_entry_conditions") or []))),
        "historical_training_exit_policy_count": int(len(list((cached.get("exit_profit_capture_learning") or {}).get("early_exit_patterns") or []))),
    }


def _load_historical_training_runtime_policy_v1(force_reload=False):
    payload = _load_historical_training_memory_cached(force_reload=bool(force_reload))
    runtime_policy = dict(payload.get("historical_training_runtime_policy_v1") or {})
    if not runtime_policy:
        return {
            "available": False,
            "training_confidence": "not_available",
            "favor_setups": [],
            "avoid_setups": [],
            "confirmation_required_setups": [],
            "best_setup_regime_pairs": [],
            "avoid_setup_regime_pairs": [],
            "entry_condition_hints": {},
            "exit_condition_hints": {},
            "generated_at": "",
            "source": "historical_training_memory_v1_missing",
        }
    return {
        "available": True,
        "training_confidence": str(runtime_policy.get("training_confidence") or payload.get("training_confidence") or "not_available"),
        "favor_setups": list(runtime_policy.get("favor_setups") or []),
        "avoid_setups": list(runtime_policy.get("avoid_setups") or []),
        "confirmation_required_setups": list(runtime_policy.get("confirmation_required_setups") or []),
        "best_setup_regime_pairs": list(runtime_policy.get("best_setup_regime_pairs") or []),
        "avoid_setup_regime_pairs": list(runtime_policy.get("avoid_setup_regime_pairs") or []),
        "entry_condition_hints": dict(runtime_policy.get("entry_condition_hints") or {}),
        "exit_condition_hints": dict(runtime_policy.get("exit_condition_hints") or {}),
        "generated_at": str(payload.get("generated_at") or ""),
        "source": "state/historical_training_memory_v1.json",
    }


def _historical_training_runtime_influence_v1(row, training_policy=None):
    r = dict(row or {})
    policy = dict(training_policy or {})
    if not bool(policy.get("available", False)):
        return {
            "historical_training_used": False,
            "historical_training_score": 0.0,
            "historical_training_alignment": "insufficient",
            "historical_training_decision": "neutral",
            "historical_training_reasons": [],
            "historical_training_penalties": [],
            "historical_training_confidence": 0.1,
            "entry_score_historical_training_adjusted": round(
                _to_float(
                    r.get("entry_score_replay_adjusted"),
                    _to_float(r.get("entry_score_signal_quality_adjusted"), _to_float(r.get("entry_score_timing_adjusted"), 0.0)),
                ),
                2,
            ),
            "signal_quality_historical_training_adjusted": False,
            "signal_quality_original_decision": str(r.get("signal_quality_original_decision") or r.get("signal_quality_decision") or "monitor_only"),
            "signal_quality_historical_training_decision": str(r.get("signal_quality_decision") or "monitor_only"),
            "learning_activation_historical_training_adjusted": False,
            "learning_activation_original_decision": str(r.get("learning_activation_original_decision") or r.get("learning_activation_decision") or "neutral"),
            "learning_activation_historical_training_decision": str(r.get("learning_activation_decision") or "neutral"),
        }

    setup_type = str(r.get("detected_setup_type") or r.get("setup_type") or "unknown").strip().lower() or "unknown"
    regime = str(r.get("regime_context") or r.get("regime") or r.get("current_regime_context") or "unknown").strip().lower() or "unknown"
    setup_band = str(r.get("setup_detection_band") or "poor").strip().lower()
    entry_band = str(r.get("entry_quality_band") or "poor").strip().lower()
    setup_score = _to_float(r.get("setup_detection_score"), 0.0)
    entry_score = _to_float(r.get("entry_quality_score"), 0.0)
    trusted = bool(r.get("trusted_quote_for_buys", False))
    valid_quote = bool(r.get("valid_quote", False))
    signal_decision = str(r.get("signal_quality_decision") or "monitor_only").strip().lower()
    signal_penalties = list(r.get("signal_quality_penalties") or [])
    timing_decision = str(r.get("entry_timing_decision") or "wait_for_confirmation").strip().lower()
    limited_data_mode = bool(r.get("limited_data_mode", False))
    context_block = str(r.get("context_activation_decision") or "").strip().lower() in {"block", "observe_only"}

    favor_setups = {str(x).strip().lower() for x in list(policy.get("favor_setups") or []) if str(x).strip()}
    avoid_setups = {str(x).strip().lower() for x in list(policy.get("avoid_setups") or []) if str(x).strip()}
    confirm_setups = {str(x).strip().lower() for x in list(policy.get("confirmation_required_setups") or []) if str(x).strip()}
    best_pairs = {
        f"{str((x or {}).get('setup_type') or '').strip().lower()}::{str((x or {}).get('regime_context') or '').strip().lower()}"
        for x in list(policy.get("best_setup_regime_pairs") or [])
        if isinstance(x, dict)
    }
    avoid_pairs = {
        f"{str((x or {}).get('setup_type') or '').strip().lower()}::{str((x or {}).get('regime_context') or '').strip().lower()}"
        for x in list(policy.get("avoid_setup_regime_pairs") or [])
        if isinstance(x, dict)
    }
    pair_key = f"{setup_type}::{regime}"

    reasons = []
    penalties = []
    support = 0.0
    negative = 0.0
    confirmation_required = False

    if setup_type in favor_setups:
        support += 2.8
        reasons.append("historical_training_favor_setup")
    if setup_type in avoid_setups:
        negative += 3.8
        penalties.append("historical_training_avoid_setup")
    if setup_type in confirm_setups:
        confirmation_required = True
        negative += 0.9
        penalties.append("historical_training_confirmation_required_setup")
    if pair_key in best_pairs:
        support += 1.4
        reasons.append("historical_training_best_setup_regime")
    if pair_key in avoid_pairs:
        negative += 1.9
        penalties.append("historical_training_avoid_setup_regime")

    if setup_band in {"strong", "elite"} and entry_band in {"moderate", "strong", "elite"}:
        support += 0.8
        reasons.append("current_setup_entry_alignment")
    if setup_band in {"poor", "weak"} or entry_band in {"poor", "weak"}:
        negative += 1.2
        penalties.append("current_setup_entry_weak")

    if timing_decision in {"avoid_for_now", "avoid_chase"}:
        negative += 0.9
        penalties.append("timing_avoid_state")
    elif timing_decision in {"wait_for_confirmation", "wait_for_pullback"}:
        confirmation_required = True

    if signal_decision == "reject":
        negative += 1.0
    elif signal_decision in {"monitor_only", "watchlist_only"}:
        negative += 0.6
    else:
        support += 0.3

    conf_label = str(policy.get("training_confidence") or "not_available").strip().lower()
    conf_weight = 1.0 if conf_label == "moderate" else (0.70 if conf_label == "limited" else 0.45)

    non_data_reject = bool(
        signal_decision == "reject"
        and any(
            not any(tok in str(p).lower() for tok in ("missing_", "history", "stale_quote", "enriched_signal_not_ready"))
            for p in signal_penalties
        )
    )
    hard_reject = bool(
        (not trusted)
        or (not valid_quote)
        or context_block
        or setup_band == "poor"
        or entry_band == "poor"
        or non_data_reject
    )

    raw_score = (support - negative) * conf_weight
    if hard_reject and raw_score > 0.0:
        raw_score = 0.0
        penalties.append("hard_safety_gate_blocks_positive_training_influence")

    strong_favorable = bool(raw_score >= 2.8 and setup_score >= 62.0 and entry_score >= 56.0)
    if timing_decision == "avoid_for_now" and raw_score > 0.0 and not strong_favorable:
        raw_score = min(raw_score, 0.0)
        penalties.append("timing_avoid_blocks_positive_training_influence")

    score = max(-6.0, min(4.0, raw_score))
    if score >= 1.0:
        alignment = "favorable"
    elif score <= -1.0:
        alignment = "unfavorable"
    elif support <= 0.0 and negative <= 0.0:
        alignment = "insufficient"
    else:
        alignment = "neutral"

    if alignment == "unfavorable" and score <= -3.0:
        decision = "suppress"
    elif alignment == "unfavorable":
        decision = "caution"
    elif confirmation_required:
        decision = "confirmation_required"
    elif alignment == "favorable":
        decision = "support"
    else:
        decision = "neutral"

    entry_base = _to_float(
        r.get("entry_score_replay_adjusted"),
        _to_float(r.get("entry_score_signal_quality_adjusted"), _to_float(r.get("entry_score_timing_adjusted"), 0.0)),
    )
    entry_adjusted = max(0.0, min(100.0, entry_base + score))

    signal_original = str(r.get("signal_quality_original_decision") or signal_decision or "monitor_only")
    signal_new = str(signal_decision or "monitor_only")
    signal_adjusted = False
    if (
        alignment == "favorable"
        and score >= 2.0
        and signal_new == "reject"
        and trusted
        and valid_quote
        and setup_band != "poor"
        and entry_band != "poor"
        and not hard_reject
        and limited_data_mode
    ):
        signal_new = "allow_with_confirmation" if timing_decision not in {"avoid_for_now", "avoid_chase"} else "watchlist_only"
        signal_adjusted = True
        reasons.append("historical_training_softens_limited_data_reject")

    learning_original = str(r.get("learning_activation_original_decision") or r.get("learning_activation_decision") or "neutral")
    learning_new = str(r.get("learning_activation_decision") or "neutral")
    learning_adjusted = False
    if alignment == "favorable" and score >= 2.5 and not hard_reject and setup_band != "poor" and entry_band != "poor":
        if learning_new == "suppress":
            learning_new = "caution"
            learning_adjusted = True
        elif learning_new == "caution":
            learning_new = "neutral"
            learning_adjusted = True
        if learning_adjusted:
            reasons.append("historical_training_reduces_over_suppression")
    elif alignment == "unfavorable" and score <= -2.8 and learning_new == "neutral":
        learning_new = "caution"
        learning_adjusted = True
        penalties.append("historical_training_negative_context")

    confidence_score = max(
        0.10,
        min(
            1.0,
            (conf_weight * 0.55)
            + ((min(100.0, max(0.0, setup_score + entry_score)) / 200.0) * 0.35)
            + (0.10 if pair_key in best_pairs or pair_key in avoid_pairs else 0.0),
        ),
    )

    return {
        "historical_training_used": True,
        "historical_training_score": round(score, 3),
        "historical_training_alignment": str(alignment),
        "historical_training_decision": str(decision),
        "historical_training_reasons": list(dict.fromkeys(reasons))[:12],
        "historical_training_penalties": list(dict.fromkeys(penalties))[:12],
        "historical_training_confidence": round(confidence_score, 4),
        "entry_score_historical_training_adjusted": round(entry_adjusted, 2),
        "signal_quality_historical_training_adjusted": bool(signal_adjusted),
        "signal_quality_original_decision": str(signal_original),
        "signal_quality_historical_training_decision": str(signal_new),
        "learning_activation_historical_training_adjusted": bool(learning_adjusted),
        "learning_activation_original_decision": str(learning_original),
        "learning_activation_historical_training_decision": str(learning_new),
    }


@router.get("/api/historical_training_engine_v1")
def historical_training_engine_v1(
    rebuild: bool = Query(default=False),
    max_rows: int = Query(default=75000),
    mode: str = Query(default="summary"),
):
    capped_rows = int(max(1000, min(200000, int(_to_float(max_rows, 75000)))))
    mode_s = str(mode or "summary").strip().lower() or "summary"

    cached_payload = _load_historical_training_memory_cached(force_reload=False)
    cached_sig = dict(cached_payload.get("cache_source_signature") or {}) if isinstance(cached_payload, dict) else {}
    cached_max_rows = int(_to_float(cached_sig.get("max_rows"), 0.0))
    if isinstance(cached_payload, dict) and cached_payload and not bool(rebuild) and cached_max_rows == capped_rows:
        out = dict(cached_payload)
        out["cache_hit"] = True
        out["cache_ttl_seconds"] = int(HISTORICAL_TRAINING_MEMORY_TTL_SECONDS)
        out["cache_path"] = HISTORICAL_TRAINING_MEMORY_PATH
        return out

    replay_payload = fmp_historical_replay_v1(force_refresh=bool(rebuild), max_trades=capped_rows)
    policy_payload = _build_historical_replay_policy_review_v1(replay_payload)
    payload = _build_historical_training_memory_v1(
        replay_payload,
        policy_payload,
        max_rows=capped_rows,
        mode=mode_s,
    )
    payload["cache_hit"] = False
    payload["cache_ttl_seconds"] = int(HISTORICAL_TRAINING_MEMORY_TTL_SECONDS)
    payload["cache_path"] = HISTORICAL_TRAINING_MEMORY_PATH
    payload["memory_persisted"] = bool(_persist_historical_training_memory(payload))
    return payload


@router.get("/api/provider_capability_audit")
def provider_capability_audit(
    run_probe: bool = Query(default=True),
    include_sample_symbols: bool = Query(default=True),
):
    from core.guardian.guardian_secure_api import GuardianSecureAPI

    def _sanitize_error(text):
        t = str(text or "").strip()
        if not t:
            return ""
        t = t.replace("\n", " ").replace("\r", " ")
        lowered = t.lower()
        for token in ("apikey=", "token=", "api_key=", "authorization", "bearer "):
            idx = lowered.find(token)
            if idx >= 0:
                t = t[:idx] + f"{token}[redacted]"
                lowered = t.lower()
        if len(t) > 220:
            t = t[:220]
        return t

    def _key_present(provider_name):
        p = str(provider_name or "").upper()
        key = configured_keys.get(p, "")
        base_present = bool(str(key or "").strip() and not str(key).startswith("YOUR_"))
        if p == "ALPACA":
            return bool(base_present and str(ALPACA_SECRET_KEY or "").strip())
        return base_present

    def _capability_hint(provider_name):
        p = str(provider_name or "").upper()
        hints = {
            "ALPACA": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "quote_support",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
            "FINNHUB": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": False, "news_catalyst": True},
                "classification": "intraday_signal_support",
                "quote_probe_supported": True,
                "intraday_history_capable": True,
                "history_quality_score": 82.0,
            },
            "POLYGON": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": False, "news_catalyst": False},
                "classification": "quote_support",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 20.0,
            },
            "TWELVEDATA": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": True, "news_catalyst": False},
                "classification": "quote_plus_volume",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 18.0,
            },
            "ALPHAVANTAGE": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": True, "news_catalyst": False},
                "classification": "quote_support",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 15.0,
            },
            "EODHD": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": False, "news_catalyst": False},
                "classification": "quote_support",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 10.0,
            },
            "FMP": {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": True, "indices": True, "forex": False, "news_catalyst": True},
                "classification": "historical_signal_support",
                "quote_probe_supported": True,
                "intraday_history_capable": True,
                "history_quality_score": 85.0,
            },
            "MORALIS": {
                "supported_asset_types": {"stocks": False, "crypto": True, "ETF": False, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "crypto_support",
                "quote_probe_supported": True,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
            "FRED": {
                "supported_asset_types": {"stocks": False, "crypto": False, "ETF": False, "indices": True, "forex": False, "news_catalyst": True},
                "classification": "catalyst/news_support",
                "quote_probe_supported": False,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
            "NASDAQ": {
                "supported_asset_types": {"stocks": False, "crypto": False, "ETF": False, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "display_only",
                "quote_probe_supported": False,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
            "DATAJOCKEY": {
                "supported_asset_types": {"stocks": False, "crypto": False, "ETF": False, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "display_only",
                "quote_probe_supported": False,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
            "SIMFIN": {
                "supported_asset_types": {"stocks": False, "crypto": False, "ETF": False, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "display_only",
                "quote_probe_supported": False,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
        }
        return hints.get(
            p,
            {
                "supported_asset_types": {"stocks": True, "crypto": False, "ETF": False, "indices": False, "forex": False, "news_catalyst": False},
                "classification": "not_currently_usable",
                "quote_probe_supported": False,
                "intraday_history_capable": False,
                "history_quality_score": 0.0,
            },
        )

    secure_api = GuardianSecureAPI()
    provider_rows = provider_status()
    diagnostics_payload = provider_diagnostics()
    ranking_meta_payload = get_ranking_snapshot_meta()
    regime_snapshot = _market_regime_snapshot()
    manager_rows = get_provider_status_summary()
    manager_map = {
        str((r or {}).get("provider", "")).upper(): dict(r or {})
        for r in (manager_rows if isinstance(manager_rows, list) else [])
    }
    provider_row_map = {
        str((r or {}).get("provider_name", "")).upper(): dict(r or {})
        for r in (provider_rows if isinstance(provider_rows, list) else [])
    }
    enabled_from_diag = [
        str(p).upper()
        for p in (diagnostics_payload.get("providers_enabled", []) if isinstance(diagnostics_payload, dict) else [])
        if str(p).strip()
    ]

    configured_keys = {}
    configured_categories = {}
    for cat, pairs in (API_POOLS or {}).items():
        for name, key in (pairs or []):
            p = str(name or "").upper()
            configured_keys[p] = str(key or "")
            configured_categories.setdefault(p, set()).add(str(cat or "unknown"))

    known_hints = {"ALPACA", "FINNHUB", "POLYGON", "TWELVEDATA", "ALPHAVANTAGE", "EODHD", "FMP", "MORALIS", "FRED", "NASDAQ", "DATAJOCKEY", "SIMFIN"}
    providers = sorted(
        set(configured_keys.keys())
        | set(provider_row_map.keys())
        | set(enabled_from_diag)
        | set(manager_map.keys())
        | known_hints
    )

    router_obj = getattr(secure_api, "_router", None)
    probe_fn = getattr(router_obj, "test_provider_quote", None)
    temp_fmp_rest_disabled = bool(
        str(os.getenv("ASTRA_TEMP_PROVIDER_STRATEGY_V1", "1")).strip().lower() in {"1", "true", "yes", "on"}
        and str(os.getenv("ASTRA_TEMP_FMP_REST_DISABLED", "1")).strip().lower() in {"1", "true", "yes", "on"}
    )
    role_matrix = dict((diagnostics_payload or {}).get("provider_role_matrix") or {})
    role_map = dict(role_matrix.get("providers") or {})
    sample_basket = ["AAPL", "MSFT", "NVDA", "SPY", "BTC-USD"] if include_sample_symbols else []
    probe_symbols = {
        "ALPACA": "AAPL",
        "FINNHUB": "AAPL",
        "POLYGON": "AAPL",
        "TWELVEDATA": "AAPL",
        "ALPHAVANTAGE": "AAPL",
        "EODHD": "AAPL",
        "FMP": "AAPL",
        "MORALIS": "BTC-USD",
        "FRED": "SPY",
    }

    provider_items = []
    now_ts = time.time()
    quote_usable_count = 0
    signal_usable_count = 0
    history_usable_count = 0
    crypto_usable_count = 0
    successful_providers = 0
    partial_providers = 0
    failed_providers = 0

    for p in providers:
        hint = _capability_hint(p)
        status_row = dict(provider_row_map.get(p) or {})
        mgr = dict(manager_map.get(p) or {})
        key_present = _key_present(p)
        configured = p in configured_keys
        enabled = bool((p in enabled_from_diag) or configured)
        sampled_symbol = str(probe_symbols.get(p) or "AAPL")
        sampled_asset_type = "crypto" if sampled_symbol in {"BTC-USD", "BTCUSD", "BTC"} else "stock"

        probe = None
        if (
            bool(run_probe)
            and callable(probe_fn)
            and bool(hint.get("quote_probe_supported", False))
            and sampled_symbol
        ):
            try:
                probe = probe_fn(provider=p, symbol=sampled_symbol, asset_type=sampled_asset_type)
            except Exception as e:
                probe = {
                    "provider": p,
                    "symbol": sampled_symbol,
                    "asset_type": sampled_asset_type,
                    "success_boolean": False,
                    "parsed_price": 0.0,
                    "parsed_prev_close": None,
                    "http_status": None,
                    "error": f"probe_exception:{str(e)[:120]}",
                    "rest_probe_skipped_due_to_hard_limit": False,
                }

        calls_total = int(_to_float(mgr.get("calls"), 0.0))
        calls_last_min = int(_to_float(mgr.get("provider_calls_last_minute"), 0.0))
        last_call_ts = float(_to_float(mgr.get("last_call_ts"), 0.0))
        last_call_attempted = bool(calls_total > 0 or probe is not None)
        freshness_seconds = round(max(0.0, now_ts - last_call_ts), 3) if last_call_ts > 0 else None
        freshness_label = "fresh" if (freshness_seconds is not None and freshness_seconds <= 120.0) else ("stale" if freshness_seconds is not None else "unknown")

        parsed_price = _to_float((probe or {}).get("parsed_price"), _to_float(status_row.get("parsed_price"), 0.0))
        parsed_prev_close = (probe or {}).get("parsed_prev_close")
        if parsed_prev_close is None:
            parsed_prev_close = status_row.get("parsed_prev_close")
        parsed_prev_close_val = _to_float(parsed_prev_close, 0.0)
        parsed_open_val = _to_float((probe or {}).get("parsed_open"), 0.0)
        parsed_high_val = _to_float((probe or {}).get("parsed_high"), 0.0)
        parsed_low_val = _to_float((probe or {}).get("parsed_low"), 0.0)
        parsed_volume_val = _to_float((probe or {}).get("parsed_volume"), 0.0)
        parsed_change_val = _to_float((probe or {}).get("parsed_change"), 0.0)
        parsed_change_pct_val = _to_float((probe or {}).get("parsed_change_percent"), 0.0)
        parsed_timestamp = (probe or {}).get("parsed_timestamp")
        dns_ok = bool(status_row.get("dns_ok", False))
        cooldown_state = str(mgr.get("provider_cooldown_state") or status_row.get("provider_cooldown_state") or "active").lower()
        http_status = (probe or {}).get("http_status")
        if http_status is None:
            http_status = status_row.get("http_status")
        err_text = _sanitize_error((probe or {}).get("error") or status_row.get("error") or "")
        probe_success = bool((probe or {}).get("success_boolean", False))
        status_success = bool(status_row.get("success_boolean", False))
        rest_skipped_hard_limit = bool((probe or {}).get("rest_probe_skipped_due_to_hard_limit", False) or bool(status_row.get("rest_probe_skipped_due_to_hard_limit", False)))

        if rest_skipped_hard_limit:
            last_status = "skipped"
        elif probe_success or status_success:
            if parsed_price > 0 and parsed_prev_close_val > 0:
                last_status = "success"
            else:
                last_status = "partial"
        elif last_call_attempted:
            last_status = "fail"
        else:
            last_status = "skipped"

        field_coverage = {
            "symbol": bool(sampled_symbol),
            "price": bool(parsed_price > 0),
            "previous_close": bool(parsed_prev_close_val > 0),
            "open": bool(parsed_open_val > 0),
            "high": bool(parsed_high_val > 0),
            "low": bool(parsed_low_val > 0),
            "volume": bool(parsed_volume_val > 0),
            "change": bool(parsed_change_val != 0.0),
            "change_percent": bool(parsed_change_pct_val != 0.0),
            "timestamp": bool(last_call_attempted and parsed_timestamp is not None),
        }
        usable_quote_fields = [k for k, v in field_coverage.items() if bool(v)]
        missing_quote_fields = [k for k, v in field_coverage.items() if not bool(v)]
        enriched_field_coverage = dict(field_coverage)
        if field_coverage.get("price") and field_coverage.get("previous_close"):
            enriched_field_coverage["change"] = True
            enriched_field_coverage["change_percent"] = True

        intraday_history_capable = bool(hint.get("intraday_history_capable", False))
        history_quality_score = _to_float(hint.get("history_quality_score"), 0.0)
        if p == "FMP" and temp_fmp_rest_disabled:
            intraday_history_capable = False
            history_quality_score = 0.0
        signal_possible = bool(intraday_history_capable and key_present and last_status in {"success", "partial"})

        signal_fields = {
            "volume_available": bool(field_coverage.get("volume", False)),
            "VWAP_available": bool(signal_possible),
            "RSI_source_possible": bool(signal_possible),
            "MACD_source_possible": bool(signal_possible),
            "moving_average_source_possible": bool(signal_possible),
            "ATR_source_possible": bool(signal_possible),
            "breakout_detection_possible": bool(signal_possible),
            "trend_detection_possible": bool(signal_possible),
        }
        history_fields = {
            "candles_available": bool(intraday_history_capable and key_present),
            "timeframe_supported": ["1m", "5m", "15m"] if intraday_history_capable and key_present else [],
            "ohlcv_available": bool(intraday_history_capable and key_present),
            "lookback_depth_available": "limited_intraday" if intraday_history_capable and key_present else "none",
            "history_quality_score": round(history_quality_score, 2),
        }
        normalized_field_coverage = {
            "quote_fields_usable_count": int(sum(1 for _, v in field_coverage.items() if bool(v))),
            "quote_fields_total": int(len(field_coverage)),
            "coverage_percent": round((sum(1 for _, v in field_coverage.items() if bool(v)) / max(1.0, float(len(field_coverage)))) * 100.0, 2),
        }
        enriched_field_coverage_summary = {
            "quote_fields_usable_count": int(sum(1 for _, v in enriched_field_coverage.items() if bool(v))),
            "quote_fields_total": int(len(enriched_field_coverage)),
            "coverage_percent": round((sum(1 for _, v in enriched_field_coverage.items() if bool(v)) / max(1.0, float(len(enriched_field_coverage)))) * 100.0, 2),
        }
        cap_per_min = int(_to_float(mgr.get("cap_per_minute"), 0.0))
        call_budget_status = {
            "cap_per_minute": int(cap_per_min),
            "calls_last_minute": int(calls_last_min),
            "utilization_percent": round((calls_last_min / max(1.0, float(cap_per_min))) * 100.0, 2) if cap_per_min > 0 else 0.0,
            "cooldown_state": str(cooldown_state),
        }
        cache_reuse_status = {
            "temp_discovery_cache_max_age_seconds": _to_float((diagnostics_payload or {}).get("temp_discovery_cache_max_age_seconds"), 0.0),
            "fmp_conserve_mode_active": bool(ranking_meta_payload.get("fmp_conserve_mode_active", False)),
            "snapshot_active": bool(ranking_meta_payload.get("snapshot_active", False)),
        }

        guardian_rejection_reasons = []
        if not dns_ok and p in provider_row_map:
            guardian_rejection_reasons.append("dns_not_ok")
        if cooldown_state == "cooldown":
            guardian_rejection_reasons.append("provider_cooldown")
        if str(http_status) == "429":
            guardian_rejection_reasons.append("rate_limited")
        if rest_skipped_hard_limit:
            guardian_rejection_reasons.append("fmp_rest_probe_skipped_hard_limit")
        if err_text:
            guardian_rejection_reasons.append(err_text)
        if parsed_price <= 0 and last_status in {"fail", "partial"}:
            guardian_rejection_reasons.append("missing_price")
        if parsed_prev_close_val <= 0 and last_status in {"partial", "fail"}:
            guardian_rejection_reasons.append("missing_previous_close")
        if not guardian_rejection_reasons and last_status in {"success", "partial"}:
            guardian_rejection_reasons.append("none")

        base_classification = str(hint.get("classification") or "not_currently_usable")
        if not key_present and configured:
            classification = "not_currently_usable"
        elif p == "FMP" and temp_fmp_rest_disabled:
            classification = "not_currently_usable"
        elif last_status in {"fail", "skipped"} and base_classification not in {"catalyst/news_support", "display_only"}:
            classification = "not_currently_usable"
        elif base_classification == "intraday_signal_support" and not signal_possible:
            classification = "quote_support" if parsed_price > 0 else "not_currently_usable"
        elif base_classification == "historical_signal_support" and not signal_possible:
            classification = "quote_support" if parsed_price > 0 else "not_currently_usable"
        else:
            classification = base_classification

        if classification in {"quote_support", "quote_plus_volume", "intraday_signal_support", "historical_signal_support"}:
            if parsed_price > 0:
                quote_usable_count += 1
        if classification in {"intraday_signal_support", "historical_signal_support"}:
            signal_usable_count += 1
        if history_fields.get("candles_available", False):
            history_usable_count += 1
        if classification == "crypto_support":
            crypto_usable_count += 1
        if last_status == "success":
            successful_providers += 1
        elif last_status == "partial":
            partial_providers += 1
        elif last_status == "fail":
            failed_providers += 1

        provider_role_policy = _provider_role_policy_v1(p)
        provider_role = dict(role_map.get(p) or {})
        provider_role_value = list(provider_role.get("role") or []) if provider_role else []
        provider_mode = str(provider_role.get("mode") or "")
        provider_channel_classification = (
            str(provider_role_policy.get("provider_channel_classification") or "")
            or (
                "macro_provider"
                if p == "FRED"
                else ("quote_provider" if classification in {"quote_support", "quote_plus_volume", "intraday_signal_support", "historical_signal_support"} else "support_provider")
            )
        )

        provider_item = {
                "provider_name": p,
                "enabled": bool(enabled),
                "configured": bool(configured),
                "configured_categories": sorted(list(configured_categories.get(p, set()))),
                "key_present": bool(key_present),
                "last_call_attempted": bool(last_call_attempted),
                "calls_total": int(calls_total),
                "calls_last_minute": int(calls_last_min),
                "last_status": str(last_status),
                "error_message": str(err_text),
                "supported_symbols_sampled": [sampled_symbol] if sampled_symbol else [],
                "sample_symbol_basket": list(sample_basket),
                "supported_asset_types": dict(hint.get("supported_asset_types") or {}),
                "provider_role": provider_role_value,
                "provider_mode": provider_mode,
                "provider_channel_classification": provider_channel_classification,
                "field_coverage_quote": field_coverage,
                "normalized_field_coverage": normalized_field_coverage,
                "enriched_field_coverage": enriched_field_coverage_summary,
                "fields_usable_by_astra": usable_quote_fields,
                "fields_missing": missing_quote_fields,
                "history_capabilities": history_fields,
                "signal_useful_fields": signal_fields,
                "call_budget_status": call_budget_status,
                "cache_reuse_status": cache_reuse_status,
                "astra_usability_classification": str(classification),
                "guardian_rejection_reasons": list(dict.fromkeys(guardian_rejection_reasons)),
                "freshness": {
                    "data_freshness_seconds": freshness_seconds,
                    "freshness_label": freshness_label,
                    "last_call_ts": last_call_ts if last_call_ts > 0 else None,
                },
                "probe_sample": {
                    "ran_probe": bool(probe is not None),
                    "symbol": sampled_symbol,
                    "asset_type": sampled_asset_type,
                    "http_status": http_status,
                    "parsed_price": round(parsed_price, 8),
                    "parsed_prev_close": round(parsed_prev_close_val, 8) if parsed_prev_close_val > 0 else None,
                    "parsed_open": round(parsed_open_val, 8) if parsed_open_val > 0 else None,
                    "parsed_high": round(parsed_high_val, 8) if parsed_high_val > 0 else None,
                    "parsed_low": round(parsed_low_val, 8) if parsed_low_val > 0 else None,
                    "parsed_volume": round(parsed_volume_val, 4) if parsed_volume_val > 0 else None,
                    "parsed_change": round(parsed_change_val, 8) if parsed_change_val != 0.0 else None,
                    "parsed_change_percent": round(parsed_change_pct_val, 6) if parsed_change_pct_val != 0.0 else None,
                    "parsed_timestamp": parsed_timestamp,
                    "rest_probe_skipped_due_to_hard_limit": bool(rest_skipped_hard_limit),
                },
                "inactive_reason_type": (
                    "intentionally_restricted"
                    if (p == "FMP" and temp_fmp_rest_disabled)
                    else ("misconfigured_or_failed" if classification == "not_currently_usable" else "active_or_limited")
                ),
            }
        provider_item.update(provider_role_policy)
        provider_items.append(provider_item)

    def _best_provider_for(target):
        candidates = []
        for item in provider_items:
            cls = str(item.get("astra_usability_classification") or "")
            st = str(item.get("last_status") or "")
            if target == "quotes" and cls in {"quote_support", "quote_plus_volume", "intraday_signal_support", "historical_signal_support"} and st in {"success", "partial"}:
                score = _to_float((item.get("probe_sample") or {}).get("parsed_price"), 0.0)
                freshness = _to_float(((item.get("freshness") or {}).get("data_freshness_seconds")), 999999.0)
                candidates.append((1.0 if score > 0 else 0.0, -freshness, item.get("provider_name")))
            if target == "history" and bool(((item.get("history_capabilities") or {}).get("candles_available"))):
                hq = _to_float(((item.get("history_capabilities") or {}).get("history_quality_score")), 0.0)
                candidates.append((hq, 0.0, item.get("provider_name")))
            if target == "crypto" and str(item.get("astra_usability_classification") or "") == "crypto_support":
                candidates.append((1.0, 0.0, item.get("provider_name")))
        if not candidates:
            return "none"
        candidates.sort(reverse=True)
        return str(candidates[0][2] or "none")

    if signal_usable_count <= 0:
        biggest_gap = "intraday_signal_support_gap"
    elif history_usable_count <= 0:
        biggest_gap = "history_depth_gap"
    elif quote_usable_count <= 1:
        biggest_gap = "quote_provider_redundancy_gap"
    else:
        biggest_gap = "none"

    summary = {
        "total_providers": int(len(provider_items)),
        "configured_providers": int(sum(1 for i in provider_items if bool(i.get("configured", False)))),
        "successful_providers": int(successful_providers),
        "partial_providers": int(partial_providers),
        "failed_providers": int(failed_providers),
        "quote_usable_count": int(quote_usable_count),
        "signal_usable_count": int(signal_usable_count),
        "history_usable_count": int(history_usable_count),
        "crypto_usable_count": int(crypto_usable_count),
        "current_best_provider_for_quotes": _best_provider_for("quotes"),
        "current_best_provider_for_history": _best_provider_for("history"),
        "current_best_provider_for_crypto": _best_provider_for("crypto"),
        "current_biggest_gap": str(biggest_gap),
    }
    fred_diag = {
        "fred_connected": bool(
            str(regime_snapshot.get("macro_data_source") or "").strip().upper() == "FRED"
            or bool(regime_snapshot.get("macro_source_active", False))
            or bool(_key_present("FRED"))
        ),
        "fred_macro_fields_available": [
            k for k in (
                "macro_yield_spread_bps",
                "macro_vix_level",
                "macro_risk_score",
                "macro_data_source",
                "macro_source_active",
                "macro_source_key_loaded",
            )
            if regime_snapshot.get(k) is not None
        ],
        "fred_last_success": str(regime_snapshot.get("last_updated_utc") or ""),
        "fred_macro_context_score": round(_to_float(regime_snapshot.get("macro_risk_score"), 0.0), 2),
        "fred_limitations": [x for x in [
            "macro_source_inactive" if not bool(regime_snapshot.get("macro_source_active", False)) else "",
            "macro_source_key_not_loaded" if not bool(regime_snapshot.get("macro_source_key_loaded", False)) else "",
            str(regime_snapshot.get("macro_source_last_error") or "")[:160],
        ] if x],
    }
    signal_continuity = _provider_signal_continuity_v1(
        provider_items=provider_items,
        ranking_meta_payload=ranking_meta_payload,
        diagnostics_payload=diagnostics_payload,
        regime_snapshot=regime_snapshot,
        manager_rows=manager_rows,
    )
    summary.update(
        {
            "quote_provider_health": signal_continuity.get("quote_provider_health"),
            "signal_provider_health": signal_continuity.get("signal_provider_health"),
            "macro_provider_health": signal_continuity.get("macro_provider_health"),
            "overall_provider_health": signal_continuity.get("overall_provider_health"),
            "current_best_provider_for_quotes": signal_continuity.get("best_quote_provider") or summary.get("current_best_provider_for_quotes"),
            "current_best_provider_for_history": signal_continuity.get("best_signal_provider") or summary.get("current_best_provider_for_history"),
            "current_biggest_gap": signal_continuity.get("biggest_provider_gap") or summary.get("current_biggest_gap"),
        }
    )

    return {
        "provider_capability_audit_v1": True,
        "generated_at_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "diagnostic_mode_only": True,
        "provider_items": provider_items,
        "provider_audit_summary": summary,
        "call_budget_status": {
            "temporary_provider_strategy_v1": bool(diagnostics_payload.get("temporary_provider_strategy_v1", False)),
            "fmp_rest_disabled_temporarily": bool(diagnostics_payload.get("fmp_rest_disabled_temporarily", False)),
            "fmp_websocket_monitor_only": bool(diagnostics_payload.get("fmp_websocket_monitor_only", False)),
            "provider_backfill_max_probes": int(_to_float(diagnostics_payload.get("provider_backfill_max_probes"), 0.0)),
            "temp_discovery_cache_max_age_seconds": _to_float(diagnostics_payload.get("temp_discovery_cache_max_age_seconds"), 0.0),
        },
        "cache_reuse_status": {
            "snapshot_active": bool(ranking_meta_payload.get("snapshot_active", False)),
            "snapshot_used": bool(ranking_meta_payload.get("snapshot_used", False)),
            "cached_valid_quote_count": int(_to_float(ranking_meta_payload.get("cached_valid_quote_count"), 0.0)),
            "live_valid_quote_count": int(_to_float(ranking_meta_payload.get("live_valid_quote_count"), 0.0)),
        },
        "fred_macro_diagnostics": fred_diag,
        "provider_signal_continuity_v1": signal_continuity,
    }


