@router.get("/api/positions")
def positions(asset_type: str | None = Query(None)):
    try:
        compact = _mobile_runtime_compaction_snapshot(force=False, include_closed_orders=True)
        # If Alpaca paper reconciliation is available, broker positions are the display truth.
        # Avoid the heavier internal enrichment path for compact mobile/dashboard views.
        if bool(compact.get("mobile_runtime_compaction_active")) and bool(compact.get("broker_positions_fetch_ok")):
            base_response = {
                "count": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                "positions": list(compact.get("desktop_positions_preview") or compact.get("true_broker_positions_preview") or []),
                "position_lifecycle_intelligence": {
                    "total_open_positions": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                    "broker_confirmed_display": True,
                    "internal_workflow_rows_hidden": int(_to_float(compact.get("stale_rows_hidden_count"), 0.0)),
                },
                "position_sync_v1": {
                    "open_position_count": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                    "source": "alpaca_broker_positions_compacted",
                },
                "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            }
            return MOBILE_RUNTIME_COMPACTION.compact_positions_response(base_response, compaction=compact)
    except Exception:
        pass
    _ensure_latest_rankings()
    at = _normalize_asset_type(asset_type) if asset_type else None
    rows = POSITION_TRACKER.get_open_positions(asset_type=at)
    top_payload, top_payload_age, top_payload_key = _top_buys_cached_payload_for_mode(
        "balanced",
        include_trace=False,
        max_age_seconds=max(TOP_BUYS_TTL_SECONDS * 4, 1800),
        allow_alt_trace=True,
    )
    if not isinstance(top_payload, dict) or not top_payload:
        latest_runtime_payload = _latest_top_buys_runtime_snapshot()
        if isinstance(latest_runtime_payload, dict) and latest_runtime_payload:
            top_payload = dict(latest_runtime_payload)
            top_payload_key = str(top_payload_key or "latest_runtime_snapshot")
            top_payload_age = _to_float(top_payload_age, 0.0)
    top_row_lookup = {}
    if isinstance(top_payload, dict):
        for bucket in ("stocks", "crypto"):
            block = top_payload.get(bucket) if isinstance(top_payload.get(bucket), dict) else {}
            for seq_key in ("final", "qualified", "best_opportunities"):
                seq = block.get(seq_key) if isinstance(block.get(seq_key), list) else []
                for item in seq:
                    if not isinstance(item, dict):
                        continue
                    sym = str(item.get("symbol") or "").upper().strip()
                    if not sym or sym in top_row_lookup:
                        continue
                    top_row_lookup[sym] = dict(item)
    if not top_row_lookup:
        for bucket in ("stocks", "crypto"):
            seq = LAST_RANKINGS.get(bucket) if isinstance(LAST_RANKINGS.get(bucket), list) else []
            for item in seq:
                if not isinstance(item, dict):
                    continue
                sym = str(item.get("symbol") or "").upper().strip()
                if not sym or sym in top_row_lookup:
                    continue
                top_row_lookup[sym] = dict(item)
    out = []
    lifecycle_state_counts = {
        "fresh_entry": 0,
        "early_winner": 0,
        "stagnant_position": 0,
        "vulnerable_winner": 0,
        "deteriorating_setup": 0,
        "higher_risk_hold": 0,
    }
    position_sync_summary = {
        "open_position_count": int(len(rows)),
        "quotes_synced_count": 0,
        "quote_fallback_count": 0,
        "zero_price_prevented_count": 0,
        "top_buys_matched_count": 0,
        "position_decision_distribution": {},
    }
    def _norm_confidence_pct(value):
        val = _to_float(value, 0.0)
        if val <= 1.0:
            val *= 100.0
        return round(max(0.0, min(100.0, val)), 2)

    for row in rows:
        symbol = str(row.get("symbol") or "").upper()
        latest = _find_latest_row(symbol, asset_type=row.get("asset_type"))
        latest_price_live = None
        if isinstance(latest, dict):
            try:
                latest_price_live = float(latest.get("price"))
                if latest_price_live <= 0:
                    latest_price_live = None
            except (TypeError, ValueError):
                latest_price_live = None
        else:
            latest = {}

        entry_price = _to_float(row.get("entry_price"), 0.0)
        prior_valid_price = _to_float(
            row.get("latest_valid_price"),
            _to_float(row.get("latest_price"), entry_price),
        )
        latest_price = latest_price_live
        position_quote_fallback_used = False
        position_last_valid_price_used = False
        if latest_price is None and prior_valid_price > 0:
            latest_price = prior_valid_price
            position_quote_fallback_used = True
            position_last_valid_price_used = True
        if latest_price is None and entry_price > 0:
            latest_price = entry_price
            position_quote_fallback_used = True
        quote_age_seconds = _to_float(latest.get("quote_age_seconds"), None)
        if quote_age_seconds is None:
            quote_age_seconds = _iso_age_seconds(latest.get("last_snapshot_timestamp") or latest.get("timestamp"))
        quote_source = str(latest.get("quote_source") or latest.get("provider_used") or latest.get("source") or row.get("quote_source") or "unknown")
        position_quote_status = "unavailable"
        if latest_price_live is not None:
            position_quote_status = "live_quote"
        elif latest_price is not None and position_last_valid_price_used:
            position_quote_status = "last_valid_fallback"
        elif latest_price is not None and entry_price > 0:
            position_quote_status = "entry_price_fallback"
        if latest_price_live is not None:
            position_sync_summary["quotes_synced_count"] = int(position_sync_summary.get("quotes_synced_count", 0)) + 1
        elif position_quote_fallback_used:
            position_sync_summary["quote_fallback_count"] = int(position_sync_summary.get("quote_fallback_count", 0)) + 1
        if latest_price_live is None and latest_price is not None and latest_price > 0:
            position_sync_summary["zero_price_prevented_count"] = int(position_sync_summary.get("zero_price_prevented_count", 0)) + 1

        unrealized = None
        if latest_price is not None and latest_price > 0 and entry_price > 0:
            unrealized = round(((latest_price - entry_price) / entry_price) * 100.0, 2)
        prior_peak = _to_float(row.get("peak_unrealized_pnl_percent"), unrealized if unrealized is not None else 0.0)
        prior_adverse = _to_float(row.get("max_adverse_pnl_percent"), unrealized if unrealized is not None else 0.0)
        peak_unrealized = (
            max(prior_peak, unrealized) if unrealized is not None else prior_peak
        )
        adverse_unrealized = (
            min(prior_adverse, unrealized) if unrealized is not None else prior_adverse
        )

        POSITION_TRACKER.update_position_snapshot(
            symbol,
            {
                "quote_batch_id": latest.get("quote_batch_id") or latest.get("entry_quote_batch_id") or "",
                "latest_price": latest_price,
                "latest_valid_price": latest_price if latest_price is not None and latest_price > 0 else prior_valid_price,
                "current_predicted_probability": latest.get("predicted_win_probability"),
                "current_consensus_strength": latest.get("consensus_strength"),
                "current_persona_disagreement_index": latest.get("persona_disagreement_index"),
                "regime_context": latest.get("regime_context", latest.get("regime")),
                "quote_quality": latest.get("quote_quality", "unknown"),
                "quote_source": quote_source,
                "last_quote_age_seconds": quote_age_seconds,
                "position_quote_status": position_quote_status,
                "position_quote_fallback_used": bool(position_quote_fallback_used),
                "position_last_valid_price_used": bool(position_last_valid_price_used),
                "peak_unrealized_pnl_percent": peak_unrealized,
                "max_adverse_pnl_percent": adverse_unrealized,
                "data_unavailable_reason": latest.get("data_unavailable_reason", ""),
                "last_snapshot_timestamp": latest.get("timestamp", ""),
            },
        )

        current_prob = latest.get("predicted_win_probability", row.get("current_predicted_probability"))
        current_consensus = latest.get("consensus_strength", row.get("current_consensus_strength"))
        current_disagreement = latest.get("persona_disagreement_index", row.get("current_persona_disagreement_index"))
        current_regime = latest.get("regime_context", row.get("current_regime_context"))
        quote_quality = latest.get("quote_quality", row.get("quote_quality"))
        quote_source = latest.get("quote_source", row.get("quote_source"))
        quote_age_seconds = (
            _to_float(latest.get("quote_age_seconds"), None)
            if isinstance(latest, dict)
            else None
        )
        if quote_age_seconds is None:
            quote_age_seconds = _iso_age_seconds(latest.get("timestamp")) if isinstance(latest, dict) else None
        data_unavailable_reason = latest.get("data_unavailable_reason", row.get("data_unavailable_reason"))
        snapshot_ts = latest.get("timestamp", row.get("last_snapshot_timestamp"))

        enriched = dict(row)
        enriched["latest_price"] = latest_price
        enriched["unrealized_pnl_percent"] = unrealized
        enriched["peak_unrealized_pnl_percent"] = peak_unrealized
        enriched["max_adverse_pnl_percent"] = adverse_unrealized
        enriched["current_predicted_probability"] = current_prob
        enriched["current_consensus_strength"] = current_consensus
        enriched["current_persona_disagreement_index"] = current_disagreement
        enriched["current_regime_context"] = current_regime
        enriched["quote_quality"] = quote_quality
        enriched["quote_source"] = quote_source
        enriched["last_quote_age_seconds"] = quote_age_seconds
        enriched["data_unavailable_reason"] = data_unavailable_reason
        enriched["last_snapshot_timestamp"] = snapshot_ts
        enriched["current_price"] = round(_to_float(latest_price, 0.0), 6) if latest_price is not None else None
        enriched["position_quote_status"] = position_quote_status
        enriched["position_quote_source"] = quote_source
        enriched["position_quote_freshness_seconds"] = quote_age_seconds
        enriched["position_quote_fallback_used"] = bool(position_quote_fallback_used)
        enriched["position_last_valid_price_used"] = bool(position_last_valid_price_used)
        top_row = top_row_lookup.get(symbol) if symbol else None
        if isinstance(top_row, dict):
            position_sync_summary["top_buys_matched_count"] = int(position_sync_summary.get("top_buys_matched_count", 0)) + 1
            enriched["aligned_top_buys_grade"] = top_row.get("grade")
            enriched["aligned_top_buys_confidence"] = _norm_confidence_pct(
                top_row.get("confidence", top_row.get("predicted_win_probability"))
            )
            enriched["aligned_top_buys_qualification"] = top_row.get("qualification")
            enriched["aligned_top_buys_state"] = top_row.get("canonical_final_state")
            enriched["aligned_signal_quality_decision"] = top_row.get("signal_quality_decision")
            enriched["aligned_entry_timing_decision"] = top_row.get("entry_timing_decision")
            enriched["aligned_learning_activation_decision"] = top_row.get("learning_activation_decision")
        else:
            enriched["aligned_top_buys_grade"] = enriched.get("aligned_top_buys_grade")
            enriched["aligned_top_buys_confidence"] = _norm_confidence_pct(
                enriched.get("current_predicted_probability", enriched.get("entry_predicted_win_probability"))
            )
            enriched["aligned_top_buys_qualification"] = None
            enriched["aligned_top_buys_state"] = None
            enriched["aligned_signal_quality_decision"] = None
            enriched["aligned_entry_timing_decision"] = None
            enriched["aligned_learning_activation_decision"] = None
        pullback_from_peak = round(
            max(0.0, _to_float(peak_unrealized, 0.0) - (_to_float(unrealized, 0.0) if unrealized is not None else _to_float(peak_unrealized, 0.0))),
            4,
        )
        enriched["pullback_from_peak_percent"] = pullback_from_peak
        consensus_drop = _to_float(enriched.get("entry_consensus_strength"), 0.0) - _to_float(current_consensus, 0.0)
        disagreement_rise = _to_float(current_disagreement, 0.0) - _to_float(enriched.get("entry_persona_disagreement_index"), 0.0)
        lifecycle_state = "stagnant_position"
        if unrealized is not None and abs(unrealized) <= 0.35:
            lifecycle_state = "fresh_entry"
        if unrealized is not None and unrealized >= 1.2 and pullback_from_peak <= 0.8:
            lifecycle_state = "early_winner"
        if unrealized is not None and unrealized >= 1.5 and pullback_from_peak >= 1.4:
            lifecycle_state = "vulnerable_winner"
        if unrealized is not None and unrealized < -1.0:
            lifecycle_state = "deteriorating_setup"
        if disagreement_rise >= 10.0 or consensus_drop >= 12.0 or _to_float(quote_age_seconds, 0.0) > 45.0:
            lifecycle_state = "higher_risk_hold"
        lifecycle_state_counts[lifecycle_state] = int(lifecycle_state_counts.get(lifecycle_state, 0)) + 1
        review_urgency_score = max(
            0.0,
            min(
                100.0,
                (max(0.0, pullback_from_peak) * 15.0)
                + (max(0.0, consensus_drop) * 1.8)
                + (max(0.0, disagreement_rise) * 1.2)
                + (6.0 if _to_float(quote_age_seconds, 0.0) > 45.0 else 0.0)
                + (14.0 if lifecycle_state in {"deteriorating_setup", "higher_risk_hold"} else 0.0),
            ),
        )
        if review_urgency_score >= 68.0:
            risk_posture = "sell_now_review"
        elif review_urgency_score >= 45.0:
            risk_posture = "reduce_or_trim_review"
        elif review_urgency_score >= 24.0:
            risk_posture = "tighten_stop_review"
        else:
            risk_posture = "hold_through_noise"
        enriched["position_lifecycle_state"] = lifecycle_state
        signal_quality_decision = str(
            (top_row or {}).get("signal_quality_decision")
            or enriched.get("aligned_signal_quality_decision")
            or ""
        ).strip().lower()
        entry_timing_decision = str(
            (top_row or {}).get("entry_timing_decision")
            or enriched.get("aligned_entry_timing_decision")
            or ""
        ).strip().lower()
        learning_activation_decision = str(
            (top_row or {}).get("learning_activation_decision")
            or enriched.get("aligned_learning_activation_decision")
            or ""
        ).strip().lower()
        policy_hint = str(
            (top_row or {}).get("historical_policy_action_hint")
            or ""
        ).strip().lower()
        qualification = str(
            (top_row or {}).get("qualification")
            or (top_row or {}).get("canonical_final_state")
            or ""
        ).strip().lower()
        position_decision = (
            "exit_review"
            if risk_posture == "sell_now_review"
            else "reduce_or_trim"
            if risk_posture == "reduce_or_trim_review"
            else "tighten_stop"
            if risk_posture == "tighten_stop_review"
            else "hold"
        )
        decision_reasons = [f"lifecycle:{risk_posture}"]
        if position_quote_status == "unavailable":
            position_decision = "data_unavailable_review"
            decision_reasons.append("no_reliable_quote")
        else:
            weak_signal = signal_quality_decision in {"reject", "monitor_only"} or policy_hint in {"monitor_only", "avoid_for_now", "paper_only"} or entry_timing_decision in {"avoid_for_now", "avoid_chase"}
            mixed_signal = signal_quality_decision in {"watchlist_only", "allow_with_confirmation"} or entry_timing_decision in {"wait_for_confirmation", "wait_for_pullback"} or learning_activation_decision in {"caution", "suppress"} or _to_float(quote_age_seconds, 0.0) > 90.0
            if weak_signal:
                position_decision = "exit_review" if unrealized is not None and unrealized <= -2.0 else ("reduce_or_trim" if unrealized is not None and unrealized < 0.0 else "tighten_stop")
                decision_reasons.append("top_buys_alignment_weak")
            elif mixed_signal:
                if position_decision not in {"exit_review", "reduce_or_trim"}:
                    position_decision = "hold_with_caution"
                decision_reasons.append("confirmation_or_caution_required")
            elif qualification in {"released_buy", "paper_ready", "paper_ready_candidate"} and signal_quality_decision == "allow" and entry_timing_decision in {"immediate", "wait_for_confirmation", "confirmation"}:
                position_decision = "strong_hold" if unrealized is not None and unrealized >= 1.0 else "hold"
                decision_reasons.append("top_buys_alignment_supportive")
        if position_decision == "data_unavailable_review":
            position_risk_state = "data_gap"
        elif position_decision in {"exit_review", "reduce_or_trim"}:
            position_risk_state = "high_risk"
        elif position_decision in {"tighten_stop", "hold_with_caution"}:
            position_risk_state = "elevated_risk"
        else:
            position_risk_state = "normal_risk"
        position_action_recommendation = (
            "exit_review"
            if position_decision == "exit_review"
            else "reduce_or_trim"
            if position_decision == "reduce_or_trim"
            else "tighten_stop"
            if position_decision == "tighten_stop"
            else "hold_with_caution"
            if position_decision == "hold_with_caution"
            else "hold"
        )
        position_decision_confidence = _norm_confidence_pct(
            (top_row or {}).get("confidence", current_prob)
        )
        if position_decision in {"data_unavailable_review", "hold_with_caution"}:
            position_decision_confidence = round(max(0.0, position_decision_confidence - 12.0), 2)
        position_decision_reason = "; ".join([r for r in decision_reasons if r][:3])
        enriched["position_decision"] = position_decision
        enriched["position_decision_confidence"] = position_decision_confidence
        enriched["position_decision_reason"] = position_decision_reason
        enriched["position_risk_state"] = position_risk_state
        enriched["position_action_recommendation"] = position_action_recommendation
        canonical_position_state = (
            "exit"
            if position_decision == "exit_review"
            else "trim"
            if position_decision == "reduce_or_trim"
            else "tighten_stop"
            if position_decision == "tighten_stop"
            else "active_position"
        )
        enriched["canonical_position_decision_state"] = canonical_position_state
        enriched["canonical_trade_workflow_state"] = {
            "state": canonical_position_state,
            "source": "position_lifecycle_engine",
        }
        enriched["position_health_monitor"] = {
            "review_urgency_score": round(review_urgency_score, 2),
            "risk_posture": risk_posture,
            "consensus_drop": round(consensus_drop, 4),
            "disagreement_rise": round(disagreement_rise, 4),
        }
        enriched["current_risk_sell_posture"] = risk_posture
        dist = dict(position_sync_summary.get("position_decision_distribution") or {})
        dist[position_decision] = int(dist.get(position_decision, 0)) + 1
        position_sync_summary["position_decision_distribution"] = dist
        out.append(enriched)

    base_response = {
        "count": len(out),
        "positions": out,
        "position_lifecycle_intelligence": {
            "lifecycle_state_counts": lifecycle_state_counts,
            "total_open_positions": int(len(out)),
            "higher_risk_hold_count": int(lifecycle_state_counts.get("higher_risk_hold", 0)),
            "deteriorating_setup_count": int(lifecycle_state_counts.get("deteriorating_setup", 0)),
            "healthy_winner_count": int(lifecycle_state_counts.get("early_winner", 0)),
            "position_lifecycle_quality_score": round(
                max(
                    0.0,
                    min(
                        100.0,
                        62.0
                        + (lifecycle_state_counts.get("early_winner", 0) * 5.0)
                        - (lifecycle_state_counts.get("deteriorating_setup", 0) * 6.0)
                        - (lifecycle_state_counts.get("higher_risk_hold", 0) * 4.0),
                    ),
                ),
                2,
            ),
            "canonical_state_counts": {
                "active_position": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "active_position")),
                "tighten_stop": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "tighten_stop")),
                "trim": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "trim")),
                "exit": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "exit")),
            },
        },
        "position_sync_v1": {
            **position_sync_summary,
            "top_buys_cache_source": str(top_payload_key or "none"),
            "top_buys_cache_age_seconds": round(max(0.0, _to_float(top_payload_age, 0.0)), 2),
        },
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }
    try:
        compaction = _mobile_runtime_compaction_snapshot(force=False, include_closed_orders=False)
        return MOBILE_RUNTIME_COMPACTION.compact_positions_response(base_response, compaction=compaction)
    except Exception:
        base_response["mobile_runtime_compaction"] = {
            "mobile_runtime_compaction_active": False,
            "mobile_payload_compacted": False,
            "full_history_preserved": True,
            "replay_learning_preserved": True,
        }
        return base_response


@router.get("/api/sell_alerts")
def position_sell_alerts():
    cached = _CACHE.get("position_sell_alerts", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= POSITION_SELL_ALERTS_TTL_SECONDS:
        return dict(cached.get("data", {}))

    _ensure_latest_rankings()
    positions_rows = POSITION_TRACKER.get_open_positions()
    open_trades = []
    pos_by_symbol = {}
    latest_by_symbol = {}
    freshness_values = []
    ws_overlay_count = 0
    for pos in positions_rows:
            symbol = str(pos.get("symbol") or "").upper()
            pos_by_symbol[symbol] = dict(pos)
            latest = _find_latest_row(symbol, asset_type=pos.get("asset_type")) or {}
            latest_by_symbol[symbol] = dict(latest)
            latest_price = latest.get("price", pos.get("latest_price"))
            quote_age_seconds = _to_float(latest.get("quote_age_seconds"), None)
            if quote_age_seconds is None:
                quote_age_seconds = _iso_age_seconds(latest.get("timestamp", pos.get("last_snapshot_timestamp")))
            if quote_age_seconds is not None:
                freshness_values.append(float(quote_age_seconds))
            quote_source = str(
                latest.get("quote_source")
                or latest.get("provider_used")
                or latest.get("source")
                or pos.get("quote_source")
                or ""
            )
            if quote_source == "alpaca_ws_overlay":
                ws_overlay_count += 1
            entry_price = _to_float(pos.get("entry_price"), 0.0)
            unrealized_pct = None
            if _to_float(latest_price, 0.0) > 0 and entry_price > 0:
                unrealized_pct = round(((_to_float(latest_price, 0.0) - entry_price) / entry_price) * 100.0, 4)
            peak_unrealized = _to_float(pos.get("peak_unrealized_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
            adverse_unrealized = _to_float(pos.get("max_adverse_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
            if unrealized_pct is not None:
                peak_unrealized = max(peak_unrealized, unrealized_pct)
                adverse_unrealized = min(adverse_unrealized, unrealized_pct)
            pullback_from_peak = round(
                max(0.0, peak_unrealized - (unrealized_pct if unrealized_pct is not None else peak_unrealized)),
                4,
            )
            POSITION_TRACKER.update_position_snapshot(
                symbol,
                {
                    "quote_batch_id": latest.get("quote_batch_id", pos.get("entry_quote_batch_id", "")),
                    "latest_price": latest_price,
                    "current_predicted_probability": latest.get("predicted_win_probability", pos.get("current_predicted_probability")),
                    "current_consensus_strength": latest.get("consensus_strength", pos.get("current_consensus_strength")),
                    "current_persona_disagreement_index": latest.get("persona_disagreement_index", pos.get("current_persona_disagreement_index")),
                    "regime_context": latest.get("regime_context", pos.get("current_regime_context")),
                    "quote_quality": latest.get("quote_quality", pos.get("quote_quality", "unknown")),
                    "quote_source": quote_source,
                    "last_quote_age_seconds": quote_age_seconds,
                    "peak_unrealized_pnl_percent": peak_unrealized,
                    "max_adverse_pnl_percent": adverse_unrealized,
                    "data_unavailable_reason": latest.get("data_unavailable_reason", pos.get("data_unavailable_reason", "")),
                    "last_snapshot_timestamp": latest.get("timestamp", pos.get("last_snapshot_timestamp", "")),
                },
            )
            open_trades.append({
                "symbol": symbol,
                "mode": pos.get("mode", "intraday"),
                "entry_timestamp": pos.get("entry_timestamp"),
                "predicted_win_probability": pos.get("entry_predicted_win_probability"),
                "current_predicted_probability": latest.get("predicted_win_probability", pos.get("current_predicted_probability", pos.get("entry_predicted_win_probability"))),
                "consensus_strength": pos.get("entry_consensus_strength"),
                "current_consensus_strength": latest.get("consensus_strength", pos.get("current_consensus_strength", pos.get("entry_consensus_strength"))),
                "persona_disagreement_index": pos.get("entry_persona_disagreement_index"),
                "current_persona_disagreement_index": latest.get("persona_disagreement_index", pos.get("current_persona_disagreement_index", pos.get("entry_persona_disagreement_index"))),
                "regime_context": pos.get("entry_regime_context"),
                "current_regime_context": latest.get("regime_context", pos.get("current_regime_context", pos.get("entry_regime_context"))),
                "quote_quality": latest.get("quote_quality", pos.get("quote_quality", "unknown")),
                "quote_source": quote_source,
                "quote_age_seconds": quote_age_seconds,
                "latest_price": latest_price,
                "entry_price": entry_price,
                "unrealized_pnl_percent": unrealized_pct,
                "peak_unrealized_pnl_percent": peak_unrealized,
                "max_adverse_pnl_percent": adverse_unrealized,
                "pullback_from_peak_percent": pullback_from_peak,
            })

    eval_payload = EXIT_INTEL.evaluate_open_trades(open_trades, live_perf=LIVE_SIGNAL_LOG.live_performance())
    learned = EXIT_LEARNING.learned_thresholds()
    learned_used = bool(learned.get("sample_size", 0) >= 20)
    learning_exit_policy = {}
    regime_policy_hints = {}
    contextual_exit_hints = {}
    contextual_hold_time_hints = {}
    sell_quality_enforcement = {}
    degradation_exit_enforcement = {}
    early_weakening_exit_trigger = {}
    premature_exit_discipline = {}
    late_exit_penalty_enforcement = {}
    try:
        insights_payload = _normalize_learning_insights_payload(_get_enriched_learning_insights_cached())
        learning_exit_policy = dict(insights_payload.get("exit_policy_hints") or {})
        regime_policy_hints = dict(insights_payload.get("regime_policy_hints") or {})
        contextual_exit_hints = dict(insights_payload.get("contextual_exit_hints") or {})
        contextual_hold_time_hints = dict(insights_payload.get("contextual_hold_time_hints") or {})
        sell_quality_enforcement = dict(insights_payload.get("sell_quality_enforcement_engine") or {})
        degradation_exit_enforcement = dict(insights_payload.get("degradation_exit_enforcement_engine") or {})
        early_weakening_exit_trigger = dict(insights_payload.get("early_weakening_exit_trigger") or {})
        premature_exit_discipline = dict(insights_payload.get("premature_exit_discipline_engine") or {})
        late_exit_penalty_enforcement = dict(insights_payload.get("late_exit_penalty_enforcement") or {})
    except Exception:
        learning_exit_policy = {}
        regime_policy_hints = {}
        contextual_exit_hints = {}
        contextual_hold_time_hints = {}
        sell_quality_enforcement = {}
        degradation_exit_enforcement = {}
        early_weakening_exit_trigger = {}
        premature_exit_discipline = {}
        late_exit_penalty_enforcement = {}
    base_pullback_threshold = max(1.2, min(2.8, _to_float(learning_exit_policy.get("trailing_pullback_exit_threshold_percent"), 2.0)))
    base_stop_loss_threshold = max(-3.2, min(-1.8, _to_float(learning_exit_policy.get("stop_loss_threshold_percent"), -2.5)))
    exit_quality_score = _to_float(learning_exit_policy.get("exit_quality_score"), 0.0)
    exit_quality_trend = str(learning_exit_policy.get("exit_quality_trend") or "unknown").lower()
    avg_capture_ratio = _to_float(learning_exit_policy.get("avg_capture_ratio_percent"), 0.0)
    if exit_quality_score >= 70.0 and exit_quality_trend == "improving":
        base_pullback_threshold = min(2.8, base_pullback_threshold + 0.1)
        base_stop_loss_threshold = max(-3.2, base_stop_loss_threshold - 0.1)
    elif exit_quality_score <= 45.0 or exit_quality_trend == "worsening":
        base_pullback_threshold = max(1.2, base_pullback_threshold - 0.15)
        base_stop_loss_threshold = min(-1.8, base_stop_loss_threshold + 0.15)
    if avg_capture_ratio < 50.0:
        base_pullback_threshold = max(1.2, base_pullback_threshold - 0.1)
    alerts = []
    action_priority_counts = {
        "sell_now": 0,
        "trim": 0,
        "reduce": 0,
        "hold_through_noise": 0,
        "monitor": 0,
    }
    for sig in eval_payload.get("signals", []):
        if not isinstance(sig, dict):
            continue
        level = str(sig.get("exit_signal") or "NONE")
        reasons = []
        explanation = str(sig.get("explanation") or "")
        if explanation and explanation != "No exit deterioration detected.":
            reasons = [x.strip() for x in explanation.split(";") if x.strip()]
        primary_trigger = reasons[0] if reasons else "none"
        secondary = reasons[1:] if len(reasons) > 1 else []
        if level in {"STRONG_EXIT", "RISK_EXIT", "TIME_EXIT"}:
            recommended_action = "EXIT"
            urgency = "high"
        elif level == "SELL_WATCH":
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
        elif level == "TIME_REVIEW":
            recommended_action = "TRIM"
            urgency = "medium"
        else:
            recommended_action = "HOLD"
            urgency = "low"

        symbol = str(sig.get("symbol") or "").upper()
        pos = pos_by_symbol.get(symbol, {})
        latest_ctx = latest_by_symbol.get(symbol, {})
        prob_drop = _to_float(sig.get("probability_drop_percent"), 0.0)
        dis_change = _to_float(pos.get("current_persona_disagreement_index"), 0.0) - _to_float(
            pos.get("entry_persona_disagreement_index"), 0.0
        )
        regime_shift = bool(sig.get("regime_shift", False))
        if learned_used and level == "NONE":
            if prob_drop >= _to_float(learned.get("probability_drop_sellwatch_threshold"), 8.0):
                recommended_action = "TIGHTEN_STOP"
                urgency = "medium"
                if primary_trigger == "none":
                    primary_trigger = "learned_probability_drop_threshold"
                secondary = list(secondary) + ["learned_threshold_trigger"]

        latest_price = _to_float(pos.get("latest_price"), 0.0)
        suggested_stop_update = None
        unrealized_pct = _to_float(pos.get("unrealized_pnl_percent"), None)
        peak_unrealized = _to_float(pos.get("peak_unrealized_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
        pullback_from_peak = _to_float(pos.get("pullback_from_peak_percent"), 0.0)
        quote_age_seconds = _to_float(pos.get("quote_age_seconds"), _to_float(pos.get("last_quote_age_seconds"), 0.0))
        current_regime = str(pos.get("current_regime_context") or "unknown").strip().lower()
        setup_key = str(
            latest_ctx.get("setup_type")
            or pos.get("entry_setup_type")
            or pos.get("setup_type")
            or "unknown"
        ).strip().lower()
        persona_key = str(
            latest_ctx.get("persona_best_fit")
            or pos.get("entry_persona_best_fit")
            or "unknown"
        ).strip().lower()
        cap_key = str(
            latest_ctx.get("market_cap_category")
            or pos.get("entry_market_cap_category")
            or "unknown"
        ).strip().lower()
        now_month = datetime.now(UTC).month
        season_key = "winter" if now_month in (12, 1, 2) else "spring" if now_month in (3, 4, 5) else "summer" if now_month in (6, 7, 8) else "fall"
        regime_hint = regime_policy_hints.get(current_regime, {}) if isinstance(regime_policy_hints, dict) else {}
        regime_mult = _to_float(regime_hint.get("multiplier"), 1.0)
        pullback_threshold = base_pullback_threshold
        stop_loss_threshold = base_stop_loss_threshold
        if regime_mult < 0.97:
            pullback_threshold = max(1.2, pullback_threshold - 0.2)
            stop_loss_threshold = min(-1.8, stop_loss_threshold + 0.2)
        elif regime_mult > 1.03:
            pullback_threshold = min(2.8, pullback_threshold + 0.2)
            stop_loss_threshold = max(-3.2, stop_loss_threshold - 0.2)
        setup_regime_hint = ((contextual_exit_hints.get("setup_regime") or {}).get(f"{setup_key}|{current_regime}") or {})
        persona_regime_hint = ((contextual_exit_hints.get("persona_regime") or {}).get(f"{persona_key}|{current_regime}") or {})
        setup_cap_hint = ((contextual_exit_hints.get("setup_cap_bucket") or {}).get(f"{setup_key}|{cap_key}") or {})
        season_setup_hint = ((contextual_exit_hints.get("season_setup") or {}).get(f"{season_key}|{setup_key}") or {})
        context_exit_hints = [h for h in (setup_regime_hint, persona_regime_hint, setup_cap_hint, season_setup_hint) if isinstance(h, dict) and h]
        hold_setup_regime_hint = ((contextual_hold_time_hints.get("setup_regime") or {}).get(f"{setup_key}|{current_regime}") or {})
        hold_persona_regime_hint = ((contextual_hold_time_hints.get("persona_regime") or {}).get(f"{persona_key}|{current_regime}") or {})
        hold_setup_cap_hint = ((contextual_hold_time_hints.get("setup_cap_bucket") or {}).get(f"{setup_key}|{cap_key}") or {})
        hold_season_setup_hint = ((contextual_hold_time_hints.get("season_setup") or {}).get(f"{season_key}|{setup_key}") or {})
        hold_time_hints = [h for h in (hold_setup_regime_hint, hold_persona_regime_hint, hold_setup_cap_hint, hold_season_setup_hint) if isinstance(h, dict) and h]
        if context_exit_hints:
            wsum = 0.0
            pb_num = 0.0
            sl_num = 0.0
            for h in context_exit_hints:
                s = max(1.0, _to_float(h.get("sample_size"), 1.0))
                w = min(2.2, s / 80.0)
                pb_num += _to_float(h.get("trailing_pullback_exit_threshold_percent"), pullback_threshold) * w
                sl_num += _to_float(h.get("stop_loss_threshold_percent"), stop_loss_threshold) * w
                wsum += w
            if wsum > 0:
                contextual_pullback = pb_num / wsum
                contextual_stop_loss = sl_num / wsum
                # Conservative blend: mostly global+regime, partially contextual.
                pullback_threshold = max(1.2, min(2.8, (pullback_threshold * 0.7) + (contextual_pullback * 0.3)))
                stop_loss_threshold = max(-3.2, min(-1.8, (stop_loss_threshold * 0.7) + (contextual_stop_loss * 0.3)))
        hold_review_intraday = _to_float(learning_exit_policy.get("time_review_intraday_minutes"), 120.0)
        hold_review_swing_days = _to_float(learning_exit_policy.get("time_review_swing_days"), 15.0)
        hold_bias = 0.0
        if hold_time_hints:
            wsum = 0.0
            intraday_num = 0.0
            swing_num = 0.0
            bias_num = 0.0
            for h in hold_time_hints:
                s = max(1.0, _to_float(h.get("sample_size"), 1.0))
                w = min(2.0, s / 80.0)
                intraday_num += _to_float(h.get("review_intraday_minutes"), hold_review_intraday) * w
                swing_num += _to_float(h.get("review_swing_days"), hold_review_swing_days) * w
                bias_num += _to_float(h.get("hold_bias"), 0.0) * w
                wsum += w
            if wsum > 0:
                hold_review_intraday = max(30.0, min(240.0, (hold_review_intraday * 0.7) + ((intraday_num / wsum) * 0.3)))
                hold_review_swing_days = max(5.0, min(35.0, (hold_review_swing_days * 0.7) + ((swing_num / wsum) * 0.3)))
                hold_bias = bias_num / wsum
        memory_row = {
            "symbol": symbol,
            "setup_type": setup_key,
            "market_regime": current_regime,
            "entry_signal_tags": latest_ctx.get("entry_signal_tags", pos.get("entry_signal_tags", "")),
            "signal_tags": latest_ctx.get("signal_tags", pos.get("signal_tags", "")),
        }
        memory_ctx = _memory_context_for_row(memory_row)
        memory_sample = int(_to_float(memory_ctx.get("memory_sample_size"), 0.0))
        memory_wr = _to_float(memory_ctx.get("memory_win_rate"), 0.0)
        memory_fast_loss = _to_float(memory_ctx.get("memory_fast_loss_rate"), 0.0)
        memory_expectancy = _to_float(memory_ctx.get("memory_expectancy"), 0.0)
        trailing_exit = False
        stop_loss_exit = False
        if unrealized_pct is not None and peak_unrealized >= 4.0 and pullback_from_peak >= pullback_threshold:
            trailing_exit = True
            if recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                recommended_action = "EXIT"
                urgency = "high"
            if primary_trigger == "none":
                primary_trigger = "profit_protection_pullback"
            secondary = list(secondary) + [f"pullback_from_peak>={pullback_threshold:.1f}%"]
        if unrealized_pct is not None and unrealized_pct <= stop_loss_threshold:
            stop_loss_exit = True
            recommended_action = "EXIT"
            urgency = "high"
            primary_trigger = "stop_loss_threshold"
            secondary = list(secondary) + [f"unrealized_pnl<={stop_loss_threshold:.1f}%"]
        # Enforcement: escalate weaker/degrading positions earlier when sell/degradation quality is poor.
        degr_enf = _to_float(degradation_exit_enforcement.get("degradation_exit_enforcement_score"), 0.0)
        early_weaken = _to_float(early_weakening_exit_trigger.get("early_weakening_exit_trigger_score"), 0.0)
        sell_enf = _to_float(sell_quality_enforcement.get("sell_quality_enforcement_score"), 0.0)
        prem_disc = _to_float(premature_exit_discipline.get("premature_exit_discipline_score"), 0.0)
        late_enf = _to_float(late_exit_penalty_enforcement.get("late_exit_penalty_enforcement_score"), 0.0)
        enforcement_pressure = max(
            0.0,
            min(
                100.0,
                (degr_enf * 0.35)
                + (early_weaken * 0.25)
                + (sell_enf * 0.20)
                + ((100.0 - prem_disc) * 0.10)
                + ((100.0 - late_enf) * 0.10),
            ),
        )
        if memory_sample >= 16:
            if memory_wr <= 26.0 or memory_fast_loss >= 9.0 or memory_expectancy <= -0.18:
                enforcement_pressure = min(100.0, enforcement_pressure + 9.0)
                secondary = list(secondary) + ["similar_setup_loser_memory_pressure"]
            elif memory_wr >= 52.0 and memory_fast_loss <= 4.0 and memory_expectancy >= 0.12:
                enforcement_pressure = max(0.0, enforcement_pressure - 5.0)
                secondary = list(secondary) + ["similar_setup_winner_memory_relief"]
        if recommended_action in {"HOLD", "TIGHTEN_STOP"} and enforcement_pressure >= 56.0:
            recommended_action = "TRIM" if enforcement_pressure < 72.0 else "EXIT"
            urgency = "high" if enforcement_pressure >= 72.0 else "medium"
            if primary_trigger == "none":
                primary_trigger = "degradation_enforcement"
            secondary = list(secondary) + [f"enforcement_pressure>={enforcement_pressure:.1f}"]
        if recommended_action == "HOLD" and prob_drop >= 8.0 and enforcement_pressure >= 48.0:
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
            secondary = list(secondary) + ["early_weakening_enforcement"]
        if quote_age_seconds and quote_age_seconds > 45 and recommended_action == "HOLD":
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
            secondary = list(secondary) + ["quote_stale>45s"]
        entry_ts = str(pos.get("entry_timestamp") or "").strip()
        hold_seconds = _iso_age_seconds(entry_ts) if entry_ts else None
        if hold_seconds and hold_seconds > 0:
            hold_minutes = hold_seconds / 60.0
            mode = str(pos.get("mode") or "").lower()
            if mode == "intraday":
                if hold_minutes >= hold_review_intraday and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                    recommended_action = "TRIM" if hold_bias <= 0.2 else recommended_action
                    urgency = "medium" if urgency == "low" else urgency
                    secondary = list(secondary) + [f"context_hold_review>{hold_review_intraday:.0f}m"]
            else:
                hold_days = hold_seconds / 86400.0
                if hold_days >= hold_review_swing_days and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                    recommended_action = "TRIM" if hold_bias <= 0.2 else recommended_action
                    urgency = "medium" if urgency == "low" else urgency
                    secondary = list(secondary) + [f"context_hold_review>{hold_review_swing_days:.1f}d"]
        if recommended_action in {"TIGHTEN_STOP", "TRIM"} and latest_price > 0:
            suggested_stop_update = round(latest_price * 0.985, 4)
        risk_est = EXIT_LEARNING.expected_risk_if_hold(
            probability_drop_percent=prob_drop,
            disagreement_increase=dis_change,
            regime_shift=regime_shift,
        )
        risk_hold = _to_float(risk_est.get("expected_risk_if_hold"), 0.0)
        risk_conf = _to_float(risk_est.get("confidence"), 0.0)
        risk_sample = _to_int(risk_est.get("sample_size"), 0)
        missed_profit_pressure = _to_float(
            risk_est.get("missed_profit_pressure"),
            _to_float(learned.get("missed_profit_pressure"), 0.0),
        )
        hold_quality_estimate = _to_float(
            risk_est.get("hold_quality_estimate"),
            _to_float(learned.get("hold_quality_estimate"), 0.0),
        )
        if risk_sample >= 20 and risk_conf >= 0.35:
            if risk_hold >= 0.74 and recommended_action in {"HOLD", "TIGHTEN_STOP", "TRIM"}:
                recommended_action = "EXIT"
                urgency = "high"
                if primary_trigger == "none":
                    primary_trigger = "exit_learning_high_risk_if_hold"
                secondary = list(secondary) + [f"risk_if_hold>={risk_hold:.2f}"]
            elif risk_hold >= 0.62 and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                recommended_action = "TRIM"
                urgency = "medium" if urgency == "low" else urgency
                if primary_trigger == "none":
                    primary_trigger = "exit_learning_elevated_risk_if_hold"
                secondary = list(secondary) + [f"risk_if_hold>={risk_hold:.2f}"]
            elif (
                risk_hold <= 0.36
                and hold_quality_estimate >= 0.58
                and missed_profit_pressure >= 0.30
                and recommended_action == "TIGHTEN_STOP"
            ):
                recommended_action = "HOLD"
                urgency = "low"
                secondary = list(secondary) + ["exit_learning_hold_quality_support"]
        exit_reason_stack = [primary_trigger] + [s for s in secondary if s]
        exit_reason_stack = [r for r in exit_reason_stack if str(r or "").strip()]
        if not exit_reason_stack:
            exit_reason_stack = ["none"]
        if recommended_action == "EXIT":
            action_priority = "sell_now"
            canonical_sell_state = "exit"
        elif recommended_action == "TRIM":
            action_priority = "trim"
            canonical_sell_state = "trim"
        elif recommended_action == "TIGHTEN_STOP":
            action_priority = "reduce"
            canonical_sell_state = "tighten_stop"
        elif recommended_action == "HOLD" and urgency == "low":
            action_priority = "hold_through_noise"
            canonical_sell_state = "active_position"
        else:
            action_priority = "monitor"
            canonical_sell_state = "active_position"
        action_priority_counts[action_priority] = int(action_priority_counts.get(action_priority, 0)) + 1
        exit_signal_confidence = max(
            0.0,
            min(
                100.0,
                (_to_float(sig.get("signal_strength_score"), 0.0) * 0.55)
                + (max(0.0, prob_drop) * 2.1)
                + (7.0 if trailing_exit else 0.0)
                + (9.0 if stop_loss_exit else 0.0)
                + (6.0 if urgency == "high" else (3.0 if urgency == "medium" else 0.0)),
            ),
        )
        if recommended_action == "EXIT":
            core_exit_state = "exit_now"
        elif recommended_action == "TRIM":
            core_exit_state = "trim_risk"
        elif recommended_action == "TIGHTEN_STOP":
            core_exit_state = "tighten_and_monitor"
        else:
            core_exit_state = "hold_cautious" if risk_hold >= 0.45 else "hold_through_noise"
        core_exit_discipline_score = max(
            0.0,
            min(
                100.0,
                (exit_signal_confidence * 0.55)
                + (risk_hold * 100.0 * 0.30)
                + ((100.0 - (hold_quality_estimate * 100.0)) * 0.15),
            ),
        )

        alert_row = {
            "symbol": sig.get("symbol"),
            "asset_type": sig.get("asset_type"),
            "alert_level": level,
            "reasons": reasons,
            "primary_trigger": primary_trigger,
            "secondary_triggers": secondary,
            "probability_drop_percent": prob_drop,
            "consensus_change": sig.get("consensus_drop", 0.0),
            "regime_change": bool(sig.get("regime_shift", False)),
            "recommended_action": recommended_action,
            "suggested_action": "Review for manual exit" if level != "NONE" else "Hold",
            "suggested_stop_update": suggested_stop_update,
            "learned_thresholds_used": learned_used,
            "expected_risk_if_hold": risk_est.get("expected_risk_if_hold", 0.0),
            "expected_risk_sample_size": risk_est.get("sample_size", 0),
            "signal_strength_score": sig.get("signal_strength_score", 0.0),
            "exit_signal_confidence": round(exit_signal_confidence, 2),
            "exit_reason_stack": exit_reason_stack,
            "strongest_exit_trigger": exit_reason_stack[0],
            "position_exit_priority": action_priority,
            "canonical_position_decision_state": canonical_sell_state,
            "canonical_trade_workflow_state": {
                "state": canonical_sell_state,
                "source": "sell_alert_engine",
            },
            "core_exit_discipline_state": core_exit_state,
            "core_exit_discipline_score": round(core_exit_discipline_score, 2),
            "urgency": urgency,
            "unrealized_pnl_percent": unrealized_pct,
            "peak_unrealized_pnl_percent": peak_unrealized,
            "pullback_from_peak_percent": pullback_from_peak,
            "quote_age_seconds": quote_age_seconds,
            "quote_source": pos.get("quote_source"),
            "trailing_exit_triggered": trailing_exit,
            "stop_loss_triggered": stop_loss_exit,
            "exit_policy_applied": {
                "trailing_pullback_threshold_percent": round(pullback_threshold, 2),
                "stop_loss_threshold_percent": round(stop_loss_threshold, 2),
                "base_policy_reason": str(learning_exit_policy.get("policy_reason") or "default"),
                "regime_multiplier": round(regime_mult, 4),
                "context_setup": setup_key,
                "context_persona": persona_key,
                "context_cap_bucket": cap_key,
                "context_season": season_key,
                "contextual_hints_used_count": len(context_exit_hints),
                "hold_time_context_hints_used_count": len(hold_time_hints),
                "hold_review_intraday_minutes": round(hold_review_intraday, 2),
                "hold_review_swing_days": round(hold_review_swing_days, 2),
                "hold_bias": round(hold_bias, 4),
                "exit_quality_score": round(exit_quality_score, 2),
                "exit_quality_trend": exit_quality_trend,
                "avg_capture_ratio_percent": round(avg_capture_ratio, 2),
                "exit_learning_expected_risk_if_hold": round(risk_hold, 4),
                "exit_learning_confidence": round(risk_conf, 4),
                "exit_learning_sample_size": int(risk_sample),
                "exit_learning_missed_profit_pressure": round(missed_profit_pressure, 4),
                "exit_learning_hold_quality_estimate": round(hold_quality_estimate, 4),
            },
            "key_signal_changes": {
                "probability_drop_percent": prob_drop,
                "consensus_change": sig.get("consensus_drop", 0.0),
                "persona_disagreement_change": round(dis_change, 4),
                "regime_shift": regime_shift,
                "enforcement_pressure": round(enforcement_pressure, 2),
                "quote_quality": pos.get("quote_quality"),
                "current_regime_context": pos.get("current_regime_context"),
                "entry_regime_context": pos.get("entry_regime_context"),
            },
            "persona_delta": {
                "entry_consensus_strength": pos.get("entry_consensus_strength"),
                "current_consensus_strength": pos.get("current_consensus_strength"),
                "entry_persona_disagreement_index": pos.get("entry_persona_disagreement_index"),
                "current_persona_disagreement_index": pos.get("current_persona_disagreement_index"),
            },
            "memory_context": memory_ctx,
        }
        alert_row.update(_sell_alert_plain_explanation(alert_row))
        alerts.append(alert_row)
    alerts = _apply_ollama_sell_explanations(alerts)
    active = [a for a in alerts if a.get("alert_level") != "NONE"]
    stale_quotes_count = len([a for a in alerts if _to_float(a.get("quote_age_seconds"), 0.0) > 45.0])
    fresh_quotes_count = len(
        [a for a in alerts if _to_float(a.get("quote_age_seconds"), -1.0) >= 0 and _to_float(a.get("quote_age_seconds"), 0.0) <= 20.0]
    )
    avg_quote_age_seconds = round(sum(freshness_values) / len(freshness_values), 2) if freshness_values else None
    payload = {
        "total_open_positions": len(open_trades),
        "active_sell_alerts": len(active),
        "sell_alert_quality_suite": {
            "action_priority_counts": action_priority_counts,
            "sell_now_count": int(action_priority_counts.get("sell_now", 0)),
            "trim_count": int(action_priority_counts.get("trim", 0)),
            "reduce_count": int(action_priority_counts.get("reduce", 0)),
            "hold_through_noise_count": int(action_priority_counts.get("hold_through_noise", 0)),
            "monitor_count": int(action_priority_counts.get("monitor", 0)),
            "avg_exit_signal_confidence": round(
                sum(_to_float(a.get("exit_signal_confidence"), 0.0) for a in alerts) / max(1, len(alerts)),
                2,
            ),
            "strongest_exit_trigger": str((active[0] or {}).get("strongest_exit_trigger") if active else "none"),
            "canonical_state_counts": {
                "active_position": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "active_position")),
                "tighten_stop": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "tighten_stop")),
                "trim": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "trim")),
                "exit": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "exit")),
            },
        },
        "monitoring_summary": {
            "ws_overlay_applied_count": int(ws_overlay_count),
            "fresh_quotes_count": int(fresh_quotes_count),
            "stale_quotes_count": int(stale_quotes_count),
            "avg_quote_age_seconds": avg_quote_age_seconds,
        },
        "learned_thresholds": learned,
        "learned_thresholds_used": learned_used,
        "learning_exit_policy": learning_exit_policy,
        "alerts": alerts,
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }
    _CACHE["position_sell_alerts"] = {"data": dict(payload), "ts": time.time()}
    return payload


def _read_json_file(path, default=None):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except Exception:
        return {} if default is None else default


def _write_json_file_safely(path, payload):
    try:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        tmp = f"{path}.tmp"
        with open(tmp, "w") as f:
            json.dump(payload, f, indent=2, sort_keys=True)
        os.replace(tmp, path)
        return True
    except Exception:
        return False


def _today_utc_key():
    try:
        return datetime.now(UTC).strftime("%Y-%m-%d")
    except Exception:
        return ""


def _fmp_governor_default_state():
    return {
        "date_utc": _today_utc_key(),
        "fmp_calls_today": 0,
        "fmp_blocked_calls_today": 0,
        "fmp_estimated_used_today_bytes": 0,
        "fmp_estimated_used_total_bytes": 0,
        "fmp_estimated_used_total_gb": 0.0,
        "last_fmp_calls_total_seen": 0,
        "last_alpaca_calls_total_seen": 0,
        "last_fallback_calls_total_seen": 0,
        "alpaca_rest_calls_today": 0,
        "fallback_provider_calls_today": 0,
        "cache_hits_seen": 0,
        "cache_misses_seen": 0,
        "cache_sets_seen": 0,
        "cache_entries_seen": 0,
        "fmp_cache_hit_rate": 0.0,
        "last_updated_utc": _now_utc_iso(),
    }


def _fmp_efficiency_default_manifest():
    return {
        "enabled": True,
        "total_fmp_calls_tracked": 0,
        "total_cache_hits": 0,
        "total_cache_misses": 0,
        "total_bytes_estimated": 0,
        "bytes_by_endpoint_family": {},
        "calls_by_endpoint_family": {},
        "avg_bytes_per_call": 0.0,
        "best_value_endpoints": [],
        "worst_value_endpoints": [],
        "blocked_due_bandwidth": 0,
        "blocked_due_call_limit": 0,
        "last_updated_at": "",
    }


def _fmp_efficiency_manifest_load():
    payload = _read_json_file(FMP_EFFICIENCY_MANIFEST_PATH, default={})
    if isinstance(payload, dict) and payload:
        return payload
    return _fmp_efficiency_default_manifest()


def _fmp_efficiency_manifest_write(payload):
    return _write_json_file_safely(FMP_EFFICIENCY_MANIFEST_PATH, dict(payload or {}))


def _fmp_efficiency_record_event(event):
    row = dict(event or {})
    row["timestamp"] = str(row.get("timestamp") or _now_utc_iso())
    row["endpoint_family"] = str(row.get("endpoint_family") or "unknown")
    row["endpoint_path_template"] = str(row.get("endpoint_path_template") or "")
    row["symbol_count"] = int(_to_float(row.get("symbol_count"), 1.0))
    row["status_code"] = int(_to_float(row.get("status_code"), 0.0))
    row["ok"] = bool(row.get("ok", False))
    row["cache_hit"] = bool(row.get("cache_hit", False))
    row["bytes_estimated"] = int(_to_float(row.get("bytes_estimated"), 0.0))
    row["bytes_actual_if_available"] = int(_to_float(row.get("bytes_actual_if_available"), 0.0))
    row["useful_fields_count"] = int(_to_float(row.get("useful_fields_count"), 0.0))
    row["useful_score"] = float(_to_float(row.get("useful_score"), 0.0))
    row["call_reason"] = str(row.get("call_reason") or "")
    row["caller_context"] = str(row.get("caller_context") or "")
    row["ttl_seconds"] = int(_to_float(row.get("ttl_seconds"), 0.0))
    row["blocked_reason"] = str(row.get("blocked_reason") or "")
    row["api_calls_delta"] = int(_to_float(row.get("api_calls_delta"), 0.0))
    row["bandwidth_delta"] = int(_to_float(row.get("bandwidth_delta"), 0.0))
    row["provider_governor_allowed"] = bool(row.get("provider_governor_allowed", True))
    with _FMP_EFFICIENCY_LOCK:
        _append_jsonl_safely(FMP_EFFICIENCY_LEDGER_PATH, row)
        manifest = _fmp_efficiency_manifest_load()
        manifest["enabled"] = True
        manifest["total_fmp_calls_tracked"] = int(_to_float(manifest.get("total_fmp_calls_tracked"), 0.0)) + 1
        if bool(row.get("cache_hit", False)):
            manifest["total_cache_hits"] = int(_to_float(manifest.get("total_cache_hits"), 0.0)) + 1
        else:
            manifest["total_cache_misses"] = int(_to_float(manifest.get("total_cache_misses"), 0.0)) + 1
        bytes_used = int(max(0, _to_float(row.get("bytes_actual_if_available"), _to_float(row.get("bytes_estimated"), 0.0))))
        manifest["total_bytes_estimated"] = int(_to_float(manifest.get("total_bytes_estimated"), 0.0)) + bytes_used
        fam = str(row.get("endpoint_family") or "unknown")
        calls_by_family = dict(manifest.get("calls_by_endpoint_family") or {})
        bytes_by_family = dict(manifest.get("bytes_by_endpoint_family") or {})
        calls_by_family[fam] = int(_to_float(calls_by_family.get(fam), 0.0)) + 1
        bytes_by_family[fam] = int(_to_float(bytes_by_family.get(fam), 0.0)) + bytes_used
        manifest["calls_by_endpoint_family"] = calls_by_family
        manifest["bytes_by_endpoint_family"] = bytes_by_family
        total_calls = int(_to_float(manifest.get("total_fmp_calls_tracked"), 0.0))
        total_bytes = int(_to_float(manifest.get("total_bytes_estimated"), 0.0))
        manifest["avg_bytes_per_call"] = round(total_bytes / max(1.0, float(total_calls)), 2)
        blocked_reason = str(row.get("blocked_reason") or "").strip().lower()
        if blocked_reason == "bandwidth_budget":
            manifest["blocked_due_bandwidth"] = int(_to_float(manifest.get("blocked_due_bandwidth"), 0.0)) + 1
        if blocked_reason in {"call_limit", "budget_guard_block", "recent_call_ttl_active"}:
            manifest["blocked_due_call_limit"] = int(_to_float(manifest.get("blocked_due_call_limit"), 0.0)) + 1
        endpoint = str(row.get("endpoint_path_template") or "")
        rollup = dict(manifest.get("_endpoint_value_rollup") or {})
        e = dict(rollup.get(endpoint) or {"n": 0, "v": 0.0})
        e["n"] = int(_to_float(e.get("n"), 0.0)) + 1
        byte_floor = max(1.0, float(bytes_used))
        e["v"] = float(_to_float(e.get("v"), 0.0)) + (float(_to_float(row.get("useful_score"), 0.0)) / byte_floor)
        rollup[endpoint] = e
        ranked = []
        for k, v in rollup.items():
            n = max(1, int(_to_float((v or {}).get("n"), 0.0)))
            ranked.append(
                {
                    "endpoint": str(k),
                    "value_per_byte": round(float(_to_float((v or {}).get("v"), 0.0)) / float(n), 8),
                    "samples": int(n),
                }
            )
        ranked.sort(key=lambda x: x["value_per_byte"], reverse=True)
        manifest["best_value_endpoints"] = ranked[:5]
        manifest["worst_value_endpoints"] = list(reversed(ranked[-5:])) if ranked else []
        manifest["last_updated_at"] = _now_utc_iso()
        manifest["_endpoint_value_rollup"] = rollup
        _fmp_efficiency_manifest_write(manifest)


def _fmp_efficiency_public_block():
    m = _fmp_efficiency_manifest_load()
    if not os.path.exists(FMP_EFFICIENCY_MANIFEST_PATH):
        _fmp_efficiency_manifest_write(m)
    if not os.path.exists(FMP_EFFICIENCY_LEDGER_PATH):
        try:
            os.makedirs(os.path.dirname(FMP_EFFICIENCY_LEDGER_PATH) or ".", exist_ok=True)
            with open(FMP_EFFICIENCY_LEDGER_PATH, "a", encoding="utf-8"):
                pass
        except Exception:
            pass
    recommendation = "keep_current_conservative_mode"
    worst = list(m.get("worst_value_endpoints") or [])
    if worst:
        recommendation = "prioritize_small_high_value_endpoints_and_cache_hits"
    return {
        "enabled": bool(m.get("enabled", True)),
        "total_fmp_calls_tracked": int(_to_float(m.get("total_fmp_calls_tracked"), 0.0)),
        "total_cache_hits": int(_to_float(m.get("total_cache_hits"), 0.0)),
        "total_cache_misses": int(_to_float(m.get("total_cache_misses"), 0.0)),
        "total_bytes_estimated": int(_to_float(m.get("total_bytes_estimated"), 0.0)),
        "avg_bytes_per_call": round(_to_float(m.get("avg_bytes_per_call"), 0.0), 2),
        "calls_by_endpoint_family": dict(m.get("calls_by_endpoint_family") or {}),
        "bytes_by_endpoint_family": dict(m.get("bytes_by_endpoint_family") or {}),
        "blocked_due_bandwidth": int(_to_float(m.get("blocked_due_bandwidth"), 0.0)),
        "blocked_due_call_limit": int(_to_float(m.get("blocked_due_call_limit"), 0.0)),
        "best_value_endpoints": list(m.get("best_value_endpoints") or []),
        "worst_value_endpoints": list(m.get("worst_value_endpoints") or []),
        "last_updated_at": str(m.get("last_updated_at") or ""),
        "recommendation": recommendation,
    }


def _fmp_enrichment_cache_load():
    payload = _read_json_file(FMP_ENRICHMENT_CACHE_PATH, default={})
    return payload if isinstance(payload, dict) else {}


def _fmp_enrichment_cache_write(payload):
    return _write_json_file_safely(FMP_ENRICHMENT_CACHE_PATH, dict(payload or {}))


def _fmp_enrichment_cache_get(endpoint_key, symbol, ttl_seconds):
    cache = _fmp_enrichment_cache_load()
    key = f"{str(endpoint_key).lower()}::{str(symbol or '').upper().strip()}"
    row = dict(cache.get(key) or {})
    if not row:
        return None
    ts = _to_float(row.get("ts"), 0.0)
    if (time.time() - ts) > max(1.0, _to_float(ttl_seconds, 0.0)):
        return None
    return row


def _fmp_enrichment_cache_set(endpoint_key, symbol, payload, bytes_used):
    cache = _fmp_enrichment_cache_load()
    key = f"{str(endpoint_key).lower()}::{str(symbol or '').upper().strip()}"
    cache[key] = {
        "ts": time.time(),
        "payload": dict(payload or {}),
        "bytes": int(max(0, _to_float(bytes_used, 0.0))),
    }
    _fmp_enrichment_cache_write(cache)


def _fmp_small_endpoint_request(endpoint_key, symbol, cycle_state, call_reason):
    endpoint = str(endpoint_key or "").strip().lower()
    sym = str(symbol or "").upper().strip()
    if endpoint not in {"quote", "profile"} or not sym:
        return {"ok": False, "blocked_reason": "unsupported_endpoint", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    ttl_seconds = int(FMP_ENRICHMENT_PROFILE_TTL_SECONDS if endpoint == "profile" else FMP_ENRICHMENT_QUOTE_TTL_SECONDS)
    path_template = f"/stable/{endpoint}?symbol={{symbol}}"
    family = "quote_profile"
    cached = _fmp_enrichment_cache_get(endpoint, sym, ttl_seconds)
    if isinstance(cached, dict) and cached:
        data_cached = dict(cached.get("payload") or {})
        fields = [str(k) for k, v in data_cached.items() if v not in (None, "", 0, 0.0)]
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 200,
                "ok": True,
                "cache_hit": True,
                "bytes_estimated": int(_to_float(cached.get("bytes"), 0.0)),
                "bytes_actual_if_available": int(_to_float(cached.get("bytes"), 0.0)),
                "useful_fields_count": int(len(fields)),
                "useful_score": float(min(100.0, len(fields) * 10.0)),
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": True,
            }
        )
        cycle_state["cache_hits"] = int(_to_float(cycle_state.get("cache_hits"), 0.0)) + 1
        return {
            "ok": True,
            "blocked_reason": "",
            "data": data_cached,
            "cache_hit": True,
            "bytes": int(_to_float(cached.get("bytes"), 0.0)),
            "fields_used": fields,
        }
    cycle_state["cache_misses"] = int(_to_float(cycle_state.get("cache_misses"), 0.0)) + 1
    governor = dict(_fmp_usage_governor_snapshot(update=False) or {})
    est_today_bytes = int(_to_float(( _read_json_file(FMP_USAGE_STATE_PATH, default={}) or {}).get("fmp_estimated_used_today_bytes"), 0.0))
    if not bool(governor.get("fmp_rest_governor_allowed", False)):
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 429,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "call_limit",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": False,
            }
        )
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "call_limit", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    if bool(governor.get("fmp_hard_stop_active", False)) or bool(governor.get("fmp_warning_active", False)):
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 0,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "bandwidth_budget",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": False,
            }
        )
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "bandwidth_budget", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    if est_today_bytes >= int(FMP_ENRICHMENT_DAILY_SOFT_CAP_BYTES):
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 0,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "bandwidth_budget",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": False,
            }
        )
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "bandwidth_budget", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    if int(_to_float(cycle_state.get("calls_made"), 0.0)) >= int(MAX_FMP_ENRICHMENT_CALLS_PER_CYCLE):
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "call_limit", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    if int(_to_float(cycle_state.get("bytes_used"), 0.0)) >= int(FMP_ENRICHMENT_CYCLE_SOFT_CAP_BYTES):
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "bandwidth_budget", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    fmp_key = _extract_fmp_key()
    endpoint_url = _fmp_build_endpoint_url(endpoint, sym, fmp_key)
    if not endpoint_url:
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "unsupported_endpoint", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    if not get_call_permission("FMP", cost=1):
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 429,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "call_limit",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": False,
            }
        )
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        return {"ok": False, "blocked_reason": "call_limit", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}
    try:
        record_call("FMP", cost=1)
        resp = requests.get(endpoint_url, timeout=5.0)
        status = int(resp.status_code)
        body_bytes = len((resp.text or "").encode("utf-8", errors="ignore"))
        cycle_state["calls_made"] = int(_to_float(cycle_state.get("calls_made"), 0.0)) + 1
        cycle_state["bytes_used"] = int(_to_float(cycle_state.get("bytes_used"), 0.0)) + int(max(0, body_bytes))
        if status >= 400:
            record_error("FMP")
            if status in {401, 403, 429}:
                record_rate_limit("FMP", status)
            _fmp_efficiency_record_event(
                {
                    "endpoint_family": family,
                    "endpoint_path_template": path_template,
                    "symbol_count": 1,
                    "status_code": status,
                    "ok": False,
                    "cache_hit": False,
                    "bytes_estimated": int(max(0, body_bytes)),
                    "bytes_actual_if_available": int(max(0, body_bytes)),
                    "useful_fields_count": 0,
                    "useful_score": 0.0,
                    "call_reason": str(call_reason or "candidate_enrichment"),
                    "caller_context": "top_buys_fmp_enrichment_v1",
                    "ttl_seconds": int(ttl_seconds),
                    "blocked_reason": f"http_{status}",
                    "api_calls_delta": 1,
                    "bandwidth_delta": int(max(0, body_bytes)),
                    "provider_governor_allowed": True,
                }
            )
            return {"ok": False, "blocked_reason": f"http_{status}", "data": {}, "cache_hit": False, "bytes": int(max(0, body_bytes)), "fields_used": []}
        parsed = resp.json()
        rows = parsed if isinstance(parsed, list) else parsed.get("_list", parsed) if isinstance(parsed, dict) else []
        data_obj = {}
        if isinstance(rows, list) and rows:
            data_obj = dict(rows[0] or {})
        elif isinstance(rows, dict):
            data_obj = dict(rows)
        fields_used = [str(k) for k, v in data_obj.items() if v not in (None, "", 0, 0.0)]
        useful_fields = int(len(fields_used))
        useful_score = float(min(100.0, useful_fields * 8.0))
        _fmp_enrichment_cache_set(endpoint, sym, data_obj, body_bytes)
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": status,
                "ok": True,
                "cache_hit": False,
                "bytes_estimated": int(max(0, body_bytes)),
                "bytes_actual_if_available": int(max(0, body_bytes)),
                "useful_fields_count": useful_fields,
                "useful_score": useful_score,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "",
                "api_calls_delta": 1,
                "bandwidth_delta": int(max(0, body_bytes)),
                "provider_governor_allowed": True,
            }
        )
        return {"ok": True, "blocked_reason": "", "data": data_obj, "cache_hit": False, "bytes": int(max(0, body_bytes)), "fields_used": fields_used}
    except Exception:
        record_error("FMP")
        cycle_state["blocked"] = int(_to_float(cycle_state.get("blocked"), 0.0)) + 1
        _fmp_efficiency_record_event(
            {
                "endpoint_family": family,
                "endpoint_path_template": path_template,
                "symbol_count": 1,
                "status_code": 0,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": str(call_reason or "candidate_enrichment"),
                "caller_context": "top_buys_fmp_enrichment_v1",
                "ttl_seconds": int(ttl_seconds),
                "blocked_reason": "request_exception",
                "api_calls_delta": 1,
                "bandwidth_delta": 0,
                "provider_governor_allowed": True,
            }
        )
        return {"ok": False, "blocked_reason": "request_exception", "data": {}, "cache_hit": False, "bytes": 0, "fields_used": []}


def _apply_controlled_fmp_enrichment_v1(payload):
    out = dict(payload or {})
    stocks = dict(out.get("stocks") or {})
    crypto = dict(out.get("crypto") or {})
    final_rows = list(stocks.get("final") or []) + list(crypto.get("final") or [])
    cycle_state = {
        "calls_made": 0,
        "bytes_used": 0,
        "cache_hits": 0,
        "cache_misses": 0,
        "blocked": 0,
    }
    seen = set()
    candidates = []
    for r in final_rows:
        if not isinstance(r, dict):
            continue
        sym = str(r.get("symbol") or "").upper().strip()
        if not sym or sym in seen:
            continue
        seen.add(sym)
        candidates.append(sym)
    candidates = candidates[: int(MAX_FMP_ENRICHMENT_SYMBOLS_PER_CYCLE)]
    by_symbol_enrichment = {}
    for sym in candidates:
        quote_enrich = _fmp_small_endpoint_request("quote", sym, cycle_state, "candidate_enrichment_quote")
        profile_enrich = _fmp_small_endpoint_request("profile", sym, cycle_state, "candidate_enrichment_profile")
        by_symbol_enrichment[sym] = {"quote": quote_enrich, "profile": profile_enrich}
    def _apply_row(row):
        r = dict(row or {})
        sym = str(r.get("symbol") or "").upper().strip()
        enrich = dict(by_symbol_enrichment.get(sym) or {})
        q = dict(enrich.get("quote") or {})
        p = dict(enrich.get("profile") or {})
        fields_used = list(dict.fromkeys(list(q.get("fields_used") or []) + list(p.get("fields_used") or [])))
        cache_hit = bool(q.get("cache_hit", False) or p.get("cache_hit", False))
        bytes_est = int(_to_float(q.get("bytes"), 0.0) + _to_float(p.get("bytes"), 0.0))
        used = bool(q.get("ok", False) or p.get("ok", False) or cache_hit)
        blocked_reason = str(q.get("blocked_reason") or p.get("blocked_reason") or "")
        src_parts = []
        if q:
            src_parts.append("quote")
        if p:
            src_parts.append("profile")
        r["fmp_enriched"] = bool(used)
        r["fmp_enrichment_source"] = "+".join(src_parts) if src_parts else "none"
        r["fmp_enrichment_cache_hit"] = bool(cache_hit)
        r["fmp_enrichment_fields_used"] = fields_used[:20]
        r["fmp_enrichment_byte_estimate"] = int(max(0, bytes_est))
        r["fmp_enrichment_reason"] = str("candidate_context_enrichment" if used else (blocked_reason or "not_enriched"))
        return r
    stocks["final"] = [_apply_row(r) for r in list(stocks.get("final") or [])]
    crypto["final"] = [_apply_row(r) for r in list(crypto.get("final") or [])]
    out["stocks"] = stocks
    out["crypto"] = crypto
    out["fmp_controlled_enrichment_v1"] = {
        "enabled": True,
        "max_fmp_enrichment_symbols_per_cycle": int(MAX_FMP_ENRICHMENT_SYMBOLS_PER_CYCLE),
        "max_fmp_enrichment_calls_per_cycle": int(MAX_FMP_ENRICHMENT_CALLS_PER_CYCLE),
        "profile_ttl_seconds": int(FMP_ENRICHMENT_PROFILE_TTL_SECONDS),
        "quote_ttl_seconds": int(FMP_ENRICHMENT_QUOTE_TTL_SECONDS),
        "daily_soft_cap_bytes": int(FMP_ENRICHMENT_DAILY_SOFT_CAP_BYTES),
        "cycle_soft_cap_bytes": int(FMP_ENRICHMENT_CYCLE_SOFT_CAP_BYTES),
        "symbols_considered": list(candidates),
        "calls_made": int(_to_float(cycle_state.get("calls_made"), 0.0)),
        "bytes_used": int(_to_float(cycle_state.get("bytes_used"), 0.0)),
        "cache_hits": int(_to_float(cycle_state.get("cache_hits"), 0.0)),
        "cache_misses": int(_to_float(cycle_state.get("cache_misses"), 0.0)),
        "blocked": int(_to_float(cycle_state.get("blocked"), 0.0)),
    }
    return out


def _fmp_supported_endpoint_map():
    return {
        "profile": {"path": "/stable/profile", "query": ["symbol", "apikey"]},
        "quote": {"path": "/stable/quote", "query": ["symbol", "apikey"]},
        "quote_short": {"path": "/stable/quote", "query": ["symbol", "apikey"]},
    }


def _fmp_build_endpoint_url(endpoint_key, symbol, api_key):
    s = str(symbol or "").upper().strip()
    k = str(api_key or "").strip()
    m = _fmp_supported_endpoint_map()
    ep = dict(m.get(str(endpoint_key or "").strip().lower()) or {})
    p = str(ep.get("path") or "").strip()
    if not p or not s or not k:
        return ""
    if p in {"/stable/profile", "/stable/quote"}:
        return f"https://financialmodelingprep.com{p}?symbol={s}&apikey={k}"
    # Conservative default: block non-small endpoints unless explicitly allowlisted.
    if str(os.getenv("ASTRA_FMP_LARGE_ENDPOINTS_ALLOW", "0")).strip().lower() not in {"1", "true", "yes", "on"}:
        _fmp_efficiency_record_event(
            {
                "endpoint_family": "blocked_large_family",
                "endpoint_path_template": str(p or ""),
                "symbol_count": 1,
                "status_code": 0,
                "ok": False,
                "cache_hit": False,
                "bytes_estimated": 0,
                "bytes_actual_if_available": 0,
                "useful_fields_count": 0,
                "useful_score": 0.0,
                "call_reason": "endpoint_build",
                "caller_context": "fmp_url_builder",
                "ttl_seconds": 0,
                "blocked_reason": "policy_blocked_large_endpoint",
                "api_calls_delta": 0,
                "bandwidth_delta": 0,
                "provider_governor_allowed": False,
            }
        )
        return ""
    return ""


def _fmp_endpoint_compatibility_snapshot():
    files = [
        os.path.join(os.getcwd(), "server_extend.py"),
        os.path.join(os.getcwd(), "engine", "provider_router.py"),
        os.path.join(os.getcwd(), "engine", "ranking_engine.py"),
    ]
    legacy_hits = []
    legacy_tokens = [
        "/api/v3/",
        "quote-short",
        "historical-price-full",
        "stock/list",
        "stock-screener",
        "earning_calendar",
        "historical-chart",
    ]
    for fp in files:
        try:
            with open(fp, "r") as f:
                txt = str(f.read() or "")
            for tok in legacy_tokens:
                if tok in txt:
                    legacy_hits.append({"file": fp, "token": tok})
        except Exception:
            continue
    return {
        "fmp_endpoint_mode": "stable",
        "fmp_legacy_endpoints_detected_count": int(len(legacy_hits)),
        "fmp_legacy_endpoints_blocked": bool(len(legacy_hits) > 0),
        "fmp_supported_endpoint_map": _fmp_supported_endpoint_map(),
    }


def _fmp_rest_activation_gate(usage_summary, hard_stop_active, emergency_stop_active, daily_remaining_gb):
    conservative = bool(FMP_CONSERVATIVE_MODE)
    smart_budget_enabled = str(os.getenv("ASTRA_FMP_SMART_BUDGET_ENABLED", "1")).strip().lower() in {"1", "true", "yes", "on"}
    env_disable_explicit = "ASTRA_TEMP_FMP_REST_DISABLED" in os.environ
    env_disabled = bool(
        str(os.getenv("ASTRA_TEMP_FMP_REST_DISABLED", "0" if smart_budget_enabled else "1")).strip().lower()
        in {"1", "true", "yes", "on"}
    )
    usage_disabled = bool((usage_summary or {}).get("fmp_rest_temporarily_disabled", False))
    budget_ok = bool(_to_float(daily_remaining_gb, 0.0) > 0.0)
    activation_allowed = bool(
        conservative
        and smart_budget_enabled
        and not (env_disable_explicit and env_disabled)
        and not bool(hard_stop_active)
        and not bool(emergency_stop_active)
        and budget_ok
        and bool(FMP_CACHE_ENABLED)
    )
    if activation_allowed:
        reason = "activation_allowed_conservative_governed_cached"
    elif env_disable_explicit and env_disabled:
        reason = "blocked_explicit_emergency_conserve_mode"
    elif not bool(smart_budget_enabled):
        reason = "blocked_smart_budget_disabled"
    elif not conservative:
        reason = "blocked_non_conservative_mode"
    elif bool(emergency_stop_active):
        reason = "blocked_emergency_stop"
    elif bool(hard_stop_active):
        reason = "blocked_hard_stop_or_daily_budget"
    elif not budget_ok:
        reason = "blocked_no_daily_budget_remaining"
    elif not bool(FMP_CACHE_ENABLED):
        reason = "blocked_cache_required"
    elif usage_disabled and not smart_budget_enabled:
        reason = "blocked_temp_disabled"
    else:
        reason = "blocked_unknown"
    return {
        "activation_allowed": bool(activation_allowed),
        "activation_reason": str(reason),
        "env_temp_disabled": bool(env_disabled),
        "env_temp_disabled_explicit": bool(env_disable_explicit),
        "usage_temp_disabled": bool(usage_disabled),
        "fmp_smart_budget_enabled": bool(smart_budget_enabled),
        "fmp_refresh_allowed_now": bool(activation_allowed),
        "fmp_refresh_block_reason": "none" if activation_allowed else str(reason),
    }


def _extract_fmp_key():
    try:
        for provider_name, provider_key in list(API_POOLS.get("stocks") or []):
            if str(provider_name or "").upper().strip() == "FMP" and str(provider_key or "").strip():
                return str(provider_key).strip()
    except Exception:
        pass
    return ""


def _fmp_rest_controlled_test(symbol="AAPL", purpose="profile_context", force=False):
    out = {
        "fmp_rest_live_test_available": False,
        "fmp_rest_last_test_ok": False,
        "fmp_rest_last_test_error": "",
        "fmp_rest_last_test_bytes": 0,
        "fmp_rest_last_test_endpoint": "",
        "fmp_rest_last_test_symbol": str(symbol or "AAPL").upper().strip(),
        "fmp_rest_last_test_cached": False,
        "fmp_rest_last_test_timestamp_utc": "",
        "fmp_rest_last_test_status_code": 0,
    }
    test_symbol = out["fmp_rest_last_test_symbol"] or "AAPL"
    cache_key = f"fmp_rest_test_v1:{purpose}:{test_symbol}"
    try:
        # If cache exists and caller did not force, do not spend any call budget.
        if not bool(force):
            cached_all = _read_json_file(FMP_REST_TEST_STATE_PATH, default={})
            cached = dict(cached_all.get(cache_key) or {}) if isinstance(cached_all, dict) else {}
            if cached:
                _fmp_efficiency_record_event(
                    {
                        "endpoint_family": "quote_profile",
                        "endpoint_path_template": "/stable/profile?symbol={symbol}",
                        "symbol_count": 1,
                        "status_code": int(_to_float(cached.get("status_code"), 0.0)),
                        "ok": bool(cached.get("ok", True)),
                        "cache_hit": True,
                        "bytes_estimated": int(_to_float(cached.get("bytes"), 0.0)),
                        "bytes_actual_if_available": int(_to_float(cached.get("bytes"), 0.0)),
                        "useful_fields_count": 6,
                        "useful_score": 60.0 if bool(cached.get("ok", True)) else 0.0,
                        "call_reason": str(purpose or "profile_context"),
                        "caller_context": "fmp_rest_controlled_test",
                        "ttl_seconds": 3600,
                        "blocked_reason": "",
                        "api_calls_delta": 0,
                        "bandwidth_delta": 0,
                        "provider_governor_allowed": True,
                    }
                )
                out["fmp_rest_live_test_available"] = True
                out["fmp_rest_last_test_ok"] = bool(cached.get("ok", True))
                out["fmp_rest_last_test_error"] = str(cached.get("error") or "")
                out["fmp_rest_last_test_status_code"] = int(_to_float(cached.get("status_code"), 0.0))
                out["fmp_rest_last_test_bytes"] = int(_to_float(cached.get("bytes"), 0.0))
                out["fmp_rest_last_test_endpoint"] = str(cached.get("endpoint") or "")
                out["fmp_rest_last_test_cached"] = True
                out["fmp_rest_last_test_timestamp_utc"] = str(cached.get("ts_utc") or "")
                return out
        fmp_key = _extract_fmp_key()
        if not fmp_key:
            out["fmp_rest_last_test_error"] = "missing_fmp_api_key"
            return out
        out["fmp_rest_live_test_available"] = True
        endpoint = _fmp_build_endpoint_url("profile", test_symbol, fmp_key)
        out["fmp_rest_last_test_endpoint"] = "/stable/profile?symbol={symbol}"
        if not endpoint:
            out["fmp_rest_last_test_error"] = "unsupported_or_invalid_endpoint_mapping"
            _fmp_efficiency_record_event(
                {
                    "endpoint_family": "quote_profile",
                    "endpoint_path_template": "/stable/profile?symbol={symbol}",
                    "symbol_count": 1,
                    "status_code": 0,
                    "ok": False,
                    "cache_hit": False,
                    "bytes_estimated": 0,
                    "bytes_actual_if_available": 0,
                    "useful_fields_count": 0,
                    "useful_score": 0.0,
                    "call_reason": str(purpose or "profile_context"),
                    "caller_context": "fmp_rest_controlled_test",
                    "ttl_seconds": 0,
                    "blocked_reason": "policy_blocked_large_endpoint",
                    "api_calls_delta": 0,
                    "bandwidth_delta": 0,
                    "provider_governor_allowed": False,
                }
            )
            return out
        if not get_call_permission("FMP", cost=1):
            out["fmp_rest_last_test_error"] = "governor_or_provider_cap_blocked"
            _fmp_efficiency_record_event(
                {
                    "endpoint_family": "quote_profile",
                    "endpoint_path_template": "/stable/profile?symbol={symbol}",
                    "symbol_count": 1,
                    "status_code": 429,
                    "ok": False,
                    "cache_hit": False,
                    "bytes_estimated": 0,
                    "bytes_actual_if_available": 0,
                    "useful_fields_count": 0,
                    "useful_score": 0.0,
                    "call_reason": str(purpose or "profile_context"),
                    "caller_context": "fmp_rest_controlled_test",
                    "ttl_seconds": 0,
                    "blocked_reason": "call_limit",
                    "api_calls_delta": 0,
                    "bandwidth_delta": 0,
                    "provider_governor_allowed": False,
                }
            )
            return out
        try:
            # Count outbound attempt once permission is granted; avoid repeated retries via cached state.
            record_call("FMP", cost=1)
            resp = requests.get(endpoint, timeout=6)
            body = resp.text if isinstance(resp.text, str) else ""
            bytes_used = len(body.encode("utf-8", errors="ignore")) if body else 0
            out["fmp_rest_last_test_status_code"] = int(resp.status_code)
            if int(resp.status_code) >= 400:
                out["fmp_rest_last_test_error"] = f"http_{int(resp.status_code)}"
                out["fmp_rest_last_test_timestamp_utc"] = _now_utc_iso()
                record_error("FMP")
                if int(resp.status_code) in {401, 403, 429}:
                    record_rate_limit("FMP", int(resp.status_code))
                cache_payload = _read_json_file(FMP_REST_TEST_STATE_PATH, default={})
                if not isinstance(cache_payload, dict):
                    cache_payload = {}
                cache_payload[cache_key] = {
                    "ok": False,
                    "error": out["fmp_rest_last_test_error"],
                    "status_code": int(resp.status_code),
                    "bytes": int(bytes_used),
                    "endpoint": out["fmp_rest_last_test_endpoint"],
                    "symbol": test_symbol,
                    "ts_utc": out["fmp_rest_last_test_timestamp_utc"],
                }
                _write_json_file_safely(FMP_REST_TEST_STATE_PATH, cache_payload)
                _fmp_efficiency_record_event(
                    {
                        "endpoint_family": "quote_profile",
                        "endpoint_path_template": "/stable/profile?symbol={symbol}",
                        "symbol_count": 1,
                        "status_code": int(resp.status_code),
                        "ok": False,
                        "cache_hit": False,
                        "bytes_estimated": int(bytes_used),
                        "bytes_actual_if_available": int(bytes_used),
                        "useful_fields_count": 0,
                        "useful_score": 0.0,
                        "call_reason": str(purpose or "profile_context"),
                        "caller_context": "fmp_rest_controlled_test",
                        "ttl_seconds": 0,
                        "blocked_reason": str(out.get("fmp_rest_last_test_error") or ""),
                        "api_calls_delta": 1,
                        "bandwidth_delta": int(bytes_used),
                        "provider_governor_allowed": True,
                    }
                )
                return out
            out["fmp_rest_last_test_ok"] = True
            out["fmp_rest_last_test_bytes"] = int(bytes_used)
            out["fmp_rest_last_test_timestamp_utc"] = _now_utc_iso()
            cache_payload = _read_json_file(FMP_REST_TEST_STATE_PATH, default={})
            if not isinstance(cache_payload, dict):
                cache_payload = {}
            cache_payload[cache_key] = {
                "ok": True,
                "status_code": int(resp.status_code),
                "bytes": int(bytes_used),
                "endpoint": out["fmp_rest_last_test_endpoint"],
                "symbol": test_symbol,
                "ts_utc": out["fmp_rest_last_test_timestamp_utc"],
            }
            _write_json_file_safely(FMP_REST_TEST_STATE_PATH, cache_payload)
            _fmp_efficiency_record_event(
                {
                    "endpoint_family": "quote_profile",
                    "endpoint_path_template": "/stable/profile?symbol={symbol}",
                    "symbol_count": 1,
                    "status_code": int(resp.status_code),
                    "ok": True,
                    "cache_hit": False,
                    "bytes_estimated": int(bytes_used),
                    "bytes_actual_if_available": int(bytes_used),
                    "useful_fields_count": 6,
                    "useful_score": 60.0,
                    "call_reason": str(purpose or "profile_context"),
                    "caller_context": "fmp_rest_controlled_test",
                    "ttl_seconds": 3600,
                    "blocked_reason": "",
                    "api_calls_delta": 1,
                    "bandwidth_delta": int(bytes_used),
                    "provider_governor_allowed": True,
                }
            )
            return out
        except Exception as e:
            out["fmp_rest_last_test_error"] = str(e)[:220]
            record_error("FMP")
            _fmp_efficiency_record_event(
                {
                    "endpoint_family": "quote_profile",
                    "endpoint_path_template": "/stable/profile?symbol={symbol}",
                    "symbol_count": 1,
                    "status_code": 0,
                    "ok": False,
                    "cache_hit": False,
                    "bytes_estimated": 0,
                    "bytes_actual_if_available": 0,
                    "useful_fields_count": 0,
                    "useful_score": 0.0,
                    "call_reason": str(purpose or "profile_context"),
                    "caller_context": "fmp_rest_controlled_test",
                    "ttl_seconds": 0,
                    "blocked_reason": "request_exception",
                    "api_calls_delta": 1,
                    "bandwidth_delta": 0,
                    "provider_governor_allowed": True,
                }
            )
            return out
    except Exception as e:
        out["fmp_rest_last_test_error"] = str(e)[:220]
        return out


def _is_likely_non_iex_symbol(symbol, context=None):
    s = str(symbol or "").upper().strip()
    ctx = dict(context or {})
    if bool(ctx.get("non_iex")):
        return True
    exchange = str(ctx.get("exchange") or ctx.get("primary_exchange") or "").upper().strip()
    if exchange and exchange not in {"IEX", "NYSE", "NASDAQ", "ARCA", "AMEX"}:
        return True
    if any(tok in s for tok in (":", "/", ".")):
        return True
    return False


def _choose_provider_for_symbol(symbol, purpose, tier, context=None):
    s = str(symbol or "").upper().strip()
    p = str(purpose or "unknown").strip().lower()
    t = str(tier or "tier2_watchlist").strip().lower()
    ctx = dict(context or {})
    valid_quote = bool(ctx.get("valid_quote", True))
    trusted_quote = bool(ctx.get("trusted_quote_for_buys", True))
    fmp_ws_enabled = str(os.getenv("ASTRA_FMP_WS_ENABLED", "0")).strip().lower() in {"1", "true", "yes", "on"}
    fmp_ws_available = bool(fmp_ws_enabled)  # websocket engine not integrated here beyond config gate
    non_iex = _is_likely_non_iex_symbol(s, ctx)

    governor = dict(ctx.get("_governor_snapshot") or {})
    if not governor:
        governor = dict(_fmp_usage_governor_snapshot(update=False) or {})
    governor_allowed = bool(governor.get("fmp_rest_governor_allowed", governor.get("fmp_enabled", False)))
    fmp_rest_disabled = bool(governor.get("fmp_rest_temporarily_disabled", True))
    cache_required = True
    refresh_allowed = False
    websocket_allowed = False
    coverage_quality = "good"
    estimated_cost_class = "low"
    reason = "default_conservative_routing"
    primary = "ALPACA"
    fallback = "FINNHUB"

    if p in {"broad_discovery", "universe_refresh", "daily_history", "fundamentals", "earnings_calendar", "sector_context", "news_context"}:
        primary = "FMP"
        fallback = "FINNHUB"
        reason = "fmp_cached_context_discovery"
        coverage_quality = "context"
        estimated_cost_class = "medium"
        refresh_allowed = bool(governor_allowed and not fmp_rest_disabled and t in {"tier3_discovery", "tier4_archive"})
        websocket_allowed = False
    elif p in {"live_monitor", "sell_monitor", "live_quote"}:
        if non_iex:
            coverage_quality = "limited_alpaca_coverage"
            if fmp_ws_available and governor_allowed:
                primary = "FMP_WS"
                fallback = "ALPACA"
                reason = "non_iex_prefers_fmp_ws"
                websocket_allowed = True
            else:
                primary = "ALPACA"
                fallback = "FMP" if governor_allowed else "FINNHUB"
                reason = "non_iex_fmp_ws_unavailable_controlled_fallback"
                websocket_allowed = False
                refresh_allowed = bool(governor_allowed and not fmp_rest_disabled)
        else:
            primary = "ALPACA_WS"
            fallback = "ALPACA"
            reason = "iex_or_us_live_monitor_prefers_alpaca_ws"
            websocket_allowed = True
            coverage_quality = "good"
    elif p in {"intraday_history"}:
        primary = "ALPACA"
        fallback = "FMP" if governor_allowed else "FINNHUB"
        reason = "intraday_history_alpaca_first_fmp_cached_fallback"
        refresh_allowed = bool(governor_allowed and not fmp_rest_disabled and t in {"tier1_active", "tier2_watchlist"})
        estimated_cost_class = "low"
    elif p in {"crypto_quote"}:
        primary = "MORALIS"
        fallback = "ALPACA"
        reason = "crypto_quote_non_fmp_primary"
        coverage_quality = "crypto"
    elif p in {"dashboard_refresh"}:
        primary = "CACHE_ONLY"
        fallback = "ALPACA"
        reason = "dashboard_cache_only_no_fmp"
        cache_required = True
        refresh_allowed = False
        websocket_allowed = False
        estimated_cost_class = "none"

    if not valid_quote or not trusted_quote:
        coverage_quality = "degraded"
    return {
        "symbol": s,
        "purpose": p,
        "tier": t,
        "primary_provider": primary,
        "fallback_provider": fallback,
        "reason": reason,
        "coverage_quality": coverage_quality,
        "cache_required": bool(cache_required),
        "refresh_allowed": bool(refresh_allowed),
        "websocket_allowed": bool(websocket_allowed),
        "governor_allowed": bool(governor_allowed),
        "estimated_cost_class": estimated_cost_class,
        "fmp_rest_governor_allowed": bool(governor_allowed and not fmp_rest_disabled),
        "non_iex_symbol": bool(non_iex),
        "fmp_ws_available": bool(fmp_ws_available),
    }


def _provider_decision_summary_snapshot(governor_snapshot=None):
    base_ctx = {"_governor_snapshot": dict(governor_snapshot or {})}
    cases = [
        _choose_provider_for_symbol("AAPL", "live_monitor", "tier1_active", dict(base_ctx, exchange="NASDAQ", non_iex=False)),
        _choose_provider_for_symbol("BABA", "live_monitor", "tier1_active", dict(base_ctx, exchange="HKEX", non_iex=True)),
        _choose_provider_for_symbol("MSFT", "fundamentals", "tier2_watchlist", dict(base_ctx, exchange="NASDAQ")),
        _choose_provider_for_symbol("TSLA", "broad_discovery", "tier3_discovery", dict(base_ctx, exchange="NASDAQ")),
        _choose_provider_for_symbol("SPY", "dashboard_refresh", "tier2_watchlist", dict(base_ctx, exchange="ARCA")),
    ]
    return {
        "iex_live_monitor_case": cases[0],
        "non_iex_live_monitor_case": cases[1],
        "fundamentals_case": cases[2],
        "discovery_case": cases[3],
        "dashboard_case": cases[4],
    }


def _tier_symbol_counts_snapshot():
    snap = _latest_top_buys_runtime_snapshot()
    if not isinstance(snap, dict):
        return {"tier1_active": 0, "tier2_watchlist": 0, "tier3_discovery": 0, "tier4_archive": 0}
    stocks = dict(snap.get("stocks") or {})
    crypto = dict(snap.get("crypto") or {})
    final_count = int(len(list(stocks.get("final") or [])) + len(list(crypto.get("final") or [])))
    watchlist_count = int(len(list(stocks.get("watchlist") or [])) + len(list(crypto.get("watchlist") or [])))
    discovery_hint = int(
        _to_float((snap.get("candidate_pipeline_trace_v1") or {}).get("stage_0_symbols_input"), 0.0)
    )
    return {
        "tier1_active": int(min(30, final_count)),
        "tier2_watchlist": int(min(150, watchlist_count)),
        "tier3_discovery": int(max(0, discovery_hint)),
        "tier4_archive": 0,
    }


def _provider_overlap_snapshot(governor_snapshot=None):
    snap = _latest_top_buys_runtime_snapshot()
    rows = []
    if isinstance(snap, dict):
        rows.extend(list(((snap.get("stocks") or {}).get("final") or [])))
        rows.extend(list(((snap.get("crypto") or {}).get("final") or [])))
    seen = set()
    dup = 0
    non_iex_to_fmp_or_fb = 0
    for r in rows:
        if not isinstance(r, dict):
            continue
        sym = str(r.get("symbol") or "").upper().strip()
        if not sym:
            continue
        if sym in seen:
            dup += 1
        seen.add(sym)
        choose = _choose_provider_for_symbol(
            sym,
            "live_monitor",
            "tier1_active",
            {
                "exchange": r.get("primary_exchange") or r.get("exchange"),
                "non_iex": _is_likely_non_iex_symbol(sym, r),
                "_governor_snapshot": dict(governor_snapshot or {}),
            },
        )
        if bool(choose.get("non_iex_symbol")) and str(choose.get("primary_provider")) in {"FMP_WS", "ALPACA"}:
            non_iex_to_fmp_or_fb += 1
    return {
        "non_iex_symbols_routed_to_fmp_or_fallback": int(non_iex_to_fmp_or_fb),
        "duplicate_symbol_calls_prevented": int(dup),
    }


def _fmp_usage_governor_snapshot(update=False):
    with _FMP_GOVERNOR_LOCK:
        now_iso = _now_utc_iso()
        today_key = _today_utc_key()
        state = _read_json_file(FMP_USAGE_STATE_PATH, default={})
        if not isinstance(state, dict) or not state:
            state = _fmp_governor_default_state()
        if str(state.get("date_utc") or "") != today_key:
            prev_total = int(_to_float(state.get("fmp_estimated_used_total_bytes"), 0.0))
            state = _fmp_governor_default_state()
            state["fmp_estimated_used_total_bytes"] = max(0, prev_total)
            state["fmp_estimated_used_total_gb"] = round(float(prev_total) / (1024.0 ** 3), 6)
            state["date_utc"] = today_key

        provider_rows = list(get_provider_status_summary() or [])
        provider_map = {}
        for row in provider_rows:
            p = str((row or {}).get("provider") or "").upper().strip()
            if p:
                provider_map[p] = dict(row or {})
        fmp_row = dict(provider_map.get("FMP") or {})
        alpaca_row = dict(provider_map.get("ALPACA") or {})
        fallback_calls_total = int(
            _to_float((provider_map.get("FINNHUB") or {}).get("calls"), 0.0)
            + _to_float((provider_map.get("TWELVEDATA") or {}).get("calls"), 0.0)
            + _to_float((provider_map.get("POLYGON") or {}).get("calls"), 0.0)
            + _to_float((provider_map.get("ALPHAVANTAGE") or {}).get("calls"), 0.0)
            + _to_float((provider_map.get("EODHD") or {}).get("calls"), 0.0)
            + _to_float((provider_map.get("MORALIS") or {}).get("calls"), 0.0)
        )
        usage_summary = dict(get_usage_summary() or {})
        cache = dict(cache_metrics() or {})
        cache_hits = int(_to_float(cache.get("hits"), 0.0))
        cache_misses = int(_to_float(cache.get("misses"), 0.0))
        cache_sets = int(_to_float(cache.get("sets"), 0.0))
        cache_entries = int(_to_float(cache.get("entries"), 0.0))

        fmp_calls_total = int(_to_float(fmp_row.get("calls"), 0.0))
        alpaca_calls_total = int(_to_float(alpaca_row.get("calls"), 0.0))
        last_fmp_seen = int(_to_float(state.get("last_fmp_calls_total_seen"), 0.0))
        last_alpaca_seen = int(_to_float(state.get("last_alpaca_calls_total_seen"), 0.0))
        last_fallback_seen = int(_to_float(state.get("last_fallback_calls_total_seen"), 0.0))

        if update:
            fmp_delta = max(0, fmp_calls_total - last_fmp_seen)
            alpaca_delta = max(0, alpaca_calls_total - last_alpaca_seen)
            fallback_delta = max(0, fallback_calls_total - last_fallback_seen)
            if fmp_delta > 0:
                state["fmp_calls_today"] = int(_to_float(state.get("fmp_calls_today"), 0.0)) + int(fmp_delta)
                estimated_bytes = int(fmp_delta * 24576)  # conservative average payload estimate
                state["fmp_estimated_used_today_bytes"] = int(_to_float(state.get("fmp_estimated_used_today_bytes"), 0.0)) + estimated_bytes
                state["fmp_estimated_used_total_bytes"] = int(_to_float(state.get("fmp_estimated_used_total_bytes"), 0.0)) + estimated_bytes
            state["alpaca_rest_calls_today"] = int(_to_float(state.get("alpaca_rest_calls_today"), 0.0)) + int(alpaca_delta)
            state["fallback_provider_calls_today"] = int(_to_float(state.get("fallback_provider_calls_today"), 0.0)) + int(fallback_delta)
            if bool(usage_summary.get("fmp_rest_temporarily_disabled", False)):
                state["fmp_blocked_calls_today"] = int(_to_float(state.get("fmp_blocked_calls_today"), 0.0)) + int(fmp_delta)
            state["last_fmp_calls_total_seen"] = int(fmp_calls_total)
            state["last_alpaca_calls_total_seen"] = int(alpaca_calls_total)
            state["last_fallback_calls_total_seen"] = int(fallback_calls_total)

        state["cache_hits_seen"] = cache_hits
        state["cache_misses_seen"] = cache_misses
        state["cache_sets_seen"] = cache_sets
        state["cache_entries_seen"] = cache_entries
        state["fmp_cache_hit_rate"] = round(
            (float(cache_hits) / max(1.0, float(cache_hits + cache_misses))) * 100.0,
            2,
        )
        state["fmp_estimated_used_total_gb"] = round(
            float(int(_to_float(state.get("fmp_estimated_used_total_bytes"), 0.0))) / (1024.0 ** 3),
            6,
        )
        state["last_updated_utc"] = now_iso

        total_gb = _to_float(state.get("fmp_estimated_used_total_gb"), 0.0)
        used_today_gb = float(int(_to_float(state.get("fmp_estimated_used_today_bytes"), 0.0))) / (1024.0 ** 3)
        daily_remaining = max(0.0, float(FMP_DAILY_BUDGET_GB) - used_today_gb)
        warning_active = bool(total_gb >= FMP_WARNING_GB)
        hard_stop_active = bool(total_gb >= FMP_HARD_STOP_GB or used_today_gb >= FMP_DAILY_BUDGET_GB)
        emergency_stop_active = bool(total_gb >= FMP_EMERGENCY_STOP_GB)
        fmp_gate = _fmp_rest_activation_gate(
            usage_summary=usage_summary,
            hard_stop_active=hard_stop_active,
            emergency_stop_active=emergency_stop_active,
            daily_remaining_gb=daily_remaining,
        )
        fmp_governor_allowed = bool(fmp_gate.get("activation_allowed", False))
        fmp_temp_disabled = bool(not fmp_governor_allowed)
        # Lift temporary provider disable safely when conservative governor permits it.
        try:
            API_CALL_MANAGER._TEMP_FMP_REST_DISABLED = bool(not fmp_governor_allowed)
        except Exception:
            pass
        fmp_enabled = bool(fmp_governor_allowed)

        ws = dict(ALPACA_WS_MONITOR.status() or {})
        ranking_meta = dict(get_ranking_snapshot_meta() or {})
        provider_priority_map = {
            "tier1_active": ["ALPACA_WS", "ALPACA", "FINNHUB", "TWELVEDATA", "POLYGON", "FMP(cache_context_only)"],
            "tier2_watchlist": ["ALPACA", "FINNHUB", "TWELVEDATA", "POLYGON", "FMP(cached_intraday_history)"],
            "tier3_discovery": ["ALPACA", "FINNHUB", "TWELVEDATA", "FMP(cached_daily_refresh)"],
            "tier4_archive": ["FMP(cached_historical_batch)", "local_db_replay"],
        }
        routing_mode = "conservative_multi_api_cached_context"
        governor_seed = {
            "fmp_enabled": bool(fmp_enabled),
            "fmp_rest_temporarily_disabled": bool(fmp_temp_disabled),
            "fmp_rest_governor_allowed": bool(fmp_governor_allowed),
            "fmp_smart_budget_enabled": bool(fmp_gate.get("fmp_smart_budget_enabled", False)),
            "fmp_refresh_allowed_now": bool(fmp_gate.get("fmp_refresh_allowed_now", False)),
            "fmp_refresh_block_reason": str(fmp_gate.get("fmp_refresh_block_reason") or ""),
        }
        decision_summary = _provider_decision_summary_snapshot(governor_snapshot=governor_seed)
        tier_counts = _tier_symbol_counts_snapshot()
        overlap = _provider_overlap_snapshot(governor_snapshot=governor_seed)

        fmp_cache_index = _read_json_file(FMP_CACHE_INDEX_PATH, default={})
        if not isinstance(fmp_cache_index, dict):
            fmp_cache_index = {}
        fmp_cache_index.update(
            {
                "last_updated_utc": now_iso,
                "cache_enabled": bool(FMP_CACHE_ENABLED),
                "no_repeat_calls": bool(FMP_NO_REPEAT_CALLS),
                "entries_estimate": int(cache_entries),
                "cache_hits_seen": int(cache_hits),
                "cache_misses_seen": int(cache_misses),
                "cache_sets_seen": int(cache_sets),
                "ttl_policy": {
                    "quote_live_like_seconds": "60-180",
                    "intraday_minutes": "15-30",
                    "daily_history_hours": "12-24",
                    "fundamentals_profile_hours": "24-168",
                    "earnings_calendar_hours": "12-24",
                    "symbol_lists_hours": "12-24",
                },
            }
        )

        governor_payload = {
            "generated_at_utc": now_iso,
            "fmp_enabled": bool(fmp_enabled),
            "fmp_conservative_mode": bool(FMP_CONSERVATIVE_MODE),
            "fmp_daily_budget_gb": float(FMP_DAILY_BUDGET_GB),
            "fmp_estimated_used_today_gb": round(used_today_gb, 6),
            "fmp_estimated_remaining_today_gb": round(daily_remaining, 6),
            "fmp_warning_active": bool(warning_active),
            "fmp_hard_stop_active": bool(hard_stop_active),
            "fmp_emergency_stop_active": bool(emergency_stop_active),
            "fmp_cache_hit_rate": round(_to_float(state.get("fmp_cache_hit_rate"), 0.0), 2),
            "fmp_calls_today": int(_to_float(state.get("fmp_calls_today"), 0.0)),
            "fmp_blocked_calls_today": int(_to_float(state.get("fmp_blocked_calls_today"), 0.0)),
            "fmp_smart_budget_enabled": bool(fmp_gate.get("fmp_smart_budget_enabled", False)),
            "fmp_rest_conserve_mode": bool(fmp_temp_disabled),
            "fmp_refresh_allowed_now": bool(fmp_gate.get("fmp_refresh_allowed_now", False)),
            "fmp_refresh_block_reason": str(fmp_gate.get("fmp_refresh_block_reason") or ""),
            "alpaca_ws_active": bool(ws.get("running", False)),
            "alpaca_ws_symbols": int(_to_float(ws.get("active_symbol_count"), 0.0)),
            "alpaca_rest_calls_today": int(_to_float(state.get("alpaca_rest_calls_today"), 0.0)),
            "fallback_provider_calls_today": int(_to_float(state.get("fallback_provider_calls_today"), 0.0)),
            "provider_priority_map": provider_priority_map,
            "data_routing_mode": routing_mode,
            "fmp_cache_enabled": bool(FMP_CACHE_ENABLED),
            "fmp_no_repeat_calls": bool(FMP_NO_REPEAT_CALLS),
            "fmp_operating_mode": str(ranking_meta.get("fmp_operating_mode") or os.getenv("ASTRA_FMP_MODE", "conserve")),
            "fmp_rest_temporarily_disabled": bool(fmp_temp_disabled),
            "fmp_rest_enabled": bool(not fmp_temp_disabled),
            "fmp_rest_governor_allowed": bool(fmp_governor_allowed),
            "fmp_rest_activation_allowed": bool(fmp_governor_allowed),
            "fmp_rest_activation_reason": str(fmp_gate.get("activation_reason") or ""),
            "fmp_rest_disable_explicit": bool(fmp_gate.get("env_temp_disabled_explicit", False)),
            "fmp_ws_available": bool(str(os.getenv("ASTRA_FMP_WS_ENABLED", "0")).strip().lower() in {"1", "true", "yes", "on"}),
            "fmp_ws_enabled": bool(str(os.getenv("ASTRA_FMP_WS_ENABLED", "0")).strip().lower() in {"1", "true", "yes", "on"}),
            "fmp_ws_active_symbols": 0,
            "fmp_ws_symbol_cap": int(FMP_WS_SYMBOL_CAP),
            "fmp_ws_reason": "not_implemented_or_not_configured"
            if not bool(str(os.getenv("ASTRA_FMP_WS_ENABLED", "0")).strip().lower() in {"1", "true", "yes", "on"})
            else "configured_but_not_integrated_in_router",
            "alpaca_ws_available": True,
            "alpaca_ws_active_symbols": int(_to_float(ws.get("active_symbol_count"), 0.0)),
            "alpaca_ws_symbol_cap": int(ALPACA_WS_SYMBOL_CAP),
            "provider_decision_summary": dict(decision_summary),
            "tier_symbol_counts": dict(tier_counts),
            "provider_health_summary": {
                "healthy_count": int(sum(1 for r in provider_rows if bool((r or {}).get("healthy", False))),
                ),
                "degraded_count": int(sum(1 for r in provider_rows if not bool((r or {}).get("healthy", False))),
                ),
                "providers_seen": int(len(provider_rows)),
            },
            "non_iex_symbols_routed_to_fmp_or_fallback": int(overlap.get("non_iex_symbols_routed_to_fmp_or_fallback", 0)),
            "duplicate_symbol_calls_prevented": int(overlap.get("duplicate_symbol_calls_prevented", 0)),
            "provider_rows": provider_rows,
        }

        _write_json_file_safely(FMP_USAGE_STATE_PATH, state)
        _write_json_file_safely(FMP_CACHE_INDEX_PATH, fmp_cache_index)
        _write_json_file_safely(API_USAGE_GOVERNOR_PATH, governor_payload)
        return governor_payload


def _runtime_integrity_status():
    default = {
        "runtime_integrity_ok": True,
        "failed_module_count": 0,
        "failed_modules": [],
        "last_integrity_check_utc": None,
    }
    try:
        payload = _read_json_file(os.path.join(STATE, "runtime_integrity_status.json"), default={})
        if not isinstance(payload, dict):
            return dict(default)
        out = dict(default)
        out["runtime_integrity_ok"] = bool(payload.get("runtime_integrity_ok", True))
        out["failed_module_count"] = int(_to_float(payload.get("failed_module_count"), 0.0))
        out["failed_modules"] = list(payload.get("failed_modules") or [])
        out["last_integrity_check_utc"] = payload.get("last_integrity_check_utc")
        return out
    except Exception:
        return dict(default)


def _pid_alive(pid):
    try:
        if not pid:
            return False
        os.kill(int(pid), 0)
        return True
    except Exception:
        return False


def _file_age_seconds(path):
    try:
        st = os.stat(path)
        return max(0.0, time.time() - float(st.st_mtime))
    except Exception:
        return None


def _tail_lines(path, limit=200):
    try:
        with open(path, "r") as f:
            lines = f.readlines()
        return [str(x).rstrip("\n") for x in lines[-int(limit):]]
    except Exception:
        return []


def _backend_watchdog_status_payload():
    pid_payload = _read_json_file(WATCHDOG_PID_PATH, {})
    pid = int(pid_payload.get("pid") or 0) if isinstance(pid_payload, dict) else 0
    if pid <= 0:
        try:
            raw = str(open(WATCHDOG_PID_PATH, "r").read().strip())
            pid = int(raw) if raw else 0
        except Exception:
            pid = 0
    pid_alive = bool(pid > 0 and _pid_alive(pid))
    hb_age = _file_age_seconds(WATCHDOG_HEARTBEAT_PATH)
    hb_fresh = bool(hb_age is not None and hb_age <= 30.0)
    uvicorn_pid_payload = _read_json_file(os.path.join(STATE, "uvicorn.pid"), {})
    uvicorn_pid = int(uvicorn_pid_payload.get("pid") or 0) if isinstance(uvicorn_pid_payload, dict) else 0
    if uvicorn_pid <= 0:
        try:
            raw = str(open(os.path.join(STATE, "uvicorn.pid"), "r").read().strip())
            uvicorn_pid = int(raw) if raw else 0
        except Exception:
            uvicorn_pid = 0
    uvicorn_alive = bool(uvicorn_pid > 0 and _pid_alive(uvicorn_pid))
    tail = _tail_lines(WATCHDOG_LOG_PATH, limit=120)
    restart_events_recent = len([ln for ln in tail if "restart" in ln.lower() or "uvicorn started" in ln.lower()])
    failure_events_recent = len(
        [
            ln
            for ln in tail
            if any(tok in ln.lower() for tok in ("health check failed", "unhealthy", "stale", "restarting", "connection limit"))
        ]
    )
    continuity_score = 100.0
    if not pid_alive:
        continuity_score -= 45.0
    if not uvicorn_alive:
        continuity_score -= 35.0
    if hb_age is None:
        continuity_score -= 10.0
    elif hb_age > 30.0:
        continuity_score -= min(25.0, (hb_age - 30.0) / 2.0)
    continuity_score -= min(20.0, failure_events_recent * 1.5)
    continuity_score += min(10.0, max(0.0, 8 - restart_events_recent))
    continuity_score = max(0.0, min(100.0, continuity_score))
    if continuity_score >= 80.0:
        mode = "healthy"
    elif continuity_score >= 55.0:
        mode = "caution"
    else:
        mode = "degraded"
    return {
        "watchdog_pid": pid if pid > 0 else None,
        "watchdog_running": pid_alive,
        "watchdog_heartbeat_age_seconds": round(hb_age, 2) if hb_age is not None else None,
        "watchdog_heartbeat_fresh": hb_fresh,
        "uvicorn_pid": uvicorn_pid if uvicorn_pid > 0 else None,
        "uvicorn_running": uvicorn_alive,
        "restart_events_recent": int(restart_events_recent),
        "failure_events_recent": int(failure_events_recent),
        "continuity_score": round(continuity_score, 2),
        "mode": mode,
    }


def _paper_worker_status_payload():
    try:
        PAPER_AUTOPILOT.refresh_enabled_from_state()
    except Exception:
        pass
    try:
        _paper_autopilot_sync_worker_artifacts()
    except Exception:
        pass
    hb = _read_json_file(PAPER_WORKER_HEARTBEAT_PATH, {})
    pid_payload = _read_json_file(PAPER_WORKER_PID_PATH, {})
    pid = int(pid_payload.get("pid") or hb.get("pid") or 0)
    running_strict_proc = bool(_pid_alive(pid))
    running_strict = bool(running_strict_proc)
    if running_strict:
        try:
            proc = subprocess.run(
                ["ps", "-p", str(int(pid)), "-o", "command="],
                capture_output=True,
                text=True,
                timeout=1.5,
            )
            cmd = str(proc.stdout or "").strip().lower()
            running_strict = "engine.paper_worker" in cmd or "paper_worker.py" in cmd
        except Exception:
            running_strict = False
    hb_updated = hb.get("updated_at")
    hb_fresh = False
    hb_age_seconds = None
    stale_after = 180
    if hb_updated:
        try:
            hb_dt = datetime.fromisoformat(str(hb_updated).replace("Z", "+00:00"))
            hb_age_seconds = max(0.0, (datetime.now(UTC) - hb_dt).total_seconds())
            interval = int(hb.get("interval_seconds") or 45)
            stale_after = max(180, interval * 4)
            hb_fresh = hb_age_seconds <= stale_after
            if not hb_fresh:
                running_strict = False
        except Exception:
            pass
    stale_pid_detected = bool(pid > 0 and (not running_strict_proc))
    stale_heartbeat_detected = bool(hb_updated and (not hb_fresh))
    continuity_score = 100.0
    if not running_strict_proc:
        continuity_score -= 35.0
    if stale_pid_detected:
        continuity_score -= 20.0
    if hb_age_seconds is None:
        continuity_score -= 15.0
    elif hb_age_seconds > stale_after:
        continuity_score -= min(35.0, ((hb_age_seconds - stale_after) / max(1.0, stale_after)) * 40.0)
    if bool(hb.get("last_error")):
        continuity_score -= 10.0
    continuity_score = max(0.0, min(100.0, continuity_score))
    running_effective = bool(running_strict or (hb_fresh and bool(hb.get("running"))))
    if running_effective and continuity_score >= 80:
        operational_mode = "healthy"
    elif running_effective and continuity_score >= 55:
        operational_mode = "caution"
    else:
        operational_mode = "degraded"
    learning_loop_summary = _learning_loop_summary_fast()
    closed_trade_learning_feed_available = bool(
        _to_float((PAPER_AUTOPILOT.status() or {}).get("total_closed_trades"), 0.0) > 0
    )
    lifecycle_learning_active = bool(
        running_effective
        and bool(hb.get("autopilot_enabled", False))
        and bool(learning_loop_summary.get("learning_loop_active", False))
    )
    return {
        "running": running_effective,
        "running_effective": running_effective,
        "running_strict": running_strict,
        "running_strict_process": running_strict_proc,
        "heartbeat_fresh": hb_fresh,
        "heartbeat_age_seconds": round(hb_age_seconds, 2) if hb_age_seconds is not None else None,
        "heartbeat_stale_after_seconds": stale_after,
        "stale_pid_detected": stale_pid_detected,
        "stale_heartbeat_detected": stale_heartbeat_detected,
        "continuity_score": round(continuity_score, 2),
        "operational_mode": operational_mode,
        "pid": pid if pid > 0 else None,
        "last_cycle_utc": hb.get("last_cycle_utc"),
        "last_error": hb.get("last_error"),
        "autopilot_enabled": bool(hb.get("autopilot_enabled")),
        "replay_training_enabled": bool(hb.get("replay_training_enabled")),
        "replay_interval_seconds": hb.get("replay_interval_seconds"),
        "replay_runs_per_cycle": hb.get("replay_runs_per_cycle"),
        "replay_runs_total": int(hb.get("replay_runs_total") or 0),
        "last_replay_run_utc": hb.get("last_replay_run_utc"),
        "last_replay_ok": hb.get("last_replay_ok"),
        "last_replay_error": hb.get("last_replay_error"),
        "last_replay_trades_generated": int(hb.get("last_replay_trades_generated") or 0),
        "last_replay_valid_trades": int(hb.get("last_replay_valid_trades") or 0),
        "last_learning_refresh_utc": hb.get("last_learning_refresh_utc"),
        "last_deep_learning_refresh_utc": hb.get("last_deep_learning_refresh_utc"),
        "deep_learning_refresh_interval_seconds": hb.get("deep_learning_refresh_interval_seconds"),
        "cycle_count": int(hb.get("cycle_count") or 0),
        "interval_seconds": hb.get("interval_seconds"),
        "last_trade_opened_timestamp": hb.get("last_trade_opened_timestamp"),
        "last_trade_closed_timestamp": hb.get("last_trade_closed_timestamp"),
        "closed_trade_learning_feed_available": closed_trade_learning_feed_available,
        "lifecycle_learning_active": lifecycle_learning_active,
        "day_learning_mode_enabled": bool(DAY_LEARNING_MODE_ENABLED),
        "day_learning_paper_only": bool(DAY_LEARNING_MODE_PAPER_ONLY),
        "day_learning_active": bool(DAY_LEARNING_MODE_ENABLED and DAY_LEARNING_MODE_PAPER_ONLY and running_effective),
        "day_learning_horizons_minutes": list(DAY_LEARNING_SHORT_HORIZONS_MINUTES),
        "day_learning_max_open_positions": int(DAY_LEARNING_MAX_OPEN_DAY_LEARNING_POSITIONS),
        "day_trade_mode_enabled": bool(hb.get("day_trade_mode_enabled", DAY_TRADING_LIFECYCLE_MODE_ENABLED)),
        "same_day_exit_required": bool(hb.get("same_day_exit_required", FORCE_CLOSE_ALL_PAPER_POSITIONS_BEFORE_MARKET_CLOSE)),
        "entry_cutoff_time_et": str(hb.get("entry_cutoff_time_et") or NO_NEW_ENTRIES_AFTER_ET),
        "force_close_time_et": str(hb.get("force_close_time_et") or FORCE_CLOSE_TIME_ET),
        "max_day_trade_hold_minutes": int(_to_float(hb.get("max_day_trade_hold_minutes"), MAX_DAY_TRADE_HOLD_MINUTES)),
        "forced_end_of_day_exit": bool(hb.get("forced_end_of_day_exit", False)),
        "forced_end_of_day_exit_reason": str(hb.get("forced_end_of_day_exit_reason") or ""),
        "holding_minutes": round(_to_float(hb.get("holding_minutes"), 0.0), 2),
        "overnight_hold_blocked": bool(hb.get("overnight_hold_blocked", False)),
        "day_trade_lifecycle_status": str(hb.get("day_trade_lifecycle_status") or _DAY_TRADING_LIFECYCLE_STATE.get("day_trade_lifecycle_status") or "disabled"),
        "forced_close_count_last_cycle": int(_to_float(hb.get("forced_close_count_last_cycle"), 0.0)),
        "last_forced_symbols": list(hb.get("last_forced_symbols") or []),
        "session_type": str(hb.get("session_type") or _DAY_TRADING_LIFECYCLE_STATE.get("session_type") or _market_session_type_et(datetime.now(UTC))),
        "session_learning_weight": float(_to_float(hb.get("session_learning_weight"), _session_learning_weight(hb.get("session_type")))),
        "session_hold_limit_minutes": int(_to_float(hb.get("session_hold_limit_minutes"), _session_hold_limit_minutes(hb.get("session_type")))),
        "session_exit_reason": str(hb.get("session_exit_reason") or ""),
        "heartbeat_updated_at": hb.get("updated_at"),
        "heartbeat_file": PAPER_WORKER_HEARTBEAT_PATH,
        "pid_file": PAPER_WORKER_PID_PATH,
    }


def _paper_endpoint_error_code(exc: Exception):
    msg = str(exc or "").lower()
    if "disk i/o error" in msg:
        return "disk_io_error"
    if "database is locked" in msg:
        return "database_locked"
    return "db_error"


def _paper_endpoint_note_failure(endpoint_key: str, error_code: str):
    state = _PAPER_ENDPOINT_FAILURE_STATE.get(endpoint_key)
    if not isinstance(state, dict):
        return
    state["ts"] = time.time()
    state["error"] = str(error_code or "unknown_error")


def _paper_endpoint_recent_failure(endpoint_key: str):
    state = _PAPER_ENDPOINT_FAILURE_STATE.get(endpoint_key) or {}
    ts = float(state.get("ts", 0.0) or 0.0)
    if ts <= 0:
        return False
    return (time.time() - ts) <= PAPER_ENDPOINT_FAILURE_COOLDOWN_SECONDS


def _paper_endpoint_stale_payload(endpoint_key: str, stale_ttl_seconds=PAPER_ENDPOINT_STALE_TTL_SECONDS):
    cached = _CACHE.get(endpoint_key, {})
    data = cached.get("data") if isinstance(cached, dict) else None
    ts = float((cached or {}).get("ts", 0.0) or 0.0)
    if not isinstance(data, dict) or not data:
        return None
    if (time.time() - ts) > float(stale_ttl_seconds):
        return None
    out = dict(data)
    out["cached"] = True
    out["stale_cache"] = True
    out["stale_cache_age_seconds"] = round(max(0.0, time.time() - ts), 2)
    state = _PAPER_ENDPOINT_FAILURE_STATE.get(endpoint_key) or {}
    out["degraded_db_access"] = True
    out["degraded_reason"] = str(state.get("error") or "db_degraded")
    out["degraded_reused_payload"] = True
    out["degraded_reused_payload_endpoint"] = endpoint_key
    return out


def _parse_iso_or_epoch(value):
    if value is None:
        return 0.0
    try:
        if isinstance(value, (int, float)):
            return float(value)
        s = str(value).strip()
        if not s:
            return 0.0
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        return datetime.fromisoformat(s).timestamp()
    except Exception:
        try:
            return float(value)
        except Exception:
            return 0.0


def _current_engine_outcome_evaluation():
    eval_t0 = time.perf_counter()
    signature = _trade_journal_outcome_signature()
    cached = _CACHE.get("current_engine_outcome_evaluation", {})
    if (
        cached.get("data")
        and cached.get("signature") == signature
        and (time.time() - float(cached.get("ts", 0.0))) <= 90
    ):
        _record_hot_path_timing("current_engine_eval_total_ms", (time.perf_counter() - eval_t0) * 1000.0)
        return dict(cached.get("data") or {})

    out = {
        "cohort_mode": "insufficient_data",
        "cohort_window_days": 30,
        "cohort_sample_sizes": {"released": 0, "paper_ready": 0, "blocked_watchlist": 0},
        "released_hero_win_rate": None,
        "paper_ready_win_rate": None,
        "blocked_watchlist_win_rate": None,
        "released_vs_paper_ready_win_rate_delta": None,
        "released_vs_blocked_win_rate_delta": None,
        "released_hero_expectancy": None,
        "paper_ready_expectancy": None,
        "blocked_watchlist_expectancy": None,
        "released_hero_expectancy_raw": None,
        "paper_ready_expectancy_raw": None,
        "blocked_watchlist_expectancy_raw": None,
        "released_high_confidence_win_rate": None,
        "released_medium_confidence_win_rate": None,
        "released_fast_loss_rate": None,
        "confidence_comparison_reliable": False,
        "cohort_quality_note": "insufficient_data",
        "post_change_cohort_mode": "post_change_current_engine_quality_gate",
        "post_change_cohort_start_utc": POST_CHANGE_COHORT_START_UTC,
        "post_change_sample_sizes": {"released": 0, "paper_ready": 0, "blocked_watchlist": 0},
        "post_change_released_win_rate": None,
        "post_change_paper_ready_win_rate": None,
        "post_change_blocked_watchlist_win_rate": None,
        "post_change_released_expectancy": None,
        "post_change_paper_ready_expectancy": None,
        "post_change_blocked_watchlist_expectancy": None,
        "post_change_released_fast_loss_rate": None,
        "post_change_high_confidence_win_rate": None,
        "post_change_medium_confidence_win_rate": None,
        "post_change_confidence_comparison_reliable": False,
        "post_change_cohort_quality_note": "insufficient_post_change_data",
        "post_change_evidence_ready": False,
        "post_change_confidence_ready": False,
        "post_change_released_vs_paper_ready_expectancy_delta": None,
        "post_change_released_vs_blocked_expectancy_delta": None,
        "current_engine_exit_timing_score": None,
        "current_engine_profit_protection_score": None,
        "current_engine_late_exit_rate": None,
        "current_engine_premature_exit_rate": None,
        "current_engine_sell_quality_note": "insufficient_current_engine_sell_side_data",
        "current_engine_sell_side_sample_size": 0,
        "post_change_exit_timing_score": None,
        "post_change_profit_protection_score": None,
        "post_change_late_exit_rate": None,
        "post_change_premature_exit_rate": None,
        "post_change_sell_quality_note": "insufficient_post_change_sell_side_data",
        "post_change_sell_side_sample_size": 0,
        "post_change_min_sample_requirements": {
            "released": 30,
            "paper_ready": 30,
            "blocked_watchlist": 30,
            "released_high_confidence": 20,
            "released_medium_confidence": 20,
        },
    }
    fetch_t0 = time.perf_counter()
    try:
        records = [dict(r or {}) for r in _get_trade_journal_outcome_rows_cached()]
    except Exception:
        records = []
    _record_hot_path_timing("current_engine_eval_db_fetch_ms", (time.perf_counter() - fetch_t0) * 1000.0)
    if not records:
        _CACHE["current_engine_outcome_evaluation"] = {"data": dict(out), "ts": time.time(), "signature": signature}
        _record_hot_path_timing("current_engine_eval_total_ms", (time.perf_counter() - eval_t0) * 1000.0)
        return out

    def _bucket(rec):
        # Canonical current-engine-compatible outcome buckets:
        # classify by current quality/confidence/allocation behavior, not legacy tier labels.
        quality = _to_float(rec.get("buy_quality_score"), 0.0)
        confidence = _to_float(rec.get("entry_confidence"), _to_float(rec.get("entry_predicted_probability"), 0.0) * 100.0)
        allocation = 0.0
        try:
            risk_ctx = rec.get("risk_context_json")
            if isinstance(risk_ctx, str) and risk_ctx:
                parsed = json.loads(risk_ctx)
                if isinstance(parsed, dict):
                    allocation = _to_float(parsed.get("allocation_score"), 0.0)
        except Exception:
            allocation = 0.0
        setup_fields = _derive_canonical_setup_fields(rec)
        setup_type = str(setup_fields.get("setup_type") or "").strip().lower()
        setup_penalty = 8.0 if setup_type in {"fallback_unclear", "unclassified_setup"} else (5.0 if setup_type == "weak_followthrough_risk" else 0.0)
        setup_clarity = _to_float(setup_fields.get("setup_clarity_score"), 0.0)
        quality_tier = str(rec.get("buy_quality_tier") or "").strip().lower()
        quality_signal = (
            (quality * 0.52)
            + (confidence * 0.33)
            + (allocation * 0.15)
            + (2.5 if quality_tier == "soft_buy" else 0.0)
            - (setup_penalty * 0.6)
        )
        if quality >= 63.15 and confidence >= 86.5 and allocation >= 58.0 and setup_clarity >= 58.0 and quality_signal >= 72.0:
            return "released"
        if quality >= 61.6 and confidence >= 80.0 and allocation >= 54.0 and setup_clarity >= 50.0 and quality_signal >= 70.0:
            return "paper_ready"
        return "blocked_watchlist"

    def _sell_side_summary(recs, sample_floor=8):
        usable = []
        capture_ratios = []
        late_flags = 0
        premature_flags = 0
        for rec in recs or []:
            peak = max(
                _to_float(rec.get("peak_unrealized_pnl_percent"), 0.0),
                _to_float(rec.get("max_favorable_excursion"), 0.0),
                0.0,
            )
            ret = _to_float(rec.get("return_percent"), _to_float(rec.get("friction_adjusted_return"), 0.0))
            drawdown_after_peak = max(0.0, _to_float(rec.get("drawdown_after_peak_percent"), 0.0))
            time_to_peak = max(0.0, _to_float(rec.get("time_to_peak_seconds"), 0.0))
            time_to_exit = max(0.0, _to_float(rec.get("time_to_exit_seconds"), 0.0))
            exit_reason = str(rec.get("exit_reason") or "").strip().lower()
            if peak <= 0.0 and ret == 0.0 and drawdown_after_peak <= 0.0:
                continue
            usable.append(rec)
            if peak > 0.0:
                capture_ratios.append(max(0.0, min(1.5, max(0.0, ret) / max(0.1, peak))))
            elif ret > 0.0:
                capture_ratios.append(1.0)
            late_flag = False
            premature_flag = False
            if peak >= 1.5:
                if ret <= max(0.25, peak * 0.35):
                    if time_to_exit > 0.0 and time_to_peak > 0.0 and time_to_exit <= (time_to_peak * 0.85):
                        premature_flag = True
                    elif any(tag in exit_reason for tag in ("manual", "time", "scalp")):
                        premature_flag = True
                if drawdown_after_peak >= max(1.0, peak * 0.45) and ret <= (peak * 0.55):
                    late_flag = True
            if ret <= -2.0 and peak >= 1.0 and drawdown_after_peak >= 1.5:
                late_flag = True
            if late_flag:
                late_flags += 1
            if premature_flag:
                premature_flags += 1
        sample_size = int(len(usable))
        if sample_size <= 0:
            return {
                "sample_size": 0,
                "exit_timing_score": None,
                "profit_protection_score": None,
                "late_exit_rate": None,
                "premature_exit_rate": None,
                "sell_quality_note": "insufficient_sell_side_fields_in_trade_journal",
            }
        profit_protection_score = None
        if capture_ratios:
            profit_protection_score = round(max(0.0, min(100.0, (sum(capture_ratios) / len(capture_ratios)) * 100.0)), 2)
        late_exit_rate = round((late_flags / max(1, sample_size)) * 100.0, 2)
        premature_exit_rate = round((premature_flags / max(1, sample_size)) * 100.0, 2)
        exit_timing_score = round(
            max(
                0.0,
                min(
                    100.0,
                    (_to_float(profit_protection_score, 0.0) * 0.45)
                    + ((100.0 - late_exit_rate) * 0.35)
                    + ((100.0 - premature_exit_rate) * 0.20),
                ),
            ),
            2,
        )
        if sample_size < sample_floor:
            note = "provisional_low_sample_sell_side_estimate_from_trade_journal_excursion_fields"
        else:
            note = "sell_side_estimate_derived_from_trade_journal_excursion_and_exit_fields"
        return {
            "sample_size": sample_size,
            "exit_timing_score": exit_timing_score,
            "profit_protection_score": profit_protection_score,
            "late_exit_rate": late_exit_rate,
            "premature_exit_rate": premature_exit_rate,
            "sell_quality_note": note,
        }

    def _evaluate_window(window_days):
        cutoff = time.time() - (window_days * 86400)
        cohort = []
        for rec in records:
            if _parse_iso_or_epoch(rec.get("exit_timestamp")) < cutoff:
                continue
            origin = str(rec.get("trade_origin") or "").strip().lower()
            # Exclude replay-heavy legacy cohorts; use live autopilot/manual outcomes for current-engine truth.
            if origin not in {"paper_autopilot", "manual"}:
                continue
            if origin == "paper_replay" and int(_to_float(rec.get("valid_label"), 1.0)) <= 0:
                continue
            cohort.append(rec)
        grouped = {"released": [], "paper_ready": [], "blocked_watchlist": []}
        grouped_rows = {"released": [], "paper_ready": [], "blocked_watchlist": []}
        high_conf_released = []
        med_conf_released = []
        for rec in cohort:
            ret = _to_float(rec.get("return_percent"), 0.0)
            g = _bucket(rec)
            grouped[g].append(ret)
            grouped_rows[g].append(rec)
            if g == "released":
                c = _to_float(rec.get("entry_confidence"), 0.0)
                if c >= 94.0:
                    high_conf_released.append(ret)
                elif c >= 90.0:
                    med_conf_released.append(ret)
        return grouped, grouped_rows, high_conf_released, med_conf_released

    bucket_t0 = time.perf_counter()
    selected_window = None
    selected = None
    for window_days in (7, 14, 30, 60, 90):
        grouped, grouped_rows, high_conf_released, med_conf_released = _evaluate_window(window_days)
        released_n = len(grouped["released"])
        paper_n = len(grouped["paper_ready"])
        blocked_n = len(grouped["blocked_watchlist"])
        if released_n >= 200 and paper_n >= 200 and blocked_n >= 200:
            selected_window = window_days
            selected = (grouped, grouped_rows, high_conf_released, med_conf_released)
            break
    if selected is None:
        grouped, grouped_rows, high_conf_released, med_conf_released = _evaluate_window(90)
        selected_window = 90
        selected = (grouped, grouped_rows, high_conf_released, med_conf_released)

    grouped, grouped_rows, high_conf_released, med_conf_released = selected

    def _win_rate(vals):
        if not vals:
            return None
        return round((sum(1 for v in vals if v > 0.0) / len(vals)) * 100.0, 2)

    def _expectancy(vals):
        if not vals:
            return None
        wins = [v for v in vals if v > 0.0]
        losses = [v for v in vals if v <= 0.0]
        win_rate = len(wins) / max(1, len(vals))
        avg_win = (sum(wins) / len(wins)) if wins else 0.0
        avg_loss = abs((sum(losses) / len(losses))) if losses else 0.0
        return (win_rate * avg_win) - ((1.0 - win_rate) * avg_loss)

    def _expectancy_clipped(vals, cap=5.0):
        if not vals:
            return None
        clipped = [max(-cap, min(cap, _to_float(v, 0.0))) for v in vals]
        return _expectancy(clipped)

    def _fast_loss_rate(vals):
        if not vals:
            return None
        return round((sum(1 for v in vals if v <= -2.0) / len(vals)) * 100.0, 2)

    released_vals = grouped["released"]
    paper_vals = grouped["paper_ready"]
    blocked_vals = grouped["blocked_watchlist"]

    released_wr = _win_rate(released_vals)
    paper_wr = _win_rate(paper_vals)
    blocked_wr = _win_rate(blocked_vals)

    released_exp_raw = _expectancy(released_vals)
    paper_exp_raw = _expectancy(paper_vals)
    blocked_exp_raw = _expectancy(blocked_vals)

    # Use clipped expectancy as canonical comparison to avoid legacy outlier distortion.
    released_exp = _expectancy_clipped(released_vals, cap=5.0)
    paper_exp = _expectancy_clipped(paper_vals, cap=5.0)
    blocked_exp = _expectancy_clipped(blocked_vals, cap=5.0)

    high_wr = _win_rate(high_conf_released)
    med_wr = _win_rate(med_conf_released)
    confidence_reliable = bool(len(high_conf_released) >= 50 and len(med_conf_released) >= 50)
    current_sell_side = _sell_side_summary(grouped_rows["released"], sample_floor=20)
    _record_hot_path_timing("current_engine_eval_bucket_ms", (time.perf_counter() - bucket_t0) * 1000.0)

    out.update(
        {
            "cohort_mode": "current_engine_autopilot_recent_window_quality_gate_clipped_expectancy",
            "cohort_window_days": int(selected_window),
            "cohort_sample_sizes": {
                "released": int(len(released_vals)),
                "paper_ready": int(len(paper_vals)),
                "blocked_watchlist": int(len(blocked_vals)),
                "released_high_confidence": int(len(high_conf_released)),
                "released_medium_confidence": int(len(med_conf_released)),
            },
            "released_hero_win_rate": released_wr,
            "paper_ready_win_rate": paper_wr,
            "blocked_watchlist_win_rate": blocked_wr,
            "released_vs_paper_ready_win_rate_delta": (
                round(_to_float(released_wr, 0.0) - _to_float(paper_wr, 0.0), 2)
                if (released_wr is not None and paper_wr is not None)
                else None
            ),
            "released_vs_blocked_win_rate_delta": (
                round(_to_float(released_wr, 0.0) - _to_float(blocked_wr, 0.0), 2)
                if (released_wr is not None and blocked_wr is not None)
                else None
            ),
            "released_hero_expectancy": round(_to_float(released_exp, 0.0), 4) if released_exp is not None else None,
            "paper_ready_expectancy": round(_to_float(paper_exp, 0.0), 4) if paper_exp is not None else None,
            "blocked_watchlist_expectancy": round(_to_float(blocked_exp, 0.0), 4) if blocked_exp is not None else None,
            "released_hero_expectancy_raw": round(_to_float(released_exp_raw, 0.0), 4) if released_exp_raw is not None else None,
            "paper_ready_expectancy_raw": round(_to_float(paper_exp_raw, 0.0), 4) if paper_exp_raw is not None else None,
            "blocked_watchlist_expectancy_raw": round(_to_float(blocked_exp_raw, 0.0), 4) if blocked_exp_raw is not None else None,
            "released_high_confidence_win_rate": high_wr,
            "released_medium_confidence_win_rate": med_wr,
            "released_fast_loss_rate": _fast_loss_rate(released_vals),
            "current_engine_exit_timing_score": current_sell_side.get("exit_timing_score"),
            "current_engine_profit_protection_score": current_sell_side.get("profit_protection_score"),
            "current_engine_late_exit_rate": current_sell_side.get("late_exit_rate"),
            "current_engine_premature_exit_rate": current_sell_side.get("premature_exit_rate"),
            "current_engine_sell_quality_note": str(current_sell_side.get("sell_quality_note") or "insufficient_current_engine_sell_side_data"),
            "current_engine_sell_side_sample_size": int(_to_float(current_sell_side.get("sample_size"), 0.0)),
            "confidence_comparison_reliable": confidence_reliable,
            "cohort_quality_note": (
                "recent autopilot/manual current-engine quality-gated window with clipped expectancy; confidence bucket compare is reliable"
                if confidence_reliable
                else "recent autopilot/manual current-engine quality-gated window with clipped expectancy; confidence bucket compare is low-sample"
            ),
        }
    )

    # Strict post-change tracker: evaluate only trades closed after canonical post-change start.
    post_t0 = time.perf_counter()
    post_change_cutoff = _parse_iso_or_epoch(POST_CHANGE_COHORT_START_UTC)
    post_grouped = {"released": [], "paper_ready": [], "blocked_watchlist": []}
    post_grouped_rows = {"released": [], "paper_ready": [], "blocked_watchlist": []}
    post_high_conf_released = []
    post_med_conf_released = []
    for rec in records:
        if _parse_iso_or_epoch(rec.get("exit_timestamp")) < post_change_cutoff:
            continue
        origin = str(rec.get("trade_origin") or "").strip().lower()
        if origin not in {"paper_autopilot", "manual"}:
            continue
        ret = _to_float(rec.get("return_percent"), 0.0)
        bucket = _bucket(rec)
        post_grouped[bucket].append(ret)
        post_grouped_rows[bucket].append(rec)
        if bucket == "released":
            c = _to_float(rec.get("entry_confidence"), 0.0)
            if c >= 94.0:
                post_high_conf_released.append(ret)
            elif c >= 90.0:
                post_med_conf_released.append(ret)
    post_conf_reliable = bool(len(post_high_conf_released) >= 20 and len(post_med_conf_released) >= 20)
    post_sell_side = _sell_side_summary(post_grouped_rows["released"], sample_floor=12)
    post_evidence_ready = bool(
        len(post_grouped["released"]) >= 30
        and len(post_grouped["paper_ready"]) >= 30
        and len(post_grouped["blocked_watchlist"]) >= 30
    )
    out.update(
        {
            "post_change_sample_sizes": {
                "released": int(len(post_grouped["released"])),
                "paper_ready": int(len(post_grouped["paper_ready"])),
                "blocked_watchlist": int(len(post_grouped["blocked_watchlist"])),
                "released_high_confidence": int(len(post_high_conf_released)),
                "released_medium_confidence": int(len(post_med_conf_released)),
            },
            "post_change_released_win_rate": _win_rate(post_grouped["released"]),
            "post_change_paper_ready_win_rate": _win_rate(post_grouped["paper_ready"]),
            "post_change_blocked_watchlist_win_rate": _win_rate(post_grouped["blocked_watchlist"]),
            "post_change_released_expectancy": (
                round(_to_float(_expectancy_clipped(post_grouped["released"], cap=5.0), 0.0), 4)
                if post_grouped["released"]
                else None
            ),
            "post_change_paper_ready_expectancy": (
                round(_to_float(_expectancy_clipped(post_grouped["paper_ready"], cap=5.0), 0.0), 4)
                if post_grouped["paper_ready"]
                else None
            ),
            "post_change_blocked_watchlist_expectancy": (
                round(_to_float(_expectancy_clipped(post_grouped["blocked_watchlist"], cap=5.0), 0.0), 4)
                if post_grouped["blocked_watchlist"]
                else None
            ),
            "post_change_released_fast_loss_rate": _fast_loss_rate(post_grouped["released"]),
            "post_change_high_confidence_win_rate": _win_rate(post_high_conf_released),
            "post_change_medium_confidence_win_rate": _win_rate(post_med_conf_released),
            "post_change_exit_timing_score": post_sell_side.get("exit_timing_score"),
            "post_change_profit_protection_score": post_sell_side.get("profit_protection_score"),
            "post_change_late_exit_rate": post_sell_side.get("late_exit_rate"),
            "post_change_premature_exit_rate": post_sell_side.get("premature_exit_rate"),
            "post_change_sell_quality_note": str(post_sell_side.get("sell_quality_note") or "insufficient_post_change_sell_side_data"),
            "post_change_sell_side_sample_size": int(_to_float(post_sell_side.get("sample_size"), 0.0)),
            "post_change_confidence_comparison_reliable": post_conf_reliable,
            "post_change_evidence_ready": post_evidence_ready,
            "post_change_confidence_ready": post_conf_reliable,
            "post_change_released_vs_paper_ready_expectancy_delta": (
                round(
                    _to_float(_expectancy_clipped(post_grouped["released"], cap=5.0), 0.0)
                    - _to_float(_expectancy_clipped(post_grouped["paper_ready"], cap=5.0), 0.0),
                    4,
                )
                if post_grouped["released"] and post_grouped["paper_ready"]
                else None
            ),
            "post_change_released_vs_blocked_expectancy_delta": (
                round(
                    _to_float(_expectancy_clipped(post_grouped["released"], cap=5.0), 0.0)
                    - _to_float(_expectancy_clipped(post_grouped["blocked_watchlist"], cap=5.0), 0.0),
                    4,
                )
                if post_grouped["released"] and post_grouped["blocked_watchlist"]
                else None
            ),
            "post_change_cohort_quality_note": (
                "post-change current-engine cohort has sufficient outcome and confidence sample sizes"
                if (post_evidence_ready and post_conf_reliable)
                else "post-change current-engine cohort has sufficient outcome samples but confidence bucket samples are still small"
                if post_evidence_ready
                else "post-change current-engine cohort sample sizes are still small"
            ),
            "post_change_min_sample_requirements": {
                "released": 30,
                "paper_ready": 30,
                "blocked_watchlist": 30,
                "released_high_confidence": 20,
                "released_medium_confidence": 20,
            },
        }
    )
    out["post_change_cohort_quality_note"] = (
        "post-change current-engine cohort has reliable confidence bucket sample sizes"
        if (post_evidence_ready and post_conf_reliable)
        else "post-change current-engine cohort has sufficient outcome samples but confidence bucket samples are still small"
        if post_evidence_ready
        else "post-change current-engine cohort sample sizes are still small"
    )

    def _band(value, cuts):
        v = _to_float(value, None)
        if v is None:
            return "unknown"
        for name, lo, hi in cuts:
            if v >= lo and v < hi:
                return name
        return cuts[-1][0] if cuts else "unknown"

    _diag_cache = {}

    def _derive_diag_fields(rec):
        item = dict(rec or {})
        rec_key = str(item.get("trade_id") or item.get("id") or "")
        if rec_key and rec_key in _diag_cache:
            return dict(_diag_cache.get(rec_key) or {})
        setup_fields = _derive_canonical_setup_fields(item)
        setup_type = str(setup_fields.get("setup_type") or "fallback_unclear").strip().lower()
        setup_clarity = _to_float(setup_fields.get("setup_clarity_score"), 0.0)
        evidence_density = _to_float(setup_fields.get("evidence_density_score"), 0.0)

        confidence = _to_float(item.get("entry_confidence"), _to_float(item.get("entry_predicted_probability"), 0.0) * 100.0)
        pred_prob_pct = _to_float(item.get("entry_predicted_probability"), 0.0) * 100.0
        buy_quality = _to_float(item.get("buy_quality_score"), 0.0)
        trade_quality = _to_float(item.get("buy_quality_score"), _to_float(item.get("friction_adjusted_return"), 0.0) * 10.0 + 60.0)
        consensus = _to_float(item.get("entry_consensus_strength"), _to_float(item.get("entry_persona_grade"), 0.0))
        disagreement_index = _to_float(item.get("entry_persona_disagreement_index"), 100.0)
        disagreement_penalty = max(0.0, min(100.0, 100.0 - disagreement_index))
        timeframe_alignment = _to_float(item.get("timeframe_alignment_score"), 50.0)

        ret = _to_float(item.get("return_percent"), _to_float(item.get("friction_adjusted_return"), 0.0))
        mfe = max(0.0, _to_float(item.get("max_favorable_excursion"), _to_float(item.get("peak_unrealized_pnl_percent"), 0.0)))
        mae = max(0.0, abs(_to_float(item.get("max_adverse_excursion"), 0.0)))
        drawdown = max(0.0, _to_float(item.get("drawdown_after_peak_percent"), 0.0))
        duration_min = max(0.0, _to_float(item.get("duration_minutes"), _to_float(item.get("time_to_exit_seconds"), 0.0) / 60.0))
        immediate_failure_risk = max(
            0.0,
            min(
                100.0,
                (max(0.0, -ret) * 17.0)
                + (max(0.0, mae - 1.0) * 9.0)
                + (12.0 if (duration_min <= 90.0 and ret < 0.0) else 0.0)
                + (8.0 if mfe <= 0.5 else 0.0),
            ),
        )
        follow_failure = max(
            0.0,
            min(
                100.0,
                (max(0.0, -ret) * 14.0)
                + (max(0.0, 2.0 - mfe) * 8.0)
                + (mae * 5.0)
                + (drawdown * 3.5),
            ),
        )
        confirmation_strength = max(
            0.0,
            min(
                100.0,
                (confidence * 0.34)
                + (pred_prob_pct * 0.18)
                + (consensus * 0.18)
                + (disagreement_penalty * 0.12)
                + (setup_clarity * 0.10)
                + (evidence_density * 0.08),
            ),
        )
        follow_strength = max(
            0.0,
            min(
                100.0,
                ((100.0 - follow_failure) * 0.56)
                + (max(0.0, min(100.0, mfe * 16.0)) * 0.18)
                + (setup_clarity * 0.12)
                + (evidence_density * 0.08)
                + (timeframe_alignment * 0.06),
            ),
        )
        entry_timing_score = max(
            0.0,
            min(
                100.0,
                (confirmation_strength * 0.38)
                + (follow_strength * 0.34)
                + (setup_clarity * 0.12)
                + (evidence_density * 0.08)
                + (timeframe_alignment * 0.08),
            ),
        )
        entry_followthrough_quality = max(
            0.0,
            min(
                100.0,
                (follow_strength * 0.52)
                + (entry_timing_score * 0.22)
                + (setup_clarity * 0.10)
                + (evidence_density * 0.10)
                + ((100.0 - immediate_failure_risk) * 0.06),
            ),
        )
        if confirmation_strength >= 78.0:
            confirmation_state = "strong_confirmation"
        elif confirmation_strength >= 66.0:
            confirmation_state = "confirmed"
        elif confirmation_strength >= 54.0:
            confirmation_state = "moderate_confirmation"
        elif confirmation_strength >= 45.0:
            confirmation_state = "pending_confirmation"
        else:
            confirmation_state = "weak_confirmation"
        if follow_strength >= 78.0:
            follow_state = "strong_follow_through"
        elif follow_strength >= 64.0:
            follow_state = "confirmed_follow_through"
        elif follow_strength >= 52.0:
            follow_state = "moderate_continuation"
        elif follow_strength >= 40.0:
            follow_state = "unclear_follow_through"
        else:
            follow_state = "weak_follow_through"

        mem = _memory_context_for_row(item)
        memory_verdict = str(mem.get("memory_verdict") or "neutral_or_low_sample")
        out_diag = {
            "setup_type": setup_type,
            "setup_clarity_score": setup_clarity,
            "evidence_density_score": evidence_density,
            "confidence": confidence,
            "buy_quality_score": buy_quality,
            "trade_quality_score": trade_quality,
            "entry_timing_score": entry_timing_score,
            "entry_followthrough_quality_score": entry_followthrough_quality,
            "immediate_failure_risk_score": immediate_failure_risk,
            "confirmation_state": confirmation_state,
            "follow_through_state": follow_state,
            "memory_verdict": memory_verdict,
            "regime": str(item.get("entry_regime") or item.get("market_regime") or "unknown").strip().lower(),
            "persona": str(item.get("entry_persona_best_fit") or item.get("persona_best_fit") or "unknown").strip().lower(),
            "cap_bucket": str(item.get("entry_market_cap_category") or item.get("market_cap_category") or "unknown").strip().lower(),
            "return_percent": ret,
        }
        if rec_key:
            _diag_cache[rec_key] = dict(out_diag)
        return out_diag

    def _rates(vals):
        n = len(vals)
        if n <= 0:
            return {"sample_size": 0, "win_rate": None, "fast_loss_rate": None, "expectancy": None}
        wins = sum(1 for v in vals if v > 0.0)
        fast_losses = sum(1 for v in vals if v <= -2.0)
        wr = (wins / n) * 100.0
        flr = (fast_losses / n) * 100.0
        exp = _expectancy_clipped(vals, cap=5.0)
        return {
            "sample_size": int(n),
            "win_rate": round(wr, 2),
            "fast_loss_rate": round(flr, 2),
            "expectancy": round(_to_float(exp, 0.0), 4) if exp is not None else None,
        }

    def _rank_group_map(rows, key_fn, min_sample=20):
        grouped_map = {}
        for row in rows:
            d = _derive_diag_fields(row)
            key = str(key_fn(d) or "unknown").strip().lower() or "unknown"
            grouped_map.setdefault(key, []).append(_to_float(d.get("return_percent"), 0.0))
        ranked = []
        for key, vals in grouped_map.items():
            rates = _rates(vals)
            if rates["sample_size"] < min_sample:
                continue
            weakness = max(
                0.0,
                min(
                    100.0,
                    ((100.0 - _to_float(rates.get("win_rate"), 0.0)) * 0.45)
                    + (_to_float(rates.get("fast_loss_rate"), 0.0) * 0.45)
                    + (max(0.0, -_to_float(rates.get("expectancy"), 0.0)) * 12.0),
                ),
            )
            strength = max(
                0.0,
                min(
                    100.0,
                    (_to_float(rates.get("win_rate"), 0.0) * 0.55)
                    + ((100.0 - _to_float(rates.get("fast_loss_rate"), 0.0)) * 0.20)
                    + (max(0.0, _to_float(rates.get("expectancy"), 0.0)) * 20.0)
                    + 5.0,
                ),
            )
            ranked.append(
                {
                    "key": key,
                    **rates,
                    "weakness_score": round(weakness, 2),
                    "strength_score": round(strength, 2),
                }
            )
        return sorted(ranked, key=lambda x: (_to_float(x.get("weakness_score"), 0.0), _to_float(x.get("sample_size"), 0.0)), reverse=True)

    def _component_weakness_rank(rows, min_sample=30):
        component_rows = []
        for r in rows:
            d = _derive_diag_fields(r)
            pairs = [
                ("confidence_band", _band(d.get("confidence"), [("very_low", 0, 78), ("low", 78, 86), ("medium", 86, 92), ("high", 92, 96), ("elite", 96, 1000)])),
                ("confirmation_state", str(d.get("confirmation_state") or "unknown")),
                ("entry_timing_band", _band(d.get("entry_timing_score"), [("weak", 0, 48), ("cautious", 48, 60), ("good", 60, 72), ("strong", 72, 1000)])),
                ("entry_followthrough_band", _band(d.get("entry_followthrough_quality_score"), [("weak", 0, 55), ("fragile", 55, 64), ("moderate", 64, 74), ("strong", 74, 1000)])),
                ("trade_quality_band", _band(d.get("trade_quality_score"), [("weak", 0, 62), ("moderate", 62, 72), ("good", 72, 82), ("elite", 82, 1000)])),
                ("buy_quality_band", _band(d.get("buy_quality_score"), [("weak", 0, 62), ("moderate", 62, 72), ("good", 72, 82), ("elite", 82, 1000)])),
                ("immediate_failure_risk_band", _band(d.get("immediate_failure_risk_score"), [("low", 0, 20), ("moderate", 20, 40), ("elevated", 40, 60), ("high", 60, 1000)])),
                ("memory_verdict", str(d.get("memory_verdict") or "neutral_or_low_sample")),
                ("setup_clarity_band", _band(d.get("setup_clarity_score"), [("low", 0, 46), ("moderate", 46, 62), ("good", 62, 76), ("strong", 76, 1000)])),
                ("evidence_density_band", _band(d.get("evidence_density_score"), [("thin", 0, 40), ("moderate", 40, 58), ("good", 58, 74), ("rich", 74, 1000)])),
                ("setup_type", str(d.get("setup_type") or "unknown")),
            ]
            ret = _to_float(d.get("return_percent"), 0.0)
            for comp, label in pairs:
                component_rows.append((comp, str(label or "unknown").strip().lower(), ret))
        grouped = {}
        for comp, label, ret in component_rows:
            grouped.setdefault((comp, label), []).append(ret)
        ranked = []
        for (comp, label), vals in grouped.items():
            rates = _rates(vals)
            if rates["sample_size"] < min_sample:
                continue
            weakness = max(
                0.0,
                min(
                    100.0,
                    ((100.0 - _to_float(rates.get("win_rate"), 0.0)) * 0.42)
                    + (_to_float(rates.get("fast_loss_rate"), 0.0) * 0.48)
                    + (max(0.0, -_to_float(rates.get("expectancy"), 0.0)) * 15.0),
                ),
            )
            strength = max(
                0.0,
                min(
                    100.0,
                    (_to_float(rates.get("win_rate"), 0.0) * 0.50)
                    + ((100.0 - _to_float(rates.get("fast_loss_rate"), 0.0)) * 0.20)
                    + (max(0.0, _to_float(rates.get("expectancy"), 0.0)) * 20.0)
                    + 4.0,
                ),
            )
            ranked.append(
                {
                    "component": comp,
                    "label": label,
                    **rates,
                    "weakness_score": round(weakness, 2),
                    "strength_score": round(strength, 2),
                }
            )
        weak = sorted(ranked, key=lambda x: (_to_float(x.get("weakness_score"), 0.0), _to_float(x.get("sample_size"), 0.0)), reverse=True)
        strong = sorted(ranked, key=lambda x: (_to_float(x.get("strength_score"), 0.0), _to_float(x.get("sample_size"), 0.0)), reverse=True)
        return weak[:14], strong[:14]

    def _promotion_leakage_snapshot():
        top_payload = _latest_top_buys_runtime_snapshot()
        top_views = dict((top_payload or {}).get("top_action_views") or {})
        hero_rows = list(top_views.get("stocks_buy_first_hero_candidates") or []) + list(top_views.get("crypto_buy_first_hero_candidates") or [])
        leak_by_reason = {}
        weak_promoted = 0
        released = 0
        for row in hero_rows:
            status = str((row or {}).get("hero_deployment_status") or "").strip().lower()
            if status != "live-ready":
                continue
            released += 1
            follow_state = str((row or {}).get("follow_through_state") or (row or {}).get("continuation_state") or "").strip().lower()
            entry_follow = _to_float((row or {}).get("entry_followthrough_quality_score"), 0.0)
            entry_timing_raw = (row or {}).get("entry_timing_score")
            entry_timing = _to_float(entry_timing_raw, None)
            if entry_timing is None:
                entry_timing = max(48.0, min(95.0, entry_follow * 0.95))
            confidence = _to_float((row or {}).get("confidence"), 0.0)
            trade_quality = _to_float((row or {}).get("trade_quality_score"), 0.0)
            reason = str((row or {}).get("enforcement_reason") or (row or {}).get("primary_hero_release_blocker") or "base_release_path").strip().lower()
            leaky = bool(
                ("weak" in follow_state)
                or ("unclear" in follow_state)
                or entry_follow < 64.0
                or trade_quality < 68.0
                or (entry_timing < 52.0 and entry_follow < 66.0)
                or (confidence >= 90.0 and entry_follow < 68.0)
            )
            leak_by_reason.setdefault(reason, {"released_count": 0, "weak_leak_count": 0})
            leak_by_reason[reason]["released_count"] += 1
            if leaky:
                leak_by_reason[reason]["weak_leak_count"] += 1
                weak_promoted += 1
        ranked = []
        for reason, counts in leak_by_reason.items():
            rel = int(counts.get("released_count", 0))
            weak_n = int(counts.get("weak_leak_count", 0))
            leak_rate = (weak_n / max(1, rel)) * 100.0
            ranked.append(
                {
                    "promotion_path": reason,
                    "released_count": rel,
                    "weak_leak_count": weak_n,
                    "weak_leak_rate": round(leak_rate, 2),
                }
            )
        ranked.sort(key=lambda x: (_to_float(x.get("weak_leak_count"), 0.0), _to_float(x.get("weak_leak_rate"), 0.0)), reverse=True)
        return {
            "released_live_ready_count": int(released),
            "weak_promoted_count": int(weak_promoted),
            "weak_promoted_rate": round((weak_promoted / max(1, released)) * 100.0, 2),
            "ranked_leak_paths": ranked[:10],
        }

    # Publish core cohort metrics immediately so fast-path callers can see
    # current-engine/post-change sample populations without waiting for the
    # heavy weak-point diagnostics section to finish.
    _CACHE["current_engine_outcome_evaluation"] = {"data": dict(out), "ts": time.time(), "signature": signature}

    current_released_rows = list(grouped_rows.get("released") or [])
    post_released_rows = list(post_grouped_rows.get("released") or [])
    current_weak_components, current_strong_components = _component_weakness_rank(current_released_rows, min_sample=30)
    post_weak_components, post_strong_components = _component_weakness_rank(post_released_rows, min_sample=20)
    current_follow_rank = _rank_group_map(current_released_rows, key_fn=lambda d: d.get("follow_through_state"), min_sample=20)
    post_follow_rank = _rank_group_map(post_released_rows, key_fn=lambda d: d.get("follow_through_state"), min_sample=12)
    current_combo_rank = _rank_group_map(current_released_rows, key_fn=lambda d: f"{d.get('persona')}|{d.get('regime')}|{d.get('setup_type')}", min_sample=20)
    post_combo_rank = _rank_group_map(post_released_rows, key_fn=lambda d: f"{d.get('persona')}|{d.get('regime')}|{d.get('setup_type')}", min_sample=12)

    def _combo_map(rows, key_fn, enough_min=16, weak_cut=56.0, strong_cut=52.0):
        raw = _rank_group_map(rows, key_fn=key_fn, min_sample=1)
        enough = [x for x in raw if int(_to_float(x.get("sample_size"), 0.0)) >= enough_min]
        sample_limited = [x for x in raw if int(_to_float(x.get("sample_size"), 0.0)) < enough_min]
        underperforming = [x for x in enough if _to_float(x.get("weakness_score"), 0.0) >= weak_cut]
        helping = [x for x in enough if _to_float(x.get("strength_score"), 0.0) >= strong_cut]
        return {
            "enough_evidence_min_sample": int(enough_min),
            "ranked_underperforming": underperforming[:12],
            "ranked_helping": helping[:12],
            "sample_limited_observations": sample_limited[:10],
        }

    current_setup_regime = _combo_map(current_released_rows, key_fn=lambda d: f"{d.get('setup_type')}|{d.get('regime')}", enough_min=18)
    current_persona_regime = _combo_map(current_released_rows, key_fn=lambda d: f"{d.get('persona')}|{d.get('regime')}", enough_min=18)
    current_setup_cap = _combo_map(current_released_rows, key_fn=lambda d: f"{d.get('setup_type')}|{d.get('cap_bucket')}", enough_min=18)
    post_setup_regime = _combo_map(post_released_rows, key_fn=lambda d: f"{d.get('setup_type')}|{d.get('regime')}", enough_min=12)
    post_persona_regime = _combo_map(post_released_rows, key_fn=lambda d: f"{d.get('persona')}|{d.get('regime')}", enough_min=12)
    post_setup_cap = _combo_map(post_released_rows, key_fn=lambda d: f"{d.get('setup_type')}|{d.get('cap_bucket')}", enough_min=12)
    out["weak_point_diagnostics"] = {
        "diagnostic_mode": "current_engine_and_post_change_released_trade_attribution",
        "current_engine": {
            "sample_size": int(len(current_released_rows)),
            "ranked_weak_score_components": current_weak_components,
            "ranked_helpful_score_components": current_strong_components,
            "ranked_follow_through_failure_states": current_follow_rank[:10],
            "ranked_underperforming_persona_regime_setup": [x for x in current_combo_rank if _to_float(x.get("weakness_score"), 0.0) >= 60.0][:12],
            "ranked_best_persona_regime_setup": [x for x in current_combo_rank if _to_float(x.get("strength_score"), 0.0) >= 55.0][:12],
            "combo_maps": {
                "setup_x_regime": current_setup_regime,
                "persona_x_regime": current_persona_regime,
                "setup_x_cap_bucket": current_setup_cap,
            },
        },
        "post_change": {
            "sample_size": int(len(post_released_rows)),
            "ranked_weak_score_components": post_weak_components,
            "ranked_helpful_score_components": post_strong_components,
            "ranked_follow_through_failure_states": post_follow_rank[:10],
            "ranked_underperforming_persona_regime_setup": [x for x in post_combo_rank if _to_float(x.get("weakness_score"), 0.0) >= 60.0][:12],
            "ranked_best_persona_regime_setup": [x for x in post_combo_rank if _to_float(x.get("strength_score"), 0.0) >= 55.0][:12],
            "combo_maps": {
                "setup_x_regime": post_setup_regime,
                "persona_x_regime": post_persona_regime,
                "setup_x_cap_bucket": post_setup_cap,
            },
        },
        "promotion_path_leakage": _promotion_leakage_snapshot(),
        "evidence_quality_note": (
            "current-engine and post-change released-trade diagnostics are evidence-based; long-history metrics are context only"
        ),
    }
    _record_hot_path_timing("current_engine_eval_post_change_ms", (time.perf_counter() - post_t0) * 1000.0)
    _CACHE["current_engine_outcome_evaluation"] = {"data": dict(out), "ts": time.time(), "signature": signature}
    _record_hot_path_timing("current_engine_eval_total_ms", (time.perf_counter() - eval_t0) * 1000.0)
    return out


def _sample_progress_pct(current, required):
    req = max(1.0, _to_float(required, 1.0))
    cur = max(0.0, _to_float(current, 0.0))
    return round(max(0.0, min(100.0, (cur / req) * 100.0)), 2)


def _sample_deficit(current, required):
    return int(max(0.0, _to_float(required, 0.0) - _to_float(current, 0.0)))


def _dominant_runtime_bottleneck(perf_suite):
    timings = ((perf_suite or {}).get("hot_path_timings_ms") or {}) if isinstance(perf_suite, dict) else {}
    rows_fetch = dict(timings.get("top_buys_rows_fetch") or {})
    pack_build = dict(timings.get("top_buys_pack_build") or {})
    learning_total = dict(timings.get("learning_insights_total") or {})
    trade_rows = dict(timings.get("trade_journal_rows_fetch") or {})
    rows_fetch_avg = _to_float(rows_fetch.get("avg_ms"), 0.0)
    rows_fetch_last = _to_float(rows_fetch.get("last_ms"), 0.0)
    rows_fetch_max = _to_float(rows_fetch.get("max_ms"), 0.0)
    pack_avg = max(1.0, _to_float(pack_build.get("avg_ms"), 0.0))
    learning_avg = _to_float(learning_total.get("avg_ms"), 0.0)
    learning_last = _to_float(learning_total.get("last_ms"), 0.0)
    trade_rows_avg = _to_float(trade_rows.get("avg_ms"), 0.0)
    trade_rows_last = _to_float(trade_rows.get("last_ms"), 0.0)
    if rows_fetch_max >= max(5000.0, trade_rows_last * 4.0) and rows_fetch_avg >= max(pack_avg * 4.0, 3000.0):
        return {
            "dominant_bottleneck": "upstream_data_rows_fetch",
            "bottleneck_side": "upstream-data-side",
            "reason": "top_buys_rows_fetch_dominates_remaining_hot_path_cost",
        }
    if trade_rows_last >= 1500.0 and trade_rows_avg >= max(learning_avg * 1.2, 1500.0) and learning_last >= 1000.0:
        return {
            "dominant_bottleneck": "trade_journal_db_fetch",
            "bottleneck_side": "code-side",
            "reason": "trade_journal_rows_fetch_is_still_dominant",
        }
    if rows_fetch_last >= 1000.0 and rows_fetch_last >= max(trade_rows_last * 2.0, 1000.0):
        return {
            "dominant_bottleneck": "upstream_data_rows_fetch",
            "bottleneck_side": "upstream-data-side",
            "reason": "top_buys_rows_fetch_is_the_only_material_live_latency_source",
        }
    return {
        "dominant_bottleneck": "steady_state_balanced",
        "bottleneck_side": "balanced_or_not_material",
        "reason": "no_single_code_side_hot_path_dominates",
    }


def _latest_top_buys_runtime_snapshot():
    with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
        snapshot_payload = dict(_TOP_BUYS_RUNTIME_SNAPSHOT_V1.get("payload") or {})
    if snapshot_payload:
        return snapshot_payload
    cache = _CACHE.get("top_buys", {}) if isinstance(_CACHE.get("top_buys"), dict) else {}
    preferred = dict(cache.get("mode::balanced") or {})
    payload = dict(preferred.get("data") or {})
    if not payload:
        for candidate in cache.values():
            if isinstance(candidate, dict) and isinstance(candidate.get("data"), dict):
                payload = dict(candidate.get("data") or {})
                if payload:
                    break
    return payload


def _top_buys_cached_payload_for_mode(buy_mode, include_trace=None, max_age_seconds=TOP_BUYS_TTL_SECONDS, allow_alt_trace=True):
    cache = _CACHE.get("top_buys", {})
    if not isinstance(cache, dict):
        return None, None, None
    mode = str(buy_mode or "balanced").strip().lower() or "balanced"
    now_ts = time.time()
    candidate_keys = []
    if include_trace is None:
        candidate_keys.extend([f"mode::{mode}::trace::0", f"mode::{mode}::trace::1", f"mode::{mode}"])
    else:
        trace_bit = "1" if bool(include_trace) else "0"
        candidate_keys.append(f"mode::{mode}::trace::{trace_bit}")
        if allow_alt_trace:
            candidate_keys.append(f"mode::{mode}::trace::{'0' if trace_bit == '1' else '1'}")
        candidate_keys.append(f"mode::{mode}")
    candidate_keys.append("mode::balanced")
    seen = set()
    for key in candidate_keys:
        if key in seen:
            continue
        seen.add(key)
        slot = cache.get(key, {})
        if not isinstance(slot, dict):
            continue
        data = slot.get("data")
        if not isinstance(data, dict) or not data:
            continue
        age = now_ts - float(slot.get("ts", 0.0))
        if age <= float(max_age_seconds):
            return dict(data), float(age), str(key)
    return None, None, None


def _top_buys_row_count(payload):
    p = dict(payload or {})
    root_rows = p.get("rows") if isinstance(p.get("rows"), list) else None
    root_top_buys = p.get("top_buys") if isinstance(p.get("top_buys"), list) else None
    stocks_n = int(
        _to_float(
            p.get("stocks_final_count"),
            len(((p.get("stocks") or {}).get("final") or [])),
        )
    )
    crypto_n = int(
        _to_float(
            p.get("crypto_final_count"),
            len(((p.get("crypto") or {}).get("final") or [])),
        )
    )
    nested_n = max(0, stocks_n + crypto_n)
    return max(nested_n, len(root_rows or []), len(root_top_buys or []))


def _top_buys_runtime_snapshot_get():
    with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
        snap = dict(_TOP_BUYS_RUNTIME_SNAPSHOT_V1 or {})
        payload = dict(snap.get("payload") or {})
    created_at = _to_float(snap.get("created_at"), 0.0)
    age = max(0.0, time.time() - created_at) if created_at > 0.0 else None
    return {
        "payload": payload,
        "created_at": created_at,
        "age_seconds": age,
        "source": str(snap.get("source") or ""),
        "build_ms": round(_to_float(snap.get("build_ms"), 0.0), 2),
        "row_count": int(_to_float(snap.get("row_count"), 0.0)),
        "is_partial": bool(snap.get("is_partial", False)),
        "refresh_status": str(snap.get("refresh_status") or "idle"),
        "last_error": str(snap.get("last_error") or ""),
        "available": bool(payload),
    }


def _top_buys_runtime_snapshot_set(payload, *, source="", build_ms=0.0, is_partial=False, refresh_status="idle", last_error=""):
    data = dict(payload or {})
    row_count = _top_buys_row_count(data)
    if row_count <= 0:
        with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
            existing_payload = bool(_TOP_BUYS_RUNTIME_SNAPSHOT_V1.get("payload"))
            if not existing_payload:
                _TOP_BUYS_RUNTIME_SNAPSHOT_V1["last_error"] = _safe_text(last_error, 160)
                _TOP_BUYS_RUNTIME_SNAPSHOT_V1["refresh_status"] = str(refresh_status or "idle")
        return False
    with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["payload"] = data
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["created_at"] = time.time()
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["source"] = str(source or "fresh_build")
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["build_ms"] = round(_to_float(build_ms, 0.0), 2)
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["row_count"] = int(row_count)
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["is_partial"] = bool(is_partial)
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["refresh_status"] = str(refresh_status or "idle")
        _TOP_BUYS_RUNTIME_SNAPSHOT_V1["last_error"] = _safe_text(last_error, 160)
    return True


def _top_buys_mark_real_payload(payload):
    rows_n = _top_buys_row_count(payload)
    if rows_n <= 0:
        return
    with _TOP_BUYS_REAL_STATE_LOCK:
        _TOP_BUYS_REAL_STATE["last_real_rows_count"] = int(rows_n)
        _TOP_BUYS_REAL_STATE["last_non_empty_ts"] = time.time()


def _append_jsonl_safely(path, row):
    try:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(dict(row or {}), default=str, separators=(",", ":")) + "\n")
        return True
    except Exception as exc:
        _CANDIDATE_LEDGER_LAST_ERROR["ts"] = time.time()
        _CANDIDATE_LEDGER_LAST_ERROR["error"] = _safe_text(str(exc), 160)
        return False


def _tail_jsonl_rows(path, max_rows=500):
    out = deque(maxlen=max(1, int(max_rows)))
    try:
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                s = str(line or "").strip()
                if not s:
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                if isinstance(obj, dict):
                    out.append(obj)
    except Exception:
        return []
    return list(out)


def _candidate_rows_from_payload(payload):
    p = dict(payload or {})
    rows = []
    for key in ("rows", "top_buys"):
        existing = p.get(key)
        if isinstance(existing, list):
            rows.extend(existing)
    for bucket in ("stocks", "crypto"):
        b = dict(p.get(bucket) or {})
        rows.extend(list(b.get("final") or []))
        rows.extend(list(b.get("qualified") or []))
        rows.extend(list(b.get("watchlist") or []))
    dedup = {}
    for r in rows:
        if not isinstance(r, dict):
            continue
        sym = str(r.get("symbol") or "").upper().strip()
        if not sym:
            continue
        old = dedup.get(sym)
        if not isinstance(old, dict):
            dedup[sym] = dict(r)
            continue
        old_state = str(old.get("canonical_final_state") or "").strip().lower()
        new_state = str(r.get("canonical_final_state") or "").strip().lower()
        if old_state not in {"released_buy", "paper_ready"} and new_state in {"released_buy", "paper_ready"}:
            dedup[sym] = dict(r)
    return list(dedup.values())


def _day_learning_session_bucket(ts_value=None):
    try:
        dt = datetime.now(UTC) if ts_value is None else datetime.fromtimestamp(float(ts_value), UTC)
        hh = int(dt.hour)
    except Exception:
        hh = 12
    if 13 <= hh < 15:
        return "pre_open"
    if 15 <= hh < 17:
        return "market_open"
    if 17 <= hh < 19:
        return "midday"
    if 19 <= hh < 21:
        return "power_hour"
    return "after_hours"


def _derive_day_learning_candidate_fields(row):
    rr = dict(row or {})
    trusted = bool(rr.get("trusted_quote_for_buys", False))
    valid = bool(rr.get("valid_quote", False))
    signal_decision = str(rr.get("signal_quality_decision") or "").strip().lower()
    timing_decision = str(rr.get("entry_precision_v2_decision") or rr.get("entry_timing_decision") or "").strip().lower()
    setup_band = str(rr.get("setup_detection_band") or "").strip().lower()
    entry_band = str(rr.get("entry_quality_band") or "").strip().lower()
    context_decision = str(rr.get("context_activation_decision") or "").strip().lower()
    hard_reject = signal_decision in {"reject", "monitor_only"} and not bool(rr.get("limited_data_mode", False))
    poor_setup = setup_band == "poor"
    poor_entry = entry_band == "poor"
    allowed_signal = signal_decision in {
        "allow",
        "allow_with_confirmation",
        "watchlist_only",
        "monitor_only",
        "neutral",
        "",
    }
    allowed_timing = timing_decision in {
        "wait_for_confirmation",
        "wait_for_pullback",
        "enter_if_confirmed",
        "immediate",
        "",
    }
    eligible = bool(
        DAY_LEARNING_MODE_ENABLED
        and trusted
        and valid
        and allowed_signal
        and allowed_timing
        and not hard_reject
        and not poor_setup
        and not poor_entry
        and context_decision != "block"
    )
    if timing_decision == "wait_for_confirmation":
        horizon = 30
    elif timing_decision == "wait_for_pullback":
        horizon = 60
    else:
        horizon = 15
    horizon = int(min(max(horizon, min(DAY_LEARNING_SHORT_HORIZONS_MINUTES)), max(DAY_LEARNING_SHORT_HORIZONS_MINUTES)))
    priority = 0.0
    priority += _to_float(rr.get("entry_quality_score"), 0.0) * 0.35
    priority += _to_float(rr.get("signal_quality_score"), 0.0) * 0.35
    priority += _to_float(rr.get("entry_precision_v2_score"), _to_float(rr.get("entry_timing_score"), 0.0)) * 0.2
    if bool(rr.get("limited_data_mode", False)):
        priority -= 6.0
    if timing_decision in {"wait_for_confirmation", "wait_for_pullback"}:
        priority += 3.0
    priority = max(0.0, min(100.0, priority))
    reason = "not_eligible"
    if eligible:
        reason = "paper_only_intraday_learning_candidate"
    elif not trusted or not valid:
        reason = "quote_not_trusted_or_invalid"
    elif hard_reject:
        reason = "hard_reject"
    elif poor_setup or poor_entry:
        reason = "poor_setup_or_entry"
    elif context_decision == "block":
        reason = "context_block"
    return {
        "day_learning_candidate": bool(eligible),
        "day_learning_horizon_minutes": int(horizon),
        "day_learning_session_bucket": _day_learning_session_bucket(time.time()),
        "day_learning_entry_context": str(timing_decision or signal_decision or "unknown"),
        "day_learning_reason": str(reason),
        "day_learning_priority_score": round(priority, 2),
    }


