def _schedule_current_engine_outcome_eval_refresh(force=False):
    now = time.time()
    if bool(_CURRENT_ENGINE_EVAL_ASYNC_STATE.get("in_progress", False)):
        return False
    if (
        not force
        and (now - float(_CURRENT_ENGINE_EVAL_ASYNC_STATE.get("last_kick_ts", 0.0))) < CURRENT_ENGINE_EVAL_ASYNC_KICK_COOLDOWN_SECONDS
    ):
        return False

    def _runner():
        with _CURRENT_ENGINE_EVAL_ASYNC_LOCK:
            _CURRENT_ENGINE_EVAL_ASYNC_STATE["in_progress"] = True
            try:
                _current_engine_outcome_evaluation()
            except Exception:
                pass
            finally:
                _CURRENT_ENGINE_EVAL_ASYNC_STATE["in_progress"] = False

    _CURRENT_ENGINE_EVAL_ASYNC_STATE["last_kick_ts"] = now
    try:
        threading.Thread(target=_runner, daemon=True).start()
        return True
    except Exception:
        _CURRENT_ENGINE_EVAL_ASYNC_STATE["in_progress"] = False
        return False


def _get_current_engine_outcome_eval_fast():
    cached = _CACHE.get("current_engine_outcome_evaluation", {})
    cached_data = dict(cached.get("data") or {}) if isinstance(cached.get("data"), dict) else {}
    age = max(0.0, time.time() - float(cached.get("ts", 0.0)))
    signature = _trade_journal_outcome_signature()
    fresh = bool(cached_data) and cached.get("signature") == signature and age <= 90.0
    if fresh:
        return cached_data

    # Keep endpoint latency bounded: refresh expensive outcome evaluation async.
    _schedule_current_engine_outcome_eval_refresh(force=not bool(cached_data))

    if cached_data:
        out = dict(cached_data)
        out["stale_cache"] = True
        out["stale_cache_reason"] = "current_engine_eval_async_refresh"
        out["stale_cache_age_seconds"] = round(age, 2)
        out["current_engine_eval_async_in_progress"] = bool(_CURRENT_ENGINE_EVAL_ASYNC_STATE.get("in_progress", False))
        return out

    out = _default_current_engine_outcome_eval_payload()
    out["current_engine_eval_warming_up"] = True
    out["current_engine_eval_async_in_progress"] = bool(_CURRENT_ENGINE_EVAL_ASYNC_STATE.get("in_progress", False))
    return out


def _build_hold_measure_status(payload, eval_payload):
    perf_suite = dict((payload or {}).get("performance_optimization_suite") or _performance_optimization_snapshot())
    post_min = dict((eval_payload or {}).get("post_change_min_sample_requirements") or {})
    post_sizes = dict((eval_payload or {}).get("post_change_sample_sizes") or {})
    current_sizes = dict((eval_payload or {}).get("cohort_sample_sizes") or {})
    current_mode = str((eval_payload or {}).get("cohort_mode") or "unavailable")
    post_mode = str((eval_payload or {}).get("post_change_cohort_mode") or "unavailable")
    top_payload = _latest_top_buys_runtime_snapshot()
    top_views = dict((top_payload or {}).get("top_action_views") or {})
    hero_rows = list((top_views.get("hero_candidates") or []))
    if not hero_rows:
        hero_rows = list((((top_payload or {}).get("stocks") or {}).get("final") or []) + (((top_payload or {}).get("crypto") or {}).get("final") or []))
    top_snapshot_available = bool(top_payload)
    released_hero_count = int(_to_float((top_payload or {}).get("released_hero_count"), 0.0))
    all_trusted = bool((top_payload or {}).get("all_top_trusted_for_buys", False))
    hero_label_violations = int(_to_float((top_payload or {}).get("hero_junk_label_violations"), 0.0))
    blocked_label_violations = int(_to_float((top_payload or {}).get("blocked_shown_as_buy_violations"), 0.0))
    confirmation_null = sum(1 for row in hero_rows if not str((row or {}).get("confirmation_state") or "").strip())
    follow_null = sum(1 for row in hero_rows if not str((row or {}).get("follow_through_state") or "").strip())
    setup_null = sum(1 for row in hero_rows if not str((row or {}).get("setup_type") or "").strip())
    trade_scores = [_to_float((row or {}).get("trade_quality_score"), 0.0) for row in hero_rows if _to_float((row or {}).get("trade_quality_score"), 0.0) > 0.0]
    trade_range = 0.0
    if trade_scores:
        trade_range = max(trade_scores) - min(trade_scores)
    top_total_timing = dict(((perf_suite.get("hot_path_timings_ms") or {}).get("top_buys_total") or {}))
    learning_timing = dict(((perf_suite.get("hot_path_timings_ms") or {}).get("learning_insights_total") or {}))
    top_total_last = _to_float(top_total_timing.get("last_ms"), 0.0)
    learning_last = _to_float(learning_timing.get("last_ms"), 0.0)
    learning_avg = _to_float(learning_timing.get("avg_ms"), 0.0)
    learning_max = _to_float(learning_timing.get("max_ms"), 0.0)
    learning_samples = int(_to_float(learning_timing.get("samples"), 0.0))
    warm_error = str(((perf_suite.get("runtime_warmup_state") or {}).get("last_error")) or "")
    bottleneck = _dominant_runtime_bottleneck(perf_suite)
    bottleneck_side = str(bottleneck.get("bottleneck_side") or "")

    release_zero_collapse_regression = bool(top_snapshot_available and released_hero_count <= 0)
    trust_integrity_regression = bool(top_snapshot_available and not all_trusted)
    hero_label_integrity_regression = bool(top_snapshot_available and (hero_label_violations > 0 or blocked_label_violations > 0))
    upstream_truthfulness_regression = bool(top_snapshot_available and (confirmation_null > 0 or follow_null > 0 or setup_null > 0 or trade_range < 5.0))
    learning_evaluator_regression = bool(
        current_mode in {"", "unavailable", "insufficient_data"}
        or post_mode in {"", "unavailable"}
        or "post_change_evidence_ready" not in (eval_payload or {})
        or "post_change_confidence_ready" not in (eval_payload or {})
    )
    learning_persistently_slow = bool(
        learning_samples >= 10
        and learning_last >= 7000.0
        and learning_avg >= 2200.0
        and learning_max >= 7000.0
        and bottleneck_side == "code-side"
    )
    top_buys_code_side_slow = bool(
        top_total_last >= 10000.0
        and bottleneck_side == "code-side"
    )
    runtime_regression = bool(
        warm_error
        or learning_persistently_slow
        or top_buys_code_side_slow
    )

    released_req = int(_to_float(post_min.get("released"), 30.0))
    paper_req = int(_to_float(post_min.get("paper_ready"), 30.0))
    blocked_req = int(_to_float(post_min.get("blocked_watchlist"), 30.0))
    high_req = int(_to_float(post_min.get("released_high_confidence"), 20.0))
    medium_req = int(_to_float(post_min.get("released_medium_confidence"), 20.0))

    released_progress = _sample_progress_pct(post_sizes.get("released"), released_req)
    paper_progress = _sample_progress_pct(post_sizes.get("paper_ready"), paper_req)
    blocked_progress = _sample_progress_pct(post_sizes.get("blocked_watchlist"), blocked_req)
