def _run_learning_loop_auto_labeler_once_v1(force=False):
    with _OUTCOME_LABELING_RUN_LOCK:
        _LEARNING_LOOP_AUTO_STATE["running"] = True
        _LEARNING_LOOP_AUTO_STATE["last_run"] = _now_utc_iso()
        _LEARNING_LOOP_AUTO_STATE["last_error"] = ""
        _LEARNING_LOOP_AUTO_STATE["runs_count"] = int(_to_float(_LEARNING_LOOP_AUTO_STATE.get("runs_count"), 0.0)) + 1
        try:
            try:
                if not os.path.exists(CANDIDATE_DECISION_LEDGER_PATH):
                    return {"ran": False, "reason": "ledger_missing", "labeled_rows": 0, "weights_updated": False}
                if os.path.getsize(CANDIDATE_DECISION_LEDGER_PATH) <= 0:
                    return {"ran": False, "reason": "ledger_empty", "labeled_rows": 0, "weights_updated": False}
                ledger_mtime = _to_float(os.path.getmtime(CANDIDATE_DECISION_LEDGER_PATH), 0.0)
                outcome_mtime = _to_float(os.path.getmtime(OUTCOME_LABELS_PATH), 0.0) if os.path.exists(OUTCOME_LABELS_PATH) else 0.0
            except Exception:
                return {"ran": False, "reason": "ledger_unavailable", "labeled_rows": 0, "weights_updated": False}
            if not bool(force):
                last_ledger_mtime = _to_float(_LEARNING_LOOP_AUTO_STATE.get("last_ledger_mtime"), 0.0)
                last_outcome_mtime = _to_float(_LEARNING_LOOP_AUTO_STATE.get("last_outcome_mtime"), 0.0)
                if ledger_mtime <= last_ledger_mtime and outcome_mtime <= last_outcome_mtime:
                    return {"ran": False, "reason": "no_new_rows", "labeled_rows": 0, "weights_updated": False}

            result = _run_outcome_labeling_pass_v1(
                horizon_minutes=LEARNING_LOOP_AUTO_DEFAULT_HORIZON_MINUTES,
                max_rows=LEARNING_LOOP_AUTO_DEFAULT_MAX_ROWS,
                dry_run=False,
                ensure_rankings=False,
            )
            labels_created = int(_to_float(result.get("labels_created"), 0.0))
            weights_updated = bool(result.get("weights_updated", False))
            _LEARNING_LOOP_AUTO_STATE["last_ledger_mtime"] = float(ledger_mtime)
            _LEARNING_LOOP_AUTO_STATE["last_outcome_mtime"] = _to_float(
                os.path.getmtime(OUTCOME_LABELS_PATH), _to_float(outcome_mtime, 0.0)
            ) if os.path.exists(OUTCOME_LABELS_PATH) else _to_float(outcome_mtime, 0.0)
            _LEARNING_LOOP_AUTO_STATE["labeled_count_last_run"] = int(labels_created)
            _LEARNING_LOOP_AUTO_STATE["last_error"] = str(result.get("last_error") or "")
            if labels_created > 0 or weights_updated:
                _LEARNING_LOOP_AUTO_STATE["last_success"] = _now_utc_iso()
            return {
                "ran": True,
                "reason": "ok",
                "labeled_rows": int(labels_created),
                "weights_updated": bool(weights_updated),
                "result": result,
            }
        finally:
            _LEARNING_LOOP_AUTO_STATE["running"] = False


def _run_learning_loop_auto_labeler_v1():
    while True:
        try:
            _run_learning_loop_auto_labeler_once_v1(force=False)
        except Exception as exc:
            _LEARNING_LOOP_AUTO_STATE["last_error"] = _safe_text(f"auto_labeler_run_failed:{exc}", 180)
        time.sleep(max(30.0, _to_float(LEARNING_LOOP_AUTO_INTERVAL_SECONDS, 300.0)))


def _start_learning_loop_auto_labeler_v1():
    with _LEARNING_LOOP_AUTO_LOCK:
        if bool(_LEARNING_LOOP_AUTO_STATE.get("thread_started", False)):
            return False
        _LEARNING_LOOP_AUTO_STATE["thread_started"] = True
        threading.Thread(target=_run_learning_loop_auto_labeler_v1, daemon=True).start()
        return True


@router.on_event("startup")
def _learning_loop_auto_labeler_startup():
    try:
        _start_learning_loop_auto_labeler_v1()
    except Exception:
        pass


def _runtime_warmup_job():
    warm_t0 = time.perf_counter()
    _WARMUP_STATE["started"] = True
    _WARMUP_STATE["finished"] = False
    _WARMUP_STATE["last_error"] = ""
    try:
        time.sleep(0.75)
        _ensure_latest_rankings()
        lightweight_warmup = str(os.getenv("ASTRA_LIGHTWEIGHT_WARMUP", "1")).strip().lower() in {"1", "true", "yes", "on"}
        if not lightweight_warmup:
            try:
                _get_enriched_learning_insights_cached(force=True)
            except Exception:
                pass
            try:
                _current_engine_outcome_evaluation()
            except Exception:
                pass
            try:
                _get_trade_journal_outcome_rows_cached()
            except Exception:
                pass
    except Exception as exc:
        _WARMUP_STATE["last_error"] = str(exc)[:160]
    finally:
        duration_ms = (time.perf_counter() - warm_t0) * 1000.0
        _WARMUP_STATE["last_duration_ms"] = duration_ms
        _WARMUP_STATE["finished"] = True
        _record_hot_path_timing("runtime_warmup_ms", duration_ms)


def _schedule_runtime_warmup():
    if bool(_WARMUP_STATE.get("started")):
        return
    _WARMUP_STATE["started"] = True
    threading.Thread(target=_runtime_warmup_job, daemon=True).start()


def _apply_learning_tab_consistency(payload, eval_payload):
    if not isinstance(payload, dict):
        return payload
    out = dict(payload)
    top_payload = _latest_top_buys_runtime_snapshot()
    stock_final = list((((top_payload or {}).get("stocks") or {}).get("final") or []))
    crypto_final = list((((top_payload or {}).get("crypto") or {}).get("final") or []))
    final_rows = stock_final + crypto_final
    top_views = ((top_payload or {}).get("top_action_views") or {})
    hero_rows = list(
        list(top_views.get("stocks_buy_first_hero_candidates") or [])
        + list(top_views.get("crypto_buy_first_hero_candidates") or [])
    )
    released = int(_to_float((top_payload or {}).get("released_hero_count"), 0.0))
    paper_ready = int(_to_float((top_payload or {}).get("paper_ready_hero_count"), 0.0))
    blocked = int(_to_float((top_payload or {}).get("blocked_hero_count"), 0.0))
    watch = int(_to_float((top_payload or {}).get("watchlist_hero_count"), 0.0))
    a_b_ranked = int(len(final_rows) + blocked + watch)
    a_b_promoted = int(len(final_rows))
    a_b_blocked = int(blocked + watch)

    actionable_engine = dict(out.get("actionable_vs_interesting_engine") or {})
    entry_engine = dict(out.get("entry_quality_engine") or {})
    strict_entry = dict(out.get("strict_entry_quality_engine") or {})
    follow_suite = dict(out.get("follow_through_entry_quality_suite") or {})
    weak_follow = dict(out.get("weak_follow_through_learning") or {})
    repair_engine = dict(out.get("confirmation_followthrough_repair_engine") or {})
    hero_suite = dict(out.get("hero_outcome_quality_suite") or {})
    sell_timing = dict(out.get("sell_timing_accuracy_suite") or {})
    sell_truth = dict(out.get("sell_truthfulness_learning_suite") or {})
    continuity = dict(out.get("buy_position_sell_continuity_suite") or {})
    a_b_release = dict(out.get("a_b_release_quality_suite") or {})
    a_b_reduce = dict(out.get("a_b_block_reduction_engine") or {})
    a_b_balance = dict(out.get("a_b_release_balance_engine") or {})

    out["actionability_quality_suite"] = {
        "a_b_ranked": int(a_b_ranked),
        "a_b_promoted": int(a_b_promoted),
        "a_b_blocked": int(a_b_blocked),
        "buy_list_purity_score": round(_to_float(actionable_engine.get("buy_list_purity_score"), 0.0), 2),
        "actionable_vs_interesting_score": round(_to_float(actionable_engine.get("actionable_vs_interesting_score"), 0.0), 2),
    }
    out["entry_execution_quality"] = {
        "entry_quality_score": round(_to_float(entry_engine.get("entry_quality_score"), 0.0), 2),
        "strict_entry_quality_score": round(_to_float(strict_entry.get("strict_entry_quality_score"), 0.0), 2),
        "confirmation_strength_score": round(_to_float(strict_entry.get("confirmation_strength_score"), _to_float(entry_engine.get("confirmation_entry_quality_score"), 0.0)), 2),
        "poor_entry_reduction_score": round(_to_float(strict_entry.get("poor_entry_reduction_score"), _to_float(entry_engine.get("bad_entry_suppression_score"), 0.0)), 2),
        "live_hero_entry_followthrough_avg": round(
            (
                sum(_to_float((r or {}).get("entry_followthrough_quality_score"), 0.0) for r in hero_rows)
                / max(1, len(hero_rows))
            ),
            2,
        ),
    }
    out["followthrough_quality"] = {
        "follow_through_entry_score": round(_to_float(follow_suite.get("follow_through_entry_score"), _to_float(entry_engine.get("follow_through_entry_score"), 0.0)), 2),
        "weak_follow_through_score": round(_to_float(weak_follow.get("weak_follow_through_score"), 0.0), 2),
        "breakout_separation_score": round(_to_float(repair_engine.get("breakout_separation_score"), 0.0), 2),
        "live_hero_weak_follow_count": int(
            sum(
                1
                for r in hero_rows
                if "weak" in str((r or {}).get("follow_through_state") or "").strip().lower()
            )
        ),
    }
    out["released_hero_quality_suite"] = {
        "released_hero_count": int(released),
        "paper_ready_hero_count": int(paper_ready),
        "blocked_hero_count": int(blocked),
        "watchlist_hero_count": int(watch),
        "released_hero_quality_score": round(_to_float(hero_suite.get("hero_outcome_quality_score"), 0.0), 2),
        "released_hero_win_rate": _to_float((eval_payload or {}).get("released_hero_win_rate"), _to_float(out.get("released_hero_win_rate"), 0.0)),
        "paper_ready_win_rate": _to_float((eval_payload or {}).get("paper_ready_win_rate"), _to_float(out.get("paper_ready_win_rate"), 0.0)),
        "blocked_watchlist_win_rate": _to_float((eval_payload or {}).get("blocked_watchlist_win_rate"), _to_float(out.get("blocked_watchlist_win_rate"), 0.0)),
        "released_vs_blocked_win_rate_delta": _to_float((eval_payload or {}).get("released_vs_blocked_win_rate_delta"), _to_float(out.get("released_vs_blocked_win_rate_delta"), 0.0)),
    }
    out["sell_signal_quality"] = {
        "sell_signal_accuracy_score": round(_to_float(sell_timing.get("sell_accuracy_score"), 0.0), 2),
        "sell_truthfulness_score": round(_to_float(sell_truth.get("sell_truthfulness_score"), 0.0), 2),
        "late_sell_rate": round(_to_float(sell_timing.get("late_sell_rate"), 0.0), 2),
        "premature_sell_rate": round(_to_float(sell_timing.get("premature_sell_rate"), 0.0), 2),
    }
    out["sell_signal_accuracy"] = round(_to_float(sell_timing.get("sell_accuracy_score"), 0.0), 2)
    out["position_quality_summary"] = {
        "candidate_to_position_consistency_score": round(_to_float(continuity.get("candidate_to_position_consistency_score"), 0.0), 2),
        "position_to_sell_consistency_score": round(_to_float(continuity.get("position_to_sell_consistency_score"), 0.0), 2),
        "buy_to_exit_workflow_quality_score": round(_to_float(continuity.get("buy_to_exit_workflow_quality_score"), 0.0), 2),
    }
    out["top_action_views_health"] = {
        "final_rows_count": int(len(final_rows)),
        "a_b_ranked": int(a_b_ranked),
        "a_b_promoted": int(a_b_promoted),
        "a_b_blocked": int(a_b_blocked),
        "all_top_trusted_for_buys": bool((top_payload or {}).get("all_top_trusted_for_buys", False)),
        "hero_junk_label_violations": int(_to_float((top_payload or {}).get("hero_junk_label_violations"), 0.0)),
        "blocked_shown_as_buy_violations": int(_to_float((top_payload or {}).get("blocked_shown_as_buy_violations"), 0.0)),
    }
    out["release_quality_guardrail_status"] = {
        "released_nonzero": bool(released > 0),
        "trust_integrity_clean": bool((top_payload or {}).get("all_top_trusted_for_buys", False)),
        "label_integrity_clean": bool(
            int(_to_float((top_payload or {}).get("hero_junk_label_violations"), 0.0)) == 0
            and int(_to_float((top_payload or {}).get("blocked_shown_as_buy_violations"), 0.0)) == 0
        ),
        "hero_quality_enforcement_score": round(_to_float((out.get("hero_quality_enforcement_gate") or {}).get("hero_quality_enforcement_score"), 0.0), 2),
    }
    out["strong_buy_actionability_recalibration"] = {
        "a_b_release_quality_score": round(_to_float(a_b_release.get("a_b_release_quality_score"), 0.0), 2),
        "a_b_block_reduction_score": round(_to_float(a_b_reduce.get("a_b_block_reduction_score"), 0.0), 2),
        "a_b_release_balance_score": round(_to_float(a_b_balance.get("a_b_release_balance_score"), 0.0), 2),
        "actionable_a_b_release_rate": round((a_b_promoted / max(1, a_b_ranked)) * 100.0, 2),
        "paper_ready_a_b_release_rate": round((paper_ready / max(1, a_b_ranked)) * 100.0, 2),
    }
    out["post_change_current_engine_quality_gate"] = {
        "post_change_cohort_mode": str((eval_payload or {}).get("post_change_cohort_mode") or ""),
        "post_change_cohort_start_utc": str((eval_payload or {}).get("post_change_cohort_start_utc") or ""),
        "post_change_sample_sizes": dict((eval_payload or {}).get("post_change_sample_sizes") or {}),
        "post_change_released_win_rate": _to_float((eval_payload or {}).get("post_change_released_win_rate"), 0.0),
        "post_change_paper_ready_win_rate": _to_float((eval_payload or {}).get("post_change_paper_ready_win_rate"), 0.0),
        "post_change_blocked_watchlist_win_rate": _to_float((eval_payload or {}).get("post_change_blocked_watchlist_win_rate"), 0.0),
        "post_change_released_expectancy": _to_float((eval_payload or {}).get("post_change_released_expectancy"), 0.0),
        "post_change_released_fast_loss_rate": _to_float((eval_payload or {}).get("post_change_released_fast_loss_rate"), 0.0),
        "post_change_high_confidence_win_rate": _to_float((eval_payload or {}).get("post_change_high_confidence_win_rate"), 0.0),
        "post_change_medium_confidence_win_rate": _to_float((eval_payload or {}).get("post_change_medium_confidence_win_rate"), 0.0),
        "post_change_confidence_comparison_reliable": bool((eval_payload or {}).get("post_change_confidence_comparison_reliable", False)),
        "post_change_cohort_quality_note": str((eval_payload or {}).get("post_change_cohort_quality_note") or ""),
        "post_change_evidence_ready": bool((eval_payload or {}).get("post_change_evidence_ready", False)),
        "post_change_confidence_ready": bool((eval_payload or {}).get("post_change_confidence_ready", False)),
    }
    out["astra_operating_standard"] = {
        "stable_runtime": bool(not bool((out.get("regression_alarms") or {}).get("runtime_regression", False))),
        "trusted_actionability": bool((top_payload or {}).get("all_top_trusted_for_buys", False)),
        "label_integrity_clean": bool(
            int(_to_float((top_payload or {}).get("hero_junk_label_violations"), 0.0)) == 0
            and int(_to_float((top_payload or {}).get("blocked_shown_as_buy_violations"), 0.0)) == 0
        ),
        "nonzero_actionable_output": bool(released > 0),
        "entry_quality_score": round(_to_float(entry_engine.get("entry_quality_score"), 0.0), 2),
        "follow_through_quality_score": round(_to_float((out.get("followthrough_quality") or {}).get("follow_through_entry_score"), 0.0), 2),
        "sell_signal_quality_score": round(_to_float((out.get("sell_signal_quality") or {}).get("sell_signal_accuracy_score"), 0.0), 2),
        "learning_truthfulness_status": str((out.get("learning_system_status") or {}).get("status") or "unknown"),
        "operating_standard_met": bool(
            released > 0
            and bool((top_payload or {}).get("all_top_trusted_for_buys", False))
            and int(_to_float((top_payload or {}).get("hero_junk_label_violations"), 0.0)) == 0
            and int(_to_float((top_payload or {}).get("blocked_shown_as_buy_violations"), 0.0)) == 0
            and _to_float(entry_engine.get("entry_quality_score"), 0.0) >= 35.0
            and _to_float((out.get("followthrough_quality") or {}).get("follow_through_entry_score"), 0.0) >= 45.0
        ),
    }
    return out


