@router.get("/api/paper_status")
def paper_status():
    _ensure_paper_autopilot_started()
    try:
        PAPER_AUTOPILOT.refresh_enabled_from_state()
    except Exception:
        pass
    cached = _CACHE.get("paper_status", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= PAPER_STATUS_TTL_SECONDS:
        payload = dict(cached.get("data", {}))
        payload["cached"] = True
        return payload
    if _paper_endpoint_recent_failure("paper_status"):
        stale_payload = _paper_endpoint_stale_payload("paper_status")
        if stale_payload:
            return stale_payload

    have_lock = _PAPER_STATUS_BUILD_LOCK.acquire(blocking=False)
    if not have_lock:
        stale_payload = _paper_endpoint_stale_payload("paper_status")
        if stale_payload:
            stale_payload["stale_cache_reason"] = "paper_status_build_in_progress"
            return stale_payload
        have_lock = _PAPER_STATUS_BUILD_LOCK.acquire(timeout=0.35)
    try:
        payload = PAPER_AUTOPILOT.status()
        payload.update(PAPER_AUTOPILOT.control_status())
        payload["worker"] = _paper_worker_status_payload()
        payload["last_trade_opened_timestamp"] = (payload.get("worker") or {}).get("last_trade_opened_timestamp")
        payload["last_trade_closed_timestamp"] = (payload.get("worker") or {}).get("last_trade_closed_timestamp")
        payload["closed_trade_learning_feed_available"] = bool((payload.get("worker") or {}).get("closed_trade_learning_feed_available", False))
        payload["lifecycle_learning_active"] = bool((payload.get("worker") or {}).get("lifecycle_learning_active", False))
        payload["day_learning_mode_enabled"] = bool((payload.get("worker") or {}).get("day_learning_mode_enabled", DAY_LEARNING_MODE_ENABLED))
        payload["day_learning_paper_only"] = bool((payload.get("worker") or {}).get("day_learning_paper_only", DAY_LEARNING_MODE_PAPER_ONLY))
        payload["day_learning_active"] = bool((payload.get("worker") or {}).get("day_learning_active", False))
        payload["day_learning_horizons_minutes"] = list((payload.get("worker") or {}).get("day_learning_horizons_minutes") or DAY_LEARNING_SHORT_HORIZONS_MINUTES)
        payload["day_learning_max_open_positions"] = int(
            _to_float((payload.get("worker") or {}).get("day_learning_max_open_positions"), DAY_LEARNING_MAX_OPEN_DAY_LEARNING_POSITIONS)
        )
        payload["day_trade_mode_enabled"] = bool((payload.get("worker") or {}).get("day_trade_mode_enabled", DAY_TRADING_LIFECYCLE_MODE_ENABLED))
        payload["same_day_exit_required"] = bool((payload.get("worker") or {}).get("same_day_exit_required", FORCE_CLOSE_ALL_PAPER_POSITIONS_BEFORE_MARKET_CLOSE))
        payload["entry_cutoff_time_et"] = str((payload.get("worker") or {}).get("entry_cutoff_time_et") or NO_NEW_ENTRIES_AFTER_ET)
        payload["force_close_time_et"] = str((payload.get("worker") or {}).get("force_close_time_et") or FORCE_CLOSE_TIME_ET)
        payload["max_day_trade_hold_minutes"] = int(_to_float((payload.get("worker") or {}).get("max_day_trade_hold_minutes"), MAX_DAY_TRADE_HOLD_MINUTES))
        payload["forced_end_of_day_exit"] = bool((payload.get("worker") or {}).get("forced_end_of_day_exit", False))
        payload["forced_end_of_day_exit_reason"] = str((payload.get("worker") or {}).get("forced_end_of_day_exit_reason") or "")
        payload["holding_minutes"] = round(_to_float((payload.get("worker") or {}).get("holding_minutes"), 0.0), 2)
        payload["overnight_hold_blocked"] = bool((payload.get("worker") or {}).get("overnight_hold_blocked", False))
        payload["day_trade_lifecycle_status"] = str((payload.get("worker") or {}).get("day_trade_lifecycle_status") or "disabled")
        payload["session_type"] = str((payload.get("worker") or {}).get("session_type") or _market_session_type_et(datetime.now(UTC)))
        payload["session_learning_weight"] = float(_to_float((payload.get("worker") or {}).get("session_learning_weight"), _session_learning_weight(payload.get("session_type"))))
        payload["session_hold_limit_minutes"] = int(_to_float((payload.get("worker") or {}).get("session_hold_limit_minutes"), _session_hold_limit_minutes(payload.get("session_type"))))
        payload["session_exit_reason"] = str((payload.get("worker") or {}).get("session_exit_reason") or "")
        payload["cached"] = False
        payload["degraded_db_access"] = False
        payload["last_updated_utc"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        _CACHE["paper_status"] = {"data": dict(payload), "ts": time.time()}
        return payload
    except sqlite3.OperationalError as exc:
        err_code = _paper_endpoint_error_code(exc)
        _paper_endpoint_note_failure("paper_status", err_code)
        stale_payload = _paper_endpoint_stale_payload("paper_status")
        if stale_payload:
            stale_payload["degraded_reason"] = err_code
            stale_payload["error"] = err_code
            return stale_payload
        worker_payload = _paper_worker_status_payload()
        return {
            "cached": False,
            "degraded_db_access": True,
            "degraded_reason": err_code,
            "worker": worker_payload,
            "autopilot_enabled": bool(worker_payload.get("autopilot_enabled", False)),
            "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "fallback_minimal_payload": True,
        }
    finally:
        if have_lock:
            _PAPER_STATUS_BUILD_LOCK.release()


