@router.post("/api/ollama/explain")
def ollama_explain(payload: dict = Body(...)):
    data = payload if isinstance(payload, dict) else {}
    question = str(data.get("question") or "").strip()
    if not question:
        return {"ok": False, "error": "question_required"}

    status = _ollama_models_status_cached(force=True)
    model = str(data.get("model") or status.get("selected_model") or "").strip()
    if not status.get("available"):
        return {"ok": False, "error": "ollama_not_available", "status": status}
    if not model:
        return {"ok": False, "error": "no_local_model_available", "status": status}

    context = {
        "system_status": system_status(),
        "top_buys": top_buys(buy_mode=str(data.get("buy_mode") or "balanced")),
        "positions": positions(),
        "sell_alerts": position_sell_alerts(),
        "learning_insights": learning_insights(),
    }
    compact_context = {
        "system_status": {
            "live_buy_universe_size": context["system_status"].get("live_buy_universe_size"),
            "live_buy_valid_quote_count": context["system_status"].get("live_buy_valid_quote_count"),
            "tier1_trusted_quote_count": context["system_status"].get("tier1_trusted_quote_count"),
            "tier1_trusted_live_quote_count": context["system_status"].get("tier1_trusted_live_quote_count"),
            "tier1_trusted_cached_quote_count": context["system_status"].get("tier1_trusted_cached_quote_count"),
            "provider_success_count_by_provider": context["system_status"].get("provider_success_count_by_provider"),
            "alpaca_ws_running": context["system_status"].get("alpaca_ws_running"),
            "alpaca_ws_active_symbol_count": context["system_status"].get("alpaca_ws_active_symbol_count"),
        },
        "top_buys": {
            "stocks_final_count": len(((context["top_buys"].get("stocks") or {}).get("final") or [])),
            "crypto_final_count": len(((context["top_buys"].get("crypto") or {}).get("final") or [])),
            "all_top_trusted_for_buys": bool(context["top_buys"].get("all_top_trusted_for_buys", False)),
            "sample_stocks": (((context["top_buys"].get("stocks") or {}).get("final") or [])[:3]),
            "sample_crypto": (((context["top_buys"].get("crypto") or {}).get("final") or [])[:3]),
        },
        "positions": {
            "open_count": int(context["positions"].get("total_open_positions", 0)),
            "sample": (context["positions"].get("positions") or [])[:4],
        },
        "sell_alerts": {
            "count": int(context["sell_alerts"].get("alert_count", 0)),
            "sample": (context["sell_alerts"].get("alerts") or [])[:4],
        },
        "learning": {
            "generated_at": (context["learning_insights"] or {}).get("generated_at"),
            "overall_trend": ((context["learning_insights"] or {}).get("high_level_summary") or {}).get("overall_trend"),
            "quality_score": ((context["learning_insights"] or {}).get("learning_quality") or {}).get("quality_score"),
            "hard_vs_soft_action": ((context["learning_insights"] or {}).get("buy_quality_policy") or {}).get("action"),
            "readiness_tier": ((context["learning_insights"] or {}).get("execution_readiness_controls") or {}).get("readiness_tier"),
        },
    }

    prompt = (
        "You are Astra local operator intelligence. "
        "Answer concisely and with clear bullets. "
        "Use only provided JSON context. "
        "Explain rationale, blockers, and next actions.\n\n"
        f"Question: {question}\n\n"
        f"Context JSON:\n{json.dumps(compact_context, ensure_ascii=True)}"
    )
    try:
        proc = subprocess.run(
            [status.get("binary_path") or "ollama", "run", model, prompt],
            capture_output=True,
            text=True,
            timeout=70,
            check=False,
        )
        if proc.returncode != 0:
            return {
                "ok": False,
                "error": (proc.stderr or proc.stdout or f"ollama_exit_{proc.returncode}").strip()[:280],
                "model": model,
            }
        answer = (proc.stdout or "").strip()
        return {
            "ok": True,
            "model": model,
            "answer": answer,
            "answer_preview": answer[:500],
            "last_updated_utc": _now_utc_iso(),
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:280], "model": model}


@router.get("/api/market_regime")
def market_regime():
    cached = _CACHE.get("market_regime", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= MARKET_REGIME_TTL_SECONDS:
        payload = dict(cached.get("data", {}))
        payload["cached"] = True
        return payload
    payload = REGIME_ENGINE.market_regime_snapshot()
    payload["cached"] = False
    payload["last_updated_utc"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    _CACHE["market_regime"] = {"data": dict(payload), "ts": time.time()}
    return payload


@router.post("/api/paper_toggle")
def paper_toggle(payload: dict = Body(...)):
    _ensure_paper_autopilot_started()
    data = payload if isinstance(payload, dict) else {}
    enabled = data.get("enabled")
    if enabled is None:
        enabled = not PAPER_AUTOPILOT.enabled()
    mode = str(data.get("paper_mode") or "").strip().lower()
    if mode in {"intraday", "swing"}:
        PAPER_AUTOPILOT.paper_mode = mode
    out = PAPER_AUTOPILOT.toggle(bool(enabled))
    # Trigger a light cycle immediately when enabling.
    if out.get("autopilot_enabled", False):
        try:
            PAPER_AUTOPILOT.run_cycle()
        except Exception:
            pass
    _CACHE["paper_status"] = {"data": None, "ts": 0.0}
    _CACHE["paper_performance"] = {"data": None, "ts": 0.0}
    return {
        **out,
        "paper_mode": PAPER_AUTOPILOT.paper_mode,
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }


@router.post("/api/paper_autopilot/start")
def paper_autopilot_start():
    _ensure_paper_autopilot_started()
