@router.post("/api/paper_replay/run")
def paper_replay_run(payload: dict = Body(None)):
    trainer = _ensure_paper_replay_trainer()
    cfg = payload if isinstance(payload, dict) else {}
    cohort_runs = max(1, min(12, int(cfg.get("cohort_runs", 1) or 1)))
    base_seed = int(cfg.get("seed", int(time.time()) % 100000))

    def _run_single(run_cfg):
        result_local = trainer.run(run_cfg)
        if not result_local.get("ok"):
            return result_local
        return result_local

    if cohort_runs == 1:
        result = _run_single(cfg)
        runs = [result.get("summary") or {}] if result.get("ok") else []
    else:
        runs = []
        result = {"ok": True}
        for i in range(cohort_runs):
            cfg_i = dict(cfg)
            cfg_i["seed"] = base_seed + i
            cfg_i["run_id"] = f"replay-{int(time.time())}-{i+1}"
            one = _run_single(cfg_i)
            if not one.get("ok"):
                result = one
                break
            runs.append(one.get("summary") or {})

    _CACHE["paper_replay_status"] = {"data": None, "ts": 0.0}
    _CACHE["paper_replay_history"] = {"data": None, "ts": 0.0}
    if not result.get("ok"):
        return {"ok": False, "error": result.get("error", "run_start_failed"), "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z")}
    status = trainer.status()

    agg = {}
    if runs:
        total_generated = sum(int((r or {}).get("trades_generated", 0) or 0) for r in runs)
        total_valid = sum(int((r or {}).get("valid_trades", 0) or 0) for r in runs)
        total_invalid = sum(int((r or {}).get("invalid_trades", 0) or 0) for r in runs)
        avg_return_weighted = 0.0
        if total_valid > 0:
            avg_return_weighted = sum(
                _to_float((r or {}).get("avg_return"), 0.0) * int((r or {}).get("valid_trades", 0) or 0)
                for r in runs
            ) / float(total_valid)
        win_rate_weighted = 0.0
        if total_valid > 0:
            win_rate_weighted = (
                sum(
                    (_to_float((r or {}).get("win_rate"), 0.0) / 100.0) * int((r or {}).get("valid_trades", 0) or 0)
                    for r in runs
                )
                / float(total_valid)
            ) * 100.0
        local_hits = sum(int((((r or {}).get("historical_ingest") or {}).get("local_dataset_hits", 0) or 0)) for r in runs)
        live_hits = sum(int((((r or {}).get("historical_ingest") or {}).get("live_fetch_hits", 0) or 0)) for r in runs)
        no_hist = sum(int((((r or {}).get("historical_ingest") or {}).get("no_history_symbols", 0) or 0)) for r in runs)
        first = runs[0] if runs else {}
        last = runs[-1] if runs else {}
        agg = {
            "cohort_runs": int(cohort_runs),
            "trades_generated_total": int(total_generated),
            "valid_trades_total": int(total_valid),
            "invalid_trades_total": int(total_invalid),
            "avg_return_weighted": round(avg_return_weighted, 4),
            "win_rate_weighted": round(win_rate_weighted, 2),
            "historical_ingest_totals": {
                "local_dataset_hits": int(local_hits),
                "live_fetch_hits": int(live_hits),
                "no_history_symbols": int(no_hist),
            },
            "improvement_vs_first_run": {
                "avg_return_delta": round(_to_float((last or {}).get("avg_return"), 0.0) - _to_float((first or {}).get("avg_return"), 0.0), 4),
                "win_rate_delta": round(_to_float((last or {}).get("win_rate"), 0.0) - _to_float((first or {}).get("win_rate"), 0.0), 2),
                "first_run_id": (first or {}).get("run_id"),
                "last_run_id": (last or {}).get("run_id"),
            },
        }

    return {
        "ok": True,
        "run_id": (runs[-1].get("run_id") if runs else None) or result.get("run_id") or status.get("last_run", {}).get("run_id"),
        "in_progress": bool(status.get("in_progress", False)),
        "summary": (runs[-1] if runs else result.get("summary")) or status.get("last_run", {}),
        "cohort_summary": agg,
        "run_summaries": runs[:12],
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }


@router.post("/api/historical_backfill/run")
def historical_backfill_run(payload: dict = Body(None)):
    trainer = _ensure_paper_replay_trainer()
    cfg = payload if isinstance(payload, dict) else {}
    symbols = [str(s).upper().strip() for s in (cfg.get("symbols") or []) if str(s).strip()]
    if not symbols:
        top = top_buys(buy_mode=str(cfg.get("buy_mode") or "balanced"))
        stocks = ((top.get("stocks") or {}).get("final") or []) if isinstance(top, dict) else []
        symbols = [str((r or {}).get("symbol") or "").upper() for r in stocks if (r or {}).get("symbol")]
    max_symbols = max(1, int(cfg.get("max_symbols", 30)))
    days_back = max(7, int(cfg.get("days_back", 180)))
    selected = symbols[:max_symbols]
    mode = str(cfg.get("mode") or "premium_step").strip().lower()
    if mode in {"premium", "premium_step", "staged"} and hasattr(trainer.historical_dataset, "run_premium_backfill_step"):
        res = trainer.historical_dataset.run_premium_backfill_step(
            selected,
            max_symbols=max_symbols,
        )
        return {
            "ok": bool(res.get("ok", False)),
            "mode": "premium_step",
            "symbols_requested": len(selected),
            "summary": res,
            "historical_depth": trainer.historical_dataset.depth_summary(),
            "premium_backfill_status": (
                trainer.historical_dataset.premium_backfill_status()
                if hasattr(trainer.historical_dataset, "premium_backfill_status")
                else {}
            ),
            "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        }
    results = []
    bars_ingested_total = 0
    for sym in selected:
        res = trainer.historical_dataset.backfill_symbol(sym, asset_type="stock", days_back=days_back, resolution="D")
        bars_ingested_total += int(res.get("bars_ingested") or 0)
        results.append(
            {
                "symbol": sym,
                "ok": bool(res.get("ok")),
                "bars_ingested": int(res.get("bars_ingested") or 0),
                "reason": str(res.get("reason") or ""),
            }
        )
    return {
        "ok": True,
        "symbols_requested": len(selected),
        "bars_ingested_total": bars_ingested_total,
        "results": results,
        "historical_depth": trainer.historical_dataset.depth_summary(),
        "premium_backfill_status": (
            trainer.historical_dataset.premium_backfill_status()
            if hasattr(trainer.historical_dataset, "premium_backfill_status")
            else {}
        ),
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }


