@router.get("/api/paper_replay/status")
def paper_replay_status():
    cached = _CACHE.get("paper_replay_status", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= PAPER_REPLAY_STATUS_TTL_SECONDS:
        payload = dict(cached.get("data", {}))
        payload["cached"] = True
        return payload
    trainer = _ensure_paper_replay_trainer()
    payload = trainer.status()
    payload["cached"] = False
    payload["last_updated_utc"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    _CACHE["paper_replay_status"] = {"data": dict(payload), "ts": time.time()}
    return payload


@router.get("/api/paper_replay/history")
def paper_replay_history():
    cached = _CACHE.get("paper_replay_history", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= PAPER_REPLAY_HISTORY_TTL_SECONDS:
        payload = dict(cached.get("data", {}))
        payload["cached"] = True
        return payload
    trainer = _ensure_paper_replay_trainer()
    rows = trainer.history(limit=10)
    payload = {
        "count": len(rows),
        "runs": rows,
        "cached": False,
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }
    _CACHE["paper_replay_history"] = {"data": dict(payload), "ts": time.time()}
    return payload


