    # Outcome-first recovery and workflow consistency suites.
    def _segment_best_worst(seg_map, sample_floor=25):
        rows = []
        if isinstance(seg_map, dict):
            for k, v in seg_map.items():
                if not isinstance(v, dict):
                    continue
                sample = _to_float(v.get("sample_size"), _to_float(v.get("trade_count"), 0.0))
                if sample < sample_floor:
                    continue
                wr = _to_float(v.get("win_rate"), 0.0)
                avg = _to_float(v.get("avg_friction_return"), _to_float(v.get("avg_return"), 0.0))
                rows.append((str(k), wr, avg, sample))
        if not rows:
            return ("insufficient_evidence", 0.0), ("insufficient_evidence", 0.0)
        rows = sorted(rows, key=lambda x: (x[1], x[2], x[3]), reverse=True)
        best = rows[0]
        worst = rows[-1]
        return (best[0], round(best[1], 2)), (worst[0], round(worst[1], 2))

    totals_combined = (out.get("totals") or {}).get("combined") or {}
    combined_win_rate = _to_float(totals_combined.get("win_rate"), 0.0)
    combined_median = _to_float(totals_combined.get("median_return"), 0.0)
    combined_avg = _to_float(totals_combined.get("avg_return"), 0.0)
    trade_count = int(_to_float(totals_combined.get("trade_count"), 0.0))

    learning_quality = out.get("learning_quality") or {}
    expectancy_realism = out.get("expectancy_friction_realism") or {}
    confidence_cal = out.get("confidence_calibration") or {}
