            entry_precision_v2_confirmation_count = 0
            entry_precision_v2_pullback_count = 0
            entry_precision_v2_avoid_count = 0
            signal_quality_decision_counts = {}
            signal_quality_band_counts = {}
            signal_quality_score_total = 0.0
            signal_quality_score_count = 0
            signal_quality_reject_count = 0
            signal_quality_confirmation_count = 0
            learning_activation_distribution = {}
            learning_activation_score_total = 0.0
            learning_activation_score_count = 0
            learning_activation_support_count = 0
            learning_activation_suppress_count = 0
            replay_influence_usage_count = 0
            replay_influence_effect_total = 0.0
            replay_influence_effect_count = 0
            replay_support_count = 0
            replay_negative_count = 0
            replay_insufficient_count = 0
            replay_influence_distribution = {}
            historical_training_runtime_used_count = 0
            historical_training_runtime_score_total = 0.0
            historical_training_runtime_score_count = 0
            historical_training_runtime_support_count = 0
            historical_training_runtime_suppress_count = 0
            confirmation_path_tuning_applied_count = 0
            confirmation_path_tuning_allowed_count = 0
            confirmation_path_tuning_avoid_to_confirmation_count = 0
            confirmation_path_tuning_score_total = 0.0
            confirmation_path_tuning_score_count = 0
            pseudo_learning_mode_active = False
            pseudo_learning_mode_reason = ""
            pseudo_learning_boost_usage_count = 0
            pseudo_learning_boost_score_total = 0.0
            pseudo_learning_boost_score_count = 0
            pseudo_learning_reinforce_count = 0
            pseudo_learning_confirm_count = 0
            pseudo_learning_suppress_count = 0
            entry_filter_v2_applied_count = 0
            entry_filter_v2_score_total = 0.0
            entry_filter_v2_score_count = 0
            entry_filter_v2_decision_counts = {}
            entry_filter_v2_suppress_count = 0
            entry_filter_v2_confirmation_count = 0
            entry_filter_v2_monitor_count = 0
            entry_filter_v2_allow_count = 0
            entry_filter_v2_penalty_counts = {}
            entry_quality_v2_score_total = 0.0
